/// Helper: create a test dataset in a temp directory and return its path.
fn create_test_dataset() -> (tempfile::TempDir, String) {
    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp.path().join("test_ds").to_str().unwrap().to_string();

    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new("name", DataType::Utf8, true),
    ]));

    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![
            Arc::new(Int32Array::from(vec![1, 2, 3, 4, 5])),
            Arc::new(StringArray::from(vec![
                "alice", "bob", "carol", "dave", "eve",
            ])),
        ],
    )
    .unwrap();

    // Use lance-c's internal runtime to write the dataset.
    lance_c::runtime::block_on(async {
        Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(batch)], schema),
            &uri,
            None,
        )
        .await
        .unwrap();
    });

    (tmp, uri)
}

/// Helper: create a larger dataset with multiple columns and many rows.
fn create_large_dataset(num_rows: i32) -> (tempfile::TempDir, String) {
    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp.path().join("large_ds").to_str().unwrap().to_string();

    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new("value", DataType::Float32, true),
        Field::new("label", DataType::Utf8, true),
    ]));

    let ids: Vec<i32> = (0..num_rows).collect();
    let values: Vec<f32> = (0..num_rows).map(|i| i as f32 * 0.5).collect();
    let labels: Vec<String> = (0..num_rows).map(|i| format!("row_{i}")).collect();
    let label_refs: Vec<&str> = labels.iter().map(|s| s.as_str()).collect();

    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![
            Arc::new(Int32Array::from(ids)),
            Arc::new(Float32Array::from(values)),
            Arc::new(StringArray::from(label_refs)),
        ],
    )
    .unwrap();

    lance_c::runtime::block_on(async {
        Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(batch)], schema),
            &uri,
            None,
        )
        .await
        .unwrap();
    });

    (tmp, uri)
}

fn c_str(s: &str) -> CString {
    CString::new(s).unwrap()
}

#[derive(Default)]
struct CapturedScanStatistics {
    calls: usize,
    iops: u64,
    requests: u64,
    bytes_read: u64,
    indices_loaded: u64,
    index_partitions_loaded: u64,
    index_comparisons: u64,
    metrics: Vec<(String, LanceScanMetricKind, u64)>,
}

unsafe extern "C" fn capture_scan_statistics(
    callback_ctx: *mut c_void,
    statistics: *const LanceScanStatistics,
) {
    assert!(!callback_ctx.is_null());
    assert!(!statistics.is_null());
    let captured = unsafe { &mut *callback_ctx.cast::<CapturedScanStatistics>() };
    let statistics = unsafe { &*statistics };
    let metrics = if statistics.metrics_len == 0 {
        &[]
    } else {
        assert!(!statistics.metrics.is_null());
        unsafe { std::slice::from_raw_parts(statistics.metrics, statistics.metrics_len) }
    };

    captured.calls += 1;
    captured.iops = statistics.iops;
    captured.requests = statistics.requests;
    captured.bytes_read = statistics.bytes_read;
    captured.indices_loaded = statistics.indices_loaded;
    captured.index_partitions_loaded = statistics.index_partitions_loaded;
    captured.index_comparisons = statistics.index_comparisons;
    captured.metrics = metrics
        .iter()
        .map(|metric| {
            let name = if metric.name_len == 0 {
                &[]
            } else {
                assert!(!metric.name.is_null());
                unsafe { std::slice::from_raw_parts(metric.name.cast::<u8>(), metric.name_len) }
            };
            (
                std::str::from_utf8(name).unwrap().to_owned(),
                metric.kind,
                metric.value,
            )
        })
        .collect();
}

#[derive(Default)]
struct AtomicScanStatisticsCapture {
    calls: AtomicUsize,
    invalid_statistics: AtomicBool,
}

unsafe extern "C" fn capture_scan_statistics_atomically(
    callback_ctx: *mut c_void,
    statistics: *const LanceScanStatistics,
) {
    if callback_ctx.is_null() {
        return;
    }
    let captured = unsafe { &*callback_ctx.cast::<AtomicScanStatisticsCapture>() };
    if statistics.is_null() {
        captured
            .invalid_statistics
            .store(true, AtomicOrdering::SeqCst);
        return;
    }
    captured.calls.fetch_add(1, AtomicOrdering::SeqCst);
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct TrackedFileRow {
    version: i64,
    base_uri: String,
    path: String,
    file_type: String,
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct PhysicalFileRow {
    base_uri: String,
    path: String,
    size_bytes: i64,
    last_modified: i64,
}

fn dictionary_string_value(array: &dyn Array, row: usize) -> String {
    if let Some(dictionary) = array.as_any().downcast_ref::<DictionaryArray<Int32Type>>() {
        let values = dictionary
            .values()
            .as_any()
            .downcast_ref::<StringArray>()
            .unwrap();
        return values
            .value(dictionary.keys().value(row) as usize)
            .to_owned();
    }
    if let Some(dictionary) = array.as_any().downcast_ref::<DictionaryArray<Int8Type>>() {
        let values = dictionary
            .values()
            .as_any()
            .downcast_ref::<StringArray>()
            .unwrap();
        return values
            .value(dictionary.keys().value(row) as usize)
            .to_owned();
    }
    panic!("expected an Int32 or Int8 string dictionary");
}

fn tracked_file_rows(batches: &[RecordBatch]) -> Vec<TrackedFileRow> {
    let mut rows = Vec::new();
    for batch in batches {
        let versions = batch
            .column_by_name("version")
            .unwrap()
            .as_any()
            .downcast_ref::<Int64Array>()
            .unwrap();
        let base_uris = batch.column_by_name("base_uri").unwrap();
        let paths = batch
            .column_by_name("path")
            .unwrap()
            .as_any()
            .downcast_ref::<StringArray>()
            .unwrap();
        let file_types = batch.column_by_name("type").unwrap();
        for row in 0..batch.num_rows() {
            rows.push(TrackedFileRow {
                version: versions.value(row),
                base_uri: dictionary_string_value(base_uris.as_ref(), row),
                path: paths.value(row).to_owned(),
                file_type: dictionary_string_value(file_types.as_ref(), row),
            });
        }
    }
    rows.sort();
    rows
}

fn physical_file_rows(batches: &[RecordBatch]) -> Vec<PhysicalFileRow> {
    let mut rows = Vec::new();
    for batch in batches {
        let base_uris = batch.column_by_name("base_uri").unwrap();
        let paths = batch
            .column_by_name("path")
            .unwrap()
            .as_any()
            .downcast_ref::<StringArray>()
            .unwrap();
        let sizes = batch
            .column_by_name("size_bytes")
            .unwrap()
            .as_any()
            .downcast_ref::<Int64Array>()
            .unwrap();
        let timestamps = batch
            .column_by_name("last_modified")
            .unwrap()
            .as_any()
            .downcast_ref::<TimestampMicrosecondArray>()
            .unwrap();
        for row in 0..batch.num_rows() {
            rows.push(PhysicalFileRow {
                base_uri: dictionary_string_value(base_uris.as_ref(), row),
                path: paths.value(row).to_owned(),
                size_bytes: sizes.value(row),
                last_modified: timestamps.value(row),
            });
        }
    }
    rows.sort();
    rows
}

fn c_stream_batches(mut stream: FFI_ArrowArrayStream) -> (Schema, Vec<RecordBatch>) {
    let reader = unsafe { ArrowArrayStreamReader::from_raw(&mut stream) }.unwrap();
    let schema = reader.schema().as_ref().clone();
    let batches = reader.map(Result::unwrap).collect();
    (schema, batches)
}

#[derive(Default)]
struct TrackedProgressState {
    events: Mutex<Vec<(u64, Option<u64>)>>,
    releases: Mutex<usize>,
    release_cv: Condvar,
}

struct TrackedProgressContext {
    state: Arc<TrackedProgressState>,
}

unsafe extern "C" fn record_tracked_progress(
    callback_ctx: *mut c_void,
    manifests_processed: u64,
    manifests_total: *const u64,
) {
    let context = unsafe { &*callback_ctx.cast::<TrackedProgressContext>() };
    let total = if manifests_total.is_null() {
        None
    } else {
        Some(unsafe { *manifests_total })
    };
    context
        .state
        .events
        .lock()
        .unwrap()
        .push((manifests_processed, total));
}

unsafe extern "C" fn release_tracked_progress(callback_ctx: *mut c_void) {
    let context = unsafe { Box::from_raw(callback_ctx.cast::<TrackedProgressContext>()) };
    *context.state.releases.lock().unwrap() += 1;
    context.state.release_cv.notify_all();
}

fn wait_for_progress_release(state: &TrackedProgressState) {
    let deadline = Instant::now() + Duration::from_secs(10);
    let mut releases = state.releases.lock().unwrap();
    while *releases == 0 {
        let remaining = deadline.saturating_duration_since(Instant::now());
        assert!(!remaining.is_zero(), "progress context was not released");
        let (guard, timeout) = state.release_cv.wait_timeout(releases, remaining).unwrap();
        releases = guard;
        assert!(
            !timeout.timed_out() || *releases > 0,
            "progress context was not released before timeout"
        );
    }
    assert_eq!(
        *releases, 1,
        "progress context must be released exactly once"
    );
}

struct BlockingProgressState {
    entered: Mutex<bool>,
    entered_cv: Condvar,
    allow_return: Mutex<bool>,
    allow_return_cv: Condvar,
    releases: Mutex<usize>,
    release_cv: Condvar,
}

struct BlockingProgressContext {
    state: Arc<BlockingProgressState>,
}

unsafe extern "C" fn block_tracked_progress(
    callback_ctx: *mut c_void,
    _manifests_processed: u64,
    _manifests_total: *const u64,
) {
    let context = unsafe { &*callback_ctx.cast::<BlockingProgressContext>() };
    *context.state.entered.lock().unwrap() = true;
    context.state.entered_cv.notify_all();
    let mut allow_return = context.state.allow_return.lock().unwrap();
    while !*allow_return {
        allow_return = context.state.allow_return_cv.wait(allow_return).unwrap();
    }
}

unsafe extern "C" fn release_blocking_progress(callback_ctx: *mut c_void) {
    let context = unsafe { Box::from_raw(callback_ctx.cast::<BlockingProgressContext>()) };
    *context.state.releases.lock().unwrap() += 1;
    context.state.release_cv.notify_all();
}

// ─── Index build progress capture fixture ───

/// Records progress events plus the exact `callback_ctx` pointer each
/// invocation received, so tests can verify the context round-trips.
#[derive(Default)]
struct ProgressCapture {
    events: Vec<(i32, String, u64, String, u64)>,
    contexts: Vec<*mut c_void>,
}

/// Heap-allocate a capture and return it as an opaque callback context.
fn new_progress_capture() -> *mut c_void {
    let capture: Box<Mutex<ProgressCapture>> = Box::new(Mutex::new(ProgressCapture::default()));
    Box::into_raw(capture).cast()
}

/// Reclaim a capture created by `new_progress_capture` and return its contents.
fn take_progress_capture(callback_ctx: *mut c_void) -> ProgressCapture {
    assert!(!callback_ctx.is_null());
    let capture = unsafe { Box::from_raw(callback_ctx.cast::<Mutex<ProgressCapture>>()) };
    capture.into_inner().unwrap()
}

/// Progress callback that records every event (and the context pointer it was
/// invoked with) into the heap `ProgressCapture` passed as `callback_ctx`.
/// Tolerates a NULL context by ignoring the call.
unsafe extern "C" fn record_build_progress(
    callback_ctx: *mut c_void,
    event: i32,
    stage: *const c_char,
    total: u64,
    unit: *const c_char,
    completed: u64,
) {
    if callback_ctx.is_null() {
        return;
    }
    let capture = unsafe { &*callback_ctx.cast::<Mutex<ProgressCapture>>() };
    let stage = unsafe { std::ffi::CStr::from_ptr(stage) }
        .to_string_lossy()
        .into_owned();
    let unit = unsafe { std::ffi::CStr::from_ptr(unit) }
        .to_string_lossy()
        .into_owned();
    let mut guard = capture.lock().unwrap();
    guard.contexts.push(callback_ctx);
    guard.events.push((event, stage, total, unit, completed));
}

/// Log of every raw `callback_ctx` a build invoked (as `usize` so the static
/// stays `Sync`), for round-trip checks that pass a sentinel or NULL context
/// instead of a capture.
static RECORDED_PROGRESS_CONTEXTS: Mutex<Vec<usize>> = Mutex::new(Vec::new());

/// Progress callback that records only the raw `callback_ctx` pointer, never
/// dereferencing it. Used for sentinel / NULL context round-trip checks.
unsafe extern "C" fn record_progress_ctx(
    callback_ctx: *mut c_void,
    _event: i32,
    _stage: *const c_char,
    _total: u64,
    _unit: *const c_char,
    _completed: u64,
) {
    RECORDED_PROGRESS_CONTEXTS
        .lock()
        .unwrap()
        .push(callback_ctx as usize);
}

/// Assert the well-formedness invariants shared by every progress-capturing
/// build: event codes are only {START, PROGRESS, COMPLETE}, stage strings are
/// non-empty, the documented numeric mapping holds per event (PROGRESS
/// reports total == 0, START reports completed == 0, COMPLETE zeroes both,
/// and only START carries a unit), and per stage the first event is START,
/// the last is COMPLETE, and START/COMPLETE counts match (one active stage at
/// a time).
fn assert_progress_events_well_formed(capture: &ProgressCapture) {
    use std::collections::HashMap;
    for (event, stage, total, unit, completed) in &capture.events {
        assert!(
            *event == 0 || *event == 1 || *event == 2,
            "unexpected progress event code {event}"
        );
        assert!(!stage.is_empty(), "progress stage must be non-empty");
        if *event == 1 {
            assert_eq!(*total, 0, "PROGRESS event must report total == 0");
        }
        if *event == 0 {
            assert_eq!(*completed, 0, "START event must report completed == 0");
        }
        if *event == 2 {
            assert_eq!(*total, 0, "COMPLETE event must report total == 0");
            assert_eq!(*completed, 0, "COMPLETE event must report completed == 0");
        }
        if *event != 0 {
            assert!(unit.is_empty(), "non-START event must report unit == \"\"");
        }
    }
    let mut order: Vec<&str> = Vec::new();
    let mut by_stage: HashMap<&str, Vec<i32>> = HashMap::new();
    for (event, stage, ..) in &capture.events {
        if !by_stage.contains_key(stage.as_str()) {
            order.push(stage);
        }
        by_stage.entry(stage.as_str()).or_default().push(*event);
    }
    for stage in order {
        let events = &by_stage[stage];
        assert_eq!(
            events.first().copied(),
            Some(0),
            "stage {stage} must begin with START"
        );
        assert_eq!(
            events.last().copied(),
            Some(2),
            "stage {stage} must end with COMPLETE"
        );
        let starts = events.iter().filter(|&&event| event == 0).count();
        let completes = events.iter().filter(|&&event| event == 2).count();
        assert_eq!(
            starts, completes,
            "stage {stage} must pair each START with a COMPLETE"
        );
    }
}

/// Helper: build a tiny dataset whose `value` column is nullable AND contains
/// at least one NULL. Used by tests that need to exercise upstream's
/// nullability-tightening pre-scan failure path.
fn create_dataset_with_nulls() -> (tempfile::TempDir, String) {
    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp.path().join("with_nulls").to_str().unwrap().to_string();
    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new("value", DataType::Float32, true),
    ]));
    let ids = Int32Array::from(vec![1, 2, 3]);
    let values = Float32Array::from(vec![Some(1.0), None, Some(3.0)]);
    let batch =
        RecordBatch::try_new(schema.clone(), vec![Arc::new(ids), Arc::new(values)]).unwrap();
    lance_c::runtime::block_on(async {
        Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(batch)], schema),
            &uri,
            None,
        )
        .await
        .unwrap();
    });
    (tmp, uri)
}

/// Helper: scan to ArrowArrayStream and collect all rows.
fn scan_all_rows(ds: *const LanceDataset) -> Vec<RecordBatch> {
    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    let mut ffi_stream = FFI_ArrowArrayStream::empty();
    let rc = unsafe { lance_scanner_to_arrow_stream(scanner, &mut ffi_stream) };
    assert_eq!(rc, 0);
    let reader = unsafe { ArrowArrayStreamReader::from_raw(&mut ffi_stream) }.unwrap();
    let batches: Vec<RecordBatch> = reader.map(|r| r.unwrap()).collect();
    unsafe { lance_scanner_close(scanner) };
    batches
}

/// Two-fragment ordering fixture with nullable, duplicated sort keys.
///
/// `id` is unique and provides the explicit tie-breaker; `category` and `rank`
/// carry NULLs and duplicates across both fragments.
fn create_ordering_dataset() -> (tempfile::TempDir, String) {
    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp.path().join("ordering_ds").to_str().unwrap().to_string();
    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new("category", DataType::Utf8, true),
        Field::new("rank", DataType::Int32, true),
    ]));

    let make_batch = |ids: Vec<i32>, groups: &[Option<&str>], ranks: &[Option<i32>]| {
        RecordBatch::try_new(
            schema.clone(),
            vec![
                Arc::new(Int32Array::from(ids)),
                Arc::new(StringArray::from(groups.to_vec())),
                Arc::new(Int32Array::from(ranks.to_vec())),
            ],
        )
        .unwrap()
    };

    lance_c::runtime::block_on(async {
        let first = make_batch(
            vec![0, 1, 2, 3, 4, 5],
            &[
                Some("b"),
                Some("b"),
                Some("a"),
                Some("a"),
                Some("b"),
                Some("a"),
            ],
            &[Some(2), None, Some(1), Some(1), Some(2), None],
        );
        Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(first)], schema.clone()),
            &uri,
            None,
        )
        .await
        .unwrap();
        let second = make_batch(
            vec![6, 7, 8, 9, 10, 11],
            &[Some("b"), Some("a"), None, Some("b"), Some("a"), None],
            &[Some(2), Some(1), Some(3), None, Some(1), Some(2)],
        );
        let mut dataset = Dataset::open(&uri).await.unwrap();
        dataset
            .append(
                arrow::record_batch::RecordBatchIterator::new(vec![Ok(second)], schema.clone()),
                None,
            )
            .await
            .unwrap();
    });

    (tmp, uri)
}

fn ordering_specs(
    specs: &[(&str, LanceOrderDirection, LanceNullOrder)],
) -> (Vec<CString>, Vec<LanceColumnOrdering>) {
    let names = specs
        .iter()
        .map(|(name, ..)| CString::new(*name).unwrap())
        .collect::<Vec<_>>();
    let orderings = specs
        .iter()
        .zip(&names)
        .map(|((_, direction, null_order), name)| LanceColumnOrdering {
            column_name: name.as_ptr(),
            direction: *direction as i32,
            null_order: *null_order as i32,
        })
        .collect();
    (names, orderings)
}

fn set_order_by(
    scanner: *mut LanceScanner,
    specs: &[(&str, LanceOrderDirection, LanceNullOrder)],
) -> i32 {
    let (_names, orderings) = ordering_specs(specs);
    unsafe {
        lance_scanner_set_order_by(
            scanner,
            if orderings.is_empty() {
                std::ptr::NonNull::<LanceColumnOrdering>::dangling().as_ptr()
            } else {
                orderings.as_ptr()
            },
            orderings.len(),
        )
    }
}

fn ordering_rows(batches: &[RecordBatch]) -> Vec<(i32, Option<String>, Option<i32>)> {
    let mut rows = Vec::new();
    for batch in batches {
        let ids = batch
            .column_by_name("id")
            .unwrap()
            .as_any()
            .downcast_ref::<Int32Array>()
            .unwrap();
        let groups = batch
            .column_by_name("category")
            .unwrap()
            .as_any()
            .downcast_ref::<StringArray>()
            .unwrap();
        let ranks = batch
            .column_by_name("rank")
            .unwrap()
            .as_any()
            .downcast_ref::<Int32Array>()
            .unwrap();
        for row in 0..batch.num_rows() {
            rows.push((
                ids.value(row),
                (!groups.is_null(row)).then(|| groups.value(row).to_owned()),
                (!ranks.is_null(row)).then(|| ranks.value(row)),
            ));
        }
    }
    rows
}

fn ordering_fixture_rows() -> Vec<(i32, Option<String>, Option<i32>)> {
    vec![
        (0, Some("b".into()), Some(2)),
        (1, Some("b".into()), None),
        (2, Some("a".into()), Some(1)),
        (3, Some("a".into()), Some(1)),
        (4, Some("b".into()), Some(2)),
        (5, Some("a".into()), None),
        (6, Some("b".into()), Some(2)),
        (7, Some("a".into()), Some(1)),
        (8, None, Some(3)),
        (9, Some("b".into()), None),
        (10, Some("a".into()), Some(1)),
        (11, None, Some(2)),
    ]
}

fn expected_ordering_rows(ids: &[i32]) -> Vec<(i32, Option<String>, Option<i32>)> {
    let fixture = ordering_fixture_rows();
    ids.iter()
        .map(|id| {
            fixture
                .iter()
                .find(|row| row.0 == *id)
                .unwrap_or_else(|| panic!("missing fixture id {id}"))
                .clone()
        })
        .collect()
}

fn projection_specs(
    specs: &[(&str, &str)],
) -> (Vec<CString>, Vec<CString>, Vec<LanceProjectionColumn>) {
    let names = specs
        .iter()
        .map(|(name, _)| CString::new(*name).unwrap())
        .collect::<Vec<_>>();
    let expressions = specs
        .iter()
        .map(|(_, expression)| CString::new(*expression).unwrap())
        .collect::<Vec<_>>();
    let columns = names
        .iter()
        .zip(&expressions)
        .map(|(name, expression)| LanceProjectionColumn {
            output_name: name.as_ptr(),
            expression: expression.as_ptr(),
        })
        .collect();
    (names, expressions, columns)
}

fn set_projection(scanner: *mut LanceScanner, specs: &[(&str, &str)]) -> i32 {
    let (_names, _expressions, columns) = projection_specs(specs);
    unsafe {
        lance_scanner_set_projection(
            scanner,
            if columns.is_empty() {
                std::ptr::NonNull::<LanceProjectionColumn>::dangling().as_ptr()
            } else {
                columns.as_ptr()
            },
            columns.len(),
        )
    }
}

/// Two-fragment projection fixture with nullable values and nested fields.
fn create_projection_dataset() -> (tempfile::TempDir, String) {
    use arrow_array::{ArrayRef, StructArray};
    use arrow_schema::Fields;

    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp
        .path()
        .join("projection_ds")
        .to_str()
        .unwrap()
        .to_string();
    let point_fields = Fields::from(vec![
        Field::new("x", DataType::Float32, true),
        Field::new("y", DataType::Float32, true),
    ]);
    let location_field = Arc::new(Field::new(
        "location",
        DataType::Struct(point_fields.clone()),
        true,
    ));
    let age_field = Arc::new(Field::new("age", DataType::Int32, true));
    let meta_fields = Fields::from(vec![location_field.clone(), age_field.clone()]);
    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new("value", DataType::Int32, true),
        Field::new("meta", DataType::Struct(meta_fields.clone()), true),
    ]));

    let make_batch = |ids: Vec<i32>,
                      values: Vec<Option<i32>>,
                      xs: Vec<Option<f32>>,
                      ys: Vec<f32>,
                      ages: Vec<Option<i32>>| {
        let location = StructArray::new(
            point_fields.clone(),
            vec![
                Arc::new(Float32Array::from(xs)) as ArrayRef,
                Arc::new(Float32Array::from(ys)) as ArrayRef,
            ],
            None,
        );
        let meta = StructArray::new(
            meta_fields.clone(),
            vec![
                Arc::new(location) as ArrayRef,
                Arc::new(Int32Array::from(ages)) as ArrayRef,
            ],
            None,
        );
        RecordBatch::try_new(
            schema.clone(),
            vec![
                Arc::new(Int32Array::from(ids)),
                Arc::new(Int32Array::from(values)),
                Arc::new(meta),
            ],
        )
        .unwrap()
    };

    lance_c::runtime::block_on(async {
        let first = make_batch(
            vec![0, 1, 2, 3],
            vec![Some(10), None, Some(12), Some(13)],
            vec![Some(0.0), Some(1.5), None, Some(3.0)],
            vec![10.0, 11.0, 12.0, 13.0],
            vec![Some(20), None, Some(22), Some(23)],
        );
        Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(first)], schema.clone()),
            &uri,
            None,
        )
        .await
        .unwrap();
        let second = make_batch(
            vec![4, 5, 6, 7],
            vec![None, Some(15), Some(16), Some(17)],
            vec![Some(4.0), Some(5.0), Some(6.5), None],
            vec![14.0, 15.0, 16.0, 17.0],
            vec![None, Some(25), Some(26), Some(27)],
        );
        let mut dataset = Dataset::open(&uri).await.unwrap();
        dataset
            .append(
                arrow::record_batch::RecordBatchIterator::new(vec![Ok(second)], schema.clone()),
                None,
            )
            .await
            .unwrap();
        assert_eq!(dataset.get_fragments().len(), 2);
    });

    (tmp, uri)
}

fn projection_rows(batches: &[RecordBatch]) -> Vec<(i32, i32, Option<f32>, Option<i32>)> {
    let mut rows = Vec::new();
    for batch in batches {
        let ids = batch
            .column_by_name("id_alias")
            .unwrap()
            .as_any()
            .downcast_ref::<Int32Array>()
            .unwrap();
        let doubled = batch
            .column_by_name("doubled")
            .unwrap()
            .as_any()
            .downcast_ref::<Int32Array>()
            .unwrap();
        let xs = batch
            .column_by_name("x")
            .unwrap()
            .as_any()
            .downcast_ref::<Float32Array>()
            .unwrap();
        let ages = batch
            .column_by_name("age")
            .unwrap()
            .as_any()
            .downcast_ref::<Int32Array>()
            .unwrap();
        for row in 0..batch.num_rows() {
            rows.push((
                ids.value(row),
                doubled.value(row),
                (!xs.is_null(row)).then(|| xs.value(row)),
                (!ages.is_null(row)).then(|| ages.value(row)),
            ));
        }
    }
    rows.sort_unstable_by_key(|row| row.0);
    rows
}

fn schema_signature(schema: &Schema) -> Vec<(String, DataType, bool)> {
    schema
        .fields()
        .iter()
        .map(|field| {
            (
                field.name().clone(),
                field.data_type().clone(),
                field.is_nullable(),
            )
        })
        .collect()
}

fn scanner_introspection_schema(scanner: *const LanceScanner) -> Schema {
    let mut ffi = FFI_ArrowSchema::empty();
    assert_eq!(
        unsafe { lance_scanner_schema(scanner, &mut ffi) },
        0,
        "{}",
        take_last_error_message()
    );
    let schema = Schema::try_from(&ffi).unwrap();
    if let Some(release) = ffi.release {
        unsafe { release(&mut ffi) };
    }
    schema
}

fn take_scanner_string(raw: *const c_char) -> String {
    assert!(!raw.is_null(), "{}", take_last_error_message());
    let value = unsafe { CStr::from_ptr(raw) }
        .to_string_lossy()
        .into_owned();
    unsafe { lance_free_string(raw) };
    value
}

fn scan_ordering_rows(scanner: *mut LanceScanner) -> Vec<(i32, Option<String>, Option<i32>)> {
    let mut stream = FFI_ArrowArrayStream::empty();
    assert_eq!(
        unsafe { lance_scanner_to_arrow_stream(scanner, &mut stream) },
        0,
        "{}",
        take_last_error_message()
    );
    let reader = unsafe { ArrowArrayStreamReader::from_raw(&mut stream) }.unwrap();
    let batches = reader.map(|batch| batch.unwrap()).collect::<Vec<_>>();
    ordering_rows(&batches)
}

fn collect_scanner(scanner: *mut LanceScanner) -> (arrow_schema::SchemaRef, Vec<RecordBatch>) {
    let mut stream = FFI_ArrowArrayStream::empty();
    assert_eq!(
        unsafe { lance_scanner_to_arrow_stream(scanner, &mut stream) },
        0,
        "{}",
        take_last_error_message()
    );
    let reader = unsafe { ArrowArrayStreamReader::from_raw(&mut stream) }.unwrap();
    let schema = reader.schema();
    let batches = reader.map(|batch| batch.unwrap()).collect();
    (schema, batches)
}

fn scan_ordering_ids(scanner: *mut LanceScanner) -> Vec<i32> {
    let mut stream = FFI_ArrowArrayStream::empty();
    assert_eq!(
        unsafe { lance_scanner_to_arrow_stream(scanner, &mut stream) },
        0,
        "{}",
        take_last_error_message()
    );
    let reader = unsafe { ArrowArrayStreamReader::from_raw(&mut stream) }.unwrap();
    let mut ids = Vec::new();
    for batch in reader {
        let batch = batch.unwrap();
        let column = batch
            .column_by_name("id")
            .unwrap()
            .as_any()
            .downcast_ref::<Int32Array>()
            .unwrap();
        ids.extend(column.values().iter().copied());
    }
    ids
}

fn ordering_row_ids(dataset: *const LanceDataset) -> std::collections::HashMap<i32, u64> {
    let scanner = unsafe { lance_scanner_new(dataset, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(unsafe { lance_scanner_with_row_id(scanner, true) }, 0);
    let mut stream = FFI_ArrowArrayStream::empty();
    assert_eq!(
        unsafe { lance_scanner_to_arrow_stream(scanner, &mut stream) },
        0,
        "{}",
        take_last_error_message()
    );
    let reader = unsafe { ArrowArrayStreamReader::from_raw(&mut stream) }.unwrap();
    let mut ids = std::collections::HashMap::new();
    for batch in reader {
        let batch = batch.unwrap();
        let id = batch
            .column_by_name("id")
            .unwrap()
            .as_any()
            .downcast_ref::<Int32Array>()
            .unwrap();
        let row_id = batch
            .column_by_name("_rowid")
            .unwrap()
            .as_any()
            .downcast_ref::<UInt64Array>()
            .unwrap();
        for row in 0..batch.num_rows() {
            ids.insert(id.value(row), row_id.value(row));
        }
    }
    unsafe { lance_scanner_close(scanner) };
    ids
}

fn native_ordering_rows(
    uri: &str,
    orderings: Vec<NativeColumnOrdering>,
    filter: Option<&str>,
    columns: Option<Vec<&str>>,
    limit: Option<i64>,
    offset: Option<i64>,
) -> Vec<(i32, Option<String>, Option<i32>)> {
    lance_c::runtime::block_on(async {
        let dataset = Dataset::open(uri).await.unwrap();
        let mut scanner = dataset.scan();
        if let Some(columns) = columns {
            scanner.project(&columns).unwrap();
        }
        if let Some(filter) = filter {
            scanner.filter(filter).unwrap();
        }
        if limit.is_some() || offset.is_some() {
            scanner.limit(limit, offset).unwrap();
        }
        scanner.order_by(Some(orderings)).unwrap();
        let stream = scanner.try_into_stream().await.unwrap();
        let batches = stream.try_collect::<Vec<_>>().await.unwrap();
        ordering_rows(&batches)
    })
}

type OrderingSpec<'a> = (&'a str, LanceOrderDirection, LanceNullOrder);
type OrderingCase<'a> = (Vec<OrderingSpec<'a>>, Vec<i32>);

