fn version_metadata(version: *const LanceVersion) -> std::collections::BTreeMap<String, String> {
    let count = unsafe { lance_version_metadata_count(version) };
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
    let mut metadata = std::collections::BTreeMap::new();
    for index in 0..count as usize {
        let key = unsafe { lance_version_metadata_key_at(version, index) };
        assert!(!key.is_null());
        let value = unsafe { lance_version_metadata_value_at(version, index) };
        assert!(!value.is_null());
        metadata.insert(
            unsafe { std::ffi::CStr::from_ptr(key) }
                .to_str()
                .unwrap()
                .to_string(),
            unsafe { std::ffi::CStr::from_ptr(value) }
                .to_str()
                .unwrap()
                .to_string(),
        );
    }
    metadata
}

fn tag_metadata(tag: *const LanceTag) -> std::collections::BTreeMap<String, String> {
    let count = unsafe { lance_tag_metadata_count(tag) };
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
    let mut metadata = std::collections::BTreeMap::new();
    for index in 0..count as usize {
        let key = unsafe { lance_tag_metadata_key_at(tag, index) };
        assert!(!key.is_null());
        let value = unsafe { lance_tag_metadata_value_at(tag, index) };
        assert!(!value.is_null());
        metadata.insert(
            unsafe { std::ffi::CStr::from_ptr(key) }
                .to_str()
                .unwrap()
                .to_string(),
            unsafe { std::ffi::CStr::from_ptr(value) }
                .to_str()
                .unwrap()
                .to_string(),
        );
    }
    metadata
}

fn tag_name(tag: *const LanceTag) -> String {
    let name = unsafe { lance_tag_name(tag) };
    assert!(!name.is_null());
    unsafe { std::ffi::CStr::from_ptr(name) }
        .to_str()
        .unwrap()
        .to_string()
}

fn find_tag(tags: *const LanceTags, name: &str) -> *const LanceTag {
    let count = unsafe { lance_tags_count(tags) };
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
    for index in 0..count as usize {
        let tag = unsafe { lance_tags_at(tags, index) };
        assert!(!tag.is_null());
        if tag_name(tag) == name {
            return tag;
        }
    }
    ptr::null()
}

fn owned_c_string(value: *const c_char) -> String {
    assert!(!value.is_null());
    let owned = unsafe { CStr::from_ptr(value) }
        .to_str()
        .unwrap()
        .to_string();
    unsafe { lance_free_string(value) };
    owned
}

fn owned_json(value: *const c_char) -> serde_json::Value {
    serde_json::from_str(&owned_c_string(value)).unwrap()
}

fn native_branch(uri: &str, name: &str) -> BranchContents {
    lance_c::runtime::block_on(async {
        Dataset::open(uri)
            .await
            .unwrap()
            .branches()
            .get(name)
            .await
            .unwrap()
    })
}

fn assert_branch_json(json: &serde_json::Value, native: &BranchContents) {
    assert_eq!(
        json["parentBranch"].as_str(),
        native.parent_branch.as_deref()
    );
    assert_eq!(
        json["parentVersion"].as_u64().unwrap(),
        native.parent_version
    );
    assert_eq!(json["createAt"].as_u64().unwrap(), native.create_at);
    assert_eq!(
        json["manifestSize"].as_u64().unwrap(),
        native.manifest_size as u64
    );

    let mapping = json["identifier"]["version_mapping"]
        .as_array()
        .expect("BranchIdentifier.version_mapping must be a JSON array");
    assert_eq!(
        mapping.len(),
        native.identifier.version_mapping.len(),
        "native identifier mapping length"
    );
    for (actual, expected) in mapping.iter().zip(&native.identifier.version_mapping) {
        let pair = actual.as_array().expect("version mapping entry");
        assert_eq!(pair.len(), 2);
        assert_eq!(pair[0].as_u64(), Some(expected.0));
        assert_eq!(pair[1].as_str(), Some(expected.1.as_str()));
    }

    let metadata = json["metadata"]
        .as_object()
        .expect("BranchContents.metadata must be a JSON object");
    assert_eq!(metadata.len(), native.metadata.len());
    for (key, value) in &native.metadata {
        assert_eq!(
            metadata.get(key).and_then(|value| value.as_str()),
            Some(value.as_str())
        );
    }
}

#[test]
fn test_current_version_details_metadata_and_version_refs() {
    let (_tmp, uri) = create_two_version_dataset();
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());
    assert_eq!(unsafe { lance_dataset_version(ds) }, 2);
    assert_eq!(unsafe { lance_dataset_count_rows(ds) }, 7);

    let current = unsafe { lance_dataset_current_version(ds) };
    assert!(!current.is_null());
    assert_eq!(unsafe { lance_version_id(current) }, 2);
    let current_metadata = version_metadata(current);
    assert_eq!(current_metadata.get("total_rows").unwrap(), "7");
    assert_eq!(current_metadata.get("total_fragments").unwrap(), "2");

    let native = lance_c::runtime::block_on(Dataset::open(&uri)).unwrap();
    let native_current = native.version();
    assert_eq!(
        unsafe { lance_version_timestamp_ns(current) },
        native_current.timestamp.timestamp_nanos_opt().unwrap(),
        "the additive accessor must preserve the native timestamp"
    );
    assert_eq!(current_metadata, native_current.metadata);

    let versions = unsafe { lance_dataset_versions(ds) };
    assert!(!versions.is_null());
    assert_eq!(unsafe { lance_versions_count(versions) }, 2);

    let version1 = unsafe { lance_versions_at(versions, 0) };
    let version2 = unsafe { lance_versions_at(versions, 1) };
    assert!(!version1.is_null());
    assert!(!version2.is_null());
    assert_eq!(unsafe { lance_version_id(version1) }, 1);
    assert_eq!(unsafe { lance_version_id(version2) }, 2);
    assert_eq!(version_metadata(version1).get("total_rows").unwrap(), "5");
    assert_eq!(
        version_metadata(version1).get("total_fragments").unwrap(),
        "1"
    );
    assert_eq!(version_metadata(version2).get("total_rows").unwrap(), "7");
    assert_eq!(
        version_metadata(version2).get("total_fragments").unwrap(),
        "2"
    );
    let timestamp1 = unsafe { lance_version_timestamp_ns(version1) };
    let timestamp2 = unsafe { lance_version_timestamp_ns(version2) };
    assert!(timestamp1 > 0 && timestamp2 >= timestamp1);
    assert_eq!(
        unsafe { lance_versions_timestamp_ms_at(versions, 1) },
        timestamp2 / 1_000_000
    );

    let refs = unsafe { lance_dataset_version_refs(ds) };
    assert!(!refs.is_null());
    assert_eq!(unsafe { lance_version_refs_count(refs) }, 2);
    assert_eq!(unsafe { lance_version_refs_id_at(refs, 0) }, 1);
    assert_eq!(unsafe { lance_version_refs_id_at(refs, 1) }, 2);

    // These handles own copied native data, so closing the source does not
    // invalidate their fields.
    unsafe { lance_dataset_close(ds) };
    assert_eq!(unsafe { lance_version_id(current) }, 2);
    assert_eq!(version_metadata(current).get("total_rows").unwrap(), "7");
    assert_eq!(unsafe { lance_versions_count(versions) }, 2);
    assert_eq!(unsafe { lance_version_id(version2) }, 2);
    assert_eq!(unsafe { lance_version_refs_count(refs) }, 2);

    unsafe {
        lance_version_refs_close(refs);
        lance_versions_close(versions);
        lance_version_close(current);
    }
}

#[test]
fn test_native_ref_variants_checkout_and_old_handles() {
    let (_tmp, uri) = create_two_version_dataset();
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let tag_ref = unsafe { lance_ref_version_number(1) };
    assert!(!tag_ref.is_null());
    let tag_name = c_str("checkout-v1");
    assert_eq!(
        unsafe { lance_dataset_tag_create(ds, tag_name.as_ptr(), tag_ref) },
        0
    );
    unsafe { lance_ref_close(tag_ref) };

    let version_number = unsafe { lance_ref_version_number(1) };
    let latest = unsafe { lance_ref_version(ptr::null(), false, 0) };
    let main_branch_version = unsafe { lance_ref_version(c_str("main").as_ptr(), true, 1) };
    let tag = unsafe { lance_ref_tag(c_str("checkout-v1").as_ptr()) };
    assert!(!version_number.is_null());
    assert!(!latest.is_null());
    assert!(!main_branch_version.is_null());
    assert!(!tag.is_null());

    let checked_v1 = unsafe { lance_dataset_checkout_ref(ds, version_number) };
    let checked_latest = unsafe { lance_dataset_checkout_ref(ds, latest) };
    let checked_main = unsafe { lance_dataset_checkout_ref(ds, main_branch_version) };
    let checked_tag = unsafe { lance_dataset_checkout_ref(ds, tag) };
    for checked in [checked_v1, checked_latest, checked_main, checked_tag] {
        assert!(!checked.is_null());
    }
    assert_eq!(unsafe { lance_dataset_version(checked_v1) }, 1);
    assert_eq!(unsafe { lance_dataset_count_rows(checked_v1) }, 5);
    assert_eq!(unsafe { lance_dataset_version(checked_latest) }, 2);
    assert_eq!(unsafe { lance_dataset_count_rows(checked_latest) }, 7);
    assert_eq!(unsafe { lance_dataset_version(checked_main) }, 1);
    assert_eq!(unsafe { lance_dataset_count_rows(checked_main) }, 5);
    assert_eq!(unsafe { lance_dataset_version(checked_tag) }, 1);
    assert_eq!(unsafe { lance_dataset_count_rows(checked_tag) }, 5);

    // The source handle still points at its original snapshot.
    assert_eq!(unsafe { lance_dataset_version(ds) }, 2);
    assert_eq!(unsafe { lance_dataset_count_rows(ds) }, 7);
    unsafe { lance_dataset_close(ds) };
    assert_eq!(unsafe { lance_dataset_count_rows(checked_tag) }, 5);

    let unknown_tag = unsafe { lance_ref_tag(c_str("missing-tag").as_ptr()) };
    assert!(!unknown_tag.is_null());
    let missing = unsafe { lance_dataset_checkout_ref(checked_tag, unknown_tag) };
    assert!(missing.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::NotFound);

    let invalid_branch = unsafe { lance_ref_version(c_str("bad branch").as_ptr(), true, 1) };
    let invalid = unsafe { lance_dataset_checkout_ref(checked_tag, invalid_branch) };
    assert!(invalid.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);

    unsafe {
        lance_ref_close(invalid_branch);
        lance_ref_close(unknown_tag);
        lance_dataset_close(checked_tag);
        lance_dataset_close(checked_main);
        lance_dataset_close(checked_latest);
        lance_dataset_close(checked_v1);
        lance_ref_close(tag);
        lance_ref_close(main_branch_version);
        lance_ref_close(latest);
        lance_ref_close(version_number);
    }
}

#[test]
fn test_version_snapshots_preserve_out_of_range_timestamps() {
    let (_tmp, uri) = create_two_version_dataset();
    let future = chrono::DateTime::parse_from_rfc3339("2263-01-01T00:00:00.123456789Z")
        .unwrap()
        .with_timezone(&chrono::Utc);
    assert!(future.timestamp_nanos_opt().is_none());

    lance_c::runtime::block_on(async {
        let native = Dataset::open(&uri).await.unwrap();
        let mut manifest = native.manifest().clone();
        manifest.set_timestamp(
            future.timestamp() as u128 * 1_000_000_000
                + u128::from(future.timestamp_subsec_nanos()),
        );
        let (store, _) = lance_io::object_store::ObjectStore::from_uri(&uri)
            .await
            .unwrap();
        lance_table::io::commit::write_manifest_file_to_path(
            &store,
            &mut manifest,
            None,
            &native.manifest_location().path,
            None,
        )
        .await
        .unwrap();
        let reopened = Dataset::open(&uri).await.unwrap();
        assert_eq!(reopened.version().timestamp, future);
        assert_eq!(reopened.count_rows(None).await.unwrap(), 7);
    });

    let ds = unsafe { lance_dataset_open(c_str(&uri).as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());
    let versions = unsafe { lance_dataset_versions(ds) };
    assert!(
        !versions.is_null(),
        "native-valid timestamps must remain listable"
    );
    assert_eq!(unsafe { lance_versions_count(versions) }, 2);
    assert_eq!(unsafe { lance_versions_id_at(versions, 1) }, 2);
    assert_eq!(
        unsafe { lance_versions_timestamp_ms_at(versions, 1) },
        future.timestamp_millis()
    );
    let current = unsafe { lance_dataset_current_version(ds) };
    assert!(!current.is_null());
    unsafe { lance_dataset_close(ds) };

    let listed = unsafe { lance_versions_at(versions, 1) };
    for snapshot in [current.cast_const(), listed] {
        assert!(!snapshot.is_null());
        assert_eq!(unsafe { lance_version_timestamp_ns(snapshot) }, 0);
        assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
        assert_eq!(unsafe { lance_version_id(snapshot) }, 2);
        assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
        assert_eq!(version_metadata(snapshot).get("total_rows").unwrap(), "7");
    }
    assert_eq!(
        unsafe { lance_versions_timestamp_ms_at(versions, 1) },
        future.timestamp_millis()
    );
    unsafe {
        lance_version_close(current);
        lance_versions_close(versions);
    }
}

#[test]
fn test_tag_snapshots_preserve_out_of_range_timestamps() {
    let (_tmp, uri) = create_two_version_dataset();
    let tag_dir = std::path::Path::new(&uri).join("_refs/tags");
    std::fs::create_dir_all(&tag_dir).unwrap();
    std::fs::write(
        tag_dir.join("wide-time.json"),
        r#"{"branch":null,"version":2,"manifestSize":123,"createdAt":"2263-01-01T00:00:00.123456789Z","updatedAt":"1600-01-01T00:00:00Z","metadata":{"purpose":"time-range"}}"#,
    )
    .unwrap();
    lance_c::runtime::block_on(async {
        let native = Dataset::open(&uri).await.unwrap();
        let tag = native.tags().get("wide-time").await.unwrap();
        assert!(tag.created_at.unwrap().timestamp_nanos_opt().is_none());
        assert!(tag.updated_at.unwrap().timestamp_nanos_opt().is_none());
    });

    let ds = unsafe { lance_dataset_open(c_str(&uri).as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());
    let tags = unsafe { lance_dataset_tags(ds) };
    assert!(!tags.is_null());
    assert_eq!(unsafe { lance_tags_count(tags) }, 1);
    let tag = unsafe { lance_dataset_tag_get(ds, c_str("wide-time").as_ptr()) };
    assert!(!tag.is_null());
    unsafe { lance_dataset_close(ds) };

    let listed = unsafe { lance_tags_at(tags, 0) };
    for snapshot in [tag.cast_const(), listed] {
        assert!(!snapshot.is_null());
        let mut timestamp = 77;
        assert_eq!(
            unsafe { lance_tag_created_at_ns(snapshot, &mut timestamp) },
            -1
        );
        assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
        assert_eq!(timestamp, 77);
        assert_eq!(
            unsafe { lance_tag_updated_at_ns(snapshot, &mut timestamp) },
            -1
        );
        assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
        assert_eq!(timestamp, 77);
        assert_eq!(unsafe { lance_tag_version(snapshot) }, 2);
        assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
        assert_eq!(unsafe { lance_tag_metadata_count(snapshot) }, 1);
    }
    unsafe {
        lance_tag_close(tag);
        lance_tags_close(tags);
    }
}

#[test]
fn test_tag_lifecycle_metadata_conflicts_and_persistence() {
    let (_tmp, uri) = create_two_version_dataset();
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let version1 = unsafe { lance_ref_version_number(1) };
    let name = c_str("release-1");
    assert_eq!(
        unsafe { lance_dataset_tag_create(ds, name.as_ptr(), version1) },
        0
    );
    unsafe { lance_ref_close(version1) };

    let tag = unsafe { lance_dataset_tag_get(ds, name.as_ptr()) };
    assert!(!tag.is_null());
    assert_eq!(tag_name(tag), "release-1");
    assert_eq!(unsafe { lance_tag_version(tag) }, 1);
    let mut branch = std::ptr::null();
    assert_eq!(unsafe { lance_tag_branch(tag, &mut branch) }, 0);
    assert!(branch.is_null());
    assert_eq!(unsafe { lance_tag_metadata_count(tag) }, 0);
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);

    let mut created_at = 0;
    let mut updated_at = 0;
    assert_eq!(unsafe { lance_tag_created_at_ns(tag, &mut created_at) }, 1);
    assert_eq!(unsafe { lance_tag_updated_at_ns(tag, &mut updated_at) }, 1);
    let native = lance_c::runtime::block_on(Dataset::open(&uri)).unwrap();
    let native_tags = native.tags();
    let native_tag = lance_c::runtime::block_on(native_tags.get("release-1")).unwrap();
    assert_eq!(
        unsafe { lance_tag_manifest_size(tag) },
        native_tag.manifest_size as u64
    );
    assert_eq!(
        created_at,
        native_tag
            .created_at
            .unwrap()
            .timestamp_nanos_opt()
            .unwrap()
    );
    assert_eq!(
        updated_at,
        native_tag
            .updated_at
            .unwrap()
            .timestamp_nanos_opt()
            .unwrap()
    );

    let duplicate = unsafe { lance_ref_version_number(2) };
    assert_eq!(
        unsafe { lance_dataset_tag_create(ds, name.as_ptr(), duplicate) },
        -1,
        "native duplicate detection must reject an existing tag"
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::CommitConflict);
    unsafe { lance_ref_close(duplicate) };

    let tags = unsafe { lance_dataset_tags(ds) };
    assert!(!tags.is_null());
    assert_eq!(unsafe { lance_tags_count(tags) }, 1);
    assert_eq!(tag_name(unsafe { lance_tags_at(tags, 0) }), "release-1");

    let tag_ref = unsafe { lance_ref_tag(name.as_ptr()) };
    assert!(!tag_ref.is_null());
    let old_checkout = unsafe { lance_dataset_checkout_ref(ds, tag_ref) };
    assert!(!old_checkout.is_null());
    assert_eq!(unsafe { lance_dataset_version(old_checkout) }, 1);

    // Keep the CStrings alive through the call.
    let owner_key = c_str("owner");
    let owner_value = c_str("lance-c");
    let empty_key = c_str("empty");
    let empty_value = c_str("");
    let metadata = [
        owner_key.as_ptr(),
        owner_value.as_ptr(),
        empty_key.as_ptr(),
        empty_value.as_ptr(),
        ptr::null(),
    ];
    assert_eq!(
        unsafe { lance_dataset_tag_replace_metadata(ds, name.as_ptr(), metadata.as_ptr()) },
        0,
        "metadata must include empty values"
    );
    unsafe { lance_dataset_close(ds) };
    assert_eq!(
        unsafe { lance_tags_count(tags) },
        1,
        "tag snapshots own their copied contents"
    );

    // The pre-update checkout retains its manifest after the tag and source
    // handle move on.
    assert_eq!(unsafe { lance_dataset_version(old_checkout) }, 1);
    assert_eq!(unsafe { lance_dataset_count_rows(old_checkout) }, 5);

    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());
    let persisted = unsafe { lance_dataset_tag_get(ds, name.as_ptr()) };
    assert!(!persisted.is_null());
    let persisted_metadata = tag_metadata(persisted);
    assert_eq!(persisted_metadata.get("owner").unwrap(), "lance-c");
    assert_eq!(persisted_metadata.get("empty").unwrap(), "");
    unsafe { lance_tag_close(persisted) };

    let version2 = unsafe { lance_ref_version_number(2) };
    assert_eq!(
        unsafe { lance_dataset_tag_update(ds, name.as_ptr(), version2) },
        0
    );
    unsafe { lance_ref_close(version2) };

    let updated = unsafe { lance_dataset_tag_get(ds, name.as_ptr()) };
    assert!(!updated.is_null());
    assert_eq!(unsafe { lance_tag_version(updated) }, 2);
    let native_updated = lance_c::runtime::block_on(native_tags.get("release-1")).unwrap();
    assert_eq!(
        unsafe { lance_tag_manifest_size(updated) },
        native_updated.manifest_size as u64
    );
    assert_eq!(tag_metadata(updated), persisted_metadata);
    let mut updated_created = 0;
    let mut updated_at_after_update = 0;
    assert_eq!(
        unsafe { lance_tag_created_at_ns(updated, &mut updated_created) },
        1
    );
    assert_eq!(
        unsafe { lance_tag_updated_at_ns(updated, &mut updated_at_after_update) },
        1
    );
    assert_eq!(updated_created, created_at);
    assert!(updated_at_after_update >= created_at);

    assert_eq!(unsafe { lance_dataset_version(old_checkout) }, 1);
    let new_checkout = unsafe { lance_dataset_checkout_ref(ds, tag_ref) };
    assert!(!new_checkout.is_null());
    assert_eq!(unsafe { lance_dataset_version(new_checkout) }, 2);
    assert_eq!(unsafe { lance_dataset_count_rows(new_checkout) }, 7);

    let alias_name = c_str("release-alias");
    let alias_ref = unsafe { lance_ref_tag(name.as_ptr()) };
    assert_eq!(
        unsafe { lance_dataset_tag_create(ds, alias_name.as_ptr(), alias_ref) },
        0
    );
    let alias = unsafe { lance_dataset_tag_get(ds, alias_name.as_ptr()) };
    assert!(!alias.is_null());
    assert_eq!(unsafe { lance_tag_version(alias) }, 2);
    unsafe { lance_tag_close(alias) };
    assert_eq!(unsafe { lance_tags_count(tags) }, 1);
    let tags_after_alias = unsafe { lance_dataset_tags(ds) };
    assert_eq!(unsafe { lance_tags_count(tags_after_alias) }, 2);
    assert!(!find_tag(tags_after_alias, "release-alias").is_null());

    assert_eq!(
        unsafe { lance_dataset_tag_delete(ds, alias_name.as_ptr()) },
        0
    );
    let deleted = unsafe { lance_dataset_tag_get(ds, alias_name.as_ptr()) };
    assert!(deleted.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::NotFound);
    assert_eq!(
        unsafe { lance_dataset_tag_delete(ds, alias_name.as_ptr()) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::NotFound);

    // NULL metadata means the native empty map, replacing prior entries.
    assert_eq!(
        unsafe { lance_dataset_tag_replace_metadata(ds, name.as_ptr(), ptr::null()) },
        0
    );
    let empty = unsafe { lance_dataset_tag_get(ds, name.as_ptr()) };
    assert!(!empty.is_null());
    assert_eq!(unsafe { lance_tag_metadata_count(empty) }, 0);
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
    unsafe { lance_tag_close(empty) };

    let invalid_name = c_str("bad/tag");
    let version1 = unsafe { lance_ref_version_number(1) };
    assert_eq!(
        unsafe { lance_dataset_tag_create(ds, invalid_name.as_ptr(), version1) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    unsafe { lance_ref_close(version1) };

    let odd_key = c_str("key");
    let odd_metadata = [odd_key.as_ptr(), ptr::null()];
    assert_eq!(
        unsafe { lance_dataset_tag_replace_metadata(ds, name.as_ptr(), odd_metadata.as_ptr()) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);

    unsafe {
        lance_tags_close(tags_after_alias);
        lance_tags_close(tags);
        lance_dataset_close(new_checkout);
        lance_dataset_close(old_checkout);
        lance_ref_close(tag_ref);
        lance_dataset_close(ds);
        lance_tag_close(updated);
        lance_tag_close(tag);
    }
}

#[test]
fn test_tag_optional_fields_match_native_defaults() {
    let (_tmp, uri) = create_two_version_dataset();
    let tag_dir = std::path::Path::new(&uri).join("_refs/tags");
    std::fs::create_dir_all(&tag_dir).unwrap();
    std::fs::write(
        tag_dir.join("legacy.json"),
        "{\"branch\":null,\"version\":1,\"manifestSize\":123}",
    )
    .unwrap();
    std::fs::write(
        tag_dir.join("branch-bound.json"),
        "{\"branch\":\"feature\",\"version\":1,\"manifestSize\":123,\"metadata\":{}}",
    )
    .unwrap();

    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());
    let tag = unsafe { lance_dataset_tag_get(ds, c_str("legacy").as_ptr()) };
    assert!(!tag.is_null());
    assert_eq!(unsafe { lance_tag_metadata_count(tag) }, 0);
    let mut created_at = 0;
    let mut updated_at = 0;
    assert_eq!(unsafe { lance_tag_created_at_ns(tag, &mut created_at) }, 0);
    assert_eq!(unsafe { lance_tag_updated_at_ns(tag, &mut updated_at) }, 0);
    let mut branch = std::ptr::null();
    assert_eq!(unsafe { lance_tag_branch(tag, &mut branch) }, 0);
    assert!(branch.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
    unsafe { lance_tag_close(tag) };

    let branch_tag = unsafe { lance_dataset_tag_get(ds, c_str("branch-bound").as_ptr()) };
    assert!(!branch_tag.is_null());
    let mut branch: *const c_char = std::ptr::null();
    assert_eq!(
        unsafe { lance_tag_branch(branch_tag, &mut branch) },
        1,
        "an explicit native branch must remain present"
    );
    assert!(!branch.is_null());
    assert_eq!(
        unsafe { std::ffi::CStr::from_ptr(branch) }
            .to_str()
            .unwrap(),
        "feature"
    );
    assert_eq!(unsafe { lance_tag_metadata_count(branch_tag) }, 0);

    // An explicitly empty map is observationally identical to the missing
    // field, matching native TagContents deserialization.
    assert_eq!(
        unsafe { lance_dataset_tag_replace_metadata(ds, c_str("legacy").as_ptr(), ptr::null()) },
        0
    );
    let tag = unsafe { lance_dataset_tag_get(ds, c_str("legacy").as_ptr()) };
    assert!(!tag.is_null());
    assert_eq!(unsafe { lance_tag_metadata_count(tag) }, 0);
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
    unsafe {
        lance_tag_close(branch_tag);
        lance_tag_close(tag);
        lance_dataset_close(ds);
    }
}

#[test]
fn test_branch_create_ref_variants_checkout_and_json() {
    let (_tmp, uri) = create_two_version_dataset();
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());
    assert_eq!(unsafe { lance_dataset_version(ds) }, 2);
    assert_eq!(unsafe { lance_dataset_count_rows(ds) }, 7);

    let main_identifier = owned_json(unsafe { lance_dataset_branch_identifier_json(ds) });
    assert_eq!(main_identifier, serde_json::json!({"version_mapping": []}));
    let initially_empty = owned_json(unsafe { lance_dataset_branches_json(ds) });
    assert_eq!(initially_empty, serde_json::json!({}));

    let tag_name = c_str("branch-source");
    let tag_source = unsafe { lance_ref_version_number(1) };
    assert_eq!(
        unsafe { lance_dataset_tag_create(ds, tag_name.as_ptr(), tag_source) },
        0
    );
    unsafe {
        lance_ref_close(tag_source);
    }

    let parent_name = c_str("feature/parent");
    let parent_ref = unsafe { lance_ref_version_number(1) };
    let parent =
        unsafe { lance_dataset_branch_create(ds, parent_name.as_ptr(), parent_ref, ptr::null()) };
    assert!(!parent.is_null());
    assert_eq!(unsafe { lance_dataset_version(parent) }, 1);
    assert_eq!(unsafe { lance_dataset_count_rows(parent) }, 5);
    unsafe {
        lance_ref_close(parent_ref);
    }

    let child_name = c_str("feature/parent/child");
    let child_ref = unsafe { lance_ref_version_number(1) };
    let child =
        unsafe { lance_dataset_branch_create(parent, child_name.as_ptr(), child_ref, ptr::null()) };
    assert!(!child.is_null());
    assert_eq!(unsafe { lance_dataset_version(child) }, 1);
    assert_eq!(unsafe { lance_dataset_count_rows(child) }, 5);
    unsafe {
        lance_ref_close(child_ref);
    }

    let from_tag_name = c_str("from-tag");
    let tag_ref = unsafe { lance_ref_tag(tag_name.as_ptr()) };
    let from_tag =
        unsafe { lance_dataset_branch_create(ds, from_tag_name.as_ptr(), tag_ref, ptr::null()) };
    assert!(!from_tag.is_null());
    assert_eq!(unsafe { lance_dataset_count_rows(from_tag) }, 5);

    let from_branch_name = c_str("from-branch");
    let branch_ref = unsafe { lance_ref_version(parent_name.as_ptr(), true, 1) };
    let from_branch = unsafe {
        lance_dataset_branch_create(ds, from_branch_name.as_ptr(), branch_ref, ptr::null())
    };
    assert!(!from_branch.is_null());
    assert_eq!(unsafe { lance_dataset_count_rows(from_branch) }, 5);

    let latest_name = c_str("latest-copy");
    let latest_ref = unsafe { lance_ref_version(ptr::null(), false, 0) };
    let latest =
        unsafe { lance_dataset_branch_create(ds, latest_name.as_ptr(), latest_ref, ptr::null()) };
    assert!(!latest.is_null());
    assert_eq!(unsafe { lance_dataset_version(latest) }, 2);
    assert_eq!(unsafe { lance_dataset_count_rows(latest) }, 7);
    assert_eq!(unsafe { lance_dataset_version(ds) }, 2);
    assert_eq!(unsafe { lance_dataset_count_rows(ds) }, 7);

    let native_parent = native_branch(&uri, "feature/parent");
    let parent_json =
        owned_json(unsafe { lance_dataset_branch_get_json(ds, parent_name.as_ptr()) });
    assert_branch_json(&parent_json, &native_parent);
    assert_eq!(parent_json["parentBranch"], serde_json::Value::Null);
    assert_eq!(parent_json["parentVersion"], 1);

    let tag_json = owned_json(unsafe { lance_dataset_branch_get_json(ds, from_tag_name.as_ptr()) });
    assert_branch_json(&tag_json, &native_branch(&uri, "from-tag"));
    assert_eq!(tag_json["parentBranch"], serde_json::Value::Null);
    assert_eq!(tag_json["parentVersion"], 1);

    let branch_json =
        owned_json(unsafe { lance_dataset_branch_get_json(ds, from_branch_name.as_ptr()) });
    assert_branch_json(&branch_json, &native_branch(&uri, "from-branch"));
    assert_eq!(branch_json["parentBranch"], "feature/parent");
    assert_eq!(branch_json["parentVersion"], 1);

    let child_identifier = owned_json(unsafe { lance_dataset_branch_identifier_json(child) });
    let native_child_identifier = lance_c::runtime::block_on(async {
        Dataset::open(&uri)
            .await
            .unwrap()
            .checkout_branch("feature/parent/child")
            .await
            .unwrap()
            .branch_identifier()
            .await
            .unwrap()
    });
    assert_eq!(
        child_identifier["version_mapping"]
            .as_array()
            .unwrap()
            .len(),
        native_child_identifier.version_mapping.len()
    );

    let native_branches = lance_c::runtime::block_on(async {
        Dataset::open(&uri)
            .await
            .unwrap()
            .list_branches()
            .await
            .unwrap()
    });
    let branches_json = owned_json(unsafe { lance_dataset_branches_json(ds) });
    let branches = branches_json.as_object().unwrap();
    assert_eq!(branches.len(), native_branches.len());
    for (name, contents) in &native_branches {
        assert_branch_json(&branches[name], contents);
    }

    let main_checkout = unsafe { lance_dataset_checkout_branch(ds, c_str("main").as_ptr()) };
    let parent_checkout = unsafe { lance_dataset_checkout_branch(ds, parent_name.as_ptr()) };
    assert!(!main_checkout.is_null());
    assert!(!parent_checkout.is_null());
    assert_eq!(unsafe { lance_dataset_version(main_checkout) }, 2);
    assert_eq!(unsafe { lance_dataset_count_rows(main_checkout) }, 7);
    assert_eq!(unsafe { lance_dataset_version(parent_checkout) }, 1);
    assert_eq!(unsafe { lance_dataset_count_rows(parent_checkout) }, 5);

    let reserved_ref = unsafe { lance_ref_version(c_str("main").as_ptr(), true, 1) };
    let reserved = unsafe {
        lance_dataset_branch_create(ds, c_str("main").as_ptr(), reserved_ref, ptr::null())
    };
    assert!(reserved.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    unsafe {
        lance_ref_close(reserved_ref);
    }

    // Owned JSON survives closing the source; checkout and branch handles keep
    // their own native snapshots.
    let branches_after_close_ptr = unsafe { lance_dataset_branches_json(ds) };
    let parent_after_close_ptr = unsafe { lance_dataset_branch_get_json(ds, parent_name.as_ptr()) };
    let identifier_after_close_ptr = unsafe { lance_dataset_branch_identifier_json(parent) };
    unsafe {
        lance_dataset_close(ds);
    }
    let branches_after_close = owned_json(branches_after_close_ptr);
    assert_eq!(branches_after_close.as_object().unwrap().len(), 5);
    assert_branch_json(
        &owned_json(parent_after_close_ptr),
        &native_branch(&uri, "feature/parent"),
    );
    let branch_identifier = owned_json(identifier_after_close_ptr);
    assert_eq!(
        branch_identifier["version_mapping"]
            .as_array()
            .unwrap()
            .len(),
        native_parent.identifier.version_mapping.len()
    );
    assert_eq!(unsafe { lance_dataset_count_rows(main_checkout) }, 7);
    assert_eq!(unsafe { lance_dataset_count_rows(parent) }, 5);

    unsafe {
        lance_dataset_close(from_tag);
        lance_dataset_close(from_branch);
        lance_dataset_close(latest);
        lance_dataset_close(child);
        lance_dataset_close(parent);
        lance_dataset_close(parent_checkout);
        lance_dataset_close(main_checkout);
        lance_ref_close(branch_ref);
        lance_ref_close(latest_ref);
        lance_ref_close(tag_ref);
    }

    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());
    for name in [
        "feature/parent/child",
        "from-branch",
        "feature/parent",
        "from-tag",
        "latest-copy",
    ] {
        let name = c_str(name);
        assert_eq!(
            unsafe { lance_dataset_branch_delete(ds, name.as_ptr()) },
            0,
            "delete branch {name:?}"
        );
    }
    assert_eq!(
        unsafe { lance_dataset_tag_delete(ds, tag_name.as_ptr()) },
        0
    );
    let remaining = owned_json(unsafe { lance_dataset_branches_json(ds) });
    assert_eq!(remaining, serde_json::json!({}));
    unsafe {
        lance_dataset_close(ds);
    }
}

#[test]
fn test_branch_metadata_full_replace_persistence_and_options() {
    let (_tmp, uri) = create_two_version_dataset();
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let latest_ref = unsafe { lance_ref_version(ptr::null(), false, 0) };
    let meta_name = c_str("meta");
    let meta =
        unsafe { lance_dataset_branch_create(ds, meta_name.as_ptr(), latest_ref, ptr::null()) };
    assert!(!meta.is_null());
    assert_eq!(unsafe { lance_dataset_count_rows(meta) }, 7);

    let empty_storage = [ptr::null::<c_char>()];
    let options_ref = unsafe { lance_ref_version_number(2) };
    let options_name = c_str("explicit-empty-options");
    let options = unsafe {
        lance_dataset_branch_create(
            ds,
            options_name.as_ptr(),
            options_ref,
            empty_storage.as_ptr(),
        )
    };
    assert!(!options.is_null());
    assert_eq!(unsafe { lance_dataset_count_rows(options) }, 7);

    let owner_key = c_str("owner");
    let owner_value = c_str("lance-c");
    let empty_key = c_str("empty");
    let empty_value = c_str("");
    let metadata = [
        owner_key.as_ptr(),
        owner_value.as_ptr(),
        empty_key.as_ptr(),
        empty_value.as_ptr(),
        ptr::null(),
    ];
    assert_eq!(
        unsafe { lance_dataset_branch_replace_metadata(ds, meta_name.as_ptr(), metadata.as_ptr()) },
        0
    );

    let meta_json = owned_json(unsafe { lance_dataset_branch_get_json(ds, meta_name.as_ptr()) });
    let native_meta = native_branch(&uri, "meta");
    assert_branch_json(&meta_json, &native_meta);
    assert_eq!(meta_json["metadata"]["owner"], "lance-c");
    assert_eq!(meta_json["metadata"]["empty"], "");

    unsafe {
        lance_dataset_close(ds);
        lance_dataset_close(meta);
        lance_dataset_close(options);
        lance_ref_close(latest_ref);
        lance_ref_close(options_ref);
    }

    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());
    let persisted = owned_json(unsafe { lance_dataset_branch_get_json(ds, meta_name.as_ptr()) });
    assert_eq!(persisted["metadata"]["owner"], "lance-c");
    assert_eq!(persisted["metadata"]["empty"], "");

    // Explicitly empty metadata is a full replacement, not a special delete.
    let empty_metadata = [ptr::null::<c_char>()];
    assert_eq!(
        unsafe {
            lance_dataset_branch_replace_metadata(ds, meta_name.as_ptr(), empty_metadata.as_ptr())
        },
        0
    );
    let odd_key = c_str("key");
    let odd_metadata = [odd_key.as_ptr(), ptr::null()];
    assert_eq!(
        unsafe {
            lance_dataset_branch_replace_metadata(ds, meta_name.as_ptr(), odd_metadata.as_ptr())
        },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert_eq!(
        unsafe {
            lance_dataset_branch_replace_metadata(ds, c_str("missing").as_ptr(), ptr::null())
        },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::NotFound);

    let duplicate_ref = unsafe { lance_ref_version_number(2) };
    let duplicate =
        unsafe { lance_dataset_branch_create(ds, meta_name.as_ptr(), duplicate_ref, ptr::null()) };
    assert!(duplicate.is_null());
    // The selected core rejects a reused branch name in its shallow-clone
    // phase before BranchContents conflict detection.
    assert_ne!(
        lance_last_error_code(),
        LanceErrorCode::Ok,
        "{}",
        take_last_error_message()
    );
    unsafe {
        lance_ref_close(duplicate_ref);
    }
    let after_duplicate =
        owned_json(unsafe { lance_dataset_branch_get_json(ds, meta_name.as_ptr()) });
    assert_eq!(after_duplicate["parentVersion"], 2);
    assert_eq!(after_duplicate["metadata"], serde_json::json!({}));

    assert_eq!(
        unsafe { lance_dataset_branch_delete(ds, options_name.as_ptr()) },
        0
    );
    assert_eq!(
        unsafe { lance_dataset_branch_delete(ds, meta_name.as_ptr()) },
        0
    );
    unsafe {
        lance_dataset_close(ds);
    }
}

#[test]
fn test_branch_deletion_protections_and_zombie_recovery() {
    let (_tmp, uri) = create_two_version_dataset();
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let parent_name = c_str("protected");
    let parent_ref = unsafe { lance_ref_version_number(1) };
    let parent =
        unsafe { lance_dataset_branch_create(ds, parent_name.as_ptr(), parent_ref, ptr::null()) };
    assert!(!parent.is_null());
    let child_name = c_str("protected/child");
    let child_ref = unsafe { lance_ref_version_number(1) };
    let child =
        unsafe { lance_dataset_branch_create(parent, child_name.as_ptr(), child_ref, ptr::null()) };
    assert!(!child.is_null());

    assert_eq!(
        unsafe { lance_dataset_branch_delete(ds, parent_name.as_ptr()) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::CommitConflict);
    unsafe {
        lance_dataset_close(child);
        lance_ref_close(child_ref);
    }
    assert_eq!(
        unsafe { lance_dataset_branch_delete(ds, child_name.as_ptr()) },
        0
    );
    assert_eq!(
        unsafe { lance_dataset_branch_delete(ds, parent_name.as_ptr()) },
        0
    );

    let tagged_name = c_str("tagged");
    let tagged_ref = unsafe { lance_ref_version_number(1) };
    let tagged =
        unsafe { lance_dataset_branch_create(ds, tagged_name.as_ptr(), tagged_ref, ptr::null()) };
    assert!(!tagged.is_null());
    let tag_name = c_str("branch-tag");
    let tag_target = unsafe { lance_ref_version(tagged_name.as_ptr(), true, 1) };
    assert_eq!(
        unsafe { lance_dataset_tag_create(ds, tag_name.as_ptr(), tag_target) },
        0
    );
    assert_eq!(
        unsafe { lance_dataset_branch_delete(ds, tagged_name.as_ptr()) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::CommitConflict);
    assert_eq!(
        unsafe { lance_dataset_tag_delete(ds, tag_name.as_ptr()) },
        0
    );
    assert_eq!(
        unsafe { lance_dataset_branch_delete(ds, tagged_name.as_ptr()) },
        0
    );

    let zombie_ref = unsafe { lance_ref_version_number(1) };
    let zombie_name = c_str("zombie");
    let zombie =
        unsafe { lance_dataset_branch_create(ds, zombie_name.as_ptr(), zombie_ref, ptr::null()) };
    assert!(!zombie.is_null());
    unsafe {
        lance_dataset_close(zombie);
        lance_ref_close(zombie_ref);
    }
    let zombie_contents = std::path::Path::new(&uri).join("_refs/branches/zombie.json");
    assert!(zombie_contents.exists());
    std::fs::remove_file(&zombie_contents).unwrap();
    assert_eq!(
        unsafe { lance_dataset_branch_delete(ds, zombie_name.as_ptr()) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::NotFound);
    assert_eq!(
        unsafe { lance_dataset_branch_force_delete(ds, zombie_name.as_ptr()) },
        0
    );
    assert!(!std::path::Path::new(&uri).join("tree/zombie").exists());
    let branches = owned_json(unsafe { lance_dataset_branches_json(ds) });
    assert!(branches.get("zombie").is_none());

    unsafe {
        lance_dataset_close(tagged);
        lance_dataset_close(parent);
        lance_ref_close(tag_target);
        lance_ref_close(tagged_ref);
        lance_ref_close(parent_ref);
        lance_dataset_close(ds);
    }
}

#[test]
fn test_branch_concurrent_fixed_ref_and_commit() {
    let (_tmp, uri) = create_two_version_dataset();
    let barrier = Arc::new(Barrier::new(3));

    let branch_uri = uri.clone();
    let branch_barrier = Arc::clone(&barrier);
    let branch_thread = std::thread::spawn(move || {
        branch_barrier.wait();
        let c_uri = c_str(&branch_uri);
        let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
        assert!(!ds.is_null());

        let reference = unsafe { lance_ref_version(ptr::null(), true, 2) };
        let name = c_str("concurrent/from-v2");
        let branch =
            unsafe { lance_dataset_branch_create(ds, name.as_ptr(), reference, ptr::null()) };
        assert!(!branch.is_null());
        let result = (unsafe { lance_dataset_version(branch) }, unsafe {
            lance_dataset_count_rows(branch)
        });
        unsafe {
            lance_dataset_close(branch);
            lance_ref_close(reference);
            lance_dataset_close(ds);
        }
        result
    });

    let commit_uri = uri.clone();
    let commit_barrier = Arc::clone(&barrier);
    let commit_thread = std::thread::spawn(move || {
        commit_barrier.wait();
        let c_uri = c_str(&commit_uri);
        let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
        assert!(!ds.is_null());

        let predicate = c_str("id = 1");
        let mut deleted = 0;
        let rc = unsafe { lance_dataset_delete(ds, predicate.as_ptr(), &mut deleted) };
        unsafe {
            lance_dataset_close(ds);
        }
        (rc, deleted)
    });

    barrier.wait();
    let (branch_version, branch_rows) = branch_thread.join().unwrap();
    let (delete_rc, deleted) = commit_thread.join().unwrap();
    assert_eq!(delete_rc, 0);
    assert_eq!(deleted, 1);

    // An explicit ref version is a stable snapshot: the concurrent main
    // commit changes main, not the branch source.
    assert_eq!(branch_version, 2);
    assert_eq!(branch_rows, 7);
    let contents = native_branch(&uri, "concurrent/from-v2");
    assert_eq!(contents.parent_branch, None);
    assert_eq!(contents.parent_version, 2);

    let (main_version, main_rows) = lance_c::runtime::block_on(async {
        let main = Dataset::open(&uri).await.unwrap();
        (main.version().version, main.count_rows(None).await.unwrap())
    });
    assert_eq!(main_version, 3);
    assert_eq!(main_rows, 6);

    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());
    assert_eq!(
        unsafe { lance_dataset_branch_delete(ds, c_str("concurrent/from-v2").as_ptr(),) },
        0
    );
    unsafe {
        lance_dataset_close(ds);
    }
}

#[test]
fn test_branch_invalid_inputs_and_missing_references() {
    let (_tmp, uri) = create_two_version_dataset();
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let version1 = unsafe { lance_ref_version_number(1) };
    for name in ["main", "", "feature//child", "bad name", "a/../b"] {
        let name = c_str(name);
        let branch =
            unsafe { lance_dataset_branch_create(ds, name.as_ptr(), version1, ptr::null()) };
        assert!(branch.is_null(), "invalid branch name {name:?}");
        assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    }

    let missing_version = unsafe { lance_ref_version_number(99) };
    let missing_branch = unsafe {
        lance_dataset_branch_create(
            ds,
            c_str("missing-version").as_ptr(),
            missing_version,
            ptr::null(),
        )
    };
    assert!(missing_branch.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::NotFound);
    unsafe {
        lance_ref_close(missing_version);
    }

    let missing_tag = unsafe { lance_ref_tag(c_str("missing-tag").as_ptr()) };
    let missing_tag_branch = unsafe {
        lance_dataset_branch_create(ds, c_str("missing-tag").as_ptr(), missing_tag, ptr::null())
    };
    assert!(missing_tag_branch.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::NotFound);
    unsafe {
        lance_ref_close(missing_tag);
    }

    let odd_key = c_str("key");
    let odd_storage = [odd_key.as_ptr(), ptr::null()];
    let odd_branch = unsafe {
        lance_dataset_branch_create(
            ds,
            c_str("odd-storage").as_ptr(),
            version1,
            odd_storage.as_ptr(),
        )
    };
    assert!(odd_branch.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);

    let invalid_utf8 = CString::new(vec![0xffu8]).unwrap();
    assert!(unsafe { lance_dataset_branch_get_json(ds, invalid_utf8.as_ptr()) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);

    assert!(unsafe { lance_dataset_branch_get_json(ds, c_str("missing").as_ptr()) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::NotFound);
    assert!(unsafe { lance_dataset_checkout_branch(ds, c_str("missing").as_ptr()) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::NotFound);
    assert_eq!(
        unsafe { lance_dataset_branch_delete(ds, c_str("missing").as_ptr()) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::NotFound);
    assert_eq!(
        unsafe { lance_dataset_branch_force_delete(ds, c_str("missing").as_ptr()) },
        0
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);

    assert!(
        unsafe {
            lance_dataset_branch_create(ptr::null(), c_str("x").as_ptr(), version1, ptr::null())
        }
        .is_null()
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(
        unsafe { lance_dataset_branch_create(ds, ptr::null(), version1, ptr::null()) }.is_null()
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(
        unsafe { lance_dataset_branch_create(ds, c_str("x").as_ptr(), ptr::null(), ptr::null()) }
            .is_null()
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(unsafe { lance_dataset_branches_json(ptr::null()) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(unsafe { lance_dataset_branch_identifier_json(ptr::null()) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(unsafe { lance_dataset_branch_get_json(ptr::null(), c_str("x").as_ptr()) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(unsafe { lance_dataset_branch_get_json(ds, ptr::null()) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(
        unsafe { lance_dataset_checkout_branch(ptr::null(), c_str("main").as_ptr()) }.is_null()
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(unsafe { lance_dataset_checkout_branch(ds, ptr::null()) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert_eq!(
        unsafe { lance_dataset_branch_delete(ptr::null(), c_str("x").as_ptr()) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert_eq!(
        unsafe { lance_dataset_branch_force_delete(ds, ptr::null()) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert_eq!(
        unsafe {
            lance_dataset_branch_replace_metadata(ptr::null(), c_str("x").as_ptr(), ptr::null())
        },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert_eq!(
        unsafe { lance_dataset_branch_replace_metadata(ds, ptr::null(), ptr::null()) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);

    unsafe {
        lance_ref_close(version1);
        lance_dataset_close(ds);
    }
}

#[test]
fn test_version_and_tag_null_bounds_and_lifetime_errors() {
    let current = unsafe { lance_dataset_current_version(ptr::null()) };
    assert!(current.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert_eq!(unsafe { lance_version_id(ptr::null()) }, 0);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert_eq!(unsafe { lance_version_timestamp_ns(ptr::null()) }, 0);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert_eq!(unsafe { lance_version_metadata_count(ptr::null()) }, 0);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(unsafe { lance_version_metadata_key_at(ptr::null(), 0) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(unsafe { lance_version_metadata_value_at(ptr::null(), 0) }.is_null());
    unsafe { lance_version_close(ptr::null_mut()) };

    assert!(unsafe { lance_dataset_version_refs(ptr::null()) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert_eq!(unsafe { lance_version_refs_count(ptr::null()) }, 0);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert_eq!(unsafe { lance_version_refs_id_at(ptr::null(), 0) }, 0);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    unsafe { lance_version_refs_close(ptr::null_mut()) };

    let no_branch = unsafe { lance_ref_version(ptr::null(), true, 1) };
    assert!(!no_branch.is_null());
    unsafe { lance_ref_close(no_branch) };
    assert!(unsafe { lance_ref_tag(ptr::null()) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    unsafe { lance_ref_close(ptr::null_mut()) };

    let (_tmp, uri) = create_two_version_dataset();
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());
    let version = unsafe { lance_ref_version_number(1) };
    assert!(!version.is_null());
    assert!(unsafe { lance_dataset_checkout_ref(ptr::null(), version) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(unsafe { lance_dataset_checkout_ref(ds, ptr::null()) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);

    let current = unsafe { lance_dataset_current_version(ds) };
    assert!(!current.is_null());
    let metadata_count = unsafe { lance_version_metadata_count(current) };
    assert!(metadata_count > 0);
    assert!(unsafe { lance_version_metadata_key_at(current, metadata_count as usize) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(unsafe { lance_version_metadata_value_at(current, metadata_count as usize) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);

    let versions = unsafe { lance_dataset_versions(ds) };
    assert!(!versions.is_null());
    let version_count = unsafe { lance_versions_count(versions) };
    assert!(unsafe { lance_versions_at(versions, version_count as usize) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let refs = unsafe { lance_dataset_version_refs(ds) };
    assert!(!refs.is_null());
    let refs_count = unsafe { lance_version_refs_count(refs) };
    assert_eq!(
        unsafe { lance_version_refs_id_at(refs, refs_count as usize) },
        0
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);

    assert!(unsafe { lance_dataset_tags(ptr::null()) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let tags = unsafe { lance_dataset_tags(ds) };
    assert!(!tags.is_null());
    let tag_count = unsafe { lance_tags_count(tags) };
    assert!(unsafe { lance_tags_at(tags, tag_count as usize) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);

    assert!(unsafe { lance_dataset_tag_get(ptr::null(), c_str("tag").as_ptr()) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(unsafe { lance_dataset_tag_get(ds, ptr::null()) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert_eq!(
        unsafe { lance_dataset_tag_create(ds, ptr::null(), version) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert_eq!(
        unsafe { lance_dataset_tag_create(ds, c_str("tag").as_ptr(), ptr::null()) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);

    assert!(unsafe { lance_tag_name(ptr::null()) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert_eq!(unsafe { lance_tag_version(ptr::null()) }, 0);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert_eq!(unsafe { lance_tag_manifest_size(ptr::null()) }, 0);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert_eq!(unsafe { lance_tag_metadata_count(ptr::null()) }, 0);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(unsafe { lance_tag_metadata_key_at(ptr::null(), 0) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(unsafe { lance_tag_metadata_value_at(ptr::null(), 0) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let mut branch: *const c_char = std::ptr::null();
    assert_eq!(unsafe { lance_tag_branch(ptr::null(), &mut branch) }, -1);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let mut timestamp = 0;
    assert_eq!(
        unsafe { lance_tag_created_at_ns(ptr::null(), &mut timestamp) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert_eq!(
        unsafe { lance_tag_updated_at_ns(ptr::null(), &mut timestamp) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    unsafe {
        lance_tag_close(ptr::null_mut());
        lance_tags_close(ptr::null_mut());
        lance_tags_close(tags);
        lance_version_refs_close(refs);
        lance_versions_close(versions);
        lance_version_close(current);
        lance_ref_close(version);
        lance_dataset_close(ds);
    }
}

// ---------------------------------------------------------------------------
// Data statistics (lance_dataset_calculate_data_stats)
// ---------------------------------------------------------------------------

/// Sum `bytes_on_disk` across every field in a statistics handle.
fn total_bytes_on_disk(stats: *const LanceDataStatistics) -> u64 {
    let count = unsafe { lance_data_statistics_count(stats) };
    (0..count)
        .map(|i| unsafe { lance_data_statistics_bytes_on_disk_at(stats, i as usize) })
        .sum()
}

/// Collect the field ids of a statistics handle in index order.
fn field_ids(stats: *const LanceDataStatistics) -> Vec<u32> {
    let count = unsafe { lance_data_statistics_count(stats) };
    (0..count)
        .map(|i| unsafe { lance_data_statistics_field_id_at(stats, i as usize) })
        .collect()
}

#[test]
fn test_data_statistics_single_fragment() {
    // create_test_dataset has two top-level fields (id=0, name=1) written with
    // the default (modern, v2+) storage format, so bytes_on_disk is populated.
    let (_tmp, uri) = create_test_dataset();
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };

    let stats = unsafe { lance_dataset_calculate_data_stats(ds) };
    assert!(!stats.is_null());
    assert_eq!(unsafe { lance_data_statistics_count(stats) }, 2);
    assert_eq!(field_ids(stats), vec![0, 1]);
    // Field id 0 is a legitimate value that collides with the error sentinel;
    // reading it on the success path must leave the error state clear so callers
    // can disambiguate a real 0 from an error via lance_last_error_code().
    assert_eq!(unsafe { lance_data_statistics_field_id_at(stats, 0) }, 0);
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
    assert!(
        total_bytes_on_disk(stats) > 0,
        "modern storage should report non-zero on-disk size"
    );

    unsafe { lance_data_statistics_close(stats) };
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_data_statistics_field_count_matches_schema() {
    // create_large_dataset has three fields (id, value, label).
    let (_tmp, uri) = create_large_dataset(50);
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };

    let stats = unsafe { lance_dataset_calculate_data_stats(ds) };
    assert!(!stats.is_null());
    assert_eq!(unsafe { lance_data_statistics_count(stats) }, 3);
    assert_eq!(field_ids(stats), vec![0, 1, 2]);
    // Every field carries data, so each reports a non-zero size.
    for i in 0..3 {
        assert!(
            unsafe { lance_data_statistics_bytes_on_disk_at(stats, i) } > 0,
            "field {i} should report non-zero on-disk size"
        );
    }

    unsafe { lance_data_statistics_close(stats) };
    unsafe { lance_dataset_close(ds) };
}

/// Write a single-fragment dataset with one Int32 `id` field holding `ids` and
/// return the on-disk byte size of that field.
fn single_fragment_id_field_bytes(ids: Vec<i32>) -> u64 {
    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp
        .path()
        .join("one_frag_stats_ds")
        .to_str()
        .unwrap()
        .to_string();
    let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int32, false)]));
    lance_c::runtime::block_on(async {
        let batch =
            RecordBatch::try_new(schema.clone(), vec![Arc::new(Int32Array::from(ids))]).unwrap();
        Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(batch)], schema.clone()),
            &uri,
            None,
        )
        .await
        .unwrap();
    });
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    let stats = unsafe { lance_dataset_calculate_data_stats(ds) };
    let bytes = unsafe { lance_data_statistics_bytes_on_disk_at(stats, 0) };
    unsafe { lance_data_statistics_close(stats) };
    unsafe { lance_dataset_close(ds) };
    bytes
}

#[test]
fn test_data_statistics_multi_fragment_sums_across_fragments() {
    // The two-fragment dataset's first fragment (ids 0..5) is identical to a
    // standalone single-fragment dataset of the same rows. If calculate_data_stats
    // counted only one fragment, the two byte totals would match; genuine
    // aggregation makes the two-fragment total strictly larger.
    let one_fragment_bytes = single_fragment_id_field_bytes(vec![0, 1, 2, 3, 4]);
    assert!(
        one_fragment_bytes > 0,
        "single fragment should report non-zero size"
    );

    let (_tmp, uri) = create_multi_fragment_dataset();
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };

    let stats = unsafe { lance_dataset_calculate_data_stats(ds) };
    assert!(!stats.is_null());
    assert_eq!(unsafe { lance_data_statistics_count(stats) }, 1);
    assert_eq!(field_ids(stats), vec![0]);

    let two_fragment_bytes = unsafe { lance_data_statistics_bytes_on_disk_at(stats, 0) };
    assert!(
        two_fragment_bytes > one_fragment_bytes,
        "two-fragment on-disk size ({two_fragment_bytes}) must exceed single-fragment \
         size ({one_fragment_bytes}); calculate_data_stats must sum across fragments"
    );

    unsafe { lance_data_statistics_close(stats) };
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_data_statistics_legacy_storage_reports_zero_bytes() {
    // The legacy (v1) file format does not track per-field on-disk sizes, so
    // upstream reports every field with bytes_on_disk == 0. The field list
    // itself is still fully populated.
    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp
        .path()
        .join("legacy_stats_ds")
        .to_str()
        .unwrap()
        .to_string();
    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new("name", DataType::Utf8, true),
    ]));
    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![
            Arc::new(Int32Array::from(vec![1, 2, 3])),
            Arc::new(StringArray::from(vec!["a", "b", "c"])),
        ],
    )
    .unwrap();
    lance_c::runtime::block_on(async {
        let params = lance::dataset::WriteParams {
            data_storage_version: Some(lance_file::version::LanceFileVersion::Legacy),
            ..Default::default()
        };
        Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(batch)], schema),
            &uri,
            Some(params),
        )
        .await
        .unwrap();
    });

    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    let stats = unsafe { lance_dataset_calculate_data_stats(ds) };
    assert!(!stats.is_null());

    assert_eq!(unsafe { lance_data_statistics_count(stats) }, 2);
    assert_eq!(field_ids(stats), vec![0, 1]);
    assert_eq!(
        total_bytes_on_disk(stats),
        0,
        "legacy storage does not track per-field on-disk size"
    );
    // The zeros above are genuine (legacy storage), not error sentinels: reading
    // an in-range field leaves the error clear, which is the documented way to
    // tell a real 0 from the out-of-range/NULL error sentinel.
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);

    unsafe { lance_data_statistics_close(stats) };
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_data_statistics_empty_schema_yields_zero_count_no_error() {
    // Lance permits a zero-field dataset. calculate_data_stats then returns a
    // valid (non-NULL) but empty snapshot: count 0 with NO error set. This is
    // exactly how a caller distinguishes it from the NULL-handle error, which
    // returns count 0 *with* InvalidArgument — the contract the count doc states.
    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp
        .path()
        .join("empty_schema_stats_ds")
        .to_str()
        .unwrap()
        .to_string();
    let schema = Arc::new(Schema::new(Vec::<Field>::new()));
    lance_c::runtime::block_on(async {
        let batch = RecordBatch::new_empty(schema.clone());
        Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(batch)], schema),
            &uri,
            None,
        )
        .await
        .unwrap();
    });

    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    let stats = unsafe { lance_dataset_calculate_data_stats(ds) };

    assert!(
        !stats.is_null(),
        "empty-schema dataset still yields a snapshot"
    );
    assert_eq!(unsafe { lance_data_statistics_count(stats) }, 0);
    assert_eq!(
        lance_last_error_code(),
        LanceErrorCode::Ok,
        "an empty snapshot must leave the error clear, unlike the NULL-handle case"
    );
    assert!(field_ids(stats).is_empty());

    unsafe { lance_data_statistics_close(stats) };
    unsafe { lance_dataset_close(ds) };
}

