#[test]
fn test_index_segment_metadata_parse_rejects_malformed_and_dangerous_input() {
    use prost::Message;

    let sentinel = std::ptr::dangling_mut::<LanceIndexSegmentMetadata>();
    let mut metadata = sentinel;
    assert_eq!(
        unsafe { lance_index_segment_metadata_parse(ptr::null(), 0, &mut metadata) },
        -1
    );
    assert_eq!(metadata, sentinel);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);

    let malformed = [0xff_u8, 0xff, 0xff];
    assert_eq!(
        unsafe {
            lance_index_segment_metadata_parse(malformed.as_ptr(), malformed.len(), &mut metadata)
        },
        -1
    );
    assert_eq!(metadata, sentinel);

    let dangerous = lance_table::format::pb::IndexMetadata {
        uuid: Some(lance_table::format::pb::Uuid {
            uuid: vec![0_u8; 16],
        }),
        fields: vec![0],
        name: "dangerous_timestamp".to_string(),
        dataset_version: 1,
        fragment_bitmap: Vec::new(),
        index_details: None,
        index_version: Some(0),
        created_at: Some(u64::MAX),
        base_id: None,
        files: Vec::new(),
        covering_fields: Vec::new(),
        clustering_id: None,
        metadata: Default::default(),
    }
    .encode_to_vec();
    assert_eq!(
        unsafe {
            lance_index_segment_metadata_parse(dangerous.as_ptr(), dangerous.len(), &mut metadata)
        },
        -1
    );
    assert_eq!(metadata, sentinel);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);

    let negative_version = lance_table::format::pb::IndexMetadata {
        uuid: Some(lance_table::format::pb::Uuid {
            uuid: vec![0_u8; 16],
        }),
        fields: vec![0],
        name: "negative_version".to_string(),
        dataset_version: 1,
        fragment_bitmap: Vec::new(),
        index_details: None,
        index_version: Some(-1),
        created_at: None,
        base_id: None,
        files: Vec::new(),
        covering_fields: Vec::new(),
        clustering_id: None,
        metadata: Default::default(),
    }
    .encode_to_vec();
    assert_eq!(
        unsafe {
            lance_index_segment_metadata_parse(
                negative_version.as_ptr(),
                negative_version.len(),
                &mut metadata,
            )
        },
        -1
    );
    assert_eq!(metadata, sentinel);

    let negative_field = lance_table::format::pb::IndexMetadata {
        uuid: Some(lance_table::format::pb::Uuid {
            uuid: vec![0_u8; 16],
        }),
        fields: vec![-1],
        name: "negative_field".to_string(),
        dataset_version: 1,
        fragment_bitmap: Vec::new(),
        index_details: None,
        index_version: Some(0),
        created_at: None,
        base_id: None,
        files: Vec::new(),
        covering_fields: Vec::new(),
        clustering_id: None,
        metadata: Default::default(),
    }
    .encode_to_vec();
    assert_eq!(
        unsafe {
            lance_index_segment_metadata_parse(
                negative_field.as_ptr(),
                negative_field.len(),
                &mut metadata,
            )
        },
        -1
    );
    assert_eq!(metadata, sentinel);
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct CompleteIndexMetadata {
    uuid: [u8; 16],
    name: String,
    fields: Vec<i32>,
    covering_fields: Vec<i32>,
    dataset_version: u64,
    fragment_ids: Vec<u32>,
    index_version: i32,
    index_type: i32,
    index_details_type_url: Option<String>,
    index_details_value: Vec<u8>,
    files: Vec<(String, u64)>,
    created_at: Option<(i64, u32)>,
    base_id: Option<u32>,
}

fn inspect_index_metadata_via_c(
    metadata: *const LanceIndexSegmentMetadata,
) -> CompleteIndexMetadata {
    assert!(!metadata.is_null());
    let mut uuid = [0_u8; 16];
    assert_eq!(
        unsafe { lance_index_segment_metadata_uuid(metadata, uuid.as_mut_ptr()) },
        0,
        "{}",
        take_last_error_message()
    );
    let name = unsafe { CStr::from_ptr(lance_index_segment_metadata_name(metadata)) }
        .to_string_lossy()
        .into_owned();
    let field_count = unsafe { lance_index_segment_metadata_field_count(metadata) };
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
    let mut fields = vec![0_i32; field_count];
    let mut written = 0_usize;
    assert_eq!(
        unsafe {
            lance_index_segment_metadata_field_ids(
                metadata,
                fields.as_mut_ptr(),
                fields.len(),
                &mut written,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    fields.truncate(written);

    let covering_count = unsafe { lance_index_segment_metadata_covering_field_count(metadata) };
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
    let mut covering_fields = Vec::with_capacity(covering_count);
    for index in 0..covering_count {
        let mut field_id = i32::MIN;
        assert_eq!(
            unsafe {
                lance_index_segment_metadata_covering_field_id_at(metadata, index, &mut field_id)
            },
            0,
            "{}",
            take_last_error_message()
        );
        covering_fields.push(field_id);
    }

    let fragment_count = unsafe { lance_index_segment_metadata_fragment_count(metadata) };
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
    let mut fragment_ids = vec![0_u32; fragment_count];
    let mut written = 0_usize;
    assert_eq!(
        unsafe {
            lance_index_segment_metadata_fragment_ids(
                metadata,
                fragment_ids.as_mut_ptr(),
                fragment_ids.len(),
                &mut written,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    fragment_ids.truncate(written);

    let type_url_ptr = unsafe { lance_index_segment_metadata_index_details_type_url(metadata) };
    let index_details_type_url = if type_url_ptr.is_null() {
        assert_eq!(lance_last_error_code(), LanceErrorCode::NotFound);
        None
    } else {
        Some(
            unsafe { CStr::from_ptr(type_url_ptr) }
                .to_string_lossy()
                .into_owned(),
        )
    };

    let mut details_len = usize::MAX;
    let details_ptr =
        unsafe { lance_index_segment_metadata_index_details_value(metadata, &mut details_len) };
    let index_details_value = if details_ptr.is_null() {
        assert_eq!(lance_last_error_code(), LanceErrorCode::NotFound);
        assert_eq!(details_len, usize::MAX);
        Vec::new()
    } else {
        assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
        unsafe { std::slice::from_raw_parts(details_ptr, details_len) }.to_vec()
    };

    let file_count = unsafe { lance_index_segment_metadata_file_count(metadata) };
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
    let mut files = Vec::with_capacity(file_count);
    for index in 0..file_count {
        let path = unsafe { lance_index_segment_metadata_file_path_at(metadata, index) };
        assert!(!path.is_null(), "{}", take_last_error_message());
        let mut size = u64::MAX;
        assert_eq!(
            unsafe { lance_index_segment_metadata_file_size_at(metadata, index, &mut size) },
            0,
            "{}",
            take_last_error_message()
        );
        files.push((
            unsafe { CStr::from_ptr(path) }
                .to_string_lossy()
                .into_owned(),
            size,
        ));
    }
    files.sort();

    let mut timestamp = LanceOptionalTimestamp {
        is_set: false,
        unix_seconds: i64::MIN,
        nanos: u32::MAX,
    };
    assert_eq!(
        unsafe { lance_index_segment_metadata_created_at(metadata, &mut timestamp) },
        0,
        "{}",
        take_last_error_message()
    );
    let created_at = timestamp
        .is_set
        .then_some((timestamp.unix_seconds, timestamp.nanos));

    let mut base_id_is_set = true;
    let mut base_id = u32::MAX;
    assert_eq!(
        unsafe {
            lance_index_segment_metadata_base_id(metadata, &mut base_id_is_set, &mut base_id)
        },
        0,
        "{}",
        take_last_error_message()
    );
    let base_id = base_id_is_set.then_some(base_id);

    CompleteIndexMetadata {
        uuid,
        name,
        fields,
        covering_fields,
        dataset_version: unsafe {
            let version = lance_index_segment_metadata_dataset_version(metadata);
            assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
            version
        },
        fragment_ids,
        index_version: unsafe {
            let version = lance_index_segment_metadata_index_version(metadata);
            assert!(version >= 0, "{}", take_last_error_message());
            version
        },
        index_type: unsafe {
            let index_type = lance_index_segment_metadata_index_type(metadata);
            assert!(index_type >= 0, "{}", take_last_error_message());
            index_type
        },
        index_details_type_url,
        index_details_value,
        files,
        created_at,
        base_id,
    }
}

fn native_index_metadata_files(
    metadata: &lance_table::format::IndexMetadata,
) -> Vec<(String, u64)> {
    let mut files = metadata
        .files
        .as_ref()
        .map(|files| {
            files
                .iter()
                .map(|file| (file.path.clone(), file.size_bytes))
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    files.sort();
    files
}

fn assert_complete_metadata_matches_native_oracle(
    actual: &CompleteIndexMetadata,
    oracle: &lance_table::format::IndexMetadata,
    expected_index_type: i32,
) {
    assert_eq!(actual.uuid, *oracle.uuid.as_bytes());
    assert_eq!(actual.name, oracle.name);
    assert_eq!(actual.fields, oracle.fields);
    assert_eq!(actual.covering_fields, oracle.covering_fields);
    assert_eq!(actual.dataset_version, oracle.dataset_version);
    assert_eq!(
        actual.fragment_ids,
        oracle
            .fragment_bitmap
            .as_ref()
            .map(|bitmap| bitmap.iter().collect::<Vec<_>>())
            .unwrap_or_default()
    );
    assert_eq!(actual.index_version, oracle.index_version);
    assert_eq!(actual.index_type, expected_index_type);
    assert_eq!(
        actual.index_details_type_url.as_deref(),
        oracle
            .index_details
            .as_ref()
            .map(|details| details.type_url.as_str())
    );
    assert_eq!(
        actual.index_details_value,
        oracle
            .index_details
            .as_ref()
            .map(|details| details.value.clone())
            .unwrap_or_default()
    );
    assert_eq!(actual.files, native_index_metadata_files(oracle));
    assert_eq!(actual.base_id, oracle.base_id);
    assert_eq!(actual.created_at.is_some(), oracle.created_at.is_some());
}

fn create_create_index_dataset() -> (tempfile::TempDir, String) {
    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp
        .path()
        .join("create_index_ds")
        .to_str()
        .unwrap()
        .to_string();
    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new("score", DataType::Int32, false),
    ]));
    let ids = (0..18).collect::<Vec<_>>();
    let scores = ids.iter().map(|id| id * 10).collect::<Vec<_>>();
    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![
            Arc::new(Int32Array::from(ids)),
            Arc::new(Int32Array::from(scores)),
        ],
    )
    .unwrap();

    lance_c::runtime::block_on(async {
        let mut dataset = Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(batch)], schema),
            &uri,
            Some(WriteParams {
                max_rows_per_file: 5,
                enable_stable_row_ids: true,
                ..Default::default()
            }),
        )
        .await
        .unwrap();
        dataset.delete("id = 4").await.unwrap();
        assert_eq!(dataset.version().version, 2);
        assert_eq!(dataset.get_fragments().len(), 4);
        assert_eq!(dataset.count_rows(None).await.unwrap(), 17);
    });

    (tmp, uri)
}

unsafe fn build_scalar_segment_via_c(
    dataset: *const LanceDataset,
    column: &str,
    index_name: &str,
    scalar_type: LanceScalarIndexType,
    params_json: &str,
    fragment_ids: &[u32],
    uuid: Option<[u8; 16]>,
) -> *mut LanceIndexSegmentMetadata {
    let column = c_str(column);
    let index_name = c_str(index_name);
    let params_json = c_str(params_json);
    let params_json_ptr = if params_json.as_bytes().is_empty() {
        ptr::null()
    } else {
        params_json.as_ptr()
    };
    let uuid_ptr = uuid.as_ref().map_or(ptr::null(), |uuid| uuid.as_ptr());
    let options = LanceIndexSegmentBuildOptions {
        fragment_ids: fragment_ids.as_ptr(),
        fragment_count: fragment_ids.len(),
        index_uuid: uuid_ptr,
        ivf_centroids: ptr::null_mut(),
        ivf_centroids_schema: ptr::null(),
        pq_codebook: ptr::null_mut(),
        pq_codebook_schema: ptr::null(),
        mode: LanceIndexSegmentBuildMode::Auto as i32,
    };
    let builder = unsafe {
        lance_index_segment_builder_new_scalar(
            dataset,
            column.as_ptr(),
            index_name.as_ptr(),
            scalar_type as i32,
            params_json_ptr,
            &options,
        )
    };
    assert!(!builder.is_null(), "{}", take_last_error_message());
    let mut bytes = ptr::null_mut();
    let mut len = 0_usize;
    assert_eq!(
        unsafe { lance_index_segment_builder_execute_uncommitted(builder, &mut bytes, &mut len) },
        0,
        "{}",
        take_last_error_message()
    );
    assert!(!bytes.is_null() && len > 0);
    let mut metadata = ptr::null_mut();
    assert_eq!(
        unsafe { lance_index_segment_metadata_parse(bytes, len, &mut metadata) },
        0,
        "{}",
        take_last_error_message()
    );
    unsafe {
        lance_free_bytes(bytes);
        lance_index_segment_builder_free(builder);
    }
    metadata
}

fn build_native_zone_map_segment(
    dataset: &mut Dataset,
    fragment_ids: &[u32],
    uuid: [u8; 16],
    index_name: &str,
    params_json: &str,
) -> lance_table::format::IndexMetadata {
    use lance::index::DatasetIndexExt;
    use lance_index::scalar::{BuiltinIndexType, ScalarIndexParams};
    use uuid::Uuid;

    let mut params = ScalarIndexParams::for_builtin(BuiltinIndexType::ZoneMap);
    params.params = Some(params_json.to_string());
    let mut builder =
        dataset.create_index_builder(&["score"], lance_index::IndexType::ZoneMap, &params);
    builder = builder
        .name(index_name.to_string())
        .index_uuid(Uuid::from_bytes(uuid))
        .fragments(fragment_ids.to_vec());
    lance_c::runtime::block_on(builder.execute_uncommitted()).unwrap()
}

fn dataset_segment_uuids(dataset: *const LanceDataset, index_name: &str) -> Vec<[u8; 16]> {
    let index_name = c_str(index_name);
    let count = unsafe { lance_dataset_index_segment_count(dataset, index_name.as_ptr()) };
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
    let mut uuids = vec![0_u8; count as usize * 16];
    let mut written = 0_u64;
    assert_eq!(
        unsafe {
            lance_dataset_index_segments(
                dataset,
                index_name.as_ptr(),
                uuids.as_mut_ptr(),
                count as usize,
                &mut written,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(written, count);
    uuids.as_chunks::<16>().0.to_vec()
}

fn metadata_from_operation(
    operation: *const LanceOperation,
    removed: bool,
    index: usize,
) -> *mut LanceIndexSegmentMetadata {
    let mut metadata = ptr::null_mut();
    let rc = unsafe {
        if removed {
            lance_operation_create_index_removed_at(operation, index, &mut metadata)
        } else {
            lance_operation_create_index_new_at(operation, index, &mut metadata)
        }
    };
    assert_eq!(rc, 0, "{}", take_last_error_message());
    assert!(!metadata.is_null());
    metadata
}

#[test]
fn test_index_metadata_complete_inspection_clone_and_native_oracle() {
    use chrono::Utc;
    use lance_table::format::pb;
    use prost::Message;
    use uuid::Uuid;

    let (_tmp, uri) = create_create_index_dataset();
    let uri_c = c_str(&uri);
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null(), "{}", take_last_error_message());
    assert_eq!(unsafe { lance_dataset_version(dataset) }, 2);
    assert_eq!(unsafe { lance_dataset_fragment_count(dataset) }, 4);

    let uuid = [
        0x10, 0x21, 0x32, 0x43, 0x54, 0x65, 0x76, 0x87, 0x98, 0xa9, 0xba, 0xcb, 0xdc, 0xed, 0xfe,
        0x0f,
    ];
    let params_json = r#"{"rows_per_zone":2,"use_seeds":false}"#;
    let before_ms = Utc::now().timestamp_millis();
    let metadata = unsafe {
        build_scalar_segment_via_c(
            dataset,
            "score",
            "score_zonemap_create",
            LanceScalarIndexType::ZoneMap,
            params_json,
            &[0, 1],
            Some(uuid),
        )
    };
    let after_ms = Utc::now().timestamp_millis();
    let actual = inspect_index_metadata_via_c(metadata);

    let mut native = lance_c::runtime::block_on(Dataset::open(&uri)).unwrap();
    let oracle = build_native_zone_map_segment(
        &mut native,
        &[0, 1],
        uuid,
        "score_zonemap_create",
        params_json,
    );
    assert_complete_metadata_matches_native_oracle(
        &actual,
        &oracle,
        LanceScalarIndexType::ZoneMap as i32,
    );
    assert_eq!(actual.fragment_ids, vec![0, 1]);
    assert!(actual.covering_fields.is_empty());
    assert!(actual.created_at.is_some());
    assert!(actual.base_id.is_none());
    assert!(!actual.files.is_empty());
    assert!(actual.files.iter().all(|(_, size)| *size > 0));
    let created_ms = actual
        .created_at
        .map(|(seconds, nanos)| seconds * 1000 + i64::from(nanos / 1_000_000))
        .unwrap();
    assert!(
        (before_ms..=after_ms).contains(&created_ms),
        "created_at {created_ms} must be recorded during this build ({before_ms}..={after_ms})"
    );
    let details =
        lance_index::pbold::ZoneMapIndexDetails::decode(actual.index_details_value.as_slice())
            .unwrap();
    assert_eq!(details.rows_per_zone, Some(2));
    assert_eq!(details.use_seeds, Some(false));

    let cloned = unsafe { lance_index_segment_metadata_clone(metadata) };
    assert!(!cloned.is_null(), "{}", take_last_error_message());
    unsafe { lance_index_segment_metadata_free(metadata) };
    let cloned_actual = inspect_index_metadata_via_c(cloned);
    assert_eq!(cloned_actual, actual, "clone must be lossless in memory");
    unsafe { lance_index_segment_metadata_free(cloned) };

    let bitmap_uuid = [
        0xf0, 0xed, 0xdc, 0xcb, 0xba, 0xa9, 0x98, 0x87, 0x76, 0x65, 0x54, 0x43, 0x32, 0x21, 0x10,
        0x01,
    ];
    let bitmap = unsafe {
        build_scalar_segment_via_c(
            dataset,
            "id",
            "id_bitmap_empty_details",
            LanceScalarIndexType::Bitmap,
            "",
            &[2],
            Some(bitmap_uuid),
        )
    };
    let mut details_len = usize::MAX;
    let details_ptr =
        unsafe { lance_index_segment_metadata_index_details_value(bitmap, &mut details_len) };
    assert!(
        !details_ptr.is_null(),
        "a present empty Any value must remain distinguishable from absence"
    );
    assert_eq!(details_len, 0);
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
    unsafe { lance_index_segment_metadata_free(bitmap) };

    let absent_details_bytes = pb::IndexMetadata {
        uuid: Some(pb::Uuid {
            uuid: Uuid::new_v4().as_bytes().to_vec(),
        }),
        fields: vec![0],
        name: "absent_details".to_string(),
        dataset_version: 2,
        fragment_bitmap: Vec::new(),
        index_details: None,
        index_version: Some(0),
        created_at: None,
        base_id: None,
        files: Vec::new(),
        covering_fields: Vec::new(),
        clustering_id: None,
        metadata: Default::default(),
    }
    .encode_to_vec();
    let mut absent_details = ptr::null_mut();
    assert_eq!(
        unsafe {
            lance_index_segment_metadata_parse(
                absent_details_bytes.as_ptr(),
                absent_details_bytes.len(),
                &mut absent_details,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    let mut untouched_len = usize::MAX;
    assert!(
        unsafe {
            lance_index_segment_metadata_index_details_value(absent_details, &mut untouched_len)
        }
        .is_null()
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::NotFound);
    assert_eq!(untouched_len, usize::MAX);
    let mut untouched_size = u64::MAX;
    assert_eq!(
        unsafe {
            lance_index_segment_metadata_file_size_at(absent_details, 0, &mut untouched_size)
        },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert_eq!(untouched_size, u64::MAX);
    unsafe { lance_index_segment_metadata_free(absent_details) };

    unsafe { lance_dataset_close(dataset) };
}

#[test]
fn test_index_metadata_clone_with_fragment_ids_and_encode() {
    use chrono::{TimeZone, Utc};
    use lance_table::format::{IndexFile, IndexMetadata, pb};
    use prost::Message;
    use uuid::Uuid;

    let created_at = Utc
        .timestamp_millis_opt(1_700_000_123_456)
        .single()
        .unwrap();
    let native = IndexMetadata {
        uuid: Uuid::from_u128(0x102132435465768798a9bacbdcedfe0f),
        name: "coverage_clone".to_string(),
        fields: vec![1, 2],
        covering_fields: vec![2],
        dataset_version: 9,
        fragment_bitmap: Some([2_u32, 5].into_iter().collect()),
        index_details: Some(std::sync::Arc::new(prost_types::Any {
            type_url: "/lance.table.InvertedIndexDetails".to_string(),
            value: b"index details payload".to_vec(),
        })),
        index_version: 3,
        created_at: Some(created_at),
        base_id: Some(7),
        files: Some(vec![
            IndexFile {
                path: "index.idx".to_string(),
                size_bytes: 101,
            },
            IndexFile {
                path: "metadata.idx".to_string(),
                size_bytes: 202,
            },
        ]),
    };
    let encoded_source = pb::IndexMetadata::from(&native).encode_to_vec();
    let mut source = ptr::null_mut();
    assert_eq!(
        unsafe {
            lance_index_segment_metadata_parse(
                encoded_source.as_ptr(),
                encoded_source.len(),
                &mut source,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    let source_before = inspect_index_metadata_via_c(source);
    assert_eq!(
        source_before.created_at,
        Some((created_at.timestamp(), created_at.timestamp_subsec_nanos()))
    );

    let replacement = [7_u32, 1, 7, 3];
    let combined = unsafe {
        lance_index_segment_metadata_clone_with_fragment_ids(
            source,
            true,
            replacement.as_ptr(),
            replacement.len(),
        )
    };
    assert!(!combined.is_null(), "{}", take_last_error_message());
    let mut expected = source_before.clone();
    expected.fragment_ids = vec![1, 3, 7];
    assert_eq!(inspect_index_metadata_via_c(combined), expected);
    assert_eq!(
        inspect_index_metadata_via_c(source),
        source_before,
        "cloning must not modify the source handle"
    );

    let dangling = std::ptr::NonNull::<u32>::dangling().as_ptr();
    let unchanged = unsafe {
        lance_index_segment_metadata_clone_with_fragment_ids(source, false, dangling, usize::MAX)
    };
    assert!(
        !unchanged.is_null(),
        "inactive fragment IDs must be ignored: {}",
        take_last_error_message()
    );
    assert_eq!(inspect_index_metadata_via_c(unchanged), source_before);

    let empty = unsafe {
        lance_index_segment_metadata_clone_with_fragment_ids(source, true, ptr::null(), 0)
    };
    assert!(!empty.is_null(), "{}", take_last_error_message());
    assert_eq!(
        inspect_index_metadata_via_c(empty).fragment_ids,
        Vec::<u32>::new()
    );

    let oversized = usize::MAX / std::mem::size_of::<u32>() + 1;
    assert!(
        unsafe {
            lance_index_segment_metadata_clone_with_fragment_ids(source, true, dangling, oversized)
        }
        .is_null()
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(message.contains("fragment_count"), "{message}");
    assert!(message.contains(&oversized.to_string()), "{message}");

    assert!(
        unsafe {
            lance_index_segment_metadata_clone_with_fragment_ids(ptr::null(), false, ptr::null(), 0)
        }
        .is_null()
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let _ = take_last_error_message();

    let mut encoded = ptr::null_mut();
    let mut encoded_len = usize::MAX;
    assert_eq!(
        unsafe { lance_index_segment_metadata_encode(combined, &mut encoded, &mut encoded_len) },
        0,
        "{}",
        take_last_error_message()
    );
    assert!(!encoded.is_null() && encoded_len > 0);
    let mut reparsed = ptr::null_mut();
    assert_eq!(
        unsafe { lance_index_segment_metadata_parse(encoded, encoded_len, &mut reparsed) },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(inspect_index_metadata_via_c(reparsed), expected);

    let sentinel = std::ptr::NonNull::<u8>::dangling().as_ptr();
    let mut sentinel_bytes = sentinel;
    let mut sentinel_len = usize::MAX;
    assert_eq!(
        unsafe {
            lance_index_segment_metadata_encode(ptr::null(), &mut sentinel_bytes, &mut sentinel_len)
        },
        -1
    );
    assert_eq!(sentinel_bytes, sentinel);
    assert_eq!(sentinel_len, usize::MAX);
    assert_eq!(
        unsafe {
            lance_index_segment_metadata_encode(combined, ptr::null_mut(), &mut sentinel_len)
        },
        -1
    );
    assert_eq!(sentinel_len, usize::MAX);
    assert_eq!(
        unsafe {
            lance_index_segment_metadata_encode(combined, &mut sentinel_bytes, ptr::null_mut())
        },
        -1
    );
    assert_eq!(sentinel_bytes, sentinel);

    unsafe {
        lance_index_segment_metadata_free(source);
        assert_eq!(
            inspect_index_metadata_via_c(combined),
            expected,
            "an owned clone must remain usable after the source is freed"
        );
        lance_free_bytes(encoded);
        lance_index_segment_metadata_free(empty);
        lance_index_segment_metadata_free(unchanged);
        lance_index_segment_metadata_free(combined);
        lance_index_segment_metadata_free(reparsed);
    }
}

#[test]
fn test_create_index_operation_constructor_validation_and_ownership() {
    let (_tmp, uri) = create_create_index_dataset();
    let uri_c = c_str(&uri);
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null(), "{}", take_last_error_message());
    let metadata = unsafe {
        build_scalar_segment_via_c(
            dataset,
            "score",
            "duplicate_segments",
            LanceScalarIndexType::ZoneMap,
            r#"{"rows_per_zone":2,"use_seeds":false}"#,
            &[0, 1],
            Some([0x42; 16]),
        )
    };

    let duplicate_entries = [metadata as *const LanceIndexSegmentMetadata; 2];
    let operation = unsafe {
        lance_operation_create_index_new(
            duplicate_entries.as_ptr(),
            duplicate_entries.len(),
            ptr::null(),
            0,
        )
    };
    assert!(!operation.is_null(), "{}", take_last_error_message());
    let mut kind = LanceOperationKind::Unknown;
    assert_eq!(
        unsafe { lance_operation_kind(operation, &mut kind) },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(kind, LanceOperationKind::CreateIndex);
    let mut new_count = u64::MAX;
    assert_eq!(
        unsafe { lance_operation_create_index_new_count(operation, &mut new_count) },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(new_count, 2, "constructor must not de-duplicate entries");
    let mut removed_count = u64::MAX;
    assert_eq!(
        unsafe { lance_operation_create_index_removed_count(operation, &mut removed_count) },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(removed_count, 0);

    unsafe { lance_index_segment_metadata_free(metadata) };
    let first = metadata_from_operation(operation, false, 0);
    let second = metadata_from_operation(operation, false, 1);
    unsafe { lance_operation_close(operation) };
    let first_value = inspect_index_metadata_via_c(first);
    let second_value = inspect_index_metadata_via_c(second);
    assert_eq!(first_value, second_value);
    assert_eq!(first_value.uuid, [0x42; 16]);
    unsafe {
        lance_index_segment_metadata_free(first);
        lance_index_segment_metadata_free(second);
    }

    let empty = unsafe { lance_operation_create_index_new(ptr::null(), 0, ptr::null(), 0) };
    assert!(!empty.is_null(), "{}", take_last_error_message());
    let non_null_empty = [ptr::null::<LanceIndexSegmentMetadata>()];
    let empty_with_non_null_arrays = unsafe {
        lance_operation_create_index_new(non_null_empty.as_ptr(), 0, non_null_empty.as_ptr(), 0)
    };
    assert!(
        !empty_with_non_null_arrays.is_null(),
        "non-NULL arrays with zero counts must be accepted: {}",
        take_last_error_message()
    );
    for operation in [empty, empty_with_non_null_arrays] {
        let mut count = u64::MAX;
        assert_eq!(
            unsafe { lance_operation_create_index_new_count(operation, &mut count) },
            0
        );
        assert_eq!(count, 0);
        assert_eq!(
            unsafe { lance_operation_create_index_removed_count(operation, &mut count) },
            0
        );
        assert_eq!(count, 0);
        unsafe { lance_operation_close(operation) };
    }

    let null_entry = [ptr::null::<LanceIndexSegmentMetadata>()];
    assert!(
        unsafe { lance_operation_create_index_new(null_entry.as_ptr(), 1, ptr::null(), 0) }
            .is_null()
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(
        message.contains("new_indices[0]") && message.contains("NULL"),
        "{message}"
    );
    assert!(unsafe { lance_operation_create_index_new(ptr::null(), 1, ptr::null(), 0) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(
        message.contains("new_indices") && message.contains("NULL"),
        "{message}"
    );
    assert!(
        unsafe { lance_operation_create_index_new(ptr::null(), 0, null_entry.as_ptr(), 1) }
            .is_null()
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(
        message.contains("removed_indices[0]") && message.contains("NULL"),
        "{message}"
    );

    unsafe { lance_dataset_close(dataset) };

    let transaction = write_uncommitted_for_batch(
        "memory://create-index-wrong-kind",
        write_batch(vec![1], vec![1.0]),
        LanceWriteMode::Create,
        ptr::null(),
    );
    let wrong_operation = native_transaction_operation(transaction);
    assert_eq!(
        native_operation_kind(wrong_operation),
        LanceOperationKind::Overwrite
    );
    let sentinel = std::ptr::dangling_mut::<LanceIndexSegmentMetadata>();
    let mut untouched = sentinel;
    assert_eq!(
        unsafe { lance_operation_create_index_new_at(wrong_operation, 0, &mut untouched) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::NotSupported);
    assert_eq!(untouched, sentinel);
    let mut untouched_count = u64::MAX;
    assert_eq!(
        unsafe { lance_operation_create_index_new_count(wrong_operation, &mut untouched_count) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::NotSupported);
    assert_eq!(untouched_count, u64::MAX);
    assert_eq!(
        unsafe { lance_operation_create_index_removed_at(wrong_operation, 0, &mut untouched) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::NotSupported);
    assert_eq!(untouched, sentinel);
    unsafe {
        lance_operation_close(wrong_operation);
        lance_transaction_close(transaction);
    }
}

#[test]
fn test_create_index_commit_replace_conflict_history_and_query() {
    let (_tmp, uri) = create_create_index_dataset();
    let uri_c = c_str(&uri);
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null(), "{}", take_last_error_message());
    let read_version = unsafe { lance_dataset_version(dataset) };
    assert_eq!(read_version, 2);
    assert_eq!(unsafe { lance_dataset_fragment_count(dataset) }, 4);

    let params = r#"{"rows_per_zone":2,"use_seeds":false}"#;
    let uuid_a = [0xa1; 16];
    let uuid_b = [0xb2; 16];
    let uuid_conflict = [0xc3; 16];
    let uuid_replacement = [0xd4; 16];
    let segment_a = unsafe {
        build_scalar_segment_via_c(
            dataset,
            "score",
            "score_zonemap_create",
            LanceScalarIndexType::ZoneMap,
            params,
            &[0, 1],
            Some(uuid_a),
        )
    };
    let segment_b = unsafe {
        build_scalar_segment_via_c(
            dataset,
            "score",
            "score_zonemap_create",
            LanceScalarIndexType::ZoneMap,
            params,
            &[2, 3],
            Some(uuid_b),
        )
    };
    let segment_a_value = inspect_index_metadata_via_c(segment_a);
    let segment_b_value = inspect_index_metadata_via_c(segment_b);
    assert_eq!(segment_a_value.fragment_ids, vec![0, 1]);
    assert_eq!(segment_b_value.fragment_ids, vec![2, 3]);

    let new_segments = [
        segment_a as *const LanceIndexSegmentMetadata,
        segment_b as *const LanceIndexSegmentMetadata,
    ];
    let create_operation = unsafe {
        lance_operation_create_index_new(new_segments.as_ptr(), new_segments.len(), ptr::null(), 0)
    };
    assert!(!create_operation.is_null(), "{}", take_last_error_message());
    let create_transaction =
        unsafe { lance_transaction_new(read_version, create_operation, ptr::null()) };
    assert!(
        !create_transaction.is_null(),
        "{}",
        take_last_error_message()
    );

    let conflict_segment = unsafe {
        build_scalar_segment_via_c(
            dataset,
            "score",
            "score_zonemap_create",
            LanceScalarIndexType::ZoneMap,
            params,
            &[0, 1, 2, 3],
            Some(uuid_conflict),
        )
    };
    let conflict_segments = [conflict_segment as *const LanceIndexSegmentMetadata];
    let conflict_operation =
        unsafe { lance_operation_create_index_new(conflict_segments.as_ptr(), 1, ptr::null(), 0) };
    assert!(
        !conflict_operation.is_null(),
        "{}",
        take_last_error_message()
    );
    let conflict_transaction =
        unsafe { lance_transaction_new(read_version, conflict_operation, ptr::null()) };
    assert!(
        !conflict_transaction.is_null(),
        "{}",
        take_last_error_message()
    );
    let replacement_segment = unsafe {
        build_scalar_segment_via_c(
            dataset,
            "score",
            "score_zonemap_create",
            LanceScalarIndexType::ZoneMap,
            params,
            &[0, 1, 2, 3],
            Some(uuid_replacement),
        )
    };
    let replacement_value = inspect_index_metadata_via_c(replacement_segment);
    assert_eq!(replacement_value.fragment_ids, vec![0, 1, 2, 3]);

    unsafe {
        lance_index_segment_metadata_free(segment_a);
        lance_index_segment_metadata_free(segment_b);
        lance_index_segment_metadata_free(conflict_segment);
        lance_operation_close(create_operation);
        lance_operation_close(conflict_operation);
        lance_dataset_close(dataset);
    }

    let mut commit_options: LanceCommitOptions = unsafe { std::mem::zeroed() };
    commit_options.has_max_retries = true;
    commit_options.max_retries = 0;
    commit_options.timeout_mode = LanceCommitTimeoutMode::Disabled as i32;
    let committed = commit_native_transaction(&uri, create_transaction, &commit_options);
    assert_eq!(
        unsafe { lance_dataset_version(committed) },
        read_version + 1
    );
    assert_eq!(unsafe { lance_dataset_count_rows(committed) }, 17);
    let mut committed_uuids = dataset_segment_uuids(committed, "score_zonemap_create");
    committed_uuids.sort();
    let mut expected_uuids = vec![uuid_a, uuid_b];
    expected_uuids.sort();
    assert_eq!(committed_uuids, expected_uuids);
    unsafe { lance_dataset_close(committed) };

    let sentinel_dataset = std::ptr::dangling_mut::<LanceDataset>();
    let mut failed_output = sentinel_dataset;
    assert_eq!(
        unsafe {
            lance_transaction_commit(
                uri_c.as_ptr(),
                conflict_transaction,
                &commit_options,
                ptr::null(),
                ptr::null(),
                &mut failed_output,
            )
        },
        -1
    );
    assert_eq!(
        lance_last_error_code(),
        LanceErrorCode::CommitConflict,
        "{}",
        take_last_error_message()
    );
    assert_eq!(
        failed_output, sentinel_dataset,
        "a losing CreateIndex commit must not write a dataset output"
    );
    unsafe { lance_transaction_close(conflict_transaction) };

    let after_conflict = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!after_conflict.is_null(), "{}", take_last_error_message());
    assert_eq!(
        unsafe { lance_dataset_version(after_conflict) },
        read_version + 1,
        "the losing transaction must not publish another version"
    );
    let mut after_conflict_uuids = dataset_segment_uuids(after_conflict, "score_zonemap_create");
    after_conflict_uuids.sort();
    assert_eq!(
        after_conflict_uuids, expected_uuids,
        "the losing transaction must not publish a duplicate segment"
    );
    let (ids, statistics) = scan_index_ids(after_conflict, "score = 70", true);
    assert_eq!(ids, vec![7]);
    assert!(
        statistics.indices_loaded > 0,
        "the committed ZoneMap index must be used by the query"
    );

    let mut transaction_at_commit = ptr::null_mut();
    assert_eq!(
        unsafe { lance_dataset_read_transaction(after_conflict, &mut transaction_at_commit) },
        0,
        "{}",
        take_last_error_message()
    );
    assert!(!transaction_at_commit.is_null());
    let committed_operation = native_transaction_operation(transaction_at_commit);
    assert_eq!(
        native_operation_kind(committed_operation),
        LanceOperationKind::CreateIndex
    );
    let mut new_count = u64::MAX;
    assert_eq!(
        unsafe { lance_operation_create_index_new_count(committed_operation, &mut new_count) },
        0
    );
    assert_eq!(new_count, 2);
    let mut removed_count = u64::MAX;
    assert_eq!(
        unsafe {
            lance_operation_create_index_removed_count(committed_operation, &mut removed_count)
        },
        0
    );
    assert_eq!(removed_count, 0);
    let history_a = metadata_from_operation(committed_operation, false, 0);
    let history_b = metadata_from_operation(committed_operation, false, 1);
    assert_eq!(
        inspect_index_metadata_via_c(history_a),
        segment_a_value,
        "persisted history must retain the complete new-index metadata"
    );
    assert_eq!(inspect_index_metadata_via_c(history_b), segment_b_value);
    let committed_proto = transaction_proto_bytes(transaction_at_commit);
    unsafe {
        lance_operation_close(committed_operation);
        lance_transaction_close(transaction_at_commit);
        lance_dataset_close(after_conflict);
    }
    assert_eq!(
        inspect_index_metadata_via_c(history_a),
        segment_a_value,
        "metadata cloned from an operation must outlive the parent handles"
    );

    let parsed_committed = transaction_from_proto_bytes(&committed_proto);
    let parsed_committed_operation = native_transaction_operation(parsed_committed);
    let parsed_a = metadata_from_operation(parsed_committed_operation, false, 0);
    let parsed_b = metadata_from_operation(parsed_committed_operation, false, 1);
    assert_eq!(inspect_index_metadata_via_c(parsed_a), segment_a_value);
    assert_eq!(inspect_index_metadata_via_c(parsed_b), segment_b_value);
    unsafe {
        lance_operation_close(parsed_committed_operation);
        lance_transaction_close(parsed_committed);
        lance_index_segment_metadata_free(parsed_a);
        lance_index_segment_metadata_free(parsed_b);
    }

    let replacement_version = read_version + 1;

    let replacement_new = [replacement_segment as *const LanceIndexSegmentMetadata];
    let removed = [
        history_a as *const LanceIndexSegmentMetadata,
        history_b as *const LanceIndexSegmentMetadata,
    ];
    let replacement_operation = unsafe {
        lance_operation_create_index_new(
            replacement_new.as_ptr(),
            1,
            removed.as_ptr(),
            removed.len(),
        )
    };
    assert!(
        !replacement_operation.is_null(),
        "{}",
        take_last_error_message()
    );
    let replacement_transaction =
        unsafe { lance_transaction_new(replacement_version, replacement_operation, ptr::null()) };
    assert!(
        !replacement_transaction.is_null(),
        "{}",
        take_last_error_message()
    );
    unsafe {
        lance_operation_close(replacement_operation);
        lance_index_segment_metadata_free(replacement_segment);
        lance_index_segment_metadata_free(history_a);
        lance_index_segment_metadata_free(history_b);
    }
    let replaced = commit_native_transaction(&uri, replacement_transaction, &commit_options);
    assert_eq!(
        unsafe { lance_dataset_version(replaced) },
        replacement_version + 1
    );
    let replaced_uuids = dataset_segment_uuids(replaced, "score_zonemap_create");
    assert_eq!(replaced_uuids, vec![uuid_replacement]);
    let (ids, statistics) = scan_index_ids(replaced, "score = 70", true);
    assert_eq!(ids, vec![7]);
    assert!(statistics.indices_loaded > 0);

    let mut replacement_history = ptr::null_mut();
    assert_eq!(
        unsafe { lance_dataset_read_transaction(replaced, &mut replacement_history) },
        0,
        "{}",
        take_last_error_message()
    );
    assert!(!replacement_history.is_null());
    let replacement_history_operation = native_transaction_operation(replacement_history);
    let mut replaced_new_count = u64::MAX;
    assert_eq!(
        unsafe {
            lance_operation_create_index_new_count(
                replacement_history_operation,
                &mut replaced_new_count,
            )
        },
        0
    );
    assert_eq!(replaced_new_count, 1);
    let mut replaced_removed_count = u64::MAX;
    assert_eq!(
        unsafe {
            lance_operation_create_index_removed_count(
                replacement_history_operation,
                &mut replaced_removed_count,
            )
        },
        0
    );
    assert_eq!(replaced_removed_count, 2);
    let persisted_replacement = metadata_from_operation(replacement_history_operation, false, 0);
    assert_eq!(
        inspect_index_metadata_via_c(persisted_replacement),
        replacement_value
    );
    let persisted_removed_a = metadata_from_operation(replacement_history_operation, true, 0);
    let persisted_removed_b = metadata_from_operation(replacement_history_operation, true, 1);
    let mut persisted_removed = [
        inspect_index_metadata_via_c(persisted_removed_a).uuid,
        inspect_index_metadata_via_c(persisted_removed_b).uuid,
    ];
    persisted_removed.sort();
    let mut original_removed = [uuid_a, uuid_b];
    original_removed.sort();
    assert_eq!(persisted_removed, original_removed);
    assert_eq!(
        inspect_index_metadata_via_c(persisted_removed_a),
        segment_a_value
    );
    assert_eq!(
        inspect_index_metadata_via_c(persisted_removed_b),
        segment_b_value
    );
    let replacement_proto = transaction_proto_bytes(replacement_history);
    unsafe {
        lance_operation_close(replacement_history_operation);
        lance_transaction_close(replacement_history);
        lance_index_segment_metadata_free(persisted_replacement);
        lance_index_segment_metadata_free(persisted_removed_a);
        lance_index_segment_metadata_free(persisted_removed_b);
        lance_dataset_close(replaced);
    }

    let parsed_replacement = transaction_from_proto_bytes(&replacement_proto);
    let parsed_replacement_operation = native_transaction_operation(parsed_replacement);
    let parsed_new = metadata_from_operation(parsed_replacement_operation, false, 0);
    let parsed_removed_a = metadata_from_operation(parsed_replacement_operation, true, 0);
    let parsed_removed_b = metadata_from_operation(parsed_replacement_operation, true, 1);
    assert_eq!(inspect_index_metadata_via_c(parsed_new), replacement_value);
    assert_eq!(
        inspect_index_metadata_via_c(parsed_removed_a),
        segment_a_value
    );
    assert_eq!(
        inspect_index_metadata_via_c(parsed_removed_b),
        segment_b_value
    );

    let removal_indices = [parsed_new as *const LanceIndexSegmentMetadata];
    let removal_operation = unsafe {
        lance_operation_create_index_new(
            ptr::null(),
            0,
            removal_indices.as_ptr(),
            removal_indices.len(),
        )
    };
    assert!(
        !removal_operation.is_null(),
        "{}",
        take_last_error_message()
    );
    let removal_transaction =
        unsafe { lance_transaction_new(replacement_version + 1, removal_operation, ptr::null()) };
    assert!(
        !removal_transaction.is_null(),
        "{}",
        take_last_error_message()
    );
    unsafe { lance_operation_close(removal_operation) };
    let removed_dataset = commit_native_transaction(&uri, removal_transaction, &commit_options);
    assert_eq!(
        unsafe { lance_dataset_version(removed_dataset) },
        replacement_version + 2
    );
    let removal_name = c_str("score_zonemap_create");
    assert_eq!(
        unsafe { lance_dataset_index_segment_count(removed_dataset, removal_name.as_ptr()) },
        0
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::NotFound);
    let (ids, statistics) = scan_index_ids(removed_dataset, "score = 70", false);
    assert_eq!(ids, vec![7]);
    assert_eq!(statistics.indices_loaded, 0);
    let mut removal_history = ptr::null_mut();
    assert_eq!(
        unsafe { lance_dataset_read_transaction(removed_dataset, &mut removal_history) },
        0,
        "{}",
        take_last_error_message()
    );
    assert!(!removal_history.is_null());
    let removal_history_operation = native_transaction_operation(removal_history);
    let mut removal_new_count = u64::MAX;
    let mut removal_removed_count = u64::MAX;
    assert_eq!(
        unsafe {
            lance_operation_create_index_new_count(
                removal_history_operation,
                &mut removal_new_count,
            )
        },
        0
    );
    assert_eq!(
        unsafe {
            lance_operation_create_index_removed_count(
                removal_history_operation,
                &mut removal_removed_count,
            )
        },
        0
    );
    assert_eq!(removal_new_count, 0);
    assert_eq!(removal_removed_count, 1);
    let removal_metadata = metadata_from_operation(removal_history_operation, true, 0);
    assert_eq!(
        inspect_index_metadata_via_c(removal_metadata),
        replacement_value
    );
    unsafe {
        lance_operation_close(removal_history_operation);
        lance_transaction_close(removal_history);
        lance_transaction_close(removal_transaction);
        lance_index_segment_metadata_free(removal_metadata);
        lance_dataset_close(removed_dataset);
    }

    unsafe {
        lance_operation_close(parsed_replacement_operation);
        lance_transaction_close(parsed_replacement);
        lance_transaction_close(create_transaction);
        lance_transaction_close(replacement_transaction);
        lance_index_segment_metadata_free(parsed_new);
        lance_index_segment_metadata_free(parsed_removed_a);
        lance_index_segment_metadata_free(parsed_removed_b);
    }
}

#[test]
fn test_create_index_native_validation_stays_in_core() {
    let (_tmp, uri) = create_create_index_dataset();
    let uri_c = c_str(&uri);
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null(), "{}", take_last_error_message());
    let version = unsafe { lance_dataset_version(dataset) };

    let btree = unsafe {
        build_scalar_segment_via_c(
            dataset,
            "id",
            "mixed_domain_idx",
            LanceScalarIndexType::BTree,
            "",
            &[0, 1],
            None,
        )
    };
    let bitmap = unsafe {
        build_scalar_segment_via_c(
            dataset,
            "id",
            "mixed_domain_idx",
            LanceScalarIndexType::Bitmap,
            "",
            &[2, 3],
            Some([0x22; 16]),
        )
    };
    let btree_value = inspect_index_metadata_via_c(btree);
    let bitmap_value = inspect_index_metadata_via_c(bitmap);
    assert_eq!(btree_value.index_type, LanceScalarIndexType::BTree as i32);
    assert_eq!(bitmap_value.index_type, LanceScalarIndexType::Bitmap as i32);

    let entries = [
        btree as *const LanceIndexSegmentMetadata,
        bitmap as *const LanceIndexSegmentMetadata,
    ];
    let operation = unsafe {
        lance_operation_create_index_new(entries.as_ptr(), entries.len(), ptr::null(), 0)
    };
    assert!(!operation.is_null(), "{}", take_last_error_message());
    let transaction = unsafe { lance_transaction_new(version, operation, ptr::null()) };
    assert!(!transaction.is_null(), "{}", take_last_error_message());
    unsafe {
        lance_operation_close(operation);
        lance_index_segment_metadata_free(btree);
        lance_index_segment_metadata_free(bitmap);
        lance_dataset_close(dataset);
    }

    let mut options: LanceCommitOptions = unsafe { std::mem::zeroed() };
    options.has_max_retries = true;
    options.max_retries = 0;
    options.timeout_mode = LanceCommitTimeoutMode::Disabled as i32;
    let sentinel = std::ptr::dangling_mut::<LanceDataset>();
    let mut output = sentinel;
    assert_eq!(
        unsafe {
            lance_transaction_commit(
                uri_c.as_ptr(),
                transaction,
                &options,
                ptr::null(),
                ptr::null(),
                &mut output,
            )
        },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(
        message.contains("mixes row-ID and row-address segments"),
        "{message}"
    );
    assert_eq!(output, sentinel);
    unsafe { lance_transaction_close(transaction) };

    let reopened = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!reopened.is_null());
    assert_eq!(unsafe { lance_dataset_version(reopened) }, version);
    assert_eq!(unsafe { lance_dataset_index_count(reopened) }, 0);
    unsafe { lance_dataset_close(reopened) };
}

/// Helper: create a dataset with a List<Utf8> column for LabelList index testing.
fn create_label_list_dataset() -> (tempfile::TempDir, String) {
    use arrow_array::ListArray;
    use arrow_array::builder::{ListBuilder, StringBuilder};

    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp.path().join("ll_ds").to_str().unwrap().to_string();

    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new(
            "tags",
            DataType::List(Arc::new(Field::new("item", DataType::Utf8, true))),
            true,
        ),
    ]));

    let mut tag_builder = ListBuilder::new(StringBuilder::new());
    tag_builder.values().append_value("rust");
    tag_builder.values().append_value("ffi");
    tag_builder.append(true);
    tag_builder.values().append_value("cpp");
    tag_builder.append(true);
    let tags: ListArray = tag_builder.finish();

    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![Arc::new(Int32Array::from(vec![1, 2])), Arc::new(tags)],
    )
    .unwrap();

    lance_c::runtime::block_on(async {
        Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(batch)], schema),
            &uri,
            None,
        )
        .await
        .unwrap();
    });

    (tmp, uri)
}

/// Create a three-fragment dataset with stable row IDs and nullable columns
/// for the native NGram, ZoneMap and BloomFilter scalar-index families.
fn create_native_scalar_index_dataset() -> (tempfile::TempDir, String) {
    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp
        .path()
        .join("native_scalar_ds")
        .to_str()
        .unwrap()
        .to_string();
    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new("text", DataType::Utf8, true),
        Field::new("score", DataType::Int32, true),
        Field::new("rank", DataType::Int32, true),
    ]));
    let texts = vec![
        Some("alpha cat"),
        Some("beta catalog"),
        Some("gamma"),
        Some("cat scatter"),
        None,
        Some("rhino"),
        Some("catalog"),
        Some("bobcat"),
        Some("rhino horn"),
        Some("dog"),
        Some("cat"),
        Some("caterpillar"),
        Some("elephant"),
        Some("cat"),
        Some("catalog"),
        Some("scatter"),
        Some("rhino"),
        Some("dogma"),
    ];
    let mut scores = (0..18).map(|id| Some(id * 10)).collect::<Vec<_>>();
    scores[7] = None;
    scores[16] = None;
    let mut ranks = (0..18).map(|id| Some(id % 5)).collect::<Vec<_>>();
    ranks[4] = None;
    ranks[13] = None;
    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![
            Arc::new(Int32Array::from_iter_values(0..18)),
            Arc::new(StringArray::from(texts)),
            Arc::new(Int32Array::from(scores)),
            Arc::new(Int32Array::from(ranks)),
        ],
    )
    .unwrap();

    lance_c::runtime::block_on(async {
        let dataset = Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(batch)], schema),
            &uri,
            Some(lance::dataset::WriteParams {
                max_rows_per_file: 6,
                enable_stable_row_ids: true,
                ..Default::default()
            }),
        )
        .await
        .unwrap();
        assert_eq!(dataset.get_fragments().len(), 3);
    });

    (tmp, uri)
}

const MINHASH_BASE: &str = "the quick brown fox jumps over the lazy dog and runs away very fast";
const MINHASH_NEAR: &str = "the quick brown fox jumps over the lazy dog and runs away very quickly";
const MINHASH_UNRELATED: &str =
    "completely unrelated sentence about columnar storage in lance files";

fn create_minhash_dataset() -> (tempfile::TempDir, String) {
    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp
        .path()
        .join("minhash_lsh_ds")
        .to_str()
        .unwrap()
        .to_string();
    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new("text", DataType::Utf8, true),
    ]));
    let texts = vec![
        Some(MINHASH_BASE),
        Some(MINHASH_NEAR),
        Some(MINHASH_UNRELATED),
        Some(MINHASH_BASE),
        None,
        Some(""),
        Some("shared apple banana cherry"),
        Some("shared apple banana cherry dragonfruit"),
        Some("another unrelated row discussing vector indices and recall"),
        Some("yet another unrelated row discussing full text search tokenizers"),
        Some("a row about fragments compaction and stable row identifiers"),
        Some("a row about the manifest and transaction commit protocol"),
    ];
    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![
            Arc::new(Int32Array::from_iter_values(0..12)),
            Arc::new(StringArray::from(texts)),
        ],
    )
    .unwrap();

    lance_c::runtime::block_on(async {
        let dataset = Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(batch)], schema),
            &uri,
            Some(WriteParams {
                max_rows_per_file: 4,
                enable_stable_row_ids: true,
                ..Default::default()
            }),
        )
        .await
        .unwrap();
        assert_eq!(dataset.fragments().len(), 3);
    });

    (tmp, uri)
}

fn append_minhash_rows(uri: &str, first_id: i32, texts: &[Option<&str>]) {
    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new("text", DataType::Utf8, true),
    ]));
    let ids = Int32Array::from_iter_values(first_id..first_id + texts.len() as i32);
    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![Arc::new(ids), Arc::new(StringArray::from(texts.to_vec()))],
    )
    .unwrap();
    lance_c::runtime::block_on(async {
        let mut dataset = Dataset::open(uri).await.unwrap();
        dataset
            .append(
                arrow::record_batch::RecordBatchIterator::new(vec![Ok(batch)], schema),
                None,
            )
            .await
            .unwrap();
    });
}

fn native_minhash_hits<F>(
    uri: &str,
    text: &str,
    limit: i64,
    offset: Option<i64>,
    configure: F,
) -> Vec<(i32, f32)>
where
    F: FnOnce(&Dataset, &mut lance::dataset::scanner::Scanner),
{
    let uri = uri.to_string();
    let text = text.to_string();
    lance_c::runtime::block_on(async move {
        let dataset = Dataset::open(&uri).await.unwrap();
        let mut scanner = dataset.scan();
        scanner
            .minhash_search(NativeMinHashQuery::new(text, "text"))
            .unwrap();
        scanner.limit(Some(limit), offset).unwrap();
        configure(&dataset, &mut scanner);
        scanner.project(&["id"]).unwrap();
        let batch = scanner.try_into_batch().await.unwrap();
        let ids = batch["id"].as_any().downcast_ref::<Int32Array>().unwrap();
        let distances = batch["_distance"]
            .as_any()
            .downcast_ref::<Float32Array>()
            .unwrap();
        ids.values()
            .iter()
            .copied()
            .zip(distances.values().iter().copied())
            .collect()
    })
}

fn native_minhash_error<F>(
    uri: &str,
    column: &str,
    text: &str,
    limit: Option<i64>,
    configure: F,
) -> String
where
    F: FnOnce(&Dataset, &mut lance::dataset::scanner::Scanner),
{
    let uri = uri.to_string();
    let column = column.to_string();
    let text = text.to_string();
    lance_c::runtime::block_on(async move {
        let dataset = Dataset::open(&uri).await.unwrap();
        let mut scanner = dataset.scan();
        scanner
            .minhash_search(NativeMinHashQuery::new(text, column))
            .unwrap();
        if let Some(limit) = limit {
            scanner.limit(Some(limit), None).unwrap();
        }
        configure(&dataset, &mut scanner);
        scanner.project(&["id"]).unwrap();
        match scanner.try_into_batch().await {
            Ok(_) => panic!("expected native MinHash search to fail"),
            Err(error) => error.to_string(),
        }
    })
}

fn collect_minhash_hits(scanner: *mut LanceScanner) -> (SchemaRef, Vec<(i32, f32)>) {
    let (schema, batches) = collect_scanner(scanner);
    let mut hits = Vec::new();
    for batch in &batches {
        let ids = batch["id"].as_any().downcast_ref::<Int32Array>().unwrap();
        let distances = batch["_distance"]
            .as_any()
            .downcast_ref::<Float32Array>()
            .unwrap();
        hits.extend(
            ids.values()
                .iter()
                .copied()
                .zip(distances.values().iter().copied()),
        );
    }
    (schema, hits)
}

fn assert_minhash_hits_match(actual: &[(i32, f32)], expected: &[(i32, f32)]) {
    assert_eq!(
        actual.len(),
        expected.len(),
        "actual={actual:?} expected={expected:?}"
    );
    for ((actual_id, actual_distance), (expected_id, expected_distance)) in
        actual.iter().zip(expected)
    {
        assert_eq!(
            actual_id, expected_id,
            "actual={actual:?} expected={expected:?}"
        );
        assert!(
            (actual_distance - expected_distance).abs() <= 1e-6,
            "distance mismatch for id {actual_id}: {actual_distance} != {expected_distance}"
        );
    }
}

fn scan_index_ids(
    dataset: *const LanceDataset,
    filter: &str,
    use_scalar_index: bool,
) -> (Vec<i32>, CapturedScanStatistics) {
    let filter = c_str(filter);
    let scanner = unsafe { lance_scanner_new(dataset, ptr::null(), filter.as_ptr()) };
    assert!(!scanner.is_null(), "{}", take_last_error_message());
    assert_eq!(
        unsafe { lance_scanner_set_use_scalar_index(scanner, use_scalar_index) },
        0
    );

    let mut captured = CapturedScanStatistics::default();
    assert_eq!(
        unsafe {
            lance_scanner_set_statistics_callback(
                scanner,
                Some(capture_scan_statistics),
                (&mut captured as *mut CapturedScanStatistics).cast(),
            )
        },
        0
    );
    let mut stream = FFI_ArrowArrayStream::empty();
    assert_eq!(
        unsafe { lance_scanner_to_arrow_stream(scanner, &mut stream) },
        0,
        "{}",
        take_last_error_message()
    );

    let mut ids = Vec::new();
    let reader = unsafe { ArrowArrayStreamReader::from_raw(&mut stream) }.unwrap();
    for batch in reader {
        let batch = batch.unwrap();
        let column = batch.column_by_name("id").expect("scan includes id");
        ids.extend(
            column
                .as_any()
                .downcast_ref::<Int32Array>()
                .unwrap()
                .values()
                .iter()
                .copied(),
        );
    }
    unsafe { lance_scanner_close(scanner) };
    ids.sort_unstable();
    (ids, captured)
}

#[test]
fn test_native_scalar_index_families_create_query_and_lifecycle() {
    let (_tmp, uri) = create_native_scalar_index_dataset();
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null(), "{}", take_last_error_message());
    assert_eq!(unsafe { lance_dataset_fragment_count(ds) }, 3);

    let text = c_str("text");
    let score = c_str("score");
    let rank = c_str("rank");
    let zone_params = c_str(r#"{"rows_per_zone":2,"use_seeds":false}"#);
    let bloom_params = c_str(r#"{"number_of_items":8,"probability":0.01}"#);

    assert_eq!(
        unsafe {
            lance_dataset_create_scalar_index(
                ds,
                text.as_ptr(),
                c_str("text_ngram").as_ptr(),
                LanceScalarIndexType::NGram as i32,
                ptr::null(),
                false,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(
        unsafe {
            lance_dataset_create_scalar_index(
                ds,
                score.as_ptr(),
                c_str("score_zonemap").as_ptr(),
                LanceScalarIndexType::ZoneMap as i32,
                zone_params.as_ptr(),
                false,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(
        unsafe {
            lance_dataset_create_scalar_index(
                ds,
                rank.as_ptr(),
                c_str("rank_bloom").as_ptr(),
                LanceScalarIndexType::BloomFilter as i32,
                bloom_params.as_ptr(),
                false,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(unsafe { lance_dataset_index_count(ds) }, 3);

    let json_ptr = unsafe { lance_dataset_index_list_json(ds) };
    assert!(!json_ptr.is_null(), "{}", take_last_error_message());
    let json = unsafe { std::ffi::CStr::from_ptr(json_ptr) }
        .to_str()
        .unwrap()
        .to_string();
    unsafe { lance_free_string(json_ptr) };
    let entries: serde_json::Value = serde_json::from_str(&json).unwrap();
    let by_name = entries
        .as_array()
        .unwrap()
        .iter()
        .map(|entry| (entry["name"].as_str().unwrap(), entry))
        .collect::<std::collections::HashMap<_, _>>();
    for (name, index_type, column) in [
        ("text_ngram", "NGram", "text"),
        ("score_zonemap", "ZoneMap", "score"),
        ("rank_bloom", "BloomFilter", "rank"),
    ] {
        let entry = by_name
            .get(name)
            .unwrap_or_else(|| panic!("missing index {name}: {json}"));
        assert_eq!(entry["type"], index_type, "{json}");
        assert_eq!(entry["columns"], serde_json::json!([column]), "{json}");
    }

    let segments_ptr = unsafe { lance_dataset_index_segments_json(ds) };
    assert!(!segments_ptr.is_null(), "{}", take_last_error_message());
    let segments = unsafe { std::ffi::CStr::from_ptr(segments_ptr) }
        .to_str()
        .unwrap()
        .to_string();
    unsafe { lance_free_string(segments_ptr) };
    let segments: serde_json::Value = serde_json::from_str(&segments).unwrap();
    let by_name = segments
        .as_array()
        .unwrap()
        .iter()
        .map(|entry| (entry["name"].as_str().unwrap(), entry))
        .collect::<std::collections::HashMap<_, _>>();
    for (name, index_type) in [
        ("text_ngram", "NGram"),
        ("score_zonemap", "ZoneMap"),
        ("rank_bloom", "BloomFilter"),
    ] {
        let entry = by_name
            .get(name)
            .unwrap_or_else(|| panic!("missing segment {name}: {segments}"));
        assert_eq!(entry["type"], index_type, "{segments}");
        assert_eq!(entry["fragment_ids"], serde_json::json!([0, 1, 2]));
    }

    unsafe { lance_dataset_close(ds) };

    let assert_indexed = |filter: &str, expected: &[i32]| {
        let query_ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
        assert!(!query_ds.is_null(), "{}", take_last_error_message());
        let (indexed, stats) = scan_index_ids(query_ds, filter, true);
        assert_eq!(indexed.as_slice(), expected, "indexed filter: {filter}");
        assert!(
            stats.indices_loaded > 0,
            "filter must load a scalar index: {filter}"
        );
        let (unindexed, unindexed_stats) = scan_index_ids(query_ds, filter, false);
        assert_eq!(unindexed.as_slice(), expected, "unindexed filter: {filter}");
        assert_eq!(
            unindexed_stats.indices_loaded, 0,
            "disabled scalar index must not load an index: {filter}"
        );
        unsafe { lance_dataset_close(query_ds) };
    };

    assert_indexed(
        "contains(text, 'cat')",
        &[0, 1, 3, 6, 7, 10, 11, 13, 14, 15],
    );
    // `scatter` and `bobcat` contain the `cat` trigram but do not start with
    // it, so the exact recheck must remove those NGram candidates.
    assert_indexed("text LIKE 'cat%'", &[3, 6, 10, 11, 13, 14]);
    assert_indexed("contains(text, 'zzzz')", &[]);

    assert_indexed("score >= 100", &[10, 11, 12, 13, 14, 15, 17]);
    assert_indexed("score = 90", &[9]);
    assert_indexed("score = 999", &[]);
    assert_indexed("score IS NULL", &[7, 16]);

    assert_indexed("rank = 3", &[3, 8]);
    assert_indexed("rank IN (1, 4)", &[1, 6, 9, 11, 14, 16]);
    assert_indexed("rank = 42", &[]);
    assert_indexed("rank IS NULL", &[4, 13]);

    let prewarm_ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!prewarm_ds.is_null(), "{}", take_last_error_message());
    for name in ["text_ngram", "score_zonemap", "rank_bloom"] {
        assert_eq!(
            unsafe { lance_dataset_prewarm_index(prewarm_ds, c_str(name).as_ptr()) },
            0,
            "prewarm {name}: {}",
            take_last_error_message()
        );
    }
    unsafe { lance_dataset_close(prewarm_ds) };

    let reopened = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!reopened.is_null(), "{}", take_last_error_message());
    let (ids, stats) = scan_index_ids(reopened, "score = 90", true);
    assert_eq!(ids, vec![9]);
    assert!(stats.indices_loaded > 0);
    let (ids, stats) = scan_index_ids(reopened, "rank = 3", true);
    assert_eq!(ids, vec![3, 8]);
    assert!(stats.indices_loaded > 0);
    let (ids, stats) = scan_index_ids(reopened, "contains(text, 'cat')", true);
    assert_eq!(ids, vec![0, 1, 3, 6, 7, 10, 11, 13, 14, 15]);
    assert!(stats.indices_loaded > 0);

    assert_eq!(
        unsafe {
            lance_dataset_create_scalar_index(
                reopened,
                score.as_ptr(),
                c_str("score_zonemap").as_ptr(),
                LanceScalarIndexType::ZoneMap as i32,
                c_str(r#"{"rows_per_zone":4,"use_seeds":false}"#).as_ptr(),
                true,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(unsafe { lance_dataset_index_count(reopened) }, 3);
    let json_ptr = unsafe { lance_dataset_index_list_json(reopened) };
    assert!(!json_ptr.is_null(), "{}", take_last_error_message());
    let json = unsafe { std::ffi::CStr::from_ptr(json_ptr) }
        .to_str()
        .unwrap()
        .to_string();
    unsafe { lance_free_string(json_ptr) };
    let entries: serde_json::Value = serde_json::from_str(&json).unwrap();
    assert_eq!(
        entries
            .as_array()
            .unwrap()
            .iter()
            .filter(|entry| entry["name"].as_str() == Some("score_zonemap"))
            .count(),
        1,
        "{json}"
    );

    for name in ["text_ngram", "score_zonemap", "rank_bloom"] {
        assert_eq!(
            unsafe { lance_dataset_drop_index(reopened, c_str(name).as_ptr()) },
            0,
            "{}",
            take_last_error_message()
        );
    }
    assert_eq!(unsafe { lance_dataset_index_count(reopened) }, 0);
    unsafe { lance_dataset_close(reopened) };
}

#[test]
fn test_native_scalar_index_segment_metadata_types() {
    let (_tmp, uri) = create_native_scalar_index_dataset();
    let uri_c = c_str(&uri);
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null(), "{}", take_last_error_message());
    let fragment_id = 0_u32;
    let options = LanceIndexSegmentBuildOptions {
        fragment_ids: &fragment_id,
        fragment_count: 1,
        index_uuid: ptr::null(),
        ivf_centroids: ptr::null_mut(),
        ivf_centroids_schema: ptr::null(),
        pq_codebook: ptr::null_mut(),
        pq_codebook_schema: ptr::null(),
        mode: LanceIndexSegmentBuildMode::Auto as i32,
    };
    let zone_params = c_str(r#"{"rows_per_zone":2,"use_seeds":false}"#);
    let bloom_params = c_str(r#"{"number_of_items":8,"probability":0.01}"#);
    let minhash_params = c_str(r#"{"num_hashes":32,"num_bands":8,"shingle_size":2}"#);

    for (column, index_type, params, expected_type, details_suffix) in [
        (
            "text",
            LanceScalarIndexType::NGram,
            ptr::null(),
            5,
            "NGramIndexDetails",
        ),
        (
            "score",
            LanceScalarIndexType::ZoneMap,
            zone_params.as_ptr(),
            6,
            "ZoneMapIndexDetails",
        ),
        (
            "rank",
            LanceScalarIndexType::BloomFilter,
            bloom_params.as_ptr(),
            7,
            "BloomFilterIndexDetails",
        ),
        (
            "text",
            LanceScalarIndexType::MinHashLsh,
            minhash_params.as_ptr(),
            8,
            "MinHashLshIndexDetails",
        ),
    ] {
        let column = c_str(column);
        let builder = unsafe {
            lance_index_segment_builder_new_scalar(
                dataset,
                column.as_ptr(),
                ptr::null(),
                index_type as i32,
                params,
                &options,
            )
        };
        assert!(!builder.is_null(), "{}", take_last_error_message());
        let mut bytes = ptr::null_mut();
        let mut len = 0_usize;
        assert_eq!(
            unsafe {
                lance_index_segment_builder_execute_uncommitted(builder, &mut bytes, &mut len)
            },
            0,
            "{}",
            take_last_error_message()
        );
        let mut metadata = ptr::null_mut();
        assert_eq!(
            unsafe { lance_index_segment_metadata_parse(bytes, len, &mut metadata) },
            0
        );
        assert_eq!(
            unsafe { lance_index_segment_metadata_index_type(metadata) },
            expected_type
        );
        let type_url = unsafe {
            std::ffi::CStr::from_ptr(lance_index_segment_metadata_index_details_type_url(
                metadata,
            ))
            .to_str()
            .unwrap()
        };
        assert!(
            type_url.ends_with(details_suffix),
            "{details_suffix}: {type_url}"
        );
        assert_eq!(
            unsafe { lance_index_segment_metadata_fragment_count(metadata) },
            1
        );
        let mut actual_fragment = u32::MAX;
        let mut written = 0_usize;
        assert_eq!(
            unsafe {
                lance_index_segment_metadata_fragment_ids(
                    metadata,
                    &mut actual_fragment,
                    1,
                    &mut written,
                )
            },
            0
        );
        assert_eq!(written, 1);
        assert_eq!(actual_fragment, fragment_id);
        unsafe {
            lance_index_segment_metadata_free(metadata);
            lance_free_bytes(bytes);
            lance_index_segment_builder_free(builder);
        }
    }

    unsafe { lance_dataset_close(dataset) };
}

#[test]
fn test_native_scalar_index_native_parameter_and_type_validation() {
    let (_tmp, uri) = create_native_scalar_index_dataset();
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null(), "{}", take_last_error_message());
    let score = c_str("score");
    let rank = c_str("rank");
    let id = c_str("id");

    let rc = unsafe {
        lance_dataset_create_scalar_index(
            ds,
            score.as_ptr(),
            c_str("bad_zonemap").as_ptr(),
            LanceScalarIndexType::ZoneMap as i32,
            c_str(r#"{"rows_per_zone":0,"use_seeds":false}"#).as_ptr(),
            false,
        )
    };
    assert_eq!(rc, -1);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(
        message.contains("zone capacity must be greater than zero"),
        "{message}"
    );

    let rc = unsafe {
        lance_dataset_create_scalar_index(
            ds,
            rank.as_ptr(),
            c_str("bad_bloom").as_ptr(),
            LanceScalarIndexType::BloomFilter as i32,
            c_str(r#"{"number_of_items":8,"probability":1.0}"#).as_ptr(),
            false,
        )
    };
    assert_eq!(rc, -1);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(
        message.contains("Failed to build SBBF") || message.contains("InvalidFpp"),
        "{message}"
    );

    let rc = unsafe {
        lance_dataset_create_scalar_index(
            ds,
            id.as_ptr(),
            c_str("bad_ngram").as_ptr(),
            LanceScalarIndexType::NGram as i32,
            ptr::null(),
            false,
        )
    };
    assert_eq!(rc, -1);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(message.contains("Utf8"), "{message}");

    let rc = unsafe {
        lance_dataset_create_scalar_index(
            ds,
            id.as_ptr(),
            c_str("bad_type").as_ptr(),
            99,
            ptr::null(),
            false,
        )
    };
    assert_eq!(rc, -1);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(take_last_error_message().contains("invalid scalar index type: 99"));

    let text = c_str("text");
    for (name, params, expected) in [
        (
            "bad_minhash_zero_bands",
            r#"{"num_bands":0}"#,
            "1 <= num_bands <= 256",
        ),
        (
            "bad_minhash_divisibility",
            r#"{"num_hashes":64,"num_bands":3}"#,
            "num_hashes to be a multiple of num_bands",
        ),
        (
            "bad_minhash_unknown",
            r#"{"signature_version":0}"#,
            "unknown field",
        ),
    ] {
        let rc = unsafe {
            lance_dataset_create_scalar_index(
                ds,
                text.as_ptr(),
                c_str(name).as_ptr(),
                LanceScalarIndexType::MinHashLsh as i32,
                c_str(params).as_ptr(),
                false,
            )
        };
        assert_eq!(rc, -1, "{name}");
        assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
        let message = take_last_error_message();
        assert!(message.contains(expected), "{name}: {message}");
    }

    let rc = unsafe {
        lance_dataset_create_scalar_index(
            ds,
            id.as_ptr(),
            c_str("bad_minhash_type").as_ptr(),
            LanceScalarIndexType::MinHashLsh as i32,
            ptr::null(),
            false,
        )
    };
    assert_eq!(rc, -1);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(
        take_last_error_message().contains("string column"),
        "MinHash must reject non-string columns natively"
    );

    let rc = unsafe {
        lance_dataset_create_scalar_index(
            ptr::null_mut(),
            id.as_ptr(),
            ptr::null(),
            LanceScalarIndexType::ZoneMap as i32,
            ptr::null(),
            false,
        )
    };
    assert_eq!(rc, -1);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(take_last_error_message().contains("dataset and column must not be NULL"));

    assert_eq!(unsafe { lance_dataset_index_count(ds) }, 0);
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_minhash_lsh_index_search_and_lifecycle() {
    let (_tmp, uri) = create_minhash_dataset();
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null(), "{}", take_last_error_message());
    assert_eq!(unsafe { lance_dataset_fragment_count(ds) }, 3);
    let mut stable_row_ids = false;
    assert_eq!(
        unsafe { lance_dataset_has_stable_row_ids(ds, &mut stable_row_ids) },
        0
    );
    assert!(stable_row_ids);

    let column = c_str("text");
    let index_name = c_str("text_minhash");
    assert_eq!(
        unsafe {
            lance_dataset_create_scalar_index(
                ds,
                column.as_ptr(),
                index_name.as_ptr(),
                LanceScalarIndexType::MinHashLsh as i32,
                ptr::null(),
                false,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(unsafe { lance_dataset_index_count(ds) }, 1);

    let index_list = take_scanner_string(unsafe { lance_dataset_index_list_json(ds) });
    let indices: serde_json::Value = serde_json::from_str(&index_list).unwrap();
    let minhash_index = indices
        .as_array()
        .unwrap()
        .iter()
        .find(|entry| entry["name"] == "text_minhash")
        .unwrap_or_else(|| panic!("missing MinHash index: {index_list}"));
    assert_eq!(minhash_index["type"], "MinHashLsh", "{index_list}");
    assert_eq!(minhash_index["columns"], serde_json::json!(["text"]));

    let segments_json = take_scanner_string(unsafe { lance_dataset_index_segments_json(ds) });
    let segments: serde_json::Value = serde_json::from_str(&segments_json).unwrap();
    let minhash_segment = segments
        .as_array()
        .unwrap()
        .iter()
        .find(|entry| entry["name"] == "text_minhash")
        .unwrap_or_else(|| panic!("missing MinHash segment: {segments_json}"));
    assert_eq!(minhash_segment["type"], "MinHashLsh", "{segments_json}");
    assert_eq!(
        minhash_segment["fragment_ids"],
        serde_json::json!([0, 1, 2])
    );

    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null(), "{}", take_last_error_message());
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(scanner, column.as_ptr(), c_str(MINHASH_BASE).as_ptr())
        },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(unsafe { lance_scanner_set_limit(scanner, 3) }, 0);
    let (schema, hits) = collect_minhash_hits(scanner);
    assert!(schema.field_with_name("_distance").is_ok(), "{schema:?}");
    assert_eq!(hits[0], (0, 0.0));
    assert_eq!(hits[1], (3, 0.0));
    let native_hits = native_minhash_hits(&uri, MINHASH_BASE, 3, None, |_, _| {});
    assert_minhash_hits_match(&hits, &native_hits);
    unsafe { lance_scanner_close(scanner) };

    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(scanner, column.as_ptr(), c_str(MINHASH_NEAR).as_ptr())
        },
        0
    );
    assert_eq!(unsafe { lance_scanner_set_limit(scanner, 2) }, 0);
    let (_, near_hits) = collect_minhash_hits(scanner);
    assert_eq!(near_hits[0].0, 1);
    assert_eq!(near_hits[0].1, 0.0);
    let native_near = native_minhash_hits(&uri, MINHASH_NEAR, 2, None, |_, _| {});
    assert_minhash_hits_match(&near_hits, &native_near);
    unsafe { lance_scanner_close(scanner) };

    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe { lance_scanner_set_minhash_query(scanner, column.as_ptr(), c"".as_ptr()) },
        0
    );
    assert_eq!(unsafe { lance_scanner_set_limit(scanner, 3) }, 0);
    let (_, empty_text_hits) = collect_minhash_hits(scanner);
    assert!(empty_text_hits.is_empty(), "{empty_text_hits:?}");
    assert!(native_minhash_hits(&uri, "", 3, None, |_, _| {}).is_empty());
    unsafe { lance_scanner_close(scanner) };

    assert_eq!(
        unsafe { lance_dataset_prewarm_index(ds, index_name.as_ptr()) },
        0,
        "{}",
        take_last_error_message()
    );
    unsafe { lance_dataset_close(ds) };

    let reopened = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!reopened.is_null(), "{}", take_last_error_message());
    let scanner = unsafe { lance_scanner_new(reopened, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(
                scanner,
                column.as_ptr(),
                c_str(MINHASH_UNRELATED).as_ptr(),
            )
        },
        0
    );
    assert_eq!(unsafe { lance_scanner_set_limit(scanner, 1) }, 0);
    let (_, unrelated_hits) = collect_minhash_hits(scanner);
    assert_eq!(unrelated_hits, vec![(2, 0.0)]);
    unsafe { lance_scanner_close(scanner) };

    let custom_params = c_str(r#"{"num_hashes":64,"num_bands":16,"shingle_size":2}"#);
    assert_eq!(
        unsafe {
            lance_dataset_create_scalar_index(
                reopened,
                column.as_ptr(),
                index_name.as_ptr(),
                LanceScalarIndexType::MinHashLsh as i32,
                custom_params.as_ptr(),
                true,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(unsafe { lance_dataset_index_count(reopened) }, 1);
    let scanner = unsafe { lance_scanner_new(reopened, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(scanner, column.as_ptr(), c_str(MINHASH_BASE).as_ptr())
        },
        0
    );
    assert_eq!(unsafe { lance_scanner_set_limit(scanner, 4) }, 0);
    let (_, replaced_hits) = collect_minhash_hits(scanner);
    assert_eq!(replaced_hits[0], (0, 0.0));
    assert_eq!(replaced_hits[1], (3, 0.0));
    let native_replaced = native_minhash_hits(&uri, MINHASH_BASE, 4, None, |_, _| {});
    assert_minhash_hits_match(&replaced_hits, &native_replaced);
    unsafe { lance_scanner_close(scanner) };

    assert_eq!(
        unsafe { lance_dataset_drop_index(reopened, index_name.as_ptr()) },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(unsafe { lance_dataset_index_count(reopened) }, 0);
    unsafe { lance_dataset_close(reopened) };
}

#[test]
fn test_minhash_search_partial_coverage_filters_masks_and_projection() {
    let (_tmp, uri) = create_minhash_dataset();
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null(), "{}", take_last_error_message());
    let column = c_str("text");
    let index_name = c_str("text_minhash");
    let params = c_str(r#"{"num_hashes":64,"num_bands":16,"shingle_size":3}"#);
    assert_eq!(
        unsafe {
            lance_dataset_create_scalar_index(
                ds,
                column.as_ptr(),
                index_name.as_ptr(),
                LanceScalarIndexType::MinHashLsh as i32,
                params.as_ptr(),
                false,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    unsafe { lance_dataset_close(ds) };

    append_minhash_rows(&uri, 12, &[Some(MINHASH_BASE), Some(MINHASH_BASE)]);
    lance_c::runtime::block_on(async {
        let mut dataset = Dataset::open(&uri).await.unwrap();
        dataset.delete("id = 1").await.unwrap();
        assert_eq!(dataset.fragments().len(), 4);
    });

    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null(), "{}", take_last_error_message());
    assert_eq!(unsafe { lance_dataset_fragment_count(ds) }, 4);

    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(scanner, column.as_ptr(), c_str(MINHASH_BASE).as_ptr())
        },
        0
    );
    assert_eq!(unsafe { lance_scanner_set_limit(scanner, 4) }, 0);
    let (_, hits) = collect_minhash_hits(scanner);
    assert_eq!(hits, vec![(0, 0.0), (3, 0.0), (12, 0.0), (13, 0.0)]);
    let native_hits = native_minhash_hits(&uri, MINHASH_BASE, 4, None, |_, _| {});
    assert_minhash_hits_match(&hits, &native_hits);
    unsafe { lance_scanner_close(scanner) };

    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(scanner, column.as_ptr(), c_str(MINHASH_BASE).as_ptr())
        },
        0
    );
    assert_eq!(unsafe { lance_scanner_set_limit(scanner, 2) }, 0);
    assert_eq!(unsafe { lance_scanner_set_offset(scanner, 1) }, 0);
    let (_, offset_hits) = collect_minhash_hits(scanner);
    let native_offset = native_minhash_hits(&uri, MINHASH_BASE, 2, Some(1), |_, _| {});
    assert_minhash_hits_match(&offset_hits, &native_offset);
    unsafe { lance_scanner_close(scanner) };

    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(scanner, column.as_ptr(), c_str(MINHASH_BASE).as_ptr())
        },
        0
    );
    assert_eq!(unsafe { lance_scanner_set_limit(scanner, 4) }, 0);
    assert_eq!(unsafe { lance_scanner_set_fast_search(scanner, true) }, 0);
    let (_, fast_hits) = collect_minhash_hits(scanner);
    assert_eq!(fast_hits, vec![(0, 0.0), (3, 0.0)]);
    let native_fast = native_minhash_hits(&uri, MINHASH_BASE, 4, None, |_, scan| {
        scan.fast_search();
    });
    assert_minhash_hits_match(&fast_hits, &native_fast);
    unsafe { lance_scanner_close(scanner) };

    for prefilter in [true, false] {
        let filter = c_str("id >= 1");
        let scanner = unsafe { lance_scanner_new(ds, ptr::null(), filter.as_ptr()) };
        assert!(!scanner.is_null());
        assert_eq!(
            unsafe {
                lance_scanner_set_minhash_query(
                    scanner,
                    column.as_ptr(),
                    c_str(MINHASH_BASE).as_ptr(),
                )
            },
            0
        );
        assert_eq!(unsafe { lance_scanner_set_limit(scanner, 2) }, 0);
        assert_eq!(
            unsafe { lance_scanner_set_prefilter(scanner, prefilter) },
            0
        );
        let (_, filtered_hits) = collect_minhash_hits(scanner);
        let native_filtered = native_minhash_hits(&uri, MINHASH_BASE, 2, None, |_, scan| {
            scan.filter("id >= 1").unwrap().prefilter(prefilter);
        });
        assert_minhash_hits_match(&filtered_hits, &native_filtered);
        unsafe { lance_scanner_close(scanner) };
    }

    let row_ids = ordering_row_ids(ds);
    let append_row_12 = row_ids[&12];
    let append_row_13 = row_ids[&13];
    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    let allowed = [append_row_12, append_row_13];
    let blocked = [append_row_12];
    assert_eq!(
        unsafe { lance_scanner_set_row_addr_allowlist(scanner, allowed.as_ptr(), allowed.len()) },
        0
    );
    assert_eq!(
        unsafe { lance_scanner_set_row_addr_blocklist(scanner, blocked.as_ptr(), blocked.len()) },
        0
    );
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(scanner, column.as_ptr(), c_str(MINHASH_BASE).as_ptr())
        },
        0
    );
    assert_eq!(unsafe { lance_scanner_set_limit(scanner, 1) }, 0);
    let (_, masked_hits) = collect_minhash_hits(scanner);
    assert_eq!(masked_hits, vec![(13, 0.0)]);
    let native_masked = native_minhash_hits(&uri, MINHASH_BASE, 1, None, |_, scan| {
        let allowed = NativeRowAddrTreeMap::from_iter([append_row_13]);
        let blocked = NativeRowAddrTreeMap::from_iter([append_row_12]);
        scan.with_row_id_prefilter(NativeRowAddrMask::from_allowed(allowed).also_block(blocked));
    });
    assert_minhash_hits_match(&masked_hits, &native_masked);
    unsafe { lance_scanner_close(scanner) };

    let mut fragment_ids = vec![0_u64; 4];
    assert_eq!(
        unsafe { lance_dataset_fragment_ids(ds, fragment_ids.as_mut_ptr()) },
        0
    );
    let appended_fragment = fragment_ids[3];
    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe { lance_scanner_set_fragment_ids(scanner, &appended_fragment, 1) },
        0
    );
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(scanner, column.as_ptr(), c_str(MINHASH_BASE).as_ptr())
        },
        0
    );
    assert_eq!(unsafe { lance_scanner_set_limit(scanner, 2) }, 0);
    let (_, fragment_hits) = collect_minhash_hits(scanner);
    assert_eq!(fragment_hits, vec![(12, 0.0), (13, 0.0)]);
    let native_fragment = native_minhash_hits(&uri, MINHASH_BASE, 2, None, |dataset, scan| {
        scan.with_fragments(vec![dataset.fragments().last().unwrap().clone()]);
    });
    assert_minhash_hits_match(&fragment_hits, &native_fragment);
    unsafe { lance_scanner_close(scanner) };

    let next_id_name = c_str("next_id");
    let id_expression = c_str("id + 1");
    let body_name = c_str("body");
    let text_expression = c_str("text");
    let distance_name = c_str("distance");
    let distance_expression = c_str("_distance");
    let projection = [
        LanceProjectionColumn {
            output_name: next_id_name.as_ptr(),
            expression: id_expression.as_ptr(),
        },
        LanceProjectionColumn {
            output_name: body_name.as_ptr(),
            expression: text_expression.as_ptr(),
        },
        LanceProjectionColumn {
            output_name: distance_name.as_ptr(),
            expression: distance_expression.as_ptr(),
        },
    ];
    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe { lance_scanner_set_projection(scanner, projection.as_ptr(), projection.len()) },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(
        unsafe { lance_scanner_disable_scoring_autoprojection(scanner) },
        0
    );
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(scanner, column.as_ptr(), c_str(MINHASH_BASE).as_ptr())
        },
        0
    );
    assert_eq!(unsafe { lance_scanner_set_limit(scanner, 1) }, 0);
    let (schema, batches) = collect_scanner(scanner);
    assert!(schema.field_with_name("next_id").is_ok(), "{schema:?}");
    assert!(schema.field_with_name("body").is_ok(), "{schema:?}");
    assert!(schema.field_with_name("distance").is_ok(), "{schema:?}");
    assert!(schema.field_with_name("_distance").is_err(), "{schema:?}");
    assert_eq!(batches.len(), 1);
    let next_id = batches[0]["next_id"]
        .as_any()
        .downcast_ref::<Int32Array>()
        .unwrap();
    let body = batches[0]["body"]
        .as_any()
        .downcast_ref::<StringArray>()
        .unwrap();
    let distance = batches[0]["distance"]
        .as_any()
        .downcast_ref::<Float32Array>()
        .unwrap();
    assert_eq!(next_id.value(0), 1);
    assert_eq!(body.value(0), MINHASH_BASE);
    assert_eq!(distance.value(0), 0.0);
    unsafe { lance_scanner_close(scanner) };

    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(scanner, column.as_ptr(), c_str(MINHASH_BASE).as_ptr())
        },
        0
    );
    assert_eq!(unsafe { lance_scanner_set_limit(scanner, 3) }, 0);
    let schema = scanner_introspection_schema(scanner);
    assert!(schema.field_with_name("_distance").is_ok(), "{schema:?}");
    let explain = take_scanner_string(unsafe { lance_scanner_explain_plan(scanner, false) });
    assert!(explain.contains("MinHashSearch"), "{explain}");
    assert!(explain.contains("MinHashFlatSearch"), "{explain}");
    let analyze = take_scanner_string(unsafe { lance_scanner_analyze_plan(scanner) });
    assert!(!analyze.is_empty());
    unsafe { lance_scanner_close(scanner) };

    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_minhash_search_validation_copy_and_native_errors() {
    let (_tmp, uri) = create_minhash_dataset();
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null(), "{}", take_last_error_message());
    let column = c_str("text");
    let index_name = c_str("text_minhash");
    assert_eq!(
        unsafe {
            lance_dataset_create_scalar_index(
                ds,
                column.as_ptr(),
                index_name.as_ptr(),
                LanceScalarIndexType::MinHashLsh as i32,
                ptr::null(),
                false,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );

    let mut column_buffer = c_str("text").into_bytes_with_nul();
    let mut text_buffer = c_str(MINHASH_UNRELATED).into_bytes_with_nul();
    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(
                scanner,
                column_buffer.as_ptr().cast(),
                text_buffer.as_ptr().cast(),
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    column_buffer[0] = b'z';
    text_buffer[0] = b'z';
    assert_eq!(unsafe { lance_scanner_set_limit(scanner, 1) }, 0);
    let (_, copied_hits) = collect_minhash_hits(scanner);
    assert_eq!(copied_hits, vec![(2, 0.0)]);
    unsafe { lance_scanner_close(scanner) };

    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(scanner, column.as_ptr(), c_str(MINHASH_BASE).as_ptr())
        },
        0
    );
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(scanner, c"".as_ptr(), c_str(MINHASH_NEAR).as_ptr())
        },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(message.contains("column to search"), "{message}");
    assert_eq!(unsafe { lance_scanner_set_limit(scanner, 2) }, 0);
    let (_, retained_hits) = collect_minhash_hits(scanner);
    assert_eq!(retained_hits[0], (0, 0.0));
    assert_eq!(retained_hits[1], (3, 0.0));
    unsafe { lance_scanner_close(scanner) };

    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(scanner, ptr::null(), c_str(MINHASH_BASE).as_ptr())
        },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(
        take_last_error_message().contains("column must not be NULL"),
        "NULL column must be rejected"
    );
    assert_eq!(
        unsafe { lance_scanner_set_minhash_query(scanner, column.as_ptr(), ptr::null()) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(
        take_last_error_message().contains("text must not be NULL"),
        "NULL text must be rejected"
    );
    unsafe { lance_scanner_close(scanner) };

    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(scanner, c"".as_ptr(), c_str(MINHASH_BASE).as_ptr())
        },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(
        take_last_error_message().contains("column to search"),
        "empty column must fail during native query construction"
    );
    let native_message = lance_c::runtime::block_on(async {
        let dataset = Dataset::open(&uri).await.unwrap();
        let mut scanner = dataset.scan();
        match scanner.minhash_search(NativeMinHashQuery::new(MINHASH_BASE, "")) {
            Ok(_) => panic!("empty MinHash column must fail natively"),
            Err(error) => error.to_string(),
        }
    });
    assert!(
        native_message.contains("column to search"),
        "{native_message}"
    );
    unsafe { lance_scanner_close(scanner) };

    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(scanner, column.as_ptr(), c_str(MINHASH_BASE).as_ptr())
        },
        0
    );
    let mut stream = FFI_ArrowArrayStream::empty();
    assert_eq!(
        unsafe { lance_scanner_to_arrow_stream(scanner, &mut stream) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(
        take_last_error_message().contains("requires a limit"),
        "native MinHash limit validation must be preserved"
    );
    let native_message = native_minhash_error(&uri, "text", MINHASH_BASE, None, |_, _| {});
    assert!(
        native_message.contains("requires a limit"),
        "{native_message}"
    );
    unsafe { lance_scanner_close(scanner) };

    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(scanner, column.as_ptr(), c_str(MINHASH_BASE).as_ptr())
        },
        0
    );
    assert_eq!(unsafe { lance_scanner_set_limit(scanner, 3) }, 0);
    assert_eq!(unsafe { lance_scanner_count_rows(scanner) }, 0);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(
        take_last_error_message().contains("Cannot use limit/offset with aggregate"),
        "MinHash count must preserve native aggregate planning"
    );
    unsafe { lance_scanner_close(scanner) };

    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(scanner, c"id".as_ptr(), c_str(MINHASH_BASE).as_ptr())
        },
        0
    );
    assert_eq!(unsafe { lance_scanner_set_limit(scanner, 3) }, 0);
    let mut stream = FFI_ArrowArrayStream::empty();
    assert_eq!(
        unsafe { lance_scanner_to_arrow_stream(scanner, &mut stream) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(
        message.contains("No MinHash LSH index found for column id"),
        "{message}"
    );
    let native_message = native_minhash_error(&uri, "id", MINHASH_BASE, Some(3), |_, _| {});
    assert!(
        native_message.contains("No MinHash LSH index found for column id"),
        "{native_message}"
    );
    unsafe { lance_scanner_close(scanner) };

    let fts_params = c_str(r#"{"base_tokenizer":"simple","language":"English"}"#);
    assert_eq!(
        unsafe {
            lance_dataset_create_scalar_index(
                ds,
                column.as_ptr(),
                c"text_fts".as_ptr(),
                LanceScalarIndexType::Inverted as i32,
                fts_params.as_ptr(),
                false,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(scanner, column.as_ptr(), c_str(MINHASH_BASE).as_ptr())
        },
        0
    );
    let fts_columns = [column.as_ptr(), ptr::null()];
    assert_eq!(
        unsafe {
            lance_scanner_full_text_search(scanner, c"fox".as_ptr(), fts_columns.as_ptr(), 0)
        },
        0
    );
    assert_eq!(unsafe { lance_scanner_set_limit(scanner, 3) }, 0);
    let mut stream = FFI_ArrowArrayStream::empty();
    assert_eq!(
        unsafe { lance_scanner_to_arrow_stream(scanner, &mut stream) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(
        message.contains("Cannot combine a MinHash search"),
        "{message}"
    );
    let native_message = native_minhash_error(&uri, "text", MINHASH_BASE, Some(3), |_, scan| {
        scan.full_text_search(FullTextSearchQuery::new("fox".to_string()))
            .unwrap();
    });
    assert!(
        native_message.contains("Cannot combine a MinHash search"),
        "{native_message}"
    );
    unsafe { lance_scanner_close(scanner) };

    lance_c::runtime::block_on(async {
        let mut dataset = Dataset::open(&uri).await.unwrap();
        dataset.delete("id = 3").await.unwrap();
    });
    unsafe { lance_dataset_close(ds) };
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null(), "{}", take_last_error_message());
    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(unsafe { lance_scanner_with_row_id(scanner, true) }, 0);
    assert_eq!(
        unsafe { lance_scanner_set_include_deleted_rows(scanner, true) },
        0
    );
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(scanner, column.as_ptr(), c_str(MINHASH_BASE).as_ptr())
        },
        0
    );
    assert_eq!(unsafe { lance_scanner_set_limit(scanner, 3) }, 0);
    let mut stream = FFI_ArrowArrayStream::empty();
    assert_eq!(
        unsafe { lance_scanner_to_arrow_stream(scanner, &mut stream) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(message.contains("deleted rows"), "{message}");
    let native_message = native_minhash_error(&uri, "text", MINHASH_BASE, Some(3), |_, scan| {
        scan.with_row_id();
        scan.include_deleted_rows();
    });
    assert!(native_message.contains("deleted rows"), "{native_message}");
    unsafe { lance_scanner_close(scanner) };

    assert_eq!(
        unsafe {
            lance_dataset_create_scalar_index(
                ds,
                c"id".as_ptr(),
                c"id_btree".as_ptr(),
                LanceScalarIndexType::BTree as i32,
                ptr::null(),
                false,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    let mut segment_uuid = [0_u8; 16];
    let mut segment_count = 0_u64;
    assert_eq!(
        unsafe {
            lance_dataset_index_segments(
                ds,
                c"id_btree".as_ptr(),
                segment_uuid.as_mut_ptr(),
                1,
                &mut segment_count,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(segment_count, 1);
    let mut fragments = vec![0_u64; 3];
    let fragment_count = unsafe { lance_dataset_fragment_count(ds) } as usize;
    fragments.resize(fragment_count, 0);
    assert_eq!(
        unsafe { lance_dataset_fragment_ids(ds, fragments.as_mut_ptr()) },
        0
    );
    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), c"id >= 0".as_ptr()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe { lance_scanner_set_fragment_ids(scanner, fragments.as_ptr(), fragments.len()) },
        0
    );
    assert_eq!(
        unsafe { lance_scanner_set_scalar_index_segment(scanner, segment_uuid.as_ptr()) },
        0
    );
    assert_eq!(
        unsafe {
            lance_scanner_set_minhash_query(scanner, column.as_ptr(), c_str(MINHASH_BASE).as_ptr())
        },
        0
    );
    assert_eq!(unsafe { lance_scanner_set_limit(scanner, 3) }, 0);
    let mut stream = FFI_ArrowArrayStream::empty();
    assert_eq!(
        unsafe { lance_scanner_to_arrow_stream(scanner, &mut stream) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(
        message.contains("scalar_index_segment requires an ordinary scan")
            && message.contains("MinHash"),
        "{message}"
    );
    unsafe { lance_scanner_close(scanner) };
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_native_zonemap_use_seeds_param() {
    let (_tmp, uri) = create_native_scalar_index_dataset();
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null(), "{}", take_last_error_message());
    let score = c_str("score");
    assert_eq!(
        unsafe {
            lance_dataset_create_scalar_index(
                ds,
                score.as_ptr(),
                c_str("score_zonemap_seeds").as_ptr(),
                LanceScalarIndexType::ZoneMap as i32,
                c_str(r#"{"rows_per_zone":2,"use_seeds":true}"#).as_ptr(),
                false,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(unsafe { lance_dataset_index_count(ds) }, 1);
    unsafe { lance_dataset_close(ds) };

    let query_ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!query_ds.is_null(), "{}", take_last_error_message());
    let (ids, stats) = scan_index_ids(query_ds, "score >= 100", true);
    assert_eq!(ids, vec![10, 11, 12, 13, 14, 15, 17]);
    assert!(stats.indices_loaded > 0);
    unsafe { lance_dataset_close(query_ds) };
}

