/// Helper: create a dataset with a FixedSizeList<Float32> column for vector index testing.
fn create_vector_dataset(num_rows: i32, dim: i32) -> (tempfile::TempDir, String) {
    use arrow_array::FixedSizeListArray;
    use arrow_array::builder::{FixedSizeListBuilder, Float32Builder};

    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp.path().join("vec_ds").to_str().unwrap().to_string();

    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new(
            "embedding",
            DataType::FixedSizeList(Arc::new(Field::new("item", DataType::Float32, true)), dim),
            false,
        ),
        Field::new("text", DataType::Utf8, true),
    ]));

    let mut emb_builder = FixedSizeListBuilder::new(Float32Builder::new(), dim);
    let texts: Vec<String> = (0..num_rows).map(|i| format!("doc {i}")).collect();
    let mut rng_seed: u32 = 1;
    for _ in 0..num_rows {
        for _ in 0..dim {
            // simple deterministic pseudo-random in [0,1)
            rng_seed = rng_seed.wrapping_mul(1664525).wrapping_add(1013904223);
            emb_builder
                .values()
                .append_value((rng_seed as f32) / (u32::MAX as f32));
        }
        emb_builder.append(true);
    }
    let embeddings: FixedSizeListArray = emb_builder.finish();
    let text_refs: Vec<&str> = texts.iter().map(|s| s.as_str()).collect();

    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![
            Arc::new(Int32Array::from((0..num_rows).collect::<Vec<_>>())),
            Arc::new(embeddings) as Arc<dyn arrow_array::Array>,
            Arc::new(StringArray::from(text_refs)),
        ],
    )
    .unwrap();

    lance_c::runtime::block_on(async {
        Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(batch)], schema),
            &uri,
            None,
        )
        .await
        .unwrap();
    });

    (tmp, uri)
}

/// Create `num_fragments` vector fragments with deterministic vectors.
/// Component `i` of global row `id` is `id as f32 + i as f32 / dim as f32`,
/// keeping nearest-neighbor orderings unambiguous.
fn create_multi_fragment_vector_dataset(
    num_fragments: i32,
    rows_per_fragment: i32,
    dim: i32,
    enable_stable_row_ids: bool,
) -> (tempfile::TempDir, String) {
    use arrow_array::builder::{FixedSizeListBuilder, Float32Builder};

    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp
        .path()
        .join("multi_vec_ds")
        .to_str()
        .unwrap()
        .to_string();
    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new(
            "embedding",
            DataType::FixedSizeList(Arc::new(Field::new("item", DataType::Float32, true)), dim),
            false,
        ),
    ]));

    lance_c::runtime::block_on(async {
        for fragment in 0..num_fragments {
            let mut vectors = FixedSizeListBuilder::new(Float32Builder::new(), dim);
            for row in 0..rows_per_fragment {
                for component in 0..dim {
                    vectors.values().append_value(
                        (fragment * rows_per_fragment + row) as f32 + component as f32 / dim as f32,
                    );
                }
                vectors.append(true);
            }
            let ids = (0..rows_per_fragment)
                .map(|row| fragment * rows_per_fragment + row)
                .collect::<Vec<_>>();
            let batch = RecordBatch::try_new(
                schema.clone(),
                vec![Arc::new(Int32Array::from(ids)), Arc::new(vectors.finish())],
            )
            .unwrap();
            let params = lance::dataset::WriteParams {
                mode: if fragment > 0 {
                    lance::dataset::WriteMode::Append
                } else {
                    lance::dataset::WriteMode::Create
                },
                enable_stable_row_ids,
                ..Default::default()
            };
            Dataset::write(
                arrow::record_batch::RecordBatchIterator::new(vec![Ok(batch)], schema.clone()),
                &uri,
                Some(params),
            )
            .await
            .unwrap();
        }
    });

    (tmp, uri)
}

fn create_float16_vector_dataset(num_rows: i32, dim: i32) -> (tempfile::TempDir, String) {
    use arrow_array::PrimitiveArray;
    use arrow_array::types::Float16Type;
    use half::f16;

    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp.path().join("f16_vec_ds").to_str().unwrap().to_string();
    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new(
            "embedding",
            DataType::FixedSizeList(Arc::new(Field::new("item", DataType::Float16, true)), dim),
            false,
        ),
    ]));
    let values = (0..num_rows)
        .flat_map(|row| {
            (0..dim).map(move |component| f16::from_f32(row as f32 + component as f32 / dim as f32))
        })
        .collect::<Vec<_>>();
    let embeddings = arrow_array::FixedSizeListArray::try_new(
        Arc::new(Field::new("item", DataType::Float16, true)),
        dim,
        Arc::new(PrimitiveArray::<Float16Type>::from(values)),
        None,
    )
    .unwrap();
    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![
            Arc::new(Int32Array::from((0..num_rows).collect::<Vec<_>>())),
            Arc::new(embeddings),
        ],
    )
    .unwrap();
    lance_c::runtime::block_on(async {
        Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(batch)], schema),
            &uri,
            None,
        )
        .await
        .unwrap();
    });
    (tmp, uri)
}

fn train_segment_pq_models(
    dataset: *const LanceDataset,
    column: &CString,
    metric: LanceMetricType,
) -> (
    FFI_ArrowArray,
    FFI_ArrowSchema,
    FFI_ArrowArray,
    FFI_ArrowSchema,
) {
    let mut centroids = FFI_ArrowArray::empty();
    let mut centroids_schema = FFI_ArrowSchema::empty();
    assert_eq!(
        unsafe {
            lance_index_train_ivf_model(
                dataset,
                column.as_ptr(),
                2,
                metric as i32,
                ptr::null(),
                0,
                &mut centroids,
                &mut centroids_schema,
            )
        },
        0
    );

    let mut codebook = FFI_ArrowArray::empty();
    let mut codebook_schema = FFI_ArrowSchema::empty();
    assert_eq!(
        unsafe {
            lance_index_train_pq_model(
                dataset,
                column.as_ptr(),
                2,
                4,
                metric as i32,
                ptr::null(),
                0,
                &mut centroids,
                &centroids_schema,
                &mut codebook,
                &mut codebook_schema,
            )
        },
        0
    );

    (centroids, centroids_schema, codebook, codebook_schema)
}

fn vector_index_options(
    index_type: LanceVectorIndexType,
    metric: LanceMetricType,
) -> LanceVectorIndexOptions {
    let mut options = unsafe { std::mem::zeroed::<LanceVectorIndexOptions>() };
    options.index_type = index_type as i32;
    options.metric = metric as i32;
    options.index_file_version = LanceIndexFileVersion::V3 as i32;
    options
}

fn set_option(value: u64) -> LanceOptionalU64 {
    LanceOptionalU64 {
        value,
        is_set: true,
    }
}

fn nearest_ids_and_statistics(
    dataset: *mut LanceDataset,
    column: &str,
    query: &[f32],
    use_index: bool,
    k: u32,
) -> (Vec<i32>, CapturedScanStatistics) {
    nearest_ids_and_statistics_typed(
        dataset,
        column,
        query.as_ptr().cast(),
        query.len(),
        LanceDataType::Float32,
        use_index,
        k,
    )
}

fn nearest_ids_and_statistics_typed(
    dataset: *mut LanceDataset,
    column: &str,
    query: *const c_void,
    query_len: usize,
    dtype: LanceDataType,
    use_index: bool,
    k: u32,
) -> (Vec<i32>, CapturedScanStatistics) {
    let scanner = unsafe { lance_scanner_new(dataset, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null(), "{}", take_last_error_message());
    let column = c_str(column);
    assert_eq!(
        unsafe {
            lance_scanner_nearest(scanner, column.as_ptr(), query, query_len, dtype as i32, k)
        },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(unsafe { lance_scanner_set_nprobes(scanner, 2) }, 0);
    assert_eq!(unsafe { lance_scanner_set_refine_factor(scanner, 8) }, 0);
    assert_eq!(
        unsafe { lance_scanner_set_use_index(scanner, use_index) },
        0
    );
    let mut captured = CapturedScanStatistics::default();
    assert_eq!(
        unsafe {
            lance_scanner_set_statistics_callback(
                scanner,
                Some(capture_scan_statistics),
                (&mut captured as *mut CapturedScanStatistics).cast(),
            )
        },
        0
    );
    let mut stream = FFI_ArrowArrayStream::empty();
    assert_eq!(
        unsafe { lance_scanner_to_arrow_stream(scanner, &mut stream) },
        0,
        "{}",
        take_last_error_message()
    );
    let reader = unsafe { ArrowArrayStreamReader::from_raw(&mut stream) }.unwrap();
    let ids = reader
        .flat_map(|batch| {
            let batch = batch.unwrap();
            batch
                .column_by_name("id")
                .unwrap()
                .as_any()
                .downcast_ref::<Int32Array>()
                .unwrap()
                .values()
                .to_vec()
        })
        .collect();
    unsafe { lance_scanner_close(scanner) };
    (ids, captured)
}

fn take_last_error_message() -> String {
    let error = lance_last_error_message();
    assert!(!error.is_null());
    let message = unsafe { std::ffi::CStr::from_ptr(error) }
        .to_string_lossy()
        .into_owned();
    unsafe { lance_free_string(error) };
    message
}

fn open_blob_test_session(base_uri: &str) -> *mut LanceFileSession {
    let uri = c_str(base_uri);
    let session =
        unsafe { lance_file_session_new(uri.as_ptr(), ptr::null(), ptr::null(), ptr::null()) };
    assert!(!session.is_null(), "{}", take_last_error_message());
    session
}

fn c_string_value(value: *const c_char) -> String {
    assert!(!value.is_null());
    let owned = unsafe { CStr::from_ptr(value) }
        .to_string_lossy()
        .into_owned();
    unsafe { lance_free_string(value) };
    owned
}

fn output_parts(array: FFI_ArrowArray, schema: FFI_ArrowSchema) -> (Field, arrow_array::ArrayRef) {
    let field = Field::try_from(&schema).unwrap();
    let data = unsafe { from_ffi(array, &schema) }.unwrap();
    (field, make_array(data))
}

fn native_descriptor_parts(
    field_name: &str,
    descriptors: impl IntoIterator<Item = lance::BlobDescriptor>,
) -> (Field, arrow_array::ArrayRef) {
    let mut builder = lance::BlobDescriptorArrayBuilder::new(field_name);
    builder.extend(descriptors).unwrap();
    builder.finish().unwrap().into_parts()
}

fn read_blob_sidecar(
    store: &lance_io::object_store::ObjectStore,
    path: &object_store::path::Path,
) -> Vec<u8> {
    let size = lance_c::runtime::block_on(store.size(path)).unwrap();
    if size == 0 {
        return Vec::new();
    }
    let size = usize::try_from(size).unwrap();
    lance_c::runtime::block_on(store.read_one_range(path, 0..size))
        .unwrap()
        .to_vec()
}

fn expected_payload_bytes(rows: &[Option<Vec<u8>>]) -> Vec<u8> {
    rows.iter()
        .filter_map(Option::as_deref)
        .flatten()
        .copied()
        .collect()
}

type BinaryPayloadCase = (
    &'static str,
    Field,
    arrow_array::ArrayRef,
    Vec<Option<Vec<u8>>>,
);

fn binary_payload_cases() -> Vec<BinaryPayloadCase> {
    let binary = BinaryArray::from(vec![
        Some(b"ignored".as_slice()),
        Some(b"alpha".as_slice()),
        None,
        Some(b"".as_slice()),
        Some(b"omega".as_slice()),
    ]);
    let binary = binary.slice(1, 4);
    let binary_field = Field::new("payload", binary.data_type().clone(), true);
    let binary: arrow_array::ArrayRef = Arc::new(binary);

    let large = LargeBinaryArray::from(vec![
        Some(b"ignored".as_slice()),
        Some(b"large-alpha".as_slice()),
        None,
        Some(b"".as_slice()),
        Some(b"large-omega".as_slice()),
    ]);
    let large = large.slice(1, 4);
    let large_field = Field::new("payload", large.data_type().clone(), true);
    let large: arrow_array::ArrayRef = Arc::new(large);

    let view = arrow_array::BinaryViewArray::from(vec![
        Some(b"ignored".as_slice()),
        Some(b"view-alpha".as_slice()),
        None,
        Some(b"".as_slice()),
        Some(b"view-omega".as_slice()),
    ]);
    let view = view.slice(1, 4);
    let view_field = Field::new("payload", view.data_type().clone(), true);
    let view: arrow_array::ArrayRef = Arc::new(view);

    let fixed = arrow_array::FixedSizeBinaryArray::try_from_sparse_iter_with_size(
        [
            Some(b"skip".as_slice()),
            Some(b"abcd".as_slice()),
            None,
            Some(b"wxyz".as_slice()),
        ]
        .into_iter(),
        4,
    )
    .unwrap();
    let fixed = fixed.slice(1, 3);
    let fixed_field = Field::new("payload", fixed.data_type().clone(), true);
    let fixed: arrow_array::ArrayRef = Arc::new(fixed);

    vec![
        (
            "binary",
            binary_field,
            binary,
            vec![
                Some(b"alpha".to_vec()),
                None,
                Some(Vec::new()),
                Some(b"omega".to_vec()),
            ],
        ),
        (
            "large-binary",
            large_field,
            large,
            vec![
                Some(b"large-alpha".to_vec()),
                None,
                Some(Vec::new()),
                Some(b"large-omega".to_vec()),
            ],
        ),
        (
            "binary-view",
            view_field,
            view,
            vec![
                Some(b"view-alpha".to_vec()),
                None,
                Some(Vec::new()),
                Some(b"view-omega".to_vec()),
            ],
        ),
        (
            "fixed-size-binary",
            fixed_field,
            fixed,
            vec![Some(b"abcd".to_vec()), None, Some(b"wxyz".to_vec())],
        ),
    ]
}

#[test]
fn test_packed_blob_writer_c_matches_native_binary_types_and_descriptor_identity() {
    let tmp = tempfile::tempdir().unwrap();
    let uri = format!("file://{}", tmp.path().display());
    let (store, base) =
        lance_c::runtime::block_on(lance_io::object_store::ObjectStore::from_uri(&uri)).unwrap();
    let session = open_blob_test_session(&uri);

    for (case_name, field, payloads, rows) in binary_payload_cases() {
        let data_file_name = format!("{case_name}.lance");
        let data_file_path =
            base.child_path(&object_store::path::Path::from(data_file_name.as_str()));
        let data_file_path_c = c_str(&data_file_name);
        let blob_id = 41;
        let writer = unsafe {
            lance_file_session_open_packed_blob_writer(session, data_file_path_c.as_ptr(), blob_id)
        };
        assert!(!writer.is_null(), "{}", take_last_error_message());
        assert_eq!(unsafe { lance_packed_blob_writer_blob_id(writer) }, blob_id);
        let c_path = c_string_value(unsafe { lance_packed_blob_writer_path(writer) });

        let mut input = FFI_ArrowArray::new(&payloads.to_data());
        let input_schema = FFI_ArrowSchema::try_from(&field).unwrap();
        assert!(input.release.is_some());
        assert_eq!(
            unsafe { lance_packed_blob_writer_write_blobs(writer, &mut input, &input_schema) },
            0,
            "{}",
            take_last_error_message()
        );
        assert!(
            input.release.is_none(),
            "the source array must be released on success"
        );
        assert!(
            input_schema.release.is_some(),
            "the source schema remains borrowed"
        );

        let mut out_array = FFI_ArrowArray::empty();
        let mut out_schema = FFI_ArrowSchema::empty();
        assert_eq!(
            unsafe {
                lance_packed_blob_writer_finish_array(
                    writer,
                    c"blob".as_ptr(),
                    &mut out_array,
                    &mut out_schema,
                )
            },
            0,
            "{}",
            take_last_error_message()
        );
        let (c_field, c_array) = output_parts(out_array, out_schema);
        let c_bytes = read_blob_sidecar(&store, &object_store::path::Path::from(c_path.as_str()));
        assert_eq!(c_bytes, expected_payload_bytes(&rows));
        unsafe { lance_packed_blob_writer_close(writer) };

        let mut native = lance_c::runtime::block_on(lance::PackedBlobWriter::try_new(
            store.as_ref().clone(),
            data_file_path,
            blob_id,
        ))
        .unwrap();
        assert_eq!(native.blob_id(), blob_id);
        assert_eq!(native.path().as_ref(), c_path);
        let row_refs = rows.iter().map(Option::as_deref).collect::<Vec<_>>();
        lance_c::runtime::block_on(native.write_packed_blobs(row_refs)).unwrap();
        let native_path = native.path().clone();
        let descriptors = lance_c::runtime::block_on(native.finish()).unwrap();
        let (native_field, native_array) = native_descriptor_parts("blob", descriptors);
        assert_eq!(c_field, native_field, "{case_name} prepared field");
        assert_eq!(
            c_array.to_data(),
            native_array.to_data(),
            "{case_name} prepared descriptors"
        );
        assert_eq!(
            read_blob_sidecar(&store, &native_path),
            c_bytes,
            "{case_name} sidecar bytes"
        );
    }

    unsafe { lance_file_session_close(session) };
}

#[test]
fn test_dedicated_blob_writer_finish_array_matches_native_and_empty() {
    let tmp = tempfile::tempdir().unwrap();
    let uri = format!("file://{}", tmp.path().display());
    let (store, base) =
        lance_c::runtime::block_on(lance_io::object_store::ObjectStore::from_uri(&uri)).unwrap();
    let session = open_blob_test_session(&uri);

    let data_file_name = "dedicated.lance";
    let data_file_path_c = c_str(data_file_name);
    let writer = unsafe {
        lance_file_session_open_dedicated_blob_writer(session, data_file_path_c.as_ptr(), 51)
    };
    assert!(!writer.is_null(), "{}", take_last_error_message());
    assert_eq!(unsafe { lance_dedicated_blob_writer_blob_id(writer) }, 51);
    let c_path = c_string_value(unsafe { lance_dedicated_blob_writer_path(writer) });
    for bytes in [b"alpha".as_slice(), b"".as_slice(), b"omega".as_slice()] {
        assert_eq!(
            unsafe { lance_dedicated_blob_writer_write(writer, bytes.as_ptr(), bytes.len()) },
            0,
            "{}",
            take_last_error_message()
        );
    }
    let mut out_array = FFI_ArrowArray::empty();
    let mut out_schema = FFI_ArrowSchema::empty();
    assert_eq!(
        unsafe {
            lance_dedicated_blob_writer_finish_array(
                writer,
                c"blob".as_ptr(),
                &mut out_array,
                &mut out_schema,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    let (c_field, c_array) = output_parts(out_array, out_schema);
    let c_bytes = read_blob_sidecar(&store, &object_store::path::Path::from(c_path.as_str()));
    assert_eq!(c_bytes, b"alphaomega");
    assert_eq!(c_array.len(), 1);
    unsafe { lance_dedicated_blob_writer_close(writer) };

    let native_path = base.child_path(&object_store::path::Path::from(data_file_name));
    let mut native = lance_c::runtime::block_on(lance::DedicatedBlobWriter::try_new(
        store.as_ref().clone(),
        native_path,
        51,
    ))
    .unwrap();
    assert_eq!(native.path().as_ref(), c_path);
    lance_c::runtime::block_on(native.write(b"alpha")).unwrap();
    lance_c::runtime::block_on(native.write(b"")).unwrap();
    lance_c::runtime::block_on(native.write(b"omega")).unwrap();
    let native_path = native.path().clone();
    let descriptor = lance_c::runtime::block_on(native.finish()).unwrap();
    let (native_field, native_array) = native_descriptor_parts("blob", [descriptor]);
    assert_eq!(c_field, native_field);
    assert_eq!(c_array.to_data(), native_array.to_data());
    assert_eq!(read_blob_sidecar(&store, &native_path), c_bytes);

    let empty_name = "dedicated-empty.lance";
    let empty_name_c = c_str(empty_name);
    let empty_writer = unsafe {
        lance_file_session_open_dedicated_blob_writer(session, empty_name_c.as_ptr(), 52)
    };
    assert!(!empty_writer.is_null(), "{}", take_last_error_message());
    let empty_path = c_string_value(unsafe { lance_dedicated_blob_writer_path(empty_writer) });
    let mut empty_array = FFI_ArrowArray::empty();
    let mut empty_schema = FFI_ArrowSchema::empty();
    assert_eq!(
        unsafe {
            lance_dedicated_blob_writer_finish_array(
                empty_writer,
                c"".as_ptr(),
                &mut empty_array,
                &mut empty_schema,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    let (empty_field, empty_array) = output_parts(empty_array, empty_schema);
    assert_eq!(empty_field.name(), "");
    let empty_bytes =
        read_blob_sidecar(&store, &object_store::path::Path::from(empty_path.as_str()));
    assert!(empty_bytes.is_empty());
    unsafe { lance_dedicated_blob_writer_close(empty_writer) };

    let empty_native = lance_c::runtime::block_on(lance::DedicatedBlobWriter::try_new(
        store.as_ref().clone(),
        base.child_path(&object_store::path::Path::from(empty_name)),
        52,
    ))
    .unwrap();
    let empty_native_path = empty_native.path().clone();
    let empty_descriptor = lance_c::runtime::block_on(empty_native.finish()).unwrap();
    let (empty_native_field, empty_native_array) = native_descriptor_parts("", [empty_descriptor]);
    assert_eq!(empty_field, empty_native_field);
    assert_eq!(empty_array.to_data(), empty_native_array.to_data());
    assert!(
        read_blob_sidecar(&store, &empty_native_path).is_empty(),
        "a dedicated writer with no writes publishes an empty object"
    );

    unsafe { lance_file_session_close(session) };
}

fn sentinel_ffi_outputs(sentinel: *mut c_void) -> (FFI_ArrowArray, FFI_ArrowSchema) {
    let mut array = FFI_ArrowArray::empty();
    array.length = 19;
    array.offset = 3;
    array.private_data = sentinel;
    let mut schema = FFI_ArrowSchema::empty();
    schema.flags = 7;
    schema.private_data = sentinel;
    (array, schema)
}

fn assert_ffi_outputs_untouched(
    array: &FFI_ArrowArray,
    schema: &FFI_ArrowSchema,
    sentinel: *mut c_void,
) {
    assert_eq!(array.private_data, sentinel);
    assert_eq!(array.length, 19);
    assert_eq!(array.offset, 3);
    assert!(array.release.is_none());
    assert_eq!(schema.private_data, sentinel);
    assert_eq!(schema.flags, 7);
    assert!(schema.release.is_none());
}

unsafe extern "C" fn release_invalid_test_array(array: *mut FFI_ArrowArray) {
    if !array.is_null() {
        unsafe { (*array).release = None };
    }
}

#[test]
fn test_blob_writer_arrow_ownership_validation_and_finish_lifecycle() {
    let tmp = tempfile::tempdir().unwrap();
    let uri = format!("file://{}", tmp.path().display());
    let session = open_blob_test_session(&uri);
    let writer = unsafe {
        lance_file_session_open_packed_blob_writer(session, c"ownership.lance".as_ptr(), 61)
    };
    assert!(!writer.is_null(), "{}", take_last_error_message());

    unsafe { lance_file_session_close(session) };
    assert_eq!(
        unsafe { lance_packed_blob_writer_write_blob(writer, ptr::null(), 0) },
        0,
        "NULL plus zero length is a valid empty packed payload"
    );
    assert_eq!(
        unsafe { lance_packed_blob_writer_write_blob(writer, ptr::null(), 1) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(take_last_error_message().contains("must not be NULL"));
    assert_eq!(
        unsafe { lance_packed_blob_writer_write_blob(writer, b"first".as_ptr(), 5) },
        0,
        "validation errors before native invocation leave the writer usable"
    );

    let non_binary = Int32Array::from(vec![1, 2, 3]);
    let non_binary_field = Field::new("payload", DataType::Int32, true);
    let mut non_binary_array = FFI_ArrowArray::new(&non_binary.to_data());
    let non_binary_schema = FFI_ArrowSchema::try_from(&non_binary_field).unwrap();
    assert_eq!(
        unsafe {
            lance_packed_blob_writer_write_blobs(writer, &mut non_binary_array, &non_binary_schema)
        },
        -1
    );
    assert!(non_binary_array.release.is_none());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(take_last_error_message().contains("expected Binary"));

    let binary = BinaryArray::from(vec![Some(b"payload".as_slice())]);
    let binary_field = Field::new("payload", DataType::Binary, true);
    let mut released_schema_array = FFI_ArrowArray::new(&binary.to_data());
    let released_schema = FFI_ArrowSchema::empty();
    assert_eq!(
        unsafe {
            lance_packed_blob_writer_write_blobs(
                writer,
                &mut released_schema_array,
                &released_schema,
            )
        },
        -1
    );
    assert!(released_schema_array.release.is_none());
    assert!(take_last_error_message().contains("uninitialised or already released"));

    let mut null_schema_array = FFI_ArrowArray::new(&binary.to_data());
    assert_eq!(
        unsafe {
            lance_packed_blob_writer_write_blobs(writer, &mut null_schema_array, ptr::null())
        },
        -1
    );
    assert!(null_schema_array.release.is_none());
    assert!(take_last_error_message().contains("schema must not be NULL"));

    let binary_schema = FFI_ArrowSchema::try_from(&binary_field).unwrap();
    let invalid_offsets = [0_i32, 2, 1, 3];
    let values = b"abc";
    let mut malformed_buffers = [
        ptr::null::<c_void>(),
        invalid_offsets.as_ptr().cast::<c_void>(),
        values.as_ptr().cast::<c_void>(),
    ];
    let mut malformed = FFI_ArrowArray::empty();
    malformed.length = 3;
    malformed.n_buffers = 3;
    malformed.buffers = malformed_buffers.as_mut_ptr();
    malformed.release = Some(release_invalid_test_array);
    assert_eq!(
        unsafe { lance_packed_blob_writer_write_blobs(writer, &mut malformed, &binary_schema) },
        -1
    );
    assert!(malformed.release.is_none());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(take_last_error_message().contains("failed validation"));

    assert_eq!(
        unsafe { lance_packed_blob_writer_write_blobs(writer, ptr::null_mut(), &binary_schema,) },
        -1
    );
    assert!(take_last_error_message().contains("payloads must not be NULL"));

    let base = BinaryArray::from(vec![Some(b"left".as_slice()), Some(b"right".as_slice())]);
    let empty = base.slice(2, 0);
    let mut empty_array = FFI_ArrowArray::new(&empty.to_data());
    empty_array.offset = 123;
    assert_eq!(
        unsafe { lance_packed_blob_writer_write_blobs(writer, &mut empty_array, &binary_schema) },
        0,
        "zero-length input must not observe its unused slice offset: {}",
        take_last_error_message()
    );
    assert!(empty_array.release.is_none());

    let sentinel = 0x5a5a_usize as *mut c_void;
    let (mut untouched_array, mut untouched_schema) = sentinel_ffi_outputs(sentinel);
    assert_eq!(
        unsafe {
            lance_packed_blob_writer_finish_array(
                writer,
                ptr::null(),
                &mut untouched_array,
                &mut untouched_schema,
            )
        },
        -1
    );
    assert_ffi_outputs_untouched(&untouched_array, &untouched_schema, sentinel);
    assert!(take_last_error_message().contains("field_name must not be NULL"));

    let (mut array_only, mut schema_only) = sentinel_ffi_outputs(sentinel);
    assert_eq!(
        unsafe {
            lance_packed_blob_writer_finish_array(
                writer,
                c"blob".as_ptr(),
                ptr::null_mut(),
                &mut schema_only,
            )
        },
        -1
    );
    assert_eq!(schema_only.private_data, sentinel);
    assert_eq!(
        unsafe {
            lance_packed_blob_writer_finish_array(
                writer,
                c"blob".as_ptr(),
                &mut array_only,
                ptr::null_mut(),
            )
        },
        -1
    );
    assert_eq!(array_only.private_data, sentinel);
    assert!(take_last_error_message().contains("out_array and out_schema"));

    let mut out_array = FFI_ArrowArray::empty();
    let mut out_schema = FFI_ArrowSchema::empty();
    assert_eq!(
        unsafe {
            lance_packed_blob_writer_finish_array(
                writer,
                c"blob".as_ptr(),
                &mut out_array,
                &mut out_schema,
            )
        },
        0,
        "preflight failures leave the active writer available: {}",
        take_last_error_message()
    );
    let (field, array) = output_parts(out_array, out_schema);
    assert_eq!(field.name(), "blob");
    assert_eq!(array.len(), 2);

    let (mut repeated_array, mut repeated_schema) = sentinel_ffi_outputs(sentinel);
    assert_eq!(
        unsafe {
            lance_packed_blob_writer_finish_array(
                writer,
                c"blob".as_ptr(),
                &mut repeated_array,
                &mut repeated_schema,
            )
        },
        -1
    );
    assert_ffi_outputs_untouched(&repeated_array, &repeated_schema, sentinel);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(take_last_error_message().contains("already finished"));
    assert_eq!(unsafe { lance_packed_blob_writer_blob_id(writer) }, 0);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(take_last_error_message().contains("already finished"));
    assert!(unsafe { lance_packed_blob_writer_path(writer) }.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(take_last_error_message().contains("already finished"));

    unsafe {
        lance_packed_blob_writer_close(writer);
        lance_packed_blob_writer_close(ptr::null_mut());
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CapturedCleanupCandidate {
    path: String,
    kind: i32,
    unverified: bool,
    size_bytes: u64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CapturedCleanupBranch {
    name: String,
    referenced_version: u64,
    cleanup_candidate: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CapturedCleanupExplanation {
    read_version: u64,
    stats: LanceRemovalStats,
    candidate_files: Vec<CapturedCleanupCandidate>,
    candidate_files_truncated: bool,
    candidate_file_limit: u64,
    referenced_branches: Vec<CapturedCleanupBranch>,
    warnings: Vec<String>,
}

fn borrowed_c_string(value: *const c_char) -> String {
    assert!(!value.is_null(), "{}", take_last_error_message());
    unsafe { CStr::from_ptr(value) }
        .to_str()
        .unwrap()
        .to_string()
}

fn capture_cleanup_explanation(
    explanation: *const LanceCleanupExplanation,
) -> CapturedCleanupExplanation {
    let read_version = unsafe { lance_cleanup_explanation_read_version(explanation) };
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);

    let mut stats = LanceRemovalStats::default();
    assert_eq!(
        unsafe { lance_cleanup_explanation_stats(explanation, &mut stats) },
        0,
        "{}",
        take_last_error_message()
    );

    let candidate_count = unsafe { lance_cleanup_explanation_candidate_count(explanation) };
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
    let mut candidate_files = Vec::new();
    for index in 0..candidate_count as usize {
        let path = unsafe { lance_cleanup_explanation_candidate_path_at(explanation, index) };
        let path = borrowed_c_string(path);
        let kind = unsafe { lance_cleanup_explanation_candidate_kind_at(explanation, index) };
        assert!(kind >= 0, "{}", take_last_error_message());
        let unverified =
            unsafe { lance_cleanup_explanation_candidate_unverified_at(explanation, index) };
        assert!(unverified >= 0, "{}", take_last_error_message());
        let size_bytes =
            unsafe { lance_cleanup_explanation_candidate_size_bytes_at(explanation, index) };
        assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
        candidate_files.push(CapturedCleanupCandidate {
            path,
            kind,
            unverified: unverified != 0,
            size_bytes,
        });
    }

    let candidate_files_truncated =
        unsafe { lance_cleanup_explanation_candidate_files_truncated(explanation) };
    assert!(
        candidate_files_truncated >= 0,
        "{}",
        take_last_error_message()
    );
    let candidate_file_limit =
        unsafe { lance_cleanup_explanation_candidate_file_limit(explanation) };
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);

    let branch_count = unsafe { lance_cleanup_explanation_referenced_branch_count(explanation) };
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
    let mut referenced_branches = Vec::new();
    for index in 0..branch_count as usize {
        let name =
            unsafe { lance_cleanup_explanation_referenced_branch_name_at(explanation, index) };
        let name = borrowed_c_string(name);
        let referenced_version =
            unsafe { lance_cleanup_explanation_referenced_branch_version_at(explanation, index) };
        assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
        let cleanup_candidate = unsafe {
            lance_cleanup_explanation_referenced_branch_cleanup_candidate_at(explanation, index)
        };
        assert!(cleanup_candidate >= 0, "{}", take_last_error_message());
        referenced_branches.push(CapturedCleanupBranch {
            name,
            referenced_version,
            cleanup_candidate: cleanup_candidate != 0,
        });
    }

    let warning_count = unsafe { lance_cleanup_explanation_warning_count(explanation) };
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
    let mut warnings = Vec::new();
    for index in 0..warning_count as usize {
        let warning = unsafe { lance_cleanup_explanation_warning_at(explanation, index) };
        warnings.push(borrowed_c_string(warning));
    }

    CapturedCleanupExplanation {
        read_version,
        stats,
        candidate_files,
        candidate_files_truncated: candidate_files_truncated != 0,
        candidate_file_limit,
        referenced_branches,
        warnings,
    }
}

fn cleanup_fixture_batch(schema: Arc<Schema>, start: i32, rows: i32) -> RecordBatch {
    RecordBatch::try_new(
        schema,
        vec![Arc::new(Int32Array::from_iter_values(start..start + rows))],
    )
    .unwrap()
}

fn create_cleanup_fixture(
    name: &str,
    fragments: i32,
    delete_predicate: Option<&str>,
) -> (tempfile::TempDir, String) {
    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp.path().join(name).to_str().unwrap().to_string();
    lance_c::runtime::block_on(async {
        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int32, false)]));
        let first = cleanup_fixture_batch(schema.clone(), 0, 4);
        let mut dataset = Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(first)], schema.clone()),
            &uri,
            None,
        )
        .await
        .unwrap();
        for fragment in 1..fragments {
            let batch = cleanup_fixture_batch(schema.clone(), fragment * 4, 4);
            dataset
                .append(
                    arrow::record_batch::RecordBatchIterator::new(vec![Ok(batch)], schema.clone()),
                    None,
                )
                .await
                .unwrap();
        }
        if let Some(predicate) = delete_predicate {
            dataset.delete(predicate).await.unwrap();
        }
    });
    (tmp, uri)
}

fn native_cleanup_version_ids(uri: &str, branch: Option<&str>) -> Vec<u64> {
    lance_c::runtime::block_on(async {
        let mut dataset = Dataset::open(uri).await.unwrap();
        if let Some(branch) = branch {
            dataset = dataset.checkout_branch(branch).await.unwrap();
        }
        dataset
            .version_refs()
            .await
            .unwrap()
            .into_iter()
            .map(|version| version.version)
            .collect()
    })
}

fn count_files_with_extension(path: &std::path::Path, extension: &str) -> usize {
    if path.is_dir() {
        std::fs::read_dir(path)
            .unwrap()
            .map(|entry| count_files_with_extension(&entry.unwrap().path(), extension))
            .sum()
    } else {
        usize::from(
            path.extension()
                .is_some_and(|candidate| candidate == std::ffi::OsStr::new(extension)),
        )
    }
}

fn files_with_extension(
    path: &std::path::Path,
    extension: &str,
    out: &mut Vec<std::path::PathBuf>,
) {
    if path.is_dir() {
        for entry in std::fs::read_dir(path).unwrap() {
            files_with_extension(&entry.unwrap().path(), extension, out);
        }
    } else if path
        .extension()
        .is_some_and(|candidate| candidate == std::ffi::OsStr::new(extension))
    {
        out.push(path.to_path_buf());
    }
}

fn sentinel_cleanup_stats() -> LanceRemovalStats {
    LanceRemovalStats {
        bytes_removed: u64::MAX,
        old_versions: u64::MAX,
        data_files_removed: u64::MAX,
        transaction_files_removed: u64::MAX,
        index_files_removed: u64::MAX,
        deletion_files_removed: u64::MAX,
        failed_deletes: u64::MAX,
    }
}

#[test]
fn test_cleanup_selectors_explanation_owned_output_and_reexecution() {
    let (tmp, uri) = create_cleanup_fixture("cleanup-selectors", 4, Some("id = 1"));
    let root = std::path::Path::new(&uri);
    let uri_c = c_str(&uri);
    assert_eq!(native_cleanup_version_ids(&uri, None), vec![1, 2, 3, 4, 5]);
    assert_eq!(count_files_with_extension(root, "manifest"), 5);

    let selected_versions = [2_u64, 3];
    let mut policy = LanceCleanupPolicy {
        has_before_timestamp: 1,
        // Beyond the i64-nanosecond range (year 3000).
        before_timestamp_seconds: 32_503_680_000,
        before_timestamp_nanos: 999_999_999,
        has_before_version: 1,
        before_version: 5,
        versions: selected_versions.as_ptr(),
        num_versions: selected_versions.len(),
        ..LanceCleanupPolicy::default()
    };
    let mut operation = LanceCleanupOperationOptions {
        has_max_candidate_files: 1,
        max_candidate_files: 1,
        ..LanceCleanupOperationOptions::default()
    };

    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null(), "{}", take_last_error_message());
    let explanation = unsafe { lance_dataset_cleanup_explain(dataset, &policy, &operation) };
    assert!(!explanation.is_null(), "{}", take_last_error_message());
    assert_eq!(count_files_with_extension(root, "manifest"), 5);

    // The explanation owns every field and remains readable after the dataset
    // handle is gone.
    unsafe { lance_dataset_close(dataset) };
    let captured = capture_cleanup_explanation(explanation);
    assert_eq!(captured.read_version, 5);
    assert_eq!(captured.stats.old_versions, 2);
    assert_eq!(captured.candidate_files.len(), 1);
    assert_eq!(captured.candidate_file_limit, 1);
    assert!(captured.candidate_files_truncated);
    assert_eq!(captured.warnings.len(), 1);
    assert!(captured.warnings[0].contains("candidate_files truncated to 1 entries"));
    assert!(!captured.candidate_files[0].path.is_empty());
    assert!(captured.candidate_files[0].size_bytes > 0);
    unsafe { lance_cleanup_explanation_close(explanation) };
    assert_eq!(count_files_with_extension(root, "manifest"), 5);

    // The timestamp selector is independent from the version selectors and
    // combines with AND.
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());
    policy.before_timestamp_seconds = 0;
    policy.before_timestamp_nanos = 0;
    operation.max_candidate_files = 100;
    let explanation = unsafe { lance_dataset_cleanup_explain(dataset, &policy, &operation) };
    assert!(!explanation.is_null(), "{}", take_last_error_message());
    let captured = capture_cleanup_explanation(explanation);
    assert_eq!(captured.stats.old_versions, 0);
    assert!(captured.candidate_files.is_empty());
    assert!(!captured.candidate_files_truncated);
    unsafe {
        lance_cleanup_explanation_close(explanation);
        lance_dataset_close(dataset);
    }

    // An explicit zero candidate limit is valid and still reports full
    // aggregate stats plus truncation.
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());
    policy.before_timestamp_seconds = 32_503_680_000;
    policy.before_timestamp_nanos = 0;
    operation.max_candidate_files = 0;
    let explanation = unsafe { lance_dataset_cleanup_explain(dataset, &policy, &operation) };
    assert!(!explanation.is_null(), "{}", take_last_error_message());
    let captured = capture_cleanup_explanation(explanation);
    assert_eq!(captured.stats.old_versions, 2);
    assert!(captured.candidate_files.is_empty());
    assert!(captured.candidate_files_truncated);
    assert_eq!(captured.candidate_file_limit, 0);
    unsafe {
        lance_cleanup_explanation_close(explanation);
        lance_dataset_close(dataset);
    }

    // Add a tag after the explanation. Execution re-evaluates references:
    // version 3 is now protected, while version 2 is still removable.
    lance_c::runtime::block_on(async {
        Dataset::open(&uri)
            .await
            .unwrap()
            .tags()
            .create("pinned-after-explain", 3_u64)
            .await
            .unwrap();
    });
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());
    policy.has_error_if_tagged_old_versions = 1;
    policy.error_if_tagged_old_versions = false;
    operation = LanceCleanupOperationOptions {
        has_delete_concurrency: 1,
        delete_concurrency: 2,
        has_delete_rate_limit: 1,
        delete_rate_limit: 1_000_000,
        ..LanceCleanupOperationOptions::default()
    };
    let mut stats = sentinel_cleanup_stats();
    assert_eq!(
        unsafe { lance_dataset_cleanup(dataset, &policy, &operation, &mut stats) },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(stats.old_versions, 1);
    assert_eq!(stats.failed_deletes, 0);
    unsafe { lance_dataset_close(dataset) };

    assert_eq!(native_cleanup_version_ids(&uri, None), vec![1, 3, 4, 5]);
    assert_eq!(count_files_with_extension(root, "manifest"), 4);
    let tag_version = lance_c::runtime::block_on(async {
        Dataset::open(&uri)
            .await
            .unwrap()
            .tags()
            .get("pinned-after-explain")
            .await
            .unwrap()
            .version
    });
    assert_eq!(tag_version, 3);
    drop(tmp);
}

#[test]
fn test_cleanup_retain_native_defaults_invalid_forms_and_operation_errors() {
    let (tmp, uri) = create_cleanup_fixture("cleanup-retain", 5, None);
    let root = std::path::Path::new(&uri);
    lance_c::runtime::block_on(async {
        Dataset::open(&uri)
            .await
            .unwrap()
            .tags()
            .create("pinned-old", 2_u64)
            .await
            .unwrap();
    });
    let uri_c = c_str(&uri);
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());

    // A zero-initialized optional tag flag inherits the native true default.
    let mut policy = LanceCleanupPolicy {
        has_before_version: 1,
        before_version: 5,
        ..LanceCleanupPolicy::default()
    };
    let explanation = unsafe { lance_dataset_cleanup_explain(dataset, &policy, ptr::null()) };
    assert!(explanation.is_null());
    assert_ne!(lance_last_error_code(), LanceErrorCode::Ok);
    assert!(take_last_error_message().contains("tagged version"));
    assert_eq!(native_cleanup_version_ids(&uri, None), vec![1, 2, 3, 4, 5]);

    // Retain-N uses the native asynchronous builder. Explicitly disabling the
    // tag error leaves the tagged version protected but continues cleanup.
    policy = LanceCleanupPolicy {
        has_retain_versions: 1,
        retain_versions: 3,
        has_error_if_tagged_old_versions: 1,
        error_if_tagged_old_versions: false,
        ..LanceCleanupPolicy::default()
    };
    let mut stats = sentinel_cleanup_stats();
    assert_eq!(
        unsafe { lance_dataset_cleanup(dataset, &policy, ptr::null(), &mut stats) },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(stats.old_versions, 1);
    assert_eq!(native_cleanup_version_ids(&uri, None), vec![2, 3, 4, 5]);

    // Native retain-N validation.
    policy = LanceCleanupPolicy {
        has_retain_versions: 1,
        retain_versions: 0,
        ..LanceCleanupPolicy::default()
    };
    let mut stats = sentinel_cleanup_stats();
    assert_eq!(
        unsafe { lance_dataset_cleanup(dataset, &policy, ptr::null(), &mut stats) },
        -1
    );
    assert_eq!(stats, sentinel_cleanup_stats());
    assert!(take_last_error_message().contains("retain_versions must be greater than 0"));

    // An explicit empty version selection reaches the native builder and is
    // rejected there rather than being treated as an absent selector.
    let empty_version_sentinel = 0_u64;
    policy = LanceCleanupPolicy {
        versions: &empty_version_sentinel,
        num_versions: 0,
        ..LanceCleanupPolicy::default()
    };
    let explanation = unsafe { lance_dataset_cleanup_explain(dataset, &policy, ptr::null()) };
    assert!(explanation.is_null());
    assert!(take_last_error_message().contains("versions must not be empty when specified"));
    assert_eq!(native_cleanup_version_ids(&uri, None), vec![2, 3, 4, 5]);

    // before_version and retain_versions write the same native field, so the
    // binding rejects the ambiguous combination instead of choosing silently.
    policy = LanceCleanupPolicy {
        has_before_version: 1,
        before_version: 4,
        has_retain_versions: 1,
        retain_versions: 2,
        ..LanceCleanupPolicy::default()
    };
    assert_eq!(
        unsafe { lance_dataset_cleanup(dataset, &policy, ptr::null(), &mut stats) },
        -1
    );
    assert!(take_last_error_message().contains("both set the native before_version"));

    let selected = [3_u64];
    policy = LanceCleanupPolicy {
        versions: selected.as_ptr(),
        num_versions: selected.len(),
        ..LanceCleanupPolicy::default()
    };

    // Native operation setters validate through their own stages.
    let invalid_concurrency = LanceCleanupOperationOptions {
        has_delete_concurrency: 1,
        delete_concurrency: 0,
        ..LanceCleanupOperationOptions::default()
    };
    let mut stats = sentinel_cleanup_stats();
    assert_eq!(
        unsafe { lance_dataset_cleanup(dataset, &policy, &invalid_concurrency, &mut stats,) },
        -1
    );
    assert_eq!(stats, sentinel_cleanup_stats());
    assert!(take_last_error_message().contains("delete_concurrency must be between 1"));
    assert_eq!(native_cleanup_version_ids(&uri, None), vec![2, 3, 4, 5]);

    let invalid_rate = LanceCleanupOperationOptions {
        has_delete_rate_limit: 1,
        delete_rate_limit: 0,
        ..LanceCleanupOperationOptions::default()
    };
    assert_eq!(
        unsafe { lance_dataset_cleanup(dataset, &policy, &invalid_rate, &mut stats) },
        -1
    );
    assert_eq!(stats, sentinel_cleanup_stats());
    assert!(take_last_error_message().contains("delete_rate_limit must be greater than 0"));

    let valid_operation = LanceCleanupOperationOptions {
        has_delete_concurrency: 1,
        delete_concurrency: 2,
        has_delete_rate_limit: 1,
        delete_rate_limit: 1_000_000,
        has_max_candidate_files: 1,
        max_candidate_files: 0,
    };
    assert_eq!(
        unsafe { lance_dataset_cleanup(dataset, &policy, &valid_operation, &mut stats,) },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(stats.old_versions, 1);
    assert_eq!(stats.failed_deletes, 0);
    unsafe { lance_dataset_close(dataset) };
    assert_eq!(native_cleanup_version_ids(&uri, None), vec![2, 4, 5]);
    assert_eq!(count_files_with_extension(root, "manifest"), 3);
    drop(tmp);
}

#[test]
fn test_cleanup_relative_duration_and_unverified_candidates() {
    let (tmp, uri) = create_cleanup_fixture("cleanup-relative", 5, None);
    let root = std::path::Path::new(&uri);
    let orphan = root.join("data").join("orphan-cleanup.lance");
    let orphan_bytes = b"unverified cleanup candidate";
    std::fs::write(&orphan, orphan_bytes).unwrap();
    let uri_c = c_str(&uri);
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());

    let selected = [2_u64];
    let mut policy = LanceCleanupPolicy {
        versions: selected.as_ptr(),
        num_versions: selected.len(),
        ..LanceCleanupPolicy::default()
    };
    let operation = LanceCleanupOperationOptions {
        has_max_candidate_files: 1,
        max_candidate_files: 100,
        ..LanceCleanupOperationOptions::default()
    };

    let explanation = unsafe { lance_dataset_cleanup_explain(dataset, &policy, &operation) };
    assert!(!explanation.is_null(), "{}", take_last_error_message());
    let captured = capture_cleanup_explanation(explanation);
    assert!(
        captured
            .candidate_files
            .iter()
            .all(|candidate| !candidate.path.ends_with("orphan-cleanup.lance"))
    );
    assert_eq!(captured.stats.data_files_removed, 0);
    unsafe { lance_cleanup_explanation_close(explanation) };

    policy.has_delete_unverified = 1;
    policy.delete_unverified = true;
    let explanation = unsafe { lance_dataset_cleanup_explain(dataset, &policy, &operation) };
    assert!(!explanation.is_null(), "{}", take_last_error_message());
    let captured = capture_cleanup_explanation(explanation);
    let orphan_candidate = captured
        .candidate_files
        .iter()
        .find(|candidate| candidate.path.ends_with("orphan-cleanup.lance"))
        .expect("explicit delete_unverified must expose the orphan candidate");
    assert_eq!(orphan_candidate.kind, 1);
    assert!(orphan_candidate.unverified);
    assert_eq!(orphan_candidate.size_bytes, orphan_bytes.len() as u64);
    assert_eq!(captured.stats.data_files_removed, 1);
    assert!(orphan.exists(), "explain must not delete files");
    unsafe { lance_cleanup_explanation_close(explanation) };

    // Relative older-than cleanup calls the native convenience operation, so
    // Lance core owns the cutoff. A negative window beyond the i64-nanosecond
    // range produces a future cutoff and removes every non-current version;
    // the recent unverified orphan remains protected by the default.
    let relative = LanceCleanupOldVersionsOptions {
        older_than_seconds: -10_000_000_000,
        ..LanceCleanupOldVersionsOptions::default()
    };
    let mut stats = sentinel_cleanup_stats();
    assert_eq!(
        unsafe { lance_dataset_cleanup_old_versions(dataset, &relative, &mut stats,) },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(stats.old_versions, 4);
    assert!(orphan.exists());
    assert_eq!(native_cleanup_version_ids(&uri, None), vec![5]);
    assert_eq!(count_files_with_extension(root, "manifest"), 1);

    let invalid_relative = LanceCleanupOldVersionsOptions {
        older_than_nanos: 1_000_000_000,
        ..LanceCleanupOldVersionsOptions::default()
    };
    let mut invalid_stats = sentinel_cleanup_stats();
    assert_eq!(
        unsafe {
            lance_dataset_cleanup_old_versions(dataset, &invalid_relative, &mut invalid_stats)
        },
        -1
    );
    assert_eq!(invalid_stats, sentinel_cleanup_stats());
    assert!(take_last_error_message().contains("older_than_nanos=1000000000"));
    assert_eq!(native_cleanup_version_ids(&uri, None), vec![5]);
    unsafe { lance_dataset_close(dataset) };
    drop(tmp);
}

#[test]
fn test_dataset_validation_deleted_rows_and_small_files() {
    let (tmp, uri) = create_cleanup_fixture("lifecycle-stats", 4, Some("id IN (1, 5)"));
    let uri_c = c_str(&uri);
    let native_deleted = lance_c::runtime::block_on(async {
        Dataset::open(&uri)
            .await
            .unwrap()
            .count_deleted_rows()
            .await
            .unwrap() as u64
    });
    assert_eq!(native_deleted, 2);

    for (threshold, expected) in [(0_usize, 0_usize), (4, 0), (5, 4), (8, 4)] {
        let native = lance_c::runtime::block_on(async {
            Dataset::open(&uri)
                .await
                .unwrap()
                .num_small_files(threshold)
                .await
        });
        assert_eq!(native, expected);
    }

    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());
    assert_eq!(
        unsafe { lance_dataset_validate(dataset) },
        0,
        "{}",
        take_last_error_message()
    );
    let mut deleted = u64::MAX;
    assert_eq!(
        unsafe { lance_dataset_count_deleted_rows(dataset, &mut deleted) },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(deleted, 2);
    let mut small_files = u64::MAX;
    assert_eq!(
        unsafe { lance_dataset_num_small_files(dataset, 5, &mut small_files) },
        0,
        "{}",
        take_last_error_message()
    );
    assert_eq!(small_files, 4);
    assert_eq!(
        unsafe { lance_dataset_num_small_files(dataset, 4, &mut small_files) },
        0
    );
    assert_eq!(small_files, 0);
    assert_eq!(
        unsafe { lance_dataset_num_small_files(dataset, 0, &mut small_files) },
        0
    );
    assert_eq!(small_files, 0);

    let mut untouched = 123_u64;
    assert_eq!(
        unsafe { lance_dataset_count_deleted_rows(ptr::null(), &mut untouched) },
        -1
    );
    assert_eq!(untouched, 123);
    assert_eq!(
        unsafe { lance_dataset_num_small_files(ptr::null(), 5, &mut untouched) },
        -1
    );
    assert_eq!(untouched, 123);
    assert_eq!(unsafe { lance_dataset_validate(ptr::null()) }, -1);
    unsafe { lance_dataset_close(dataset) };

    // A controlled invalid fixture: opening only reads the manifest, while
    // validation checks fragment data and must reach the native failure.
    let mut data_files = Vec::new();
    files_with_extension(std::path::Path::new(&uri), "lance", &mut data_files);
    assert!(!data_files.is_empty());
    std::fs::remove_file(&data_files[0]).unwrap();
    let native_failure =
        lance_c::runtime::block_on(async { Dataset::open(&uri).await.unwrap().validate().await });
    assert!(native_failure.is_err());
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());
    assert_eq!(unsafe { lance_dataset_validate(dataset) }, -1);
    assert_ne!(lance_last_error_code(), LanceErrorCode::Ok);
    assert!(!take_last_error_message().is_empty());
    unsafe { lance_dataset_close(dataset) };
    drop(tmp);
}

#[test]
fn test_cleanup_branch_cascade_and_copied_explanation() {
    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp
        .path()
        .join("cleanup-branches")
        .to_str()
        .unwrap()
        .to_string();
    lance_c::runtime::block_on(async {
        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int32, false)]));
        let first = cleanup_fixture_batch(schema.clone(), 0, 4);
        let mut main = Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(first)], schema.clone()),
            &uri,
            Some(WriteParams {
                auto_cleanup: Some(AutoCleanupParams {
                    interval: 1,
                    older_than: chrono::TimeDelta::zero(),
                }),
                skip_auto_cleanup: true,
                ..Default::default()
            }),
        )
        .await
        .unwrap();
        for fragment in 1..3 {
            let batch = cleanup_fixture_batch(schema.clone(), fragment * 4, 4);
            main.append(
                arrow::record_batch::RecordBatchIterator::new(vec![Ok(batch)], schema.clone()),
                Some(WriteParams {
                    skip_auto_cleanup: true,
                    ..Default::default()
                }),
            )
            .await
            .unwrap();
        }
        let mut branch = main.create_branch("dev", 2_u64, None).await.unwrap();
        let branch_batch = cleanup_fixture_batch(schema.clone(), 100, 4);
        branch
            .append(
                arrow::record_batch::RecordBatchIterator::new(
                    vec![Ok(branch_batch)],
                    schema.clone(),
                ),
                Some(WriteParams {
                    skip_auto_cleanup: true,
                    ..Default::default()
                }),
            )
            .await
            .unwrap();
        let main_batch = cleanup_fixture_batch(schema.clone(), 200, 4);
        main.append(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(main_batch)], schema),
            Some(WriteParams {
                skip_auto_cleanup: true,
                ..Default::default()
            }),
        )
        .await
        .unwrap();
    });

    assert_eq!(native_cleanup_version_ids(&uri, None), vec![1, 2, 3, 4]);
    assert_eq!(native_cleanup_version_ids(&uri, Some("dev")), vec![2, 3]);
    let root = std::path::Path::new(&uri);
    let before_manifests = count_files_with_extension(root, "manifest");

    let policy = LanceCleanupPolicy {
        has_retain_versions: 1,
        retain_versions: 1,
        has_clean_referenced_branches: 1,
        clean_referenced_branches: true,
        ..LanceCleanupPolicy::default()
    };
    let operation = LanceCleanupOperationOptions {
        has_max_candidate_files: 1,
        max_candidate_files: 100,
        ..LanceCleanupOperationOptions::default()
    };
    let uri_c = c_str(&uri);
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());
    let explanation = unsafe { lance_dataset_cleanup_explain(dataset, &policy, &operation) };
    assert!(!explanation.is_null(), "{}", take_last_error_message());
    let captured = capture_cleanup_explanation(explanation);
    assert_eq!(captured.read_version, 4);
    assert_eq!(captured.referenced_branches.len(), 1);
    assert_eq!(captured.referenced_branches[0].name, "dev");
    // The native BranchIdentifier records the parent version this branch
    // descends from, not the branch's own latest version.
    assert_eq!(captured.referenced_branches[0].referenced_version, 2);
    assert!(captured.referenced_branches[0].cleanup_candidate);
    assert_eq!(
        count_files_with_extension(root, "manifest"),
        before_manifests
    );
    unsafe { lance_cleanup_explanation_close(explanation) };

    let mut stats = sentinel_cleanup_stats();
    assert_eq!(
        unsafe { lance_dataset_cleanup(dataset, &policy, &operation, &mut stats) },
        0,
        "{}",
        take_last_error_message()
    );
    let after_manifests = count_files_with_extension(root, "manifest");
    assert_eq!(
        before_manifests - after_manifests,
        stats.old_versions as usize
    );
    unsafe { lance_dataset_close(dataset) };

    // Cascade cleanup uses the referenced branch's own manifest config. The
    // parent manifest that anchors the branch's remaining lineage is retained.
    assert_eq!(native_cleanup_version_ids(&uri, None), vec![2, 4]);
    assert_eq!(native_cleanup_version_ids(&uri, Some("dev")), vec![3]);
    assert_eq!(after_manifests, 3);
    drop(tmp);
}

#[test]
fn test_vector_index_segment_rejects_strict_subset_dot_pq() {
    let (_tmp, uri) = create_multi_fragment_vector_dataset(2, 64, 8, false);
    let uri_c = c_str(&uri);
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());
    let column = c_str("embedding");
    let mut fragment_ids = [0_u64; 2];
    assert_eq!(
        unsafe { lance_dataset_fragment_ids(dataset, fragment_ids.as_mut_ptr()) },
        0
    );
    let selected_fragments = fragment_ids.map(|fragment_id| fragment_id as u32);
    let (mut centroids, centroids_schema, mut codebook, codebook_schema) =
        train_segment_pq_models(dataset, &column, LanceMetricType::Dot);
    let params = LanceVectorIndexSegmentParams {
        index_type: LanceVectorIndexType::IvfPq as i32,
        metric: LanceMetricType::Dot as i32,
        num_partitions: 2,
        num_sub_vectors: 2,
        num_bits: 4,
        max_iterations: 2,
        hnsw_m: 0,
        hnsw_ef_construction: 0,
        sample_rate: 16,
    };
    let mut options = LanceIndexSegmentBuildOptions {
        fragment_ids: ptr::null(),
        fragment_count: 0,
        index_uuid: ptr::null(),
        ivf_centroids: &mut centroids,
        ivf_centroids_schema: &centroids_schema,
        pq_codebook: &mut codebook,
        pq_codebook_schema: &codebook_schema,
        mode: LanceIndexSegmentBuildMode::Precomputed as i32,
    };

    // Full coverage takes Lance's ordinary build path, which assigns PQ codes
    // with an L2 quantizer and records L2 in the index metadata, so supplied
    // DOT PQ models are safe there and must remain supported.
    let builder = unsafe {
        lance_index_segment_builder_new_vector(
            dataset,
            column.as_ptr(),
            ptr::null(),
            &params,
            &options,
        )
    };
    if builder.is_null() {
        panic!(
            "precomputed DOT PQ must remain supported for an implicit full-dataset selection: {}",
            take_last_error_message()
        );
    }
    assert!(!centroids.is_released());
    assert!(!codebook.is_released());
    let mut bytes = ptr::null_mut();
    let mut len = 0;
    let rc =
        unsafe { lance_index_segment_builder_execute_uncommitted(builder, &mut bytes, &mut len) };
    if rc != 0 {
        panic!(
            "implicit full-dataset DOT PQ selection should execute: {}",
            take_last_error_message()
        );
    }
    assert!(!bytes.is_null());
    assert!(len > 0);
    unsafe {
        lance_free_bytes(bytes);
        lance_index_segment_builder_free(builder);
    }

    options.fragment_ids = selected_fragments.as_ptr();
    options.fragment_count = selected_fragments.len();
    options.mode = LanceIndexSegmentBuildMode::Auto as i32;
    let builder = unsafe {
        lance_index_segment_builder_new_vector(
            dataset,
            column.as_ptr(),
            ptr::null(),
            &params,
            &options,
        )
    };
    if builder.is_null() {
        panic!(
            "AUTO with a DOT PQ codebook must remain supported when every fragment is explicit: {}",
            take_last_error_message()
        );
    }
    assert!(!centroids.is_released());
    assert!(!codebook.is_released());
    unsafe { lance_index_segment_builder_free(builder) };

    let hnsw_params = LanceVectorIndexSegmentParams {
        index_type: LanceVectorIndexType::IvfHnswPq as i32,
        hnsw_m: 4,
        hnsw_ef_construction: 16,
        ..params
    };
    options.fragment_ids = ptr::null();
    options.fragment_count = 0;
    options.mode = LanceIndexSegmentBuildMode::Precomputed as i32;
    let builder = unsafe {
        lance_index_segment_builder_new_vector(
            dataset,
            column.as_ptr(),
            ptr::null(),
            &hnsw_params,
            &options,
        )
    };
    if builder.is_null() {
        panic!(
            "precomputed DOT IVF_HNSW_PQ must remain supported for the full dataset: {}",
            take_last_error_message()
        );
    }
    assert!(!centroids.is_released());
    assert!(!codebook.is_released());
    unsafe { lance_index_segment_builder_free(builder) };

    let (_single_tmp, single_uri) = create_multi_fragment_vector_dataset(1, 64, 8, false);
    let single_uri_c = c_str(&single_uri);
    let single_dataset = unsafe { lance_dataset_open(single_uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!single_dataset.is_null());
    let mut single_fragment_id = [0_u64; 1];
    assert_eq!(
        unsafe { lance_dataset_fragment_ids(single_dataset, single_fragment_id.as_mut_ptr()) },
        0
    );
    let single_fragment_id = single_fragment_id[0] as u32;
    options.fragment_ids = &single_fragment_id;
    options.fragment_count = 1;
    options.mode = LanceIndexSegmentBuildMode::Auto as i32;
    let builder = unsafe {
        lance_index_segment_builder_new_vector(
            single_dataset,
            column.as_ptr(),
            ptr::null(),
            &params,
            &options,
        )
    };
    if builder.is_null() {
        panic!(
            "the only explicit fragment is still full coverage and must remain supported: {}",
            take_last_error_message()
        );
    }
    assert!(!centroids.is_released());
    assert!(!codebook.is_released());
    unsafe {
        lance_index_segment_builder_free(builder);
        lance_dataset_close(single_dataset);
    }

    // A strict subset takes Lance's distributed build path, which rewraps the
    // supplied codebook with a DOT ProductQuantizer (make_global_pq) and
    // silently breaks the L2 PQ-assignment contract; reject it in both modes.
    let selected_fragment = selected_fragments[0];
    options.fragment_ids = &selected_fragment;
    options.fragment_count = 1;
    options.mode = LanceIndexSegmentBuildMode::Precomputed as i32;
    let builder = unsafe {
        lance_index_segment_builder_new_vector(
            dataset,
            column.as_ptr(),
            ptr::null(),
            &params,
            &options,
        )
    };
    assert!(
        builder.is_null(),
        "strict-subset DOT PQ must not be accepted in PRECOMPUTED"
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(message.contains("metric=DOT"), "{message}");
    assert!(message.contains("strict fragment subset"), "{message}");
    assert!(message.contains("40f15ed1"), "{message}");
    assert!(message.contains("1 of 2 fragments"), "{message}");
    assert!(!centroids.is_released());
    assert!(!codebook.is_released());

    options.mode = LanceIndexSegmentBuildMode::Auto as i32;
    let builder = unsafe {
        lance_index_segment_builder_new_vector(
            dataset,
            column.as_ptr(),
            ptr::null(),
            &params,
            &options,
        )
    };
    assert!(
        builder.is_null(),
        "strict-subset DOT PQ must not be accepted in AUTO"
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(message.contains("1 of 2 fragments"), "{message}");
    assert!(!centroids.is_released());
    assert!(!codebook.is_released());

    options.mode = LanceIndexSegmentBuildMode::Precomputed as i32;
    let builder = unsafe {
        lance_index_segment_builder_new_vector(
            dataset,
            column.as_ptr(),
            ptr::null(),
            &hnsw_params,
            &options,
        )
    };
    assert!(
        builder.is_null(),
        "strict-subset DOT IVF_HNSW_PQ must not be accepted"
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(message.contains("metric=DOT"), "{message}");
    assert!(!centroids.is_released());
    assert!(!codebook.is_released());

    unsafe {
        if let Some(release) = centroids.release {
            release(&mut centroids);
        }
        if let Some(release) = codebook.release {
            release(&mut codebook);
        }
        lance_dataset_close(dataset);
    }
}

#[test]
fn test_vector_segment_options_preserve_dot_pq_fragment_scope_guard() {
    let (_tmp, uri) = create_multi_fragment_vector_dataset(2, 64, 8, false);
    let dataset = unsafe { lance_dataset_open(c_str(&uri).as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());
    let column = c_str("embedding");
    let mut fragment_ids = [0_u64; 2];
    assert_eq!(
        unsafe { lance_dataset_fragment_ids(dataset, fragment_ids.as_mut_ptr()) },
        0
    );
    let fragment_ids = fragment_ids.map(|id| id as u32);
    let (mut centroids, centroids_schema, mut codebook, codebook_schema) =
        train_segment_pq_models(dataset, &column, LanceMetricType::Dot);

    for index_type in [LanceVectorIndexType::IvfPq, LanceVectorIndexType::IvfHnswPq] {
        let mut options = vector_index_options(index_type, LanceMetricType::Dot);
        options.num_partitions = set_option(2);
        options.num_sub_vectors = set_option(2);
        options.num_bits = set_option(4);
        options.ivf_centroids = &mut centroids;
        options.ivf_centroids_schema = &centroids_schema;
        options.pq_codebook = &mut codebook;
        options.pq_codebook_schema = &codebook_schema;
        let mut scope = LanceVectorIndexSegmentScope {
            fragment_ids: fragment_ids.as_ptr(),
            fragment_count: 1,
            index_uuid: ptr::null(),
        };
        let builder = unsafe {
            lance_index_segment_builder_new_vector_with_options(
                dataset,
                column.as_ptr(),
                ptr::null(),
                &options,
                &scope,
            )
        };
        assert!(
            builder.is_null(),
            "DOT precomputed {index_type:?} must reject a strict subset"
        );
        assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
        let error = take_last_error_message();
        assert!(error.contains("metric=DOT"), "{error}");
        assert!(error.contains("1 of 2 fragments"), "{error}");
        assert!(!centroids.is_released());
        assert!(!codebook.is_released());

        // Definition-only builds do not assign PQ codes to fragment rows.
        options.has_train = true;
        options.train = false;
        let builder = unsafe {
            lance_index_segment_builder_new_vector_with_options(
                dataset,
                column.as_ptr(),
                ptr::null(),
                &options,
                &scope,
            )
        };
        assert!(
            !builder.is_null(),
            "definition-only {index_type:?}: {}",
            take_last_error_message()
        );
        let mut bytes = ptr::null_mut();
        let mut len = 0;
        assert_eq!(
            unsafe {
                lance_index_segment_builder_execute_uncommitted(builder, &mut bytes, &mut len)
            },
            0,
            "{}",
            take_last_error_message()
        );
        assert!(!bytes.is_null());
        assert!(len > 0);
        unsafe {
            lance_free_bytes(bytes);
            lance_index_segment_builder_free(builder);
        }
        options.has_train = false;

        // Implicit and explicit full coverage use native L2 PQ assignment.
        for fragment_count in [0, fragment_ids.len()] {
            scope.fragment_ids = if fragment_count == 0 {
                ptr::null()
            } else {
                fragment_ids.as_ptr()
            };
            scope.fragment_count = fragment_count;
            let builder = unsafe {
                lance_index_segment_builder_new_vector_with_options(
                    dataset,
                    column.as_ptr(),
                    ptr::null(),
                    &options,
                    &scope,
                )
            };
            assert!(!builder.is_null(), "{}", take_last_error_message());
            unsafe { lance_index_segment_builder_free(builder) };
        }

        scope.fragment_ids = fragment_ids.as_ptr();
        scope.fragment_count = 1;
        for metric in [LanceMetricType::L2, LanceMetricType::Cosine] {
            options.metric = metric as i32;
            let builder = unsafe {
                lance_index_segment_builder_new_vector_with_options(
                    dataset,
                    column.as_ptr(),
                    ptr::null(),
                    &options,
                    &scope,
                )
            };
            assert!(!builder.is_null(), "{}", take_last_error_message());
            unsafe { lance_index_segment_builder_free(builder) };
        }
        assert!(!centroids.is_released());
        assert!(!codebook.is_released());
    }
    unsafe {
        if let Some(release) = centroids.release {
            release(&mut centroids);
        }
        if let Some(release) = codebook.release {
            release(&mut codebook);
        }
        lance_dataset_close(dataset);
    }
}

