#[test]
fn test_scanner_nearest_multi_fragment() {
    use arrow_array::builder::{FixedSizeListBuilder, Float32Builder};

    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp.path().join("multifrag").to_str().unwrap().to_string();
    let dim: i32 = 8;
    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new(
            "embedding",
            DataType::FixedSizeList(Arc::new(Field::new("item", DataType::Float32, true)), dim),
            false,
        ),
    ]));

    let mut batches = Vec::new();
    for frag in 0..2i32 {
        let mut emb = FixedSizeListBuilder::new(Float32Builder::new(), dim);
        let ids: Vec<i32> = (0..32i32).map(|i| frag * 32 + i).collect();
        for _ in 0..32 {
            for _ in 0..dim {
                emb.values().append_value(0.5);
            }
            emb.append(true);
        }
        batches.push(
            RecordBatch::try_new(
                schema.clone(),
                vec![Arc::new(Int32Array::from(ids)), Arc::new(emb.finish())],
            )
            .unwrap(),
        );
    }

    lance_c::runtime::block_on(async {
        Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(
                vec![Ok(batches[0].clone())],
                schema.clone(),
            ),
            &uri,
            None,
        )
        .await
        .unwrap();
        let params = lance::dataset::WriteParams {
            mode: lance::dataset::WriteMode::Append,
            ..Default::default()
        };
        Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(batches[1].clone())], schema),
            &uri,
            Some(params),
        )
        .await
        .unwrap();
    });

    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert_eq!(unsafe { lance_dataset_fragment_count(ds) }, 2);

    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    let column = c_str("embedding");
    let query: Vec<f32> = vec![0.5; 8];
    unsafe {
        lance_scanner_nearest(
            scanner,
            column.as_ptr(),
            query.as_ptr() as *const std::ffi::c_void,
            8,
            LanceDataType::Float32 as i32,
            20,
        );
    }
    let mut stream = FFI_ArrowArrayStream::empty();
    assert_eq!(
        unsafe { lance_scanner_to_arrow_stream(scanner, &mut stream as *mut _) },
        0
    );
    let reader = unsafe { ArrowArrayStreamReader::from_raw(&mut stream as *mut _).unwrap() };
    let mut total = 0;
    for b in reader {
        total += b.unwrap().num_rows();
    }
    assert_eq!(total, 20);

    unsafe { lance_scanner_close(scanner) };
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_scanner_nearest_null_safety() {
    let column = c_str("embedding");
    let query: Vec<f32> = vec![0.0; 8];
    // NULL scanner
    let rc = unsafe {
        lance_scanner_nearest(
            ptr::null_mut(),
            column.as_ptr(),
            query.as_ptr() as *const std::ffi::c_void,
            8,
            LanceDataType::Float32 as i32,
            5,
        )
    };
    assert_eq!(rc, -1);

    // Build a valid scanner.
    let (_tmp, uri) = create_vector_dataset(8, 8);
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };

    // NULL column.
    let rc2 = unsafe {
        lance_scanner_nearest(
            scanner,
            ptr::null(),
            query.as_ptr() as *const std::ffi::c_void,
            8,
            LanceDataType::Float32 as i32,
            5,
        )
    };
    assert_eq!(rc2, -1);

    // NULL query_data.
    let rc3 = unsafe {
        lance_scanner_nearest(
            scanner,
            column.as_ptr(),
            ptr::null(),
            8,
            LanceDataType::Float32 as i32,
            5,
        )
    };
    assert_eq!(rc3, -1);

    unsafe { lance_scanner_close(scanner) };
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_scanner_full_text_search() {
    let (_tmp, uri) = create_test_dataset();
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    let column = c_str("name");
    // Build inverted index on `name` first.
    let inverted_params = c_str(r#"{"base_tokenizer":"simple","language":"English"}"#);
    unsafe {
        lance_dataset_create_scalar_index(
            ds,
            column.as_ptr(),
            ptr::null(),
            LanceScalarIndexType::Inverted as i32,
            inverted_params.as_ptr(),
            false,
        );
    }
    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    let q = c_str("alice");
    let cols = [column.as_ptr(), ptr::null()];
    let rc = unsafe { lance_scanner_full_text_search(scanner, q.as_ptr(), cols.as_ptr(), 0) };
    assert_eq!(rc, 0, "{}", unsafe {
        std::ffi::CStr::from_ptr(lance_last_error_message()).to_string_lossy()
    });

    let mut stream = FFI_ArrowArrayStream::empty();
    assert_eq!(
        unsafe { lance_scanner_to_arrow_stream(scanner, &mut stream as *mut _) },
        0
    );
    let reader = unsafe { ArrowArrayStreamReader::from_raw(&mut stream as *mut _).unwrap() };
    let schema = reader.schema();
    assert!(
        schema.field_with_name("_score").is_ok(),
        "_score column missing from schema"
    );
    let mut total = 0;
    for b in reader {
        total += b.unwrap().num_rows();
    }
    assert!(total >= 1, "expected at least 1 hit for 'alice'");
    unsafe { lance_scanner_close(scanner) };
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_scanner_fts_projection_and_scoring_autoprojection() {
    use lance_index::scalar::FullTextSearchQuery;

    let (_tmp, uri) = create_test_dataset();
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    let column = c_str("name");
    let inverted_params = c_str(r#"{"base_tokenizer":"simple","language":"English"}"#);
    assert_eq!(
        unsafe {
            lance_dataset_create_scalar_index(
                ds,
                column.as_ptr(),
                ptr::null(),
                LanceScalarIndexType::Inverted as i32,
                inverted_params.as_ptr(),
                false,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );

    let fts_rows = |schema: &Schema, batches: &[RecordBatch]| {
        let id_name = if schema.field_with_name("id_alias").is_ok() {
            "id_alias"
        } else {
            "id"
        };
        let mut rows = Vec::new();
        for batch in batches {
            let ids = batch
                .column_by_name(id_name)
                .unwrap()
                .as_any()
                .downcast_ref::<Int32Array>()
                .unwrap();
            let scores = batch
                .column_by_name("_score")
                .map(|array| array.as_any().downcast_ref::<Float32Array>().unwrap());
            for row in 0..batch.num_rows() {
                rows.push((
                    ids.value(row),
                    scores.and_then(|values| (!values.is_null(row)).then(|| values.value(row))),
                ));
            }
        }
        rows.sort_unstable_by_key(|row| row.0);
        rows
    };

    let scan_c = |projection: &[(&str, &str)], disable: bool| {
        let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
        assert_eq!(
            set_projection(scanner, projection),
            0,
            "{}",
            take_last_error_message()
        );
        if disable {
            assert_eq!(
                unsafe { lance_scanner_disable_scoring_autoprojection(scanner) },
                0
            );
        }
        let query = c_str("alice");
        let columns = [column.as_ptr(), ptr::null()];
        assert_eq!(
            unsafe { lance_scanner_full_text_search(scanner, query.as_ptr(), columns.as_ptr(), 0) },
            0,
            "{}",
            take_last_error_message()
        );
        let result = collect_scanner(scanner);
        unsafe { lance_scanner_close(scanner) };
        result
    };

    let scan_native = |projection: &[(&str, &str)], disable: bool| {
        lance_c::runtime::block_on(async {
            let dataset = Dataset::open(&uri).await.unwrap();
            let mut scanner = dataset.scan();
            scanner.project_with_transform(projection).unwrap();
            if disable {
                scanner.disable_scoring_autoprojection();
            }
            scanner
                .full_text_search(
                    FullTextSearchQuery::new("alice".to_string())
                        .with_columns(&["name".to_string()])
                        .unwrap(),
                )
                .unwrap();
            let stream = scanner.try_into_stream().await.unwrap();
            let schema = stream.schema();
            let batches = stream.try_collect::<Vec<_>>().await.unwrap();
            (schema, batches)
        })
    };

    let projection = [("id_alias", "id"), ("name_alias", "name")];
    let explicit_score = [
        ("id_alias", "id"),
        ("name_alias", "name"),
        ("_score", "_score"),
    ];
    for (projection, disable, expect_score) in [
        (projection.as_slice(), false, true),
        (projection.as_slice(), true, false),
        (explicit_score.as_slice(), true, true),
    ] {
        let (c_schema, c_batches) = scan_c(projection, disable);
        assert_eq!(
            c_schema.field_with_name("_score").is_ok(),
            expect_score,
            "disable={disable}"
        );
        let (native_schema, native_batches) = scan_native(projection, disable);
        assert_eq!(
            schema_signature(c_schema.as_ref()),
            schema_signature(native_schema.as_ref())
        );
        assert_eq!(
            fts_rows(c_schema.as_ref(), &c_batches),
            fts_rows(native_schema.as_ref(), &native_batches)
        );
    }

    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_fts_fuzzy() {
    let (_tmp, uri) = create_test_dataset();
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    let column = c_str("name");
    let inverted_params = c_str(r#"{"base_tokenizer":"simple","language":"English"}"#);
    unsafe {
        lance_dataset_create_scalar_index(
            ds,
            column.as_ptr(),
            ptr::null(),
            LanceScalarIndexType::Inverted as i32,
            inverted_params.as_ptr(),
            false,
        );
    }
    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    // "alise" within edit distance 2 of "alice" (in the test fixture).
    let q = c_str("alise");
    let cols = [column.as_ptr(), ptr::null()];
    let rc = unsafe { lance_scanner_full_text_search(scanner, q.as_ptr(), cols.as_ptr(), 2) };
    assert_eq!(rc, 0, "{}", unsafe {
        std::ffi::CStr::from_ptr(lance_last_error_message()).to_string_lossy()
    });

    let mut stream = FFI_ArrowArrayStream::empty();
    assert_eq!(
        unsafe { lance_scanner_to_arrow_stream(scanner, &mut stream as *mut _) },
        0
    );
    let reader = unsafe { ArrowArrayStreamReader::from_raw(&mut stream as *mut _).unwrap() };
    let mut total = 0;
    for b in reader {
        total += b.unwrap().num_rows();
    }
    assert!(total >= 1, "expected fuzzy match for 'alise' → 'alice'");

    unsafe { lance_scanner_close(scanner) };
    unsafe { lance_dataset_close(ds) };
}

fn create_typed_fts_dataset() -> (tempfile::TempDir, String) {
    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp
        .path()
        .join("typed_fts_dataset")
        .to_str()
        .unwrap()
        .to_string();
    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new("title", DataType::Utf8, false),
        Field::new("body", DataType::Utf8, false),
        Field::new("category", DataType::Utf8, false),
    ]));

    let make_batch =
        |ids: Vec<i32>, titles: Vec<&str>, bodies: Vec<&str>, categories: Vec<&str>| {
            RecordBatch::try_new(
                schema.clone(),
                vec![
                    Arc::new(Int32Array::from(ids)),
                    Arc::new(StringArray::from(titles)),
                    Arc::new(StringArray::from(bodies)),
                    Arc::new(StringArray::from(categories)),
                ],
            )
            .unwrap()
        };
    let first = make_batch(
        vec![1, 2, 3, 4],
        vec!["alpha beta", "alpha", "alpha beta", "beta gamma"],
        vec!["gamma rust", "delta rust", "gamma", "alpha"],
        vec!["a", "b", "a", "b"],
    );
    let second = make_batch(
        vec![5, 6, 7, 8, 9, 10],
        vec!["rust rust", "rust", "lance", "delta", "rusty", "bust"],
        vec![
            "lance",
            "rust rust rust",
            "database",
            "alpha",
            "suffix",
            "prefix",
        ],
        vec!["a", "b", "a", "b", "a", "b"],
    );

    lance_c::runtime::block_on(async {
        Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(first)], schema.clone()),
            &uri,
            None,
        )
        .await
        .unwrap()
        .append(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(second)], schema),
            None,
        )
        .await
        .unwrap();
    });

    let uri_c = c_str(&uri);
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null(), "{}", take_last_error_message());
    let params = c_str(r#"{"base_tokenizer":"simple","language":"English","with_position":true}"#);
    for column in ["title", "body"] {
        let column = c_str(column);
        assert_eq!(
            unsafe {
                lance_dataset_create_scalar_index(
                    dataset,
                    column.as_ptr(),
                    ptr::null(),
                    LanceScalarIndexType::Inverted as i32,
                    params.as_ptr(),
                    false,
                )
            },
            0,
            "{}",
            take_last_error_message()
        );
    }
    unsafe { lance_dataset_close(dataset) };

    (tmp, uri)
}

