fn typed_match(
    terms: &str,
    column: Option<&str>,
    options: &LanceFtsMatchOptions,
) -> *mut LanceFtsQuery {
    let terms = c_str(terms);
    let column = column.map(c_str);
    let query = unsafe {
        lance_fts_query_match_new(
            terms.as_ptr(),
            column.as_ref().map_or(ptr::null(), |value| value.as_ptr()),
            options,
        )
    };
    assert!(!query.is_null(), "{}", take_last_error_message());
    query
}

