#[test]
fn test_prepared_fts_row_id_output_is_explicit() {
    let (_tmp, uri) = create_test_dataset();
    let uri_c = c_str(&uri);
    let column = c_str("name");
    let query = c_str("alice");
    let inverted_params = c_str(r#"{"base_tokenizer":"simple","language":"English"}"#);

    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert_eq!(
        unsafe {
            lance_dataset_create_scalar_index(
                dataset,
                column.as_ptr(),
                ptr::null(),
                LanceScalarIndexType::Inverted as i32,
                inverted_params.as_ptr(),
                false,
            )
        },
        0
    );
    let context = unsafe {
        lance_dataset_prepare_fts_match_query(
            dataset,
            column.as_ptr(),
            query.as_ptr(),
            LanceFtsMatchOperator::Or as i32,
            0,
            LanceFtsCoverageMode::Strict as i32,
        )
    };
    assert!(!context.is_null(), "{}", unsafe {
        std::ffi::CStr::from_ptr(lance_last_error_message()).to_string_lossy()
    });

    let id = c_str("id");
    let columns = [id.as_ptr(), ptr::null()];
    let scan_schema = |with_row_id: bool| {
        let scanner = unsafe { lance_scanner_new(dataset, columns.as_ptr(), ptr::null()) };
        assert!(!scanner.is_null());
        if with_row_id {
            assert_eq!(unsafe { lance_scanner_with_row_id(scanner, true) }, 0);
        }
        assert_eq!(
            unsafe { lance_scanner_set_fts_query_context(scanner, context) },
            0
        );
        let mut stream = FFI_ArrowArrayStream::empty();
        assert_eq!(
            unsafe { lance_scanner_to_arrow_stream(scanner, &mut stream) },
            0,
            "{}",
            unsafe { std::ffi::CStr::from_ptr(lance_last_error_message()).to_string_lossy() }
        );
        let reader = unsafe { ArrowArrayStreamReader::from_raw(&mut stream).unwrap() };
        let schema = reader.schema();
        let rows: usize = reader.map(|batch| batch.unwrap().num_rows()).sum();
        assert!(rows > 0);
        unsafe { lance_scanner_close(scanner) };
        schema
    };

    let without_row_id = scan_schema(false);
    assert_eq!(without_row_id.fields().len(), 2);
    assert!(without_row_id.field_with_name("id").is_ok());
    assert!(without_row_id.field_with_name("_score").is_ok());
    assert!(without_row_id.field_with_name("_rowid").is_err());

    let with_row_id = scan_schema(true);
    assert_eq!(with_row_id.fields().len(), 3);
    assert!(with_row_id.field_with_name("id").is_ok());
    assert!(with_row_id.field_with_name("_score").is_ok());
    assert!(with_row_id.field_with_name("_rowid").is_ok());

    unsafe { lance_fts_query_context_close(context) };
    unsafe { lance_dataset_close(dataset) };
}

#[test]
fn test_prepared_fts_expression_projection_and_scoring_control() {
    let (_tmp, uri) = create_test_dataset();
    let uri_c = c_str(&uri);
    let column = c_str("name");
    let query = c_str("alice");
    let inverted_params = c_str(r#"{"base_tokenizer":"simple","language":"English"}"#);

    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert_eq!(
        unsafe {
            lance_dataset_create_scalar_index(
                dataset,
                column.as_ptr(),
                ptr::null(),
                LanceScalarIndexType::Inverted as i32,
                inverted_params.as_ptr(),
                false,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    let context = unsafe {
        lance_dataset_prepare_fts_match_query(
            dataset,
            column.as_ptr(),
            query.as_ptr(),
            LanceFtsMatchOperator::Or as i32,
            0,
            LanceFtsCoverageMode::Strict as i32,
        )
    };
    assert!(!context.is_null(), "{}", take_last_error_message());
    let row_ids = ordering_row_ids(dataset);
    let allow_ids = [row_ids[&1]];
    let filter = c_str("id <= 1");

    let scan = |projection: &[(&str, &str)], disable: bool| {
        let scanner = unsafe { lance_scanner_new(dataset, ptr::null(), filter.as_ptr()) };
        assert_eq!(
            set_projection(scanner, projection),
            0,
            "{}",
            take_last_error_message()
        );
        if disable {
            assert_eq!(
                unsafe { lance_scanner_disable_scoring_autoprojection(scanner) },
                0
            );
        }
        assert_eq!(
            unsafe { lance_scanner_set_fts_query_context(scanner, context) },
            0,
            "{}",
            take_last_error_message()
        );
        assert_eq!(
            unsafe {
                lance_scanner_set_row_addr_allowlist(scanner, allow_ids.as_ptr(), allow_ids.len())
            },
            0,
            "{}",
            take_last_error_message()
        );
        let introspected_schema = scanner_introspection_schema(scanner);
        assert_eq!(
            schema_signature(&scanner_introspection_schema(scanner)),
            schema_signature(&introspected_schema)
        );
        let count = unsafe { lance_scanner_count_rows(scanner) };
        assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
        let analyze_count =
            take_scanner_string(unsafe { lance_scanner_analyze_count_plan(scanner) });
        assert!(analyze_count.contains("AggregateExec"), "{analyze_count}");
        assert_eq!(
            unsafe { lance_scanner_set_batch_size(scanner, 2) },
            0,
            "inspection and count must leave FTS configuration editable"
        );
        let (schema, batches) = collect_scanner(scanner);
        assert_eq!(
            schema_signature(&schema),
            schema_signature(&introspected_schema)
        );
        assert_eq!(
            count,
            batches.iter().map(RecordBatch::num_rows).sum::<usize>() as u64
        );
        assert_eq!(count, 1);
        unsafe { lance_scanner_close(scanner) };
        (
            schema,
            batches.iter().map(RecordBatch::num_rows).sum::<usize>(),
            count,
        )
    };

    let projection = [("id_alias", "id")];
    let explicit_score = [("id_alias", "id"), ("_score", "_score")];

    let (legacy_schema, legacy_rows, legacy_count) = scan(&projection, false);
    assert!(legacy_schema.field_with_name("_score").is_ok());
    assert!(legacy_rows > 0);
    assert_eq!(legacy_count, legacy_rows as u64);

    let (disabled_schema, disabled_rows, disabled_count) = scan(&projection, true);
    assert!(disabled_schema.field_with_name("_score").is_err());
    assert_eq!(disabled_rows, legacy_rows);
    assert_eq!(disabled_count, legacy_rows as u64);

    let (explicit_schema, explicit_rows, explicit_count) = scan(&explicit_score, true);
    assert!(explicit_schema.field_with_name("_score").is_ok());
    assert_eq!(explicit_rows, legacy_rows);
    assert_eq!(explicit_count, legacy_rows as u64);

    unsafe {
        lance_fts_query_context_close(context);
        lance_dataset_close(dataset);
    };
}

#[test]
fn test_prepare_fts_query_index_only_allows_unindexed_fragment() {
    let (_tmp, uri) = create_test_dataset();
    let uri_c = c_str(&uri);
    let column = c_str("name");
    let query = c_str("alice");
    let inverted_params = c_str(r#"{"base_tokenizer":"simple","language":"English"}"#);

    let indexed_snapshot = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert_eq!(
        unsafe {
            lance_dataset_create_scalar_index(
                indexed_snapshot,
                column.as_ptr(),
                ptr::null(),
                LanceScalarIndexType::Inverted as i32,
                inverted_params.as_ptr(),
                false,
            )
        },
        0
    );
    unsafe { lance_dataset_close(indexed_snapshot) };

    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new("name", DataType::Utf8, true),
    ]));
    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![
            Arc::new(Int32Array::from(vec![6, 7])),
            Arc::new(StringArray::from(vec!["alice", "alice alice"])),
        ],
    )
    .unwrap();
    append_batch(&uri, schema, batch);

    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    let strict = unsafe {
        lance_dataset_prepare_fts_match_query(
            dataset,
            column.as_ptr(),
            query.as_ptr(),
            LanceFtsMatchOperator::Or as i32,
            0,
            LanceFtsCoverageMode::Strict as i32,
        )
    };
    assert!(strict.is_null());
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = unsafe {
        std::ffi::CStr::from_ptr(lance_last_error_message())
            .to_string_lossy()
            .into_owned()
    };
    assert!(message.contains("unindexed fragments"), "{message}");

    let context = unsafe {
        lance_dataset_prepare_fts_match_query(
            dataset,
            column.as_ptr(),
            query.as_ptr(),
            LanceFtsMatchOperator::Or as i32,
            0,
            LanceFtsCoverageMode::IndexOnly as i32,
        )
    };
    assert!(!context.is_null());
    let segment_uuids = load_fts_segment_uuids(&uri, "name");
    assert_eq!(segment_uuids.len(), 1);

    let scanner = unsafe { lance_scanner_new(dataset, ptr::null(), ptr::null()) };
    assert_eq!(
        unsafe { lance_scanner_set_fts_query_context(scanner, context) },
        0
    );
    // Scanner retains an Arc; closing the public handle does not invalidate it.
    unsafe { lance_fts_query_context_close(context) };
    assert_eq!(
        unsafe {
            lance_scanner_set_fts_index_segments(
                scanner,
                segment_uuids.as_ptr().cast::<u8>(),
                segment_uuids.len(),
            )
        },
        0
    );
    let mut stream = FFI_ArrowArrayStream::empty();
    assert_eq!(
        unsafe { lance_scanner_to_arrow_stream(scanner, &mut stream) },
        0
    );
    let reader = unsafe { ArrowArrayStreamReader::from_raw(&mut stream).unwrap() };
    let total_rows: usize = reader.map(|batch| batch.unwrap().num_rows()).sum();
    assert_eq!(
        total_rows, 1,
        "INDEX_ONLY must exclude both matching rows in the unindexed fragment"
    );

    unsafe { lance_scanner_close(scanner) };
    unsafe { lance_dataset_close(dataset) };
}

#[test]
fn test_prepared_fts_index_only_empty_segment_returns_empty_shard() {
    use lance::index::DatasetIndexExt;
    use lance_index::{IndexType, scalar::InvertedIndexParams};

    let (_tmp, uri) = create_test_dataset();
    lance_c::runtime::block_on(async {
        let mut dataset = Dataset::open(&uri).await.unwrap();
        let params = InvertedIndexParams::default().with_position(true);
        dataset
            .create_index_builder(&["name"], IndexType::Inverted, &params)
            .name("empty_name_fts".to_string())
            .train(false)
            .await
            .unwrap();
        let segments = dataset
            .load_indices_by_name("empty_name_fts")
            .await
            .unwrap();
        assert_eq!(segments.len(), 1);
        assert!(
            segments[0]
                .fragment_bitmap
                .as_ref()
                .is_some_and(|fragment_bitmap| fragment_bitmap.is_empty())
        );
    });

    let uri_c = c_str(&uri);
    let column = c_str("name");
    let query = c_str("alice");
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    let segment_uuids = load_fts_segment_uuids(&uri, "name");
    assert_eq!(segment_uuids.len(), 1);

    for phrase in [false, true] {
        let context = unsafe {
            if phrase {
                lance_dataset_prepare_fts_phrase_query(
                    dataset,
                    column.as_ptr(),
                    query.as_ptr(),
                    0,
                    LanceFtsCoverageMode::IndexOnly as i32,
                )
            } else {
                lance_dataset_prepare_fts_match_query(
                    dataset,
                    column.as_ptr(),
                    query.as_ptr(),
                    LanceFtsMatchOperator::Or as i32,
                    0,
                    LanceFtsCoverageMode::IndexOnly as i32,
                )
            }
        };
        assert!(!context.is_null(), "{}", unsafe {
            std::ffi::CStr::from_ptr(lance_last_error_message()).to_string_lossy()
        });
        for fast_search in [false, true] {
            let scanner = unsafe { lance_scanner_new(dataset, ptr::null(), ptr::null()) };
            assert_eq!(
                unsafe { lance_scanner_set_fts_query_context(scanner, context) },
                0
            );
            assert_eq!(
                unsafe {
                    lance_scanner_set_fts_index_segments(
                        scanner,
                        segment_uuids.as_ptr().cast::<u8>(),
                        segment_uuids.len(),
                    )
                },
                0
            );
            assert_eq!(
                unsafe { lance_scanner_set_fast_search(scanner, fast_search) },
                0
            );

            let introspected_schema = scanner_introspection_schema(scanner);
            assert_eq!(
                schema_signature(&scanner_introspection_schema(scanner)),
                schema_signature(&introspected_schema)
            );
            let explain = take_scanner_string(unsafe { lance_scanner_explain_plan(scanner, true) });
            assert!(!explain.is_empty());
            assert!(explain.contains("EmptyExec"), "{explain}");
            assert_eq!(unsafe { lance_scanner_count_rows(scanner) }, 0);
            assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
            assert_eq!(unsafe { lance_scanner_count_rows(scanner) }, 0);
            let analyze_count =
                take_scanner_string(unsafe { lance_scanner_analyze_count_plan(scanner) });
            assert!(analyze_count.contains("AggregateExec"), "{analyze_count}");
            assert_eq!(
                unsafe { lance_scanner_set_batch_size(scanner, 2) },
                0,
                "planning and count must leave the scanner configurable"
            );

            let mut stream = FFI_ArrowArrayStream::empty();
            assert_eq!(
                unsafe { lance_scanner_to_arrow_stream(scanner, &mut stream) },
                0,
                "phrase={phrase}, fast_search={fast_search}: {}",
                unsafe { std::ffi::CStr::from_ptr(lance_last_error_message()).to_string_lossy() }
            );
            let reader = unsafe { ArrowArrayStreamReader::from_raw(&mut stream).unwrap() };
            assert_eq!(
                schema_signature(&reader.schema()),
                schema_signature(&introspected_schema)
            );
            let total_rows: usize = reader.map(|batch| batch.unwrap().num_rows()).sum();
            assert_eq!(total_rows, 0);
            unsafe { lance_scanner_close(scanner) };
        }
        unsafe { lance_fts_query_context_close(context) };
    }
    unsafe { lance_dataset_close(dataset) };
}

#[test]
fn test_prepared_fts_global_scorer_is_shared_across_segment_splits() {
    use lance::index::DatasetIndexExt;
    use lance_index::optimize::OptimizeOptions;

    let (_tmp, uri) = create_test_dataset();
    let uri_c = c_str(&uri);
    let column = c_str("name");
    let query = c_str("alice");
    let inverted_params = c_str(r#"{"base_tokenizer":"simple","language":"English"}"#);

    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert_eq!(
        unsafe {
            lance_dataset_create_scalar_index(
                dataset,
                column.as_ptr(),
                ptr::null(),
                LanceScalarIndexType::Inverted as i32,
                inverted_params.as_ptr(),
                false,
            )
        },
        0
    );
    unsafe { lance_dataset_close(dataset) };

    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new("name", DataType::Utf8, true),
    ]));
    append_batch(
        &uri,
        schema.clone(),
        RecordBatch::try_new(
            schema,
            vec![
                Arc::new(Int32Array::from(vec![6, 7])),
                Arc::new(StringArray::from(vec!["alice", "alice alice"])),
            ],
        )
        .unwrap(),
    );
    lance_c::runtime::block_on(async {
        let mut dataset = Dataset::open(&uri).await.unwrap();
        dataset
            .optimize_indices(&OptimizeOptions::append())
            .await
            .unwrap();
    });

    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    let context = unsafe {
        lance_dataset_prepare_fts_match_query(
            dataset,
            column.as_ptr(),
            query.as_ptr(),
            LanceFtsMatchOperator::Or as i32,
            0,
            LanceFtsCoverageMode::Strict as i32,
        )
    };
    assert!(!context.is_null(), "{}", unsafe {
        std::ffi::CStr::from_ptr(lance_last_error_message()).to_string_lossy()
    });
    let segment_uuids = load_fts_segment_uuids(&uri, "name");
    assert_eq!(segment_uuids.len(), 2);

    let full_scores = collect_context_fts_scores(dataset, context, None);
    assert_eq!(full_scores.len(), 3);
    let full_count = collect_context_fts_count(dataset, context, None);
    assert_eq!(full_count, full_scores.len() as u64);
    let mut split_scores = std::collections::HashMap::new();
    let mut split_count = 0;
    for segment_uuid in &segment_uuids {
        let segment = std::slice::from_ref(segment_uuid);
        let scores = collect_context_fts_scores(dataset, context, Some(segment));
        let count = collect_context_fts_count(dataset, context, Some(segment));
        assert_eq!(count, scores.len() as u64);
        split_count += count;
        for (id, score) in scores {
            assert!(split_scores.insert(id, score).is_none());
        }
    }
    assert_eq!(split_count, full_count);
    assert_eq!(split_scores.len(), full_scores.len());
    for (id, expected_score) in full_scores {
        let actual_score = split_scores.get(&id).unwrap();
        assert!(
            (actual_score - expected_score).abs() < 1e-6,
            "id={id}, full={expected_score}, split={actual_score}"
        );
    }

    let scanner = unsafe { lance_scanner_new(dataset, ptr::null(), ptr::null()) };
    let duplicate_segments = [segment_uuids[0], segment_uuids[0]];
    assert_eq!(
        unsafe {
            lance_scanner_set_fts_index_segments(
                scanner,
                duplicate_segments.as_ptr().cast::<u8>(),
                duplicate_segments.len(),
            )
        },
        -1
    );
    assert!(unsafe { lance_scanner_set_fts_query_context(scanner, ptr::null()) } < 0);

    unsafe { lance_scanner_close(scanner) };

    let unknown_segment_scanner = unsafe { lance_scanner_new(dataset, ptr::null(), ptr::null()) };
    assert_eq!(
        unsafe { lance_scanner_set_fts_query_context(unknown_segment_scanner, context) },
        0
    );
    let unknown_uuid = [0_u8; 16];
    assert_eq!(
        unsafe {
            lance_scanner_set_fts_index_segments(unknown_segment_scanner, unknown_uuid.as_ptr(), 1)
        },
        0,
        "membership is validated against the attached context at scan time"
    );
    let mut stream = FFI_ArrowArrayStream::empty();
    assert_eq!(
        unsafe { lance_scanner_to_arrow_stream(unknown_segment_scanner, &mut stream) },
        -1
    );
    unsafe { lance_scanner_close(unknown_segment_scanner) };

    let independently_reopened = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!independently_reopened.is_null());
    assert_eq!(
        unsafe { lance_dataset_version(independently_reopened) },
        unsafe { lance_dataset_version(dataset) },
        "the identity check must reject equal URI/version locator metadata"
    );
    let reopened_scanner =
        unsafe { lance_scanner_new(independently_reopened, ptr::null(), ptr::null()) };
    assert_eq!(
        unsafe { lance_scanner_set_fts_query_context(reopened_scanner, context) },
        -1,
        "an independently opened dataset must not reuse the prepared context"
    );
    let message = unsafe {
        std::ffi::CStr::from_ptr(lance_last_error_message())
            .to_string_lossy()
            .into_owned()
    };
    assert!(
        message.contains("same process-local dataset snapshot"),
        "{message}"
    );
    unsafe { lance_scanner_close(reopened_scanner) };
    unsafe { lance_dataset_close(independently_reopened) };

    let old_snapshot = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 2) };
    assert!(!old_snapshot.is_null());
    let old_snapshot_scanner = unsafe { lance_scanner_new(old_snapshot, ptr::null(), ptr::null()) };
    assert_eq!(
        unsafe { lance_scanner_set_fts_query_context(old_snapshot_scanner, context) },
        -1,
        "a context must not be attached to a different dataset version"
    );
    unsafe { lance_scanner_close(old_snapshot_scanner) };
    unsafe { lance_dataset_close(old_snapshot) };

    unsafe { lance_fts_query_context_close(context) };
    unsafe { lance_dataset_close(dataset) };
}

#[test]
fn test_prepared_fts_prefilter_is_scoped_to_selected_segments() {
    use lance::index::DatasetIndexExt;
    use lance_index::IndexCriteria;
    use lance_index::optimize::OptimizeOptions;

    let (_tmp, uri) = create_test_dataset();
    let uri_c = c_str(&uri);
    let column = c_str("name");
    let query = c_str("alice");
    let inverted_params = c_str(r#"{"base_tokenizer":"simple","language":"English"}"#);

    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert_eq!(
        unsafe {
            lance_dataset_create_scalar_index(
                dataset,
                column.as_ptr(),
                ptr::null(),
                LanceScalarIndexType::Inverted as i32,
                inverted_params.as_ptr(),
                false,
            )
        },
        0
    );
    unsafe { lance_dataset_close(dataset) };

    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new("name", DataType::Utf8, true),
    ]));
    append_batch(
        &uri,
        schema.clone(),
        RecordBatch::try_new(
            schema,
            vec![
                Arc::new(Int32Array::from(vec![6, 7])),
                Arc::new(StringArray::from(vec!["alice", "alice alice"])),
            ],
        )
        .unwrap(),
    );
    lance_c::runtime::block_on(async {
        let mut dataset = Dataset::open(&uri).await.unwrap();
        dataset
            .optimize_indices(&OptimizeOptions::append())
            .await
            .unwrap();
    });

    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    let context = unsafe {
        lance_dataset_prepare_fts_match_query(
            dataset,
            column.as_ptr(),
            query.as_ptr(),
            LanceFtsMatchOperator::Or as i32,
            0,
            LanceFtsCoverageMode::Strict as i32,
        )
    };
    assert!(!context.is_null(), "{}", take_last_error_message());

    let mut fragment_ids = [0_u64; 2];
    assert_eq!(unsafe { lance_dataset_fragment_count(dataset) }, 2);
    assert_eq!(
        unsafe { lance_dataset_fragment_ids(dataset, fragment_ids.as_mut_ptr()) },
        0
    );
    let selected_segment_uuid = lance_c::runtime::block_on(async {
        let dataset = Dataset::open(&uri).await.unwrap();
        let logical_index = dataset
            .load_scalar_index(IndexCriteria::default().for_column("name").supports_fts())
            .await
            .unwrap()
            .unwrap();
        let segments = dataset
            .load_indices_by_name(&logical_index.name)
            .await
            .unwrap();
        assert_eq!(segments.len(), 2);

        let selected_fragment_id = u32::try_from(fragment_ids[1]).unwrap();
        let unselected_fragment_id = u32::try_from(fragment_ids[0]).unwrap();
        let selected_segments = segments
            .iter()
            .filter(|segment| {
                segment
                    .fragment_bitmap
                    .as_ref()
                    .is_some_and(|bitmap| bitmap.iter().any(|id| id == selected_fragment_id))
            })
            .collect::<Vec<_>>();
        assert_eq!(selected_segments.len(), 1);
        assert!(
            !selected_segments[0]
                .fragment_bitmap
                .as_ref()
                .unwrap()
                .iter()
                .any(|id| id == unselected_fragment_id),
            "the selected FTS segment should cover only the appended fragment"
        );
        *selected_segments[0].uuid.as_bytes()
    });

    let full_scores = collect_context_fts_scores(dataset, context, None);
    let mut full_ids = full_scores.keys().copied().collect::<Vec<_>>();
    full_ids.sort_unstable();
    assert_eq!(full_ids, vec![1, 6, 7]);

    // Match rows in both fragments: four rows in the unselected fragment and
    // both rows in the selected fragment. The prefilter scan must stay scoped
    // to the selected segment's fragment.
    let filter = c_str("id != 2");
    let scanner = unsafe { lance_scanner_new(dataset, ptr::null(), filter.as_ptr()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe { lance_scanner_set_fts_query_context(scanner, context) },
        0
    );
    assert_eq!(
        unsafe { lance_scanner_set_fts_index_segments(scanner, selected_segment_uuid.as_ptr(), 1) },
        0
    );
    assert_eq!(unsafe { lance_scanner_set_prefilter(scanner, true) }, 0);
    let mut captured = CapturedScanStatistics::default();
    assert_eq!(
        unsafe {
            lance_scanner_set_statistics_callback(
                scanner,
                Some(capture_scan_statistics),
                (&mut captured as *mut CapturedScanStatistics).cast(),
            )
        },
        0
    );

    let mut stream = FFI_ArrowArrayStream::empty();
    assert_eq!(
        unsafe { lance_scanner_to_arrow_stream(scanner, &mut stream) },
        0,
        "{}",
        take_last_error_message()
    );
    let reader = unsafe { ArrowArrayStreamReader::from_raw(&mut stream).unwrap() };
    let mut filtered_scores = std::collections::HashMap::new();
    for batch in reader {
        let batch = batch.unwrap();
        let ids = batch
            .column_by_name("id")
            .unwrap()
            .as_any()
            .downcast_ref::<Int32Array>()
            .unwrap();
        let scores = batch
            .column_by_name("_score")
            .unwrap()
            .as_any()
            .downcast_ref::<Float32Array>()
            .unwrap();
        for row in 0..batch.num_rows() {
            assert!(
                filtered_scores
                    .insert(ids.value(row), scores.value(row))
                    .is_none()
            );
        }
    }
    let mut filtered_ids = filtered_scores.keys().copied().collect::<Vec<_>>();
    filtered_ids.sort_unstable();
    assert_eq!(filtered_ids, vec![6, 7]);
    for id in &filtered_ids {
        let actual_score = filtered_scores[id];
        let global_score = full_scores[id];
        assert!(
            (actual_score - global_score).abs() < 1e-6,
            "id={id}, selected-segment score={actual_score}, global score={global_score}"
        );
    }

    let metric_count = |name: &str| {
        captured
            .metrics
            .iter()
            .filter(|(metric, kind, _)| metric == name && *kind == LanceScanMetricKind::Count)
            .map(|(_, _, value)| *value)
            .sum::<u64>()
    };
    assert_eq!(captured.calls, 1);
    assert_eq!(
        metric_count("prefilter_input_rows"),
        2,
        "prefilter should read only the two rows in the selected segment's fragment"
    );
    assert_eq!(metric_count("prefilter_row_ids"), 2);

    unsafe {
        lance_scanner_close(scanner);
        lance_fts_query_context_close(context);
        lance_dataset_close(dataset);
    }
}

#[test]
fn test_prepare_fts_queries_reject_invalid_inputs() {
    let (_tmp, uri) = create_test_dataset();
    let uri_c = c_str(&uri);
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    let column = c_str("name");
    let query = c_str("alice");
    let empty = c_str("");

    assert!(
        unsafe {
            lance_dataset_prepare_fts_match_query(
                ptr::null(),
                column.as_ptr(),
                query.as_ptr(),
                LanceFtsMatchOperator::Or as i32,
                0,
                LanceFtsCoverageMode::Strict as i32,
            )
        }
        .is_null()
    );
    assert!(
        unsafe {
            lance_dataset_prepare_fts_match_query(
                dataset,
                empty.as_ptr(),
                query.as_ptr(),
                LanceFtsMatchOperator::Or as i32,
                0,
                LanceFtsCoverageMode::Strict as i32,
            )
        }
        .is_null()
    );
    assert!(
        unsafe {
            lance_dataset_prepare_fts_match_query(
                dataset,
                column.as_ptr(),
                empty.as_ptr(),
                LanceFtsMatchOperator::Or as i32,
                0,
                LanceFtsCoverageMode::Strict as i32,
            )
        }
        .is_null()
    );
    assert!(
        unsafe {
            lance_dataset_prepare_fts_match_query(
                dataset,
                column.as_ptr(),
                query.as_ptr(),
                LanceFtsMatchOperator::Or as i32,
                0,
                99,
            )
        }
        .is_null()
    );
    assert!(
        unsafe {
            lance_dataset_prepare_fts_match_query(
                dataset,
                column.as_ptr(),
                query.as_ptr(),
                99,
                0,
                LanceFtsCoverageMode::Strict as i32,
            )
        }
        .is_null()
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = unsafe {
        std::ffi::CStr::from_ptr(lance_last_error_message())
            .to_string_lossy()
            .into_owned()
    };
    assert!(message.contains("invalid match_operator"), "{message}");
    assert!(
        unsafe {
            lance_dataset_prepare_fts_phrase_query(
                dataset,
                column.as_ptr(),
                ptr::null(),
                0,
                LanceFtsCoverageMode::Strict as i32,
            )
        }
        .is_null()
    );
    let scanner = unsafe { lance_scanner_new(dataset, ptr::null(), ptr::null()) };
    assert_eq!(
        unsafe { lance_scanner_set_fts_index_segments(scanner, ptr::null(), 1) },
        -1
    );
    assert_eq!(
        unsafe { lance_scanner_set_fts_index_segments(scanner, ptr::null(), 0) },
        0
    );
    unsafe { lance_scanner_close(scanner) };
    unsafe { lance_fts_query_context_close(ptr::null_mut()) };
    unsafe { lance_dataset_close(dataset) };
}

#[test]
fn test_nearest_after_fts_is_rejected() {
    let (_tmp, uri) = create_vector_dataset(64, 8);
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };

    // Set FTS first (no inverted index needed for this test — error happens
    // at the second call, before any stream materialization).
    let q = c_str("foo");
    unsafe {
        lance_scanner_full_text_search(scanner, q.as_ptr(), ptr::null(), 0);
    }

    let column = c_str("embedding");
    let query: Vec<f32> = vec![0.5; 8];
    let rc = unsafe {
        lance_scanner_nearest(
            scanner,
            column.as_ptr(),
            query.as_ptr() as *const std::ffi::c_void,
            8,
            LanceDataType::Float32 as i32,
            5,
        )
    };
    assert_eq!(rc, -1);
    let msg = unsafe {
        std::ffi::CStr::from_ptr(lance_last_error_message())
            .to_string_lossy()
            .into_owned()
    };
    let lower = msg.to_lowercase();
    assert!(
        lower.contains("full_text")
            || lower.contains("fts")
            || lower.contains("mutually exclusive"),
        "msg was: {}",
        msg
    );

    unsafe { lance_scanner_close(scanner) };
    unsafe { lance_dataset_close(ds) };
}

// ---------------------------------------------------------------------------
// Dataset writer (lance_dataset_write)
// ---------------------------------------------------------------------------

fn write_schema() -> Arc<Schema> {
    Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new("val", DataType::Float32, true),
    ]))
}

fn write_batch(ids: Vec<i32>, vals: Vec<f32>) -> RecordBatch {
    assert_eq!(ids.len(), vals.len());
    RecordBatch::try_new(
        write_schema(),
        vec![
            Arc::new(Int32Array::from(ids)),
            Arc::new(Float32Array::from(vals)),
        ],
    )
    .unwrap()
}

fn ffi_record_batch(batch: &RecordBatch) -> (FFI_ArrowArray, FFI_ArrowSchema) {
    let struct_array: StructArray = batch.clone().into();
    (
        FFI_ArrowArray::new(&struct_array.into_data()),
        FFI_ArrowSchema::try_from(batch.schema().as_ref()).unwrap(),
    )
}

fn write_replacement_data_file(path: &str, batch: &RecordBatch) -> LanceFileWriteSummary {
    let (mut array, schema) = ffi_record_batch(batch);
    let mut imported = ptr::null_mut();
    assert_eq!(
        unsafe { lance_batch_from_arrow(&mut array, &schema, &mut imported) },
        0,
        "{}",
        take_last_error_message()
    );
    assert!(array.release.is_none());

    let path = c_str(path);
    let version = c_str("2.1");
    let mut options: LanceFileWriterOptions = unsafe { std::mem::zeroed() };
    options.version = version.as_ptr();
    let writer = unsafe {
        lance_file_writer_open(path.as_ptr(), &schema, &options, ptr::null(), ptr::null())
    };
    assert!(!writer.is_null(), "{}", take_last_error_message());
    assert_eq!(
        unsafe { lance_file_writer_write_batch(writer, imported) },
        0,
        "{}",
        take_last_error_message()
    );
    unsafe { lance_batch_free(imported) };

    let mut summary = LanceFileWriteSummary::default();
    assert_eq!(
        unsafe { lance_file_writer_finish(writer, &mut summary) },
        0,
        "{}",
        take_last_error_message()
    );
    unsafe { lance_file_writer_close(writer) };
    summary
}

#[test]
fn test_dataset_write_create() {
    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp.path().join("new_ds").to_str().unwrap().to_string();
    let c_uri = c_str(&uri);

    let ffi_schema = schema_to_ffi(&write_schema());
    let mut stream = batch_to_ffi_stream(write_batch(vec![1, 2, 3], vec![1.0, 2.0, 3.0]));

    let rc = unsafe {
        lance_dataset_write(
            c_uri.as_ptr(),
            &ffi_schema,
            &mut stream,
            LanceWriteMode::Create as i32,
            ptr::null(),
            ptr::null_mut(),
        )
    };
    assert_eq!(rc, 0, "lance_dataset_write create failed");
    assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);

    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());
    assert_eq!(unsafe { lance_dataset_count_rows(ds) }, 3);
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_dataset_write_populates_out_dataset() {
    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp.path().join("ds").to_str().unwrap().to_string();
    let c_uri = c_str(&uri);

    let ffi_schema = schema_to_ffi(&write_schema());
    let mut stream = batch_to_ffi_stream(write_batch(vec![1, 2, 3], vec![1.0, 2.0, 3.0]));

    let mut out_ds: *mut LanceDataset = ptr::null_mut();
    let rc = unsafe {
        lance_dataset_write(
            c_uri.as_ptr(),
            &ffi_schema,
            &mut stream,
            LanceWriteMode::Create as i32,
            ptr::null(),
            &mut out_ds,
        )
    };
    assert_eq!(rc, 0);
    assert!(!out_ds.is_null(), "out_dataset must be populated");
    assert_eq!(unsafe { lance_dataset_count_rows(out_ds) }, 3);
    unsafe { lance_dataset_close(out_ds) };
}

