#[test]
fn test_scanner_set_substrait_filter_invalid_inputs() {
    let (_tmp, uri) = create_test_dataset();
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());

    let bytes = [0u8; 4];

    // NULL scanner.
    let rc =
        unsafe { lance_scanner_set_substrait_filter(ptr::null_mut(), bytes.as_ptr(), bytes.len()) };
    assert_eq!(rc, -1);

    // NULL bytes pointer with non-zero len.
    let rc = unsafe { lance_scanner_set_substrait_filter(scanner, ptr::null(), 4) };
    assert_eq!(rc, -1);

    // Zero len (empty filter) is rejected.
    let rc = unsafe { lance_scanner_set_substrait_filter(scanner, bytes.as_ptr(), 0) };
    assert_eq!(rc, -1);

    unsafe { lance_scanner_close(scanner) };
    unsafe { lance_dataset_close(ds) };
}

fn sorted_cells(batches: &[RecordBatch]) -> Vec<Vec<Cell>> {
    let mut rows = cells(batches);
    rows.sort_by_key(|row| format!("{row:?}"));
    rows
}

fn native_aggregate_batches_with_filter(
    uri: &str,
    bytes: &[u8],
    filter: Option<&str>,
) -> Vec<RecordBatch> {
    lance_c::runtime::block_on(async {
        let dataset = Dataset::open(uri).await.unwrap();
        let mut scanner = dataset.scan();
        if let Some(filter) = filter {
            scanner.filter(filter).unwrap();
        }
        scanner
            .aggregate(NativeAggregateExpr::substrait(bytes.to_vec()))
            .unwrap();
        let stream = scanner.try_into_stream().await.unwrap();
        stream.try_collect::<Vec<_>>().await.unwrap()
    })
}

fn native_aggregate_error(uri: &str, bytes: &[u8]) -> String {
    lance_c::runtime::block_on(async {
        let dataset = Dataset::open(uri).await.unwrap();
        let mut scanner = dataset.scan();
        match scanner.aggregate(NativeAggregateExpr::substrait(bytes.to_vec())) {
            Ok(_) => panic!("invalid Substrait aggregate unexpectedly parsed"),
            Err(error) => error.to_string(),
        }
    })
}

fn ordering_substrait_id_at_least(threshold: i32) -> Vec<u8> {
    use datafusion::logical_expr::{col, lit};
    use datafusion::prelude::SessionContext;
    use lance_datafusion::substrait::encode_substrait;

    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, false),
        Field::new("category", DataType::Utf8, true),
        Field::new("rank", DataType::Int32, true),
    ]));
    encode_substrait(
        col("id").gt_eq(lit(threshold)),
        schema,
        &SessionContext::new().state(),
    )
    .unwrap()
}

fn schema_names(schema: &Schema) -> Vec<&str> {
    schema
        .fields()
        .iter()
        .map(|field| field.name().as_str())
        .collect()
}

#[test]
fn test_scanner_substrait_aggregate_grouped_matches_native() {
    let (_tmp, uri) = create_ordering_dataset();
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let bytes = aggregate_plan(
        &[1],
        &[
            AggregateKind::CountStar,
            AggregateKind::Count(2),
            AggregateKind::Sum(0),
            AggregateKind::Sum(2),
            AggregateKind::Min(0),
            AggregateKind::Max(0),
        ],
        &[
            "group",
            "rows",
            "ranks",
            "ids",
            "rank_total",
            "min_id",
            "max_id",
        ],
    );
    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe { lance_scanner_set_substrait_aggregate(scanner, bytes.as_ptr(), bytes.len()) },
        0,
        "{}",
        take_last_error_message()
    );

    let (schema, batches) = collect_scanner(scanner);
    assert_eq!(
        schema_names(&schema),
        vec![
            "group",
            "rows",
            "ranks",
            "ids",
            "rank_total",
            "min_id",
            "max_id"
        ]
    );
    let actual = sorted_cells(&batches);
    let mut expected = vec![
        vec![
            Cell::Null,
            Cell::Int(2),
            Cell::Int(2),
            Cell::Int(19),
            Cell::Int(5),
            Cell::Int(8),
            Cell::Int(11),
        ],
        vec![
            Cell::Text("a".into()),
            Cell::Int(5),
            Cell::Int(4),
            Cell::Int(27),
            Cell::Int(4),
            Cell::Int(2),
            Cell::Int(10),
        ],
        vec![
            Cell::Text("b".into()),
            Cell::Int(5),
            Cell::Int(3),
            Cell::Int(20),
            Cell::Int(6),
            Cell::Int(0),
            Cell::Int(9),
        ],
    ];
    expected.sort_by_key(|row| format!("{row:?}"));
    assert_eq!(actual, expected);
    assert_eq!(
        actual,
        sorted_cells(&native_aggregate_batches_with_filter(&uri, &bytes, None))
    );

    unsafe {
        lance_scanner_close(scanner);
        lance_dataset_close(ds);
    }
}

