    assert_eq!(rc, 0);

    let names = schema_field_names(ds);
    assert_eq!(names, vec!["id", "value", "tag"]);
    // Metadata-only rename preserves row count.
    assert_eq!(unsafe { lance_dataset_count_rows(ds) }, 4);

