    // Storage order matches id order (single fragment written 0..5).
    let mut stream = new_column_stream("extra", vec![1000, 1001, 1002, 1003, 1004]);
    let rc = unsafe { lance_dataset_add_columns_stream(ds, &mut stream, 0) };
