#[test]
fn test_add_columns_stream_batch_size_overflow_rejected() {
    // Mirrors the SQL overflow test: a batch_size beyond u32::MAX is rejected
    // rather than silently wrapped. `from_raw` runs before the batch_size check,
    // so the stream must still be consumed — proven via the drop counter (a bare
    // `release.is_none()` check would be vacuous, since `from_raw` clears that
    // slot unconditionally).
    let (_tmp, uri) = create_large_dataset(5);
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let (mut stream, drop_count) = make_counted_stream(&write_schema());
    let too_big = u32::MAX as u64 + 1;
    let rc = unsafe { lance_dataset_add_columns_stream(ds, &mut stream, too_big) };
    assert_eq!(rc, -1);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert_stream_consumed(&stream, &drop_count);

    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_add_columns_stream_missing_callback_rejected() {
    // A stream missing a mandatory CADI callback must be rejected at the FFI
    // boundary rather than aborting the process via an `unwrap()` deep inside
    // arrow-rs (which only guards against a NULL `release`). Cover both the
    // `get_schema` (construction) and `get_next` (iteration) callbacks, since
    // they abort on different arrow-rs code paths. The drop counter proves our
    // manual `release_fn(stream)` actually frees the reader on this path (which
    // does not go through `from_raw`).
    let (_tmp, uri) = create_large_dataset(5);
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    for sabotage in ["get_schema", "get_next"] {
        let (mut stream, drop_count) = make_counted_stream(&write_schema());
        match sabotage {
            "get_schema" => stream.get_schema = None,
            "get_next" => stream.get_next = None,
            other => unreachable!("unknown sabotage target: {other}"),
        }
        let rc = unsafe { lance_dataset_add_columns_stream(ds, &mut stream, 0) };
        assert_eq!(rc, -1, "{sabotage}=None must be rejected");
        assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
        assert_stream_consumed(&stream, &drop_count);
        // We also null the caller's `release` slot so a non-compliant producer
        // cannot trigger a second release.
        assert!(
            stream.release.is_none(),
            "{sabotage}: release slot must be cleared"
        );
    }

    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_add_columns_stream_already_released_rejected() {
    // A stream with `release == None` is the CADI "already released" sentinel
    // (the first conjunct of the callback guard). It must be rejected, and our
    // handler must NOT invoke any release callback. `FFI_ArrowArrayStream::empty()`
    // owns no resources, so this path leaks nothing.
    let (_tmp, uri) = create_large_dataset(2);
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let mut stream = FFI_ArrowArrayStream::empty();
    let rc = unsafe { lance_dataset_add_columns_stream(ds, &mut stream, 0) };
    assert_eq!(rc, -1);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);

    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_add_columns_stream_null_dataset_consumes_stream() {
    // The dataset-NULL check runs *after* `from_raw`, so the stream is consumed
    // (released) even on that error path — proven via the drop counter.
    let (mut stream, drop_count) = make_counted_stream(&write_schema());
    let rc = unsafe { lance_dataset_add_columns_stream(ptr::null_mut(), &mut stream, 0) };
    assert_eq!(rc, -1);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert_stream_consumed(&stream, &drop_count);
}

#[test]
fn test_multivector_nearest_rejects_null_handle() {
    let column = c_str("vectors");
    let query = [1.0f32, 0.0];
    let status = unsafe {
        lance_scanner_nearest_multivector(
            ptr::null_mut(),
            column.as_ptr(),
            query.as_ptr().cast(),
            2,
            1,
            0,
            1,
        )
    };
    assert_eq!(status, -1);
    let error = lance_last_error_message();
    assert!(!error.is_null());
    let message = unsafe { std::ffi::CStr::from_ptr(error) }
        .to_string_lossy()
        .into_owned();
    unsafe { lance_free_string(error) };
    assert!(message.contains("NULL"));
}

// Segment scans deliberately use an unprojected nullable key and a residual
// predicate so a candidate LIMIT or loss of filter columns changes the answer.
fn create_scalar_segment_fixture(
    kind: lance_index::IndexType,
    stable: bool,
) -> (tempfile::TempDir, String, Vec<[u8; 16]>) {
    create_scalar_segment_fixture_with_options(kind, stable, None, &[&[0], &[1]])
}

fn create_scalar_segment_fixture_with_options(
    kind: lance_index::IndexType,
    stable: bool,
    storage_version: Option<lance_file::version::LanceFileVersion>,
    segment_fragments: &[&[u32]],
) -> (tempfile::TempDir, String, Vec<[u8; 16]>) {
    let key = Arc::new(Int32Array::from(
        (0..12)
            .map(|id| if id % 4 == 0 { None } else { Some(id % 3) })
            .collect::<Vec<_>>(),
    ));
    create_scalar_segment_fixture_from_key(kind, stable, storage_version, segment_fragments, key)
}

fn create_scalar_segment_fixture_from_key(
    kind: lance_index::IndexType,
    stable: bool,
    storage_version: Option<lance_file::version::LanceFileVersion>,
    segment_fragments: &[&[u32]],
    key: arrow_array::ArrayRef,
) -> (tempfile::TempDir, String, Vec<[u8; 16]>) {
    use lance::dataset::WriteParams;
    use lance::index::DatasetIndexExt;
    use lance_index::scalar::{BuiltinIndexType, ScalarIndexParams};
    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp.path().join("segments").to_str().unwrap().to_owned();
    let uuids = lance_c::runtime::block_on(async {
        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int32, false),
            Field::new("key", key.data_type().clone(), true),
        ]));
        let row_count = key.len();
        let batch = RecordBatch::try_new(
            schema.clone(),
            vec![
                Arc::new(Int32Array::from_iter_values(0..row_count as i32)),
                key,
            ],
        )
        .unwrap();
        let mut ds = Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(batch)], schema),
            &uri,
            Some(WriteParams {
                max_rows_per_file: 4,
                enable_stable_row_ids: stable,
                data_storage_version: storage_version,
                ..Default::default()
            }),
        )
        .await
        .unwrap();
        let params = ScalarIndexParams::for_builtin(BuiltinIndexType::try_from(kind).unwrap());
        let fragments = ds.get_fragments();
        assert_eq!(fragments.len(), row_count.div_ceil(4));
        let mut segments = Vec::new();
        for fragment_ids in segment_fragments {
            segments.push(
                ds.create_index_builder(&["key"], kind, &params)
                    .name("key_idx".into())
                    .fragments(fragment_ids.to_vec())
                    .execute_uncommitted()
                    .await
                    .unwrap(),
            );
        }
        let uuids = segments.iter().map(|s| *s.uuid.as_bytes()).collect();
        ds.commit_existing_index_segments("key_idx", "key", segments)
            .await
            .unwrap();
        uuids
    });
    (tmp, uri, uuids)
}

fn scalar_segment_ids(
    uri: &str,
    uuid: &[u8; 16],
    fragments: &[u64],
    filter: &str,
    limit: Option<i64>,
    offset: i64,
) -> (Vec<i32>, CapturedScanStatistics) {
    scalar_segment_ids_with_filter(
        uri,
        uuid,
        fragments,
        ScalarSegmentFilter::Sql(filter),
        limit,
        offset,
    )
}

enum ScalarSegmentFilter<'a> {
    Sql(&'a str),
    Substrait(&'a [u8]),
}

fn scalar_segment_ids_with_filter(
    uri: &str,
    uuid: &[u8; 16],
    fragments: &[u64],
    filter: ScalarSegmentFilter<'_>,
    limit: Option<i64>,
    offset: i64,
) -> (Vec<i32>, CapturedScanStatistics) {
    scalar_segment_ids_with_auto(uri, uuid, fragments, filter, limit, offset, false)
}

fn scalar_segment_ids_with_auto(
    uri: &str,
    uuid: &[u8; 16],
    fragments: &[u64],
    filter: ScalarSegmentFilter<'_>,
    limit: Option<i64>,
    offset: i64,
    auto_selection: bool,
) -> (Vec<i32>, CapturedScanStatistics) {
    let uri = c_str(uri);
    let sql = match filter {
        ScalarSegmentFilter::Sql(sql) => Some(c_str(sql)),
        ScalarSegmentFilter::Substrait(_) => None,
    };
    let id = c_str("id");
    let columns = [id.as_ptr(), ptr::null()];
    let mut captured = CapturedScanStatistics::default();
    let mut ids = Vec::new();
    unsafe {
        let ds = lance_dataset_open(uri.as_ptr(), ptr::null(), 0);
        assert!(!ds.is_null());
        let scanner = lance_scanner_new(
            ds,
            columns.as_ptr(),
            sql.as_ref().map_or(ptr::null(), |s| s.as_ptr()),
        );
        assert!(!scanner.is_null());
        if let ScalarSegmentFilter::Substrait(bytes) = filter {
            assert_eq!(
                lance_scanner_set_substrait_filter(scanner, bytes.as_ptr(), bytes.len()),
                0
            );
        }
        assert_eq!(
            lance_scanner_set_fragment_ids(scanner, fragments.as_ptr(), fragments.len()),
            0
        );
        assert_eq!(
            lance_scanner_set_scalar_index_segment(scanner, uuid.as_ptr()),
            0
        );
        assert_eq!(
            lance_scanner_set_scalar_index_auto_selection(scanner, auto_selection),
            0
        );
        if let Some(limit) = limit {
            assert_eq!(lance_scanner_set_limit(scanner, limit), 0);
        }
        assert_eq!(lance_scanner_set_offset(scanner, offset), 0);
        assert_eq!(
            lance_scanner_set_statistics_callback(
                scanner,
                Some(capture_scan_statistics),
                (&mut captured as *mut CapturedScanStatistics).cast()
            ),
            0
        );
        let mut stream = FFI_ArrowArrayStream::empty();
        let rc = lance_scanner_to_arrow_stream(scanner, &mut stream);
        assert_eq!(
            rc,
            0,
            "{}",
            if rc != 0 {
                take_last_error_message()
            } else {
                String::new()
            }
        );
        assert_eq!(
            lance_scanner_set_scalar_index_segment(scanner, ptr::null()),
            -1
        );
        assert_eq!(
            lance_scanner_set_scalar_index_auto_selection(scanner, !auto_selection),
            -1
        );
        {
            let reader = ArrowArrayStreamReader::from_raw(&mut stream).unwrap();
            for batch in reader {
                let batch = batch.unwrap();
                assert_eq!(batch.num_columns(), 1);
                ids.extend(
                    batch
                        .column(0)
                        .as_any()
                        .downcast_ref::<Int32Array>()
                        .unwrap()
                        .values()
                        .iter()
                        .copied(),
                );
            }
        }
        lance_scanner_close(scanner);
        lance_dataset_close(ds);
    }
    (ids, captured)
}

#[test]
fn test_scalar_segment_scan_applies_expression_projection() {
    let (_tmp, uri, uuids) = create_scalar_segment_fixture(lance_index::IndexType::BTree, false);
    let uri = c_str(&uri);
    let filter = c_str("key >= 0 AND id >= 1");
    let dataset = unsafe { lance_dataset_open(uri.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());
    let scanner = unsafe { lance_scanner_new(dataset, ptr::null(), filter.as_ptr()) };
    assert!(!scanner.is_null());
    assert_eq!(
        set_projection(scanner, &[("id_alias", "id"), ("key_copy", "key + 0")],),
        0,
        "{}",
        take_last_error_message()
    );
    let fragments = [0u64];
    assert_eq!(
        unsafe { lance_scanner_set_fragment_ids(scanner, fragments.as_ptr(), fragments.len()) },
        0
    );
    assert_eq!(
        unsafe { lance_scanner_set_scalar_index_segment(scanner, uuids[0].as_ptr()) },
        0,
        "{}",
        take_last_error_message()
    );

    let (schema, batches) = collect_scanner(scanner);
    assert_eq!(
        schema
            .fields()
            .iter()
            .map(|field| field.name().as_str())
            .collect::<Vec<_>>(),
        vec!["id_alias", "key_copy"]
    );
    let mut rows = Vec::new();
    for batch in batches {
        let ids = batch
            .column_by_name("id_alias")
            .unwrap()
            .as_any()
            .downcast_ref::<Int32Array>()
            .unwrap();
        let keys = batch
            .column_by_name("key_copy")
            .unwrap()
            .as_any()
            .downcast_ref::<Int32Array>()
            .unwrap();
        for row in 0..batch.num_rows() {
            rows.push((ids.value(row), keys.value(row)));
        }
    }
    rows.sort_unstable();
    assert_eq!(rows, vec![(1, 1), (2, 2), (3, 0)]);

    unsafe {
        lance_scanner_close(scanner);
        lance_dataset_close(dataset);
    }
}

#[test]
fn test_scalar_segment_introspection_and_count_use_configured_scope() {
    let (_tmp, uri, uuids) = create_scalar_segment_fixture(lance_index::IndexType::BTree, false);
    let uri = c_str(&uri);
    let filter = c_str("key >= 0 AND id >= 2");
    let dataset = unsafe { lance_dataset_open(uri.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());
    let fragments = [0_u64];

    for use_scalar_index in [false, true] {
        let scanner = unsafe { lance_scanner_new(dataset, ptr::null(), filter.as_ptr()) };
        assert!(!scanner.is_null());
        assert_eq!(
            unsafe { lance_scanner_set_fragment_ids(scanner, fragments.as_ptr(), fragments.len()) },
            0
        );
        assert_eq!(
            unsafe { lance_scanner_set_scalar_index_segment(scanner, uuids[0].as_ptr()) },
            0,
            "{}",
            take_last_error_message()
        );
        assert_eq!(
            unsafe { lance_scanner_set_use_scalar_index(scanner, use_scalar_index) },
            0
        );
        let mut captured = CapturedScanStatistics::default();
        assert_eq!(
            unsafe {
                lance_scanner_set_statistics_callback(
                    scanner,
                    Some(capture_scan_statistics),
                    (&mut captured as *mut CapturedScanStatistics).cast(),
                )
            },
            0
        );

        let introspected_schema = scanner_introspection_schema(scanner);
        assert_eq!(
            schema_signature(&scanner_introspection_schema(scanner)),
            schema_signature(&introspected_schema)
        );
        let count = unsafe { lance_scanner_count_rows(scanner) };
        assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
        assert_eq!(count, 2);
        assert_eq!(unsafe { lance_scanner_count_rows(scanner) }, count);
        assert_eq!(captured.calls, 0, "count must not invoke stream statistics");

        let analyze_count =
            take_scanner_string(unsafe { lance_scanner_analyze_count_plan(scanner) });
        assert!(analyze_count.contains("AggregateExec"), "{analyze_count}");
        let analyze = take_scanner_string(unsafe { lance_scanner_analyze_plan(scanner) });
        assert!(!analyze.is_empty());
        assert_eq!(
            captured.calls, 0,
            "analyze must not invoke stream statistics"
        );

        assert_eq!(
            unsafe { lance_scanner_set_batch_size(scanner, 1) },
            0,
            "scalar-segment planning must leave configuration editable"
        );
        let (stream_schema, batches) = collect_scanner(scanner);
        assert_eq!(
            schema_signature(&stream_schema),
            schema_signature(&introspected_schema)
        );
        let ids = batches
            .iter()
            .flat_map(|batch| {
                batch
                    .column_by_name("id")
                    .unwrap()
                    .as_any()
                    .downcast_ref::<Int32Array>()
                    .unwrap()
                    .values()
                    .iter()
                    .copied()
            })
            .collect::<Vec<_>>();
        let mut ids = ids;
        ids.sort_unstable();
        assert_eq!(ids, vec![2, 3]);
        assert_eq!(count, ids.len() as u64);
        assert_eq!(captured.calls, 1);

        assert_eq!(
            unsafe { lance_scanner_set_scalar_index_segment(scanner, ptr::null()) },
            -1,
            "real iteration must still freeze scalar-segment configuration"
        );
        unsafe { lance_scanner_close(scanner) };
    }

    unsafe { lance_dataset_close(dataset) };
}

#[test]
fn test_runtime_scalar_index_selection_uses_page_cost_and_honors_switch() {
    assert_eq!(
        unsafe { lance_scanner_set_scalar_index_auto_selection(ptr::null_mut(), true) },
        -1
    );
    use lance::dataset::WriteParams;
    use lance::index::DatasetIndexExt;
    use lance_index::{IndexType, scalar::ScalarIndexParams};
    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp
        .path()
        .join("runtime_selection")
        .to_str()
        .unwrap()
        .to_owned();
    let (grouping, fragments) = lance_c::runtime::block_on(async {
        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int32, false),
            Field::new("key", DataType::Int32, false),
        ]));
        let batch = RecordBatch::try_new(
            schema.clone(),
            vec![
                Arc::new(Int32Array::from_iter_values(0..16384)),
                Arc::new(Int32Array::from_iter_values(0..16384)),
            ],
        )
        .unwrap();
        let mut ds = Dataset::write(
            arrow::record_batch::RecordBatchIterator::new(vec![Ok(batch)], schema),
            &uri,
            Some(WriteParams {
                max_rows_per_file: 4096,
                ..Default::default()
            }),
        )
        .await
        .unwrap();
        ds.create_index(
            &["key"],
            IndexType::BTree,
            Some("key_idx".into()),
            &ScalarIndexParams::default(),
            false,
        )
        .await
        .unwrap();
        ds.create_index(
            &["id"],
            IndexType::BTree,
            Some("id_idx".into()),
            &ScalarIndexParams::default(),
            false,
        )
        .await
        .unwrap();
        let indices = ds.load_indices().await.unwrap();
        let uuid = *indices
            .iter()
            .find(|i| i.name == "key_idx")
            .unwrap()
            .uuid
            .as_bytes();
        let fragments: Vec<_> = ds.get_fragments().iter().map(|f| f.id() as u64).collect();
        (uuid, fragments)
    });
    let metric = |stats: &CapturedScanStatistics, key: &str| {
        stats
            .metrics
            .iter()
            .filter(|(name, _, _)| name == key)
            .map(|(_, _, n)| n)
            .sum::<u64>()
    };
    for enabled in [false, true] {
        let (ids, stats) = scalar_segment_ids_with_auto(
            &uri,
            &grouping,
            &fragments,
            ScalarSegmentFilter::Sql("key >= 0 AND id = 123"),
            None,
            0,
            enabled,
        );
        assert_eq!(ids, vec![123]);
        assert_eq!(
            metric(&stats, "scalar_index_auto_changed"),
            u64::from(enabled)
        );
        assert_eq!(
            metric(&stats, "scalar_index_auto_candidates"),
            if enabled { 2 } else { 0 }
        );
        if enabled {
            assert_eq!(metric(&stats, "scalar_index_auto_estimated_pages"), 1);
            assert_eq!(metric(&stats, "scalar_index_auto_estimated_rows"), 4096);
            assert_eq!(metric(&stats, "scalar_segments_searched"), 1);
        }
    }
    let (ids, stats) = scalar_segment_ids_with_auto(
        &uri,
        &grouping,
        &fragments,
        ScalarSegmentFilter::Sql("key >= 0"),
        None,
        0,
        true,
    );
    assert_eq!(ids.len(), 16384);
    assert_eq!(metric(&stats, "scalar_index_auto_full_scans"), 1);
    assert_eq!(metric(&stats, "scalar_segments_searched"), 0);
    let (ids, stats) = scalar_segment_ids_with_auto(
        &uri,
        &grouping,
        &fragments,
        ScalarSegmentFilter::Sql("key >= 0 AND id = 20000"),
        None,
        0,
        true,
    );
    assert!(ids.is_empty());
    assert_eq!(metric(&stats, "scalar_index_auto_changed"), 1);
    assert_eq!(metric(&stats, "scalar_index_auto_estimated_pages"), 0);
    // A switch cannot broaden an explicitly assigned fragment domain.
    let (ids, _) = scalar_segment_ids_with_auto(
        &uri,
        &grouping,
        &[fragments[1]],
        ScalarSegmentFilter::Sql("key >= 0 AND id >= 0"),
        Some(2),
        1,
        true,
    );
    assert_eq!(ids, vec![4097, 4098]);
}

#[test]
fn test_scalar_segment_scope_residual_limit_and_unindexed_fallback() {
    for kind in [
        lance_index::IndexType::BTree,
        lance_index::IndexType::Bitmap,
    ] {
        let (_tmp, uri, uuids) = create_scalar_segment_fixture(kind, false);
        let (ids, stats) =
            scalar_segment_ids(&uri, &uuids[0], &[0], "key >= 0 AND id >= 2", None, 0);
        assert_eq!(ids, vec![2, 3]);
        assert_eq!(stats.calls, 1);
        assert!(
            stats
                .metrics
                .iter()
                .any(|(name, _, value)| name == "scalar_segments_searched" && *value == 1)
        );
        let (ids, _) =
            scalar_segment_ids(&uri, &uuids[0], &[0], "key >= 0 AND id >= 2", Some(1), 1);
        assert_eq!(
            ids,
            vec![3],
            "offset and limit must apply after residual filtering"
        );
        let (ids, _) = scalar_segment_ids(&uri, &uuids[1], &[1], "key >= 0 AND id >= 2", None, 0);
        assert_eq!(ids, vec![5, 6, 7]);
        let (ids, stats) =
            scalar_segment_ids(&uri, &uuids[0], &[0, 2], "key >= 0 AND id >= 2", None, 0);
        assert_eq!(
            ids,
            vec![2, 3, 9, 10, 11],
            "partial coverage must not omit unindexed rows"
        );
        assert!(
            stats
                .metrics
                .iter()
                .any(|(name, _, _)| name == "scalar_segment_fallback_partial_coverage")
        );
        let (ids, stats) = scalar_segment_ids(&uri, &uuids[0], &[0], "key = 99 OR id = 0", None, 0);
        assert_eq!(
            ids,
            vec![0],
            "OR must not use just one branch as candidates"
        );
        assert!(
            stats
                .metrics
                .iter()
                .any(|(name, _, _)| name == "scalar_segment_fallback_no_driver")
        );
        let (ids, _) = scalar_segment_ids(&uri, &uuids[0], &[0], "key = 99", None, 0);
        assert!(ids.is_empty());
    }
}

#[test]
fn test_scalar_segment_boolean_predicates_preserve_scope_and_nulls() {
    for kind in [
        lance_index::IndexType::BTree,
        lance_index::IndexType::Bitmap,
    ] {
        for stable in [false, true] {
            let (_tmp, uri, uuids) =
                create_scalar_segment_fixture_with_options(kind, stable, None, &[&[0, 1], &[2]]);
            for (filter, expected) in [
                ("key IN (1, 2)", vec![1, 2, 5, 7]),
                ("key = 1 OR key = 2", vec![1, 2, 5, 7]),
                ("key IN (0, 1, 2)", vec![1, 2, 3, 5, 6, 7]),
                ("key IN (0, 1, 2, 99)", vec![1, 2, 3, 5, 6, 7]),
                ("key IN (1, 2) AND id >= 2", vec![2, 5, 7]),
                ("(key = 1 OR key = 2) AND key > 1", vec![2, 5]),
                ("NOT (key = 1 OR key = 2)", vec![3, 6]),
                ("key NOT IN (1, 2)", vec![3, 6]),
                ("key IS NULL OR key = 1", vec![0, 1, 4, 7]),
                ("key = 98 OR key = 99", vec![]),
            ] {
                let (ids, stats) = scalar_segment_ids(&uri, &uuids[0], &[0, 1], filter, None, 0);
                assert_eq!(ids, expected, "{kind:?}, stable={stable}, {filter}");
                assert_eq!(stats.calls, 1);
                assert!(
                    stats
                        .metrics
                        .iter()
                        .any(|(name, _, value)| name == "scalar_segments_searched" && *value == 1),
                    "{kind:?}, stable={stable}, {filter}: {:?}",
                    stats.metrics
                );
                assert!(
                    !stats
                        .metrics
                        .iter()
                        .any(|(name, _, value)| name == "scalar_segment_fallbacks" && *value != 0),
                    "{kind:?}, stable={stable}, {filter}: {:?}",
                    stats.metrics
                );
            }
            let (ids, _) = scalar_segment_ids(&uri, &uuids[0], &[0], "key IN (1, 2)", None, 0);
            assert_eq!(
                ids,
                vec![1, 2],
                "index coverage must not widen the scan scope"
            );
            let (ids, _) = scalar_segment_ids(
                &uri,
                &uuids[0],
                &[0, 1],
                "key IN (1, 2) AND id >= 2",
                Some(1),
                1,
            );
            assert_eq!(ids, vec![5], "residual filtering must precede pagination");
            let (ids, stats) =
                scalar_segment_ids(&uri, &uuids[0], &[0, 2], "key IN (1, 2)", None, 0);
            assert_eq!(ids, vec![1, 2, 10, 11]);
            assert!(stats.metrics.iter().any(|(name, _, value)| name
                == "scalar_segment_fallback_partial_coverage"
                && *value == 1));
            // A missing OR branch cannot be discarded, even if the other branch is indexed.
            let (ids, stats) =
                scalar_segment_ids(&uri, &uuids[0], &[0, 1], "key IN (1, 2) OR id = 0", None, 0);
            assert_eq!(ids, vec![0, 1, 2, 5, 7]);
            assert!(stats.metrics.iter().any(|(name, _, value)| name
                == "scalar_segment_fallback_no_driver"
                && *value == 1));
            for (filter, expected) in [
                ("key IN (1, NULL)", vec![1, 7]),
                ("key NOT IN (1, NULL)", vec![]),
                ("NOT (key = 1 OR id = 2)", vec![3, 5, 6]),
            ] {
                let (ids, _) = scalar_segment_ids(&uri, &uuids[0], &[0, 1], filter, None, 0);
                assert_eq!(ids, expected, "{kind:?}, stable={stable}, {filter}");
            }
        }
    }
}

#[test]
fn test_scalar_segment_boolean_truth_tests_preserve_null_rows() {
    for kind in [
        lance_index::IndexType::BTree,
        lance_index::IndexType::Bitmap,
    ] {
        for stable in [false, true] {
            let key = Arc::new(arrow_array::BooleanArray::from(vec![
                None,
                Some(true),
                Some(false),
                Some(false),
                None,
                Some(true),
                Some(false),
                Some(true),
                None,
                Some(false),
                Some(true),
                Some(false),
            ]));
            let (_tmp, uri, uuids) =
                create_scalar_segment_fixture_from_key(kind, stable, None, &[&[0, 1], &[2]], key);
            for (filter, expected) in [
                ("NOT (key IS TRUE)", vec![0, 2, 3, 4, 6]),
                ("NOT (key IS FALSE)", vec![0, 1, 4, 5, 7]),
                ("key IS NOT TRUE", vec![0, 2, 3, 4, 6]),
                ("key IS NOT FALSE", vec![0, 1, 4, 5, 7]),
                ("key IS TRUE", vec![1, 5, 7]),
                ("key IS FALSE", vec![2, 3, 6]),
                ("NOT (key IS TRUE AND id >= 2)", vec![0, 1, 2, 3, 4, 6]),
                ("NOT (key IS FALSE OR id = 0)", vec![1, 4, 5, 7]),
                ("(key IS TRUE) = false", vec![0, 2, 3, 4, 6]),
            ] {
                let (ids, stats) = scalar_segment_ids(&uri, &uuids[0], &[0, 1], filter, None, 0);
                assert_eq!(ids, expected, "{kind:?}, stable={stable}, {filter}");
                assert_eq!(stats.calls, 1);
                assert!(
                    stats.metrics.iter().any(|(name, _, value)| name
                        == "scalar_segment_fallback_boolean_truth_test"
                        && *value == 1),
                    "{filter}: {:?}",
                    stats.metrics
                );
                assert!(
                    !stats
                        .metrics
                        .iter()
                        .any(|(name, _, value)| name == "scalar_segments_searched" && *value != 0)
                );
            }
            let (ids, _) =
                scalar_segment_ids(&uri, &uuids[0], &[0], "NOT (key IS TRUE)", Some(1), 1);
            assert_eq!(ids, vec![2], "fallback must preserve scope and pagination");
            let (ids, stats) =
                scalar_segment_ids(&uri, &uuids[0], &[0, 1], "NOT (key = true)", None, 0);
            assert_eq!(ids, vec![2, 3, 6], "ordinary NOT must still exclude NULLs");
            assert!(
                stats
                    .metrics
                    .iter()
                    .any(|(name, _, value)| name == "scalar_segments_searched" && *value == 1)
            );
        }
    }
}

#[test]
fn test_scalar_segment_string_in_candidates_and_deleted_rows() {
    use lance::index::DatasetIndexExt;
    for kind in [
        lance_index::IndexType::BTree,
        lance_index::IndexType::Bitmap,
    ] {
        for stable in [false, true] {
            let key = Arc::new(StringArray::from(vec![
                None,
                Some("alpha"),
                Some("beta"),
                Some("gamma"),
                None,
                Some("beta"),
                Some("gamma"),
                Some("alpha"),
                None,
                Some("gamma"),
                Some("alpha"),
                Some("beta"),
            ]));
            let (_tmp, uri, uuids) =
                create_scalar_segment_fixture_from_key(kind, stable, None, &[&[0, 1], &[2]], key);
            let (ids, stats) = scalar_segment_ids(
                &uri,
                &uuids[0],
                &[0, 1],
                "key IN ('alpha', 'beta')",
                None,
                0,
            );
            assert_eq!(ids, vec![1, 2, 5, 7]);
            assert!(
                stats
                    .metrics
                    .iter()
                    .any(|(name, _, value)| name == "scalar_segment_candidate_rows" && *value == 4)
            );
            assert!(
                stats
                    .metrics
                    .iter()
                    .any(|(name, _, value)| name == "rows_scanned" && *value == 4)
            );
            lance_c::runtime::block_on(async {
                let mut ds = Dataset::open(&uri).await.unwrap();
                ds.delete("id IN (1, 6)").await.unwrap();
                assert_eq!(ds.load_indices().await.unwrap().len(), 2);
            });
            for (filter, expected) in [
                ("key IN ('alpha', 'beta')", vec![2, 5, 7]),
                ("NOT (key = 'alpha' OR key = 'beta')", vec![3]),
            ] {
                let (ids, _) = scalar_segment_ids(&uri, &uuids[0], &[0, 1], filter, None, 0);
                assert_eq!(ids, expected, "{kind:?}, stable={stable}, {filter}");
            }
        }
    }
}

#[test]
fn test_scalar_segment_boolean_predicates_do_not_search_other_indices() {
    use lance::index::DatasetIndexExt;
    use lance_index::scalar::{BuiltinIndexType, ScalarIndexParams};
    let (_tmp, uri, uuids) = create_scalar_segment_fixture_with_options(
        lance_index::IndexType::BTree,
        false,
        None,
        &[&[0, 1], &[2]],
    );
    lance_c::runtime::block_on(async {
        let mut ds = Dataset::open(&uri).await.unwrap();
        ds.create_index_builder(
            &["id"],
            lance_index::IndexType::BTree,
            &ScalarIndexParams::for_builtin(BuiltinIndexType::BTree),
        )
        .name("id_idx".into())
        .await
        .unwrap();
    });
    for (filter, expected, accelerated) in [
        ("key = 1 AND id >= 2", vec![7], true),
        (
            "(key = 1 AND id >= 2) OR (key = 2 AND id < 6)",
            vec![2, 5, 7],
            true,
        ),
        ("key = 1 OR id = 0", vec![0, 1, 7], false),
        // Negating a necessary conjunct alone would incorrectly drop id 0 and 1.
        ("NOT (key = 1 AND id >= 2)", vec![0, 1, 2, 3, 5, 6], false),
    ] {
        let (ids, stats) = scalar_segment_ids(&uri, &uuids[0], &[0, 1], filter, None, 0);
        assert_eq!(ids, expected, "{filter}");
        let searched = stats
            .metrics
            .iter()
            .any(|(name, _, value)| name == "scalar_segments_searched" && *value == 1);
        assert_eq!(searched, accelerated, "{filter}: {:?}", stats.metrics);
    }
}

#[test]
fn test_scalar_segment_metadata_residuals_fall_back_within_scope() {
    for kind in [
        lance_index::IndexType::BTree,
        lance_index::IndexType::Bitmap,
    ] {
        for stable in [false, true] {
            // One segment covers two fragments; the third fragment is unindexed.
            // Project only id so metadata residuals must survive independently
            // of both the stored schema and the output projection.
            let (_tmp, uri, uuids) =
                create_scalar_segment_fixture_with_options(kind, stable, None, &[&[0, 1]]);
            for residual in [
                "_rowid > 0",
                "_rowaddr > 0",
                "_row_created_at_version IS NOT NULL",
                "_row_last_updated_at_version IS NOT NULL",
            ] {
                let filter = format!("key >= 0 AND {residual}");
                for (fragments, expected) in [
                    (vec![0], vec![1, 2, 3]),
                    (vec![1], vec![5, 6, 7]),
                    (vec![0, 1], vec![1, 2, 3, 5, 6, 7]),
                ] {
                    let (ids, stats) =
                        scalar_segment_ids(&uri, &uuids[0], &fragments, &filter, None, 0);
                    assert_eq!(ids, expected, "{kind:?}, stable={stable}, {filter}");
                    assert_eq!(stats.calls, 1);
                    assert_eq!(stats.indices_loaded, 0);
                    assert_eq!(stats.index_comparisons, 0);
                    assert!(stats.metrics.iter().any(|(name, _, value)| {
                        name == "scalar_segment_fallback_filter_schema" && *value == 1
                    }));
                    assert!(!stats.metrics.iter().any(|(name, _, value)| {
                        name == "scalar_segments_searched" && *value != 0
                    }));
                }
            }
            let (ids, _) = scalar_segment_ids(
                &uri,
                &uuids[0],
                &[0],
                "key >= 0 AND _rowid > 1 AND _rowaddr > 1",
                Some(1),
                1,
            );
            assert_eq!(ids, vec![3], "apply the residual before LIMIT/OFFSET");
            for column in [
                "_rowid",
                "_rowaddr",
                "_row_created_at_version",
                "_row_last_updated_at_version",
            ] {
                let filter = format!("key >= 0 AND {column} IS NULL");
                let (ids, _) = scalar_segment_ids(&uri, &uuids[0], &[0, 1], &filter, None, 0);
                assert!(ids.is_empty(), "must retain the residual: {filter}");
            }
            let (ids, stats) =
                scalar_segment_ids(&uri, &uuids[0], &[0, 2], "key >= 0 AND _rowid > 0", None, 0);
            assert_eq!(ids, vec![1, 2, 3, 9, 10, 11]);
            assert!(stats.metrics.iter().any(|(name, _, value)| {
                name == "scalar_segment_fallback_partial_coverage" && *value == 1
            }));
        }
    }
}

#[test]
fn test_scalar_segment_label_list_exact_candidates() {
    use arrow_array::builder::{Int32Builder, ListBuilder};
    use lance::index::DatasetIndexExt;
    use lance_index::IndexType;

    for stable in [false, true] {
        let mut lists = ListBuilder::new(Int32Builder::new());
        for row in 0..16 {
            match row {
                0 | 9 | 13 => lists.append(false),
                1 | 10 | 14 => lists.append(true),
                4 => {
                    lists.values().append_value(7);
                    lists.append(true);
                }
                _ => {
                    lists.values().append_value(42);
                    if row == 3 || row == 11 || row == 15 {
                        lists.values().append_value(7);
                    }
                    if row == 6 {
                        lists.values().append_null();
                    }
                    lists.append(true);
                }
            }
        }
        // S0 covers fragments 0 and 1, S1 covers 2, and 3 is unindexed.
        let (_tmp, uri, uuids) = create_scalar_segment_fixture_from_key(
            IndexType::LabelList,
            stable,
            None,
            &[&[0, 1], &[2]],
            Arc::new(lists.finish()),
        );
        let predicate = "array_contains(key, CAST(42 AS INT))";
        let filter = format!("{predicate} AND id >= 3");
        for (fragments, expected) in [(vec![0, 1], vec![3, 5, 6, 7]), (vec![0], vec![3])] {
            let (ids, stats) = scalar_segment_ids(&uri, &uuids[0], &fragments, &filter, None, 0);
            assert_eq!(ids, expected, "stable={stable}");
            assert_eq!(stats.calls, 1);
            assert!(
                stats
                    .metrics
                    .iter()
                    .any(|(name, _, value)| { name == "scalar_segments_searched" && *value == 1 }),
                "stable={stable}, metrics={:?}",
                stats.metrics
            );
            assert!(
                !stats
                    .metrics
                    .iter()
                    .any(|(name, _, value)| { name == "scalar_segment_fallbacks" && *value != 0 })
            );
        }
        let (ids, _) = scalar_segment_ids(&uri, &uuids[0], &[0, 1], &filter, Some(1), 1);
        assert_eq!(ids, vec![5], "limit/offset must follow the residual filter");
        let (ids, _) = scalar_segment_ids(&uri, &uuids[1], &[2], &filter, None, 0);
        assert_eq!(ids, vec![8, 11]);
        let (ids, stats) = scalar_segment_ids(&uri, &uuids[0], &[0, 3], &filter, None, 0);
        assert_eq!(ids, vec![3, 12, 15]);
        assert!(stats.metrics.iter().any(|(name, _, value)| {
            name == "scalar_segment_fallback_partial_coverage" && *value == 1
        }));
        let (ids, stats) = scalar_segment_ids(
            &uri,
            &uuids[0],
            &[0],
            &format!("{predicate} OR id = 0"),
            None,
            0,
        );
        assert_eq!(ids, vec![0, 2, 3]);
        assert!(stats.metrics.iter().any(|(name, _, value)| {
            name == "scalar_segment_fallback_no_driver" && *value == 1
        }));

        for (predicate, expected) in [
            (
                "array_has_all(key, [CAST(42 AS INT), CAST(7 AS INT)])",
                vec![3],
            ),
            (
                "array_has_any(key, [CAST(42 AS INT), CAST(99 AS INT)])",
                vec![2, 3, 5, 6, 7],
            ),
            ("array_contains(key, CAST(99 AS INT))", vec![]),
            ("array_contains(key, CAST(NULL AS INT))", vec![]),
            ("array_has_any(key, [])", vec![]),
        ] {
            let (ids, _) = scalar_segment_ids(&uri, &uuids[0], &[0, 1], predicate, None, 0);
            assert_eq!(ids, expected, "{predicate}, stable={stable}");
        }
        // An untyped integer literal casts this Int32 list to Int64. Such
        // a column expression must retain the scan fallback.
        let (ids, stats) =
            scalar_segment_ids(&uri, &uuids[0], &[0, 1], "array_contains(key, 42)", None, 0);
        assert_eq!(ids, vec![2, 3, 5, 6, 7]);
        assert!(stats.metrics.iter().any(|(name, _, value)| {
            name == "scalar_segment_fallback_no_driver" && *value == 1
        }));

        lance_c::runtime::block_on(async {
            let mut ds = Dataset::open(&uri).await.unwrap();
            ds.delete("id = 3").await.unwrap();
            assert_eq!(ds.load_indices().await.unwrap().len(), 2);
        });
        let (ids, _) = scalar_segment_ids(&uri, &uuids[0], &[0, 1], &filter, None, 0);
        assert_eq!(ids, vec![5, 6, 7]);
    }
}

#[test]
fn test_scalar_segment_string_labels_via_substrait() {
    use arrow_array::builder::{ListBuilder, StringBuilder};
    use datafusion::prelude::SessionContext;
    use lance_datafusion::{planner::Planner, substrait::encode_substrait};
    use lance_index::IndexType;

    for stable in [false, true] {
        let mut labels = ListBuilder::new(StringBuilder::new());
        for row in 0..16 {
            match row % 8 {
                0 => labels.append(false),
                1 => labels.append(true),
                n => {
                    if [2, 4, 5, 7].contains(&n) {
                        labels.values().append_value("red");
                    }
                    if [3, 4, 7].contains(&n) {
                        labels.values().append_value("blue");
                    }
                    if [5, 6].contains(&n) {
                        labels.values().append_null();
                    }
                    if n == 7 {
                        labels.values().append_value("red");
                    }
                    labels.append(true);
                }
            }
        }
        let (_tmp, uri, uuids) = create_scalar_segment_fixture_from_key(
            IndexType::LabelList,
            stable,
            None,
            &[&[0, 1], &[2]],
            Arc::new(labels.finish()),
        );
        let schema = lance_c::runtime::block_on(async {
            Arc::new(Schema::from(Dataset::open(&uri).await.unwrap().schema()))
        });
        let planner = Planner::new(schema.clone());
        let state = SessionContext::new().state();
        let encode = |sql: &str| {
            encode_substrait(planner.parse_filter(sql).unwrap(), schema.clone(), &state).unwrap()
        };
        for (filter, expected, candidates) in [
            ("array_contains(key, 'red')", vec![2, 4, 5, 7], 4),
            (
                "array_contains(key, 'red') AND array_contains(key, 'blue')",
                vec![4, 7],
                2,
            ),
            (
                "array_contains(key, 'red') OR array_contains(key, 'blue')",
                vec![2, 3, 4, 5, 7],
                5,
            ),
            ("array_has_all(key, ['red', 'blue'])", vec![4, 7], 2),
            (
                "array_has_any(key, ['red', 'blue'])",
                vec![2, 3, 4, 5, 7],
                5,
            ),
            ("array_contains(key, 'missing')", vec![], 0),
            ("array_contains(key, 'red') AND id >= 4", vec![4, 5, 7], 4),
        ] {
            let bytes = encode(filter);
            let (ids, stats) = scalar_segment_ids_with_filter(
                &uri,
                &uuids[0],
                &[0, 1],
                ScalarSegmentFilter::Substrait(&bytes),
                None,
                0,
            );
            assert_eq!(ids, expected, "stable={stable}, {filter}");
            // Candidate counts distinguish indexed label intersections from reading
            // one label's matches and applying the second label only as a residual.
            assert!(
                stats
                    .metrics
                    .iter()
                    .any(|(name, _, value)| name == "scalar_segment_candidate_rows"
                        && *value == candidates),
                "{filter}: {:?}",
                stats.metrics
            );
            assert_eq!(
                ids,
                scalar_segment_ids(&uri, &uuids[0], &[0, 1], filter, None, 0).0
            );
            assert!(
                stats
                    .metrics
                    .iter()
                    .any(|(name, _, value)| name == "scalar_segments_searched" && *value == 1),
                "{filter}: {:?}",
                stats.metrics
            );
            assert!(
                !stats
                    .metrics
                    .iter()
                    .any(|(name, _, value)| name == "scalar_segment_fallbacks" && *value != 0),
                "{filter}: {:?}",
                stats.metrics
            );
        }
        // Cross-engine callers must not equate NULL membership or ordered-subsequence
        // functions with Lance's membership and set-containment semantics.
        for (filter, expected) in [
            ("array_contains(key, CAST(NULL AS STRING))", vec![]),
            ("array_has_any(key, [])", vec![]),
            // The pinned Lance planner treats an empty all-label query as true,
            // including on NULL lists; compare against its unindexed path below.
            ("array_has_all(key, [])", vec![0, 1, 2, 3, 4, 5, 6, 7]),
            ("array_has_all(key, ['blue', 'red'])", vec![4, 7]),
            ("array_contains(key, 'red') OR id = 0", vec![0, 2, 4, 5, 7]),
        ] {
            let bytes = encode(filter);
            let (ids, _) = scalar_segment_ids_with_filter(
                &uri,
                &uuids[0],
                &[0, 1],
                ScalarSegmentFilter::Substrait(&bytes),
                None,
                0,
            );
            let baseline = lance_c::runtime::block_on(async {
                use futures::TryStreamExt;
                let ds = Dataset::open(&uri).await.unwrap();
                let mut scan = ds.scan();
                scan.project(&["id"]).unwrap();
                scan.use_scalar_index(false);
                scan.with_fragments(
                    ds.get_fragments()
                        .into_iter()
                        .take(2)
                        .map(|f| f.metadata().clone())
                        .collect(),
                );
                scan.filter(filter).unwrap();
                let batches: Vec<RecordBatch> = scan
                    .try_into_stream()
                    .await
                    .unwrap()
                    .try_collect()
                    .await
                    .unwrap();
                batches
                    .iter()
                    .flat_map(|batch| {
                        batch
                            .column(0)
                            .as_any()
                            .downcast_ref::<Int32Array>()
                            .unwrap()
                            .values()
                            .iter()
                            .copied()
                    })
                    .collect::<Vec<_>>()
            });
            assert_eq!(
                ids, baseline,
                "indexed vs unindexed: stable={stable}, {filter}"
            );
            assert_eq!(ids, expected, "stable={stable}, {filter}");
        }
        let filter = "array_contains(key, 'red') AND array_contains(key, 'blue') AND id >= 4";
        let bytes = encode(filter);
        let (ids, _) = scalar_segment_ids_with_filter(
            &uri,
            &uuids[0],
            &[1],
            ScalarSegmentFilter::Substrait(&bytes),
            Some(1),
            1,
        );
        assert_eq!(
            ids,
            vec![7],
            "residual filtering and fragment scope precede pagination"
        );
        let (ids, stats) = scalar_segment_ids_with_filter(
            &uri,
            &uuids[0],
            &[0, 3],
            ScalarSegmentFilter::Substrait(&bytes),
            None,
            0,
        );
        assert_eq!(
            ids,
            vec![12, 15],
            "fallback must include matching unindexed fragments"
        );
        assert!(stats.metrics.iter().any(|(name, _, value)| name
            == "scalar_segment_fallback_partial_coverage"
            && *value == 1));
        lance_c::runtime::block_on(async {
            let mut ds = Dataset::open(&uri).await.unwrap();
            ds.delete("id = 4").await.unwrap();
        });
        let (ids, _) = scalar_segment_ids_with_filter(
            &uri,
            &uuids[0],
            &[0, 1],
            ScalarSegmentFilter::Substrait(&bytes),
            None,
            0,
        );
        assert_eq!(ids, vec![7]);
    }
}

#[test]
fn test_scalar_segment_text_indices_still_fall_back() {
    for kind in [lance_index::IndexType::Fm, lance_index::IndexType::NGram] {
        for stable in [false, true] {
            let key = Arc::new(StringArray::from(vec![
                Some("needle"),
                None,
                Some(""),
                Some("other"),
                Some("needle"),
                Some("other"),
                Some(""),
                None,
            ]));
            let (_tmp, uri, uuids) =
                create_scalar_segment_fixture_from_key(kind, stable, None, &[&[0, 1]], key);
            for (predicate, expected) in [
                ("contains(key, 'needle')", vec![0]),
                ("contains(key, '')", vec![0, 2, 3]),
            ] {
                let (ids, stats) = scalar_segment_ids(&uri, &uuids[0], &[0], predicate, None, 0);
                assert_eq!(ids, expected, "{kind:?}, stable={stable}, {predicate}");
                assert!(
                    stats.metrics.iter().any(|(name, _, value)| {
                        name == "scalar_segment_fallbacks" && *value == 1
                    })
                );
                if predicate == "contains(key, 'needle')" {
                    assert!(stats.metrics.iter().any(|(name, _, value)| {
                        name == "scalar_segment_fallback_index_type" && *value == 1
                    }));
                }
                assert!(
                    !stats.metrics.iter().any(|(name, _, value)| {
                        name == "scalar_segments_searched" && *value != 0
                    })
                );
            }
        }
    }
}

