#[test]
fn test_scalar_segment_honors_use_scalar_index_false() {
    let (_tmp, uri, uuids) = create_scalar_segment_fixture(lance_index::IndexType::BTree, false);
    let (ids, stats) = scalar_segment_ids(&uri, &uuids[0], &[0], "key >= 0", None, 0);
    assert_eq!(ids, vec![1, 2, 3]);
    assert!(
        stats
            .metrics
            .iter()
            .any(|(name, _, value)| name == "scalar_segments_searched" && *value == 1)
    );

    let uri = c_str(&uri);
    unsafe {
        let ds = lance_dataset_open(uri.as_ptr(), ptr::null(), 0);
        assert!(!ds.is_null());
        for disable_first in [false, true] {
            for (fragments, filter, limit, offset, expected) in [
                (vec![0u64], "key >= 0", None, 0, vec![1, 2, 3]),
                (vec![0, 2], "key >= 0 AND id >= 2", Some(2), 1, vec![3, 9]),
            ] {
                let filter = c_str(filter);
                let scanner = lance_scanner_new(ds, ptr::null(), filter.as_ptr());
                assert!(!scanner.is_null());
                assert_eq!(
                    lance_scanner_set_fragment_ids(scanner, fragments.as_ptr(), fragments.len()),
                    0
                );
                if disable_first {
                    assert_eq!(lance_scanner_set_use_scalar_index(scanner, false), 0);
                }
                assert_eq!(
                    lance_scanner_set_scalar_index_segment(scanner, uuids[0].as_ptr()),
                    0
                );
                if !disable_first {
                    assert_eq!(lance_scanner_set_use_scalar_index(scanner, false), 0);
                }
                if let Some(limit) = limit {
                    assert_eq!(lance_scanner_set_limit(scanner, limit), 0);
                }
                assert_eq!(lance_scanner_set_offset(scanner, offset), 0);
                let mut captured = CapturedScanStatistics::default();
                assert_eq!(
                    lance_scanner_set_statistics_callback(
                        scanner,
                        Some(capture_scan_statistics),
                        (&mut captured as *mut CapturedScanStatistics).cast(),
                    ),
                    0
                );
                let mut stream = FFI_ArrowArrayStream::empty();
                assert_eq!(lance_scanner_to_arrow_stream(scanner, &mut stream), 0);
                let mut ids = Vec::new();
                for batch in ArrowArrayStreamReader::from_raw(&mut stream).unwrap() {
                    let batch = batch.unwrap();
                    ids.extend_from_slice(
                        batch
                            .column_by_name("id")
                            .unwrap()
                            .as_any()
                            .downcast_ref::<Int32Array>()
                            .unwrap()
                            .values(),
                    );
                }
                assert_eq!(ids, expected);
                assert_eq!(captured.calls, 1);
                for metric in ["scalar_segments_searched", "scalar_segment_candidate_rows"] {
                    assert_eq!(
                        captured
                            .metrics
                            .iter()
                            .filter(|(name, _, _)| name == metric)
                            .map(|(_, _, value)| *value)
                            .sum::<u64>(),
                        0,
                        "{metric}"
                    );
                }
                assert_eq!(captured.indices_loaded, 0);
                assert_eq!(captured.index_comparisons, 0);
                assert!(captured.metrics.iter().any(|(name, _, value)| name
                    == "scalar_segment_fallback_disabled"
                    && *value == 1));
                lance_scanner_close(scanner);
            }
        }
        lance_dataset_close(ds);
    }
}

#[test]
fn test_scalar_segment_rejects_include_deleted_rows_after_index_rebuild() {
    use lance::index::DatasetIndexExt;
    use lance_index::scalar::{BuiltinIndexType, ScalarIndexParams};

    let (_tmp, uri, _) = create_scalar_segment_fixture(lance_index::IndexType::BTree, false);
    let uuid = lance_c::runtime::block_on(async {
        let mut ds = Dataset::open(&uri).await.unwrap();
        ds.delete("id = 2").await.unwrap();
        ds.drop_index("key_idx").await.unwrap();
        // A segment built after the delete cannot return the tombstoned row,
        // even though its search result is Exact for the indexed live rows.
        let params = ScalarIndexParams::for_builtin(BuiltinIndexType::BTree);
        let segment = ds
            .create_index_builder(&["key"], lance_index::IndexType::BTree, &params)
            .name("key_idx".into())
            .fragments(vec![0])
            .execute_uncommitted()
            .await
            .unwrap();
        let uuid = *segment.uuid.as_bytes();
        ds.commit_existing_index_segments("key_idx", "key", vec![segment])
            .await
            .unwrap();
        uuid
    });

    let (ids, _) = scalar_segment_ids(&uri, &uuid, &[0], "key >= 0 AND id >= 2", None, 0);
    assert_eq!(ids, vec![3], "live-row segment scans remain supported");

    let uri = c_str(&uri);
    let filter = c_str("key >= 0 AND id >= 2");
    unsafe {
        let ds = lance_dataset_open(uri.as_ptr(), ptr::null(), 0);
        assert!(!ds.is_null());
        // Check both setter orders: compatibility is validated at stream creation.
        for segment_first in [None, Some(false), Some(true)] {
            let scanner = lance_scanner_new(ds, ptr::null(), filter.as_ptr());
            assert!(!scanner.is_null());
            assert_eq!(
                lance_scanner_set_fragment_ids(scanner, [0u64].as_ptr(), 1),
                0
            );
            assert_eq!(lance_scanner_with_row_id(scanner, true), 0);
            if segment_first.is_none() {
                assert_eq!(lance_scanner_set_use_scalar_index(scanner, false), 0);
            }
            if segment_first == Some(true) {
                assert_eq!(
                    lance_scanner_set_scalar_index_segment(scanner, uuid.as_ptr()),
                    0
                );
            }
            assert_eq!(lance_scanner_set_include_deleted_rows(scanner, true), 0);
            if segment_first == Some(false) {
                assert_eq!(
                    lance_scanner_set_scalar_index_segment(scanner, uuid.as_ptr()),
                    0
                );
            }
            let mut stream = FFI_ArrowArrayStream::empty();
            let rc = lance_scanner_to_arrow_stream(scanner, &mut stream);
            if segment_first.is_some() {
                assert_eq!(rc, -1, "segment scans must not silently omit deleted rows");
                assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
                assert!(take_last_error_message().contains("include_deleted_rows=true"));
            } else {
                assert_eq!(rc, 0);
                let reader = ArrowArrayStreamReader::from_raw(&mut stream).unwrap();
                let mut ids = Vec::new();
                for batch in reader {
                    let batch = batch.unwrap();
                    ids.extend_from_slice(
                        batch
                            .column_by_name("id")
                            .unwrap()
                            .as_any()
                            .downcast_ref::<Int32Array>()
                            .unwrap()
                            .values(),
                    );
                }
                ids.sort_unstable();
                assert_eq!(
                    ids,
                    vec![2, 3],
                    "ordinary scans can still read tombstoned rows"
                );
            }
            lance_scanner_close(scanner);
        }
        lance_dataset_close(ds);
    }
}

#[test]
fn test_scalar_segment_requires_explicit_domain_and_checks_uuid() {
    let (_tmp, uri, uuids) = create_scalar_segment_fixture(lance_index::IndexType::BTree, false);
    let uri = c_str(&uri);
    let filter = c_str("key >= 0");
    unsafe {
        assert_eq!(
            lance_scanner_set_scalar_index_segment(ptr::null_mut(), ptr::null()),
            -1
        );
        let ds = lance_dataset_open(uri.as_ptr(), ptr::null(), 0);
        let scanner = lance_scanner_new(ds, ptr::null(), filter.as_ptr());
        assert_eq!(
            lance_scanner_set_scalar_index_segment(scanner, uuids[0].as_ptr()),
            0
        );
        let mut batch = ptr::null_mut();
        assert_eq!(lance_scanner_next(scanner, &mut batch), -1);
        assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
        lance_scanner_close(scanner);
        let scanner = lance_scanner_new(ds, ptr::null(), filter.as_ptr());
        assert_eq!(
            lance_scanner_set_fragment_ids(scanner, [0u64].as_ptr(), 1),
            0
        );
        assert_eq!(
            lance_scanner_set_scalar_index_segment(scanner, [0u8; 16].as_ptr()),
            0
        );
        assert_eq!(lance_scanner_next(scanner, &mut batch), -1);
        assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
        lance_scanner_close(scanner);
        lance_dataset_close(ds);
    }
}

// ---------------------------------------------------------------------------
// Scanner blob handling
// ---------------------------------------------------------------------------

// Mirror of the C enum `LanceBlobHandling`; the FFI parameter is an int32.
const BLOB_HANDLING_BLOBS_DESCRIPTIONS: i32 = 0;
const BLOB_HANDLING_ALL_BINARY: i32 = 1;
const BLOB_HANDLING_ALL_DESCRIPTIONS: i32 = 2;

/// Sub-fields of a Blob v2 description struct, in schema order.
const BLOB_DESCRIPTION_FIELDS: [&str; 5] = ["kind", "position", "size", "blob_id", "blob_uri"];

/// Blob storage thresholds used by [`create_blob_v2_dataset`].
const BLOB_INLINE_THRESHOLD: usize = 16;
const BLOB_DEDICATED_THRESHOLD: usize = 256;

/// Blob sizes of the five rows in each fragment: inline, packed and dedicated
/// against the thresholds above, then an empty blob and a null.
const BLOB_ROW_SIZES: [Option<usize>; 5] = [Some(8), Some(128), Some(1024), Some(0), None];

/// First `id` of each fragment; also seeds its payloads.
const BLOB_FRAGMENT_BASE_IDS: [u32; 2] = [0, 100];

/// Blob payload: byte `i` is `(i * 7 + 3 + seed) as u8`.
fn blob_payload(len: usize, seed: usize) -> Vec<u8> {
    (0..len).map(|i| (i * 7 + 3 + seed) as u8).collect()
}

/// One fragment's batch: ids `base_id..base_id + 5`, blobs per
/// [`BLOB_ROW_SIZES`], `raw-<id>` in the plain binary column (null where the
/// blob is null).
fn blob_batch(schema: &Arc<Schema>, base_id: u32) -> RecordBatch {
    let seed = base_id as usize;
    let mut blobs = lance::BlobArrayBuilder::new(BLOB_ROW_SIZES.len());
    for size in BLOB_ROW_SIZES {
        match size {
            Some(0) => blobs.push_empty().unwrap(),
            Some(len) => blobs.push_bytes(blob_payload(len, seed)).unwrap(),
            None => blobs.push_null().unwrap(),
        }
    }

    let ids: Vec<u32> = (0..BLOB_ROW_SIZES.len() as u32)
        .map(|row| base_id + row)
        .collect();
    let raw: Vec<Vec<u8>> = ids
        .iter()
        .map(|id| format!("raw-{id}").into_bytes())
        .collect();
    let raw_array = BinaryArray::from_iter(
        raw.iter()
            .zip(BLOB_ROW_SIZES)
            .map(|(value, size)| size.map(|_| value.as_slice())),
    );

    RecordBatch::try_new(
        schema.clone(),
        vec![
            Arc::new(UInt32Array::from(ids)),
            blobs.finish().unwrap(),
            Arc::new(raw_array),
        ],
    )
    .unwrap()
}

/// Two-fragment v2.2 dataset with a blob column, a plain binary column and an
/// id column; one [`blob_batch`] per entry of [`BLOB_FRAGMENT_BASE_IDS`].
///
/// With `enable_stable_row_ids` a `_rowid` goes through the row id index
/// instead of being the row address.
fn create_blob_v2_dataset(enable_stable_row_ids: bool) -> (tempfile::TempDir, String) {
    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp.path().join("blob_ds").to_str().unwrap().to_string();

    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::UInt32, false),
        lance::blob_field_with_options(
            "blob",
            true,
            lance::BlobFieldOptions {
                inline_size_threshold: Some(BLOB_INLINE_THRESHOLD),
                dedicated_size_threshold: std::num::NonZeroUsize::new(BLOB_DEDICATED_THRESHOLD),
            },
        ),
        Field::new("raw", DataType::Binary, true),
    ]));

    lance_c::runtime::block_on(async {
        for (fragment, base_id) in BLOB_FRAGMENT_BASE_IDS.into_iter().enumerate() {
            let params = lance::dataset::WriteParams {
                mode: if fragment == 0 {
                    lance::dataset::WriteMode::Create
                } else {
                    lance::dataset::WriteMode::Append
                },
                // Blob v2 is a 2.2 storage feature.
                data_storage_version: Some(lance_file::version::LanceFileVersion::V2_2),
                enable_stable_row_ids,
                ..Default::default()
            };
            Dataset::write(
                arrow::record_batch::RecordBatchIterator::new(
                    vec![Ok(blob_batch(&schema, base_id))],
                    schema.clone(),
                ),
                &uri,
                Some(params),
            )
            .await
            .unwrap();
        }
    });

    (tmp, uri)
}

/// Run the scanner through the C Arrow stream; return its schema and batches.
fn scan_stream(scanner: *mut LanceScanner) -> (Schema, Vec<RecordBatch>) {
    let mut ffi_stream = FFI_ArrowArrayStream::empty();
    assert_eq!(
        unsafe { lance_scanner_to_arrow_stream(scanner, &mut ffi_stream) },
        0,
        "to_arrow_stream should succeed"
    );
    let reader = unsafe { ArrowArrayStreamReader::from_raw(&mut ffi_stream) }.unwrap();
    let schema = reader.schema().as_ref().clone();
    let batches: Vec<RecordBatch> = reader.map(|batch| batch.unwrap()).collect();
    (schema, batches)
}

/// Collect `(id, blob bytes)` pairs from batches whose blob column was
/// materialized as bytes, sorted by id.
fn collect_blob_bytes(batches: &[RecordBatch]) -> Vec<(u32, Option<Vec<u8>>)> {
    let mut rows = Vec::new();
    for batch in batches {
        let ids = batch
            .column_by_name("id")
            .expect("id column")
            .as_any()
            .downcast_ref::<UInt32Array>()
            .expect("id is UInt32");
        let blobs = batch
            .column_by_name("blob")
            .expect("blob column")
            .as_any()
            .downcast_ref::<LargeBinaryArray>()
            .expect("blob is LargeBinary");
        for row in 0..batch.num_rows() {
            let value = (!blobs.is_null(row)).then(|| blobs.value(row).to_vec());
            rows.push((ids.value(row), value));
        }
    }
    rows.sort_by_key(|(id, _)| *id);
    rows
}

/// Collect `(id, raw bytes)` pairs from the plain binary column, sorted by id.
fn collect_raw_bytes(batches: &[RecordBatch]) -> Vec<(u32, Option<Vec<u8>>)> {
    let mut rows = Vec::new();
    for batch in batches {
        let ids = batch
            .column_by_name("id")
            .expect("id column")
            .as_any()
            .downcast_ref::<UInt32Array>()
            .expect("id is UInt32");
        let raw = batch
            .column_by_name("raw")
            .expect("raw column")
            .as_any()
            .downcast_ref::<BinaryArray>()
            .expect("raw is Binary");
        for row in 0..batch.num_rows() {
            let value = (!raw.is_null(row)).then(|| raw.value(row).to_vec());
            rows.push((ids.value(row), value));
        }
    }
    rows.sort_by_key(|(id, _)| *id);
    rows
}

/// Assert that the plain binary column of the fragment based at `base_id`
/// round-tripped: `raw-<id>` bytes, and null in the last row.
fn assert_raw_bytes_of_fragment(rows: &[(u32, Option<Vec<u8>>)], base_id: u32) {
    let row = |id: u32| -> &Option<Vec<u8>> {
        &rows
            .iter()
            .find(|(row_id, _)| *row_id == id)
            .unwrap_or_else(|| panic!("row {id} missing from scan output"))
            .1
    };

    for offset in 0..4 {
        let id = base_id + offset;
        assert_eq!(
            row(id).as_deref(),
            Some(format!("raw-{id}").as_bytes()),
            "plain binary payload of row {id} must round-trip byte for byte"
        );
    }
    assert_eq!(
        row(base_id + 4),
        &None,
        "null plain binary value must stay null"
    );
}

/// Assert that the five rows written for `base_id` round-tripped byte for byte.
fn assert_blob_bytes_of_fragment(rows: &[(u32, Option<Vec<u8>>)], base_id: u32) {
    let row = |id: u32| -> &Option<Vec<u8>> {
        &rows
            .iter()
            .find(|(row_id, _)| *row_id == id)
            .unwrap_or_else(|| panic!("row {id} missing from scan output"))
            .1
    };
    let seed = base_id as usize;

    assert_eq!(
        row(base_id).as_deref(),
        Some(blob_payload(8, seed).as_slice()),
        "inline blob (8 bytes) must round-trip byte for byte"
    );
    assert_eq!(
        row(base_id + 1).as_deref(),
        Some(blob_payload(128, seed).as_slice()),
        "packed blob (128 bytes) must round-trip byte for byte"
    );
    assert_eq!(
        row(base_id + 2).as_deref(),
        Some(blob_payload(1024, seed).as_slice()),
        "dedicated blob (1024 bytes) must round-trip byte for byte"
    );
    assert_eq!(
        row(base_id + 3).as_deref(),
        Some([].as_slice()),
        "empty blob must be a zero-length, non-null value"
    );
    assert_eq!(row(base_id + 4), &None, "null blob must stay null");
}

/// Assert that the named field is a blob description struct.
fn assert_blob_description_field(schema: &Schema, name: &str) {
    let field = schema.field_with_name(name).expect("field exists");
    match field.data_type() {
        DataType::Struct(children) => {
            let names: Vec<&str> = children.iter().map(|c| c.name().as_str()).collect();
            assert_eq!(
                names, BLOB_DESCRIPTION_FIELDS,
                "{name} should be a blob description struct"
            );
        }
        other => panic!("{name} should be a blob description struct, got {other:?}"),
    }
}

#[test]
fn test_scanner_blob_handling_all_binary_materializes_bytes() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe { lance_scanner_set_blob_handling(scanner, BLOB_HANDLING_ALL_BINARY) },
        0
    );

    let (schema, batches) = scan_stream(scanner);
    let blob_field = schema.field_with_name("blob").expect("blob column");
    assert_eq!(
        *blob_field.data_type(),
        DataType::LargeBinary,
        "ALL_BINARY should materialize the blob column as bytes"
    );

    // Neither blob marker survives materialization (lance v11), so a C caller
    // cannot tell a materialized blob from a plain binary column by metadata.
    let metadata = blob_field.metadata();
    assert!(
        !metadata.contains_key("lance-encoding:blob"),
        "the blob marker should not survive materialization: {metadata:?}"
    );
    assert!(
        !metadata.contains_key("ARROW:extension:name"),
        "the blob v2 extension name should not survive materialization: {metadata:?}"
    );

    let rows = collect_blob_bytes(&batches);
    assert_eq!(rows.len(), 10, "both fragments should be scanned");
    assert_blob_bytes_of_fragment(&rows, 0);
    assert_blob_bytes_of_fragment(&rows, 100);

    unsafe { lance_scanner_close(scanner) };
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_scanner_blob_handling_defaults_to_descriptions() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    // Without the setter, and with an explicit BLOBS_DESCRIPTIONS, the blob
    // column is a description struct while plain binary columns stay bytes.
    for handling in [None, Some(BLOB_HANDLING_BLOBS_DESCRIPTIONS)] {
        let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
        assert!(!scanner.is_null());
        if let Some(handling) = handling {
            assert_eq!(
                unsafe { lance_scanner_set_blob_handling(scanner, handling) },
                0
            );
        }

        let (schema, batches) = scan_stream(scanner);
        assert_blob_description_field(&schema, "blob");
        assert_eq!(
            *schema
                .field_with_name("raw")
                .expect("raw column")
                .data_type(),
            DataType::Binary,
            "a plain binary column stays bytes under {handling:?}"
        );
        assert_eq!(
            batches.iter().map(|b| b.num_rows()).sum::<usize>(),
            10,
            "both fragments should be scanned under {handling:?}"
        );

        let raw_rows = collect_raw_bytes(&batches);
        assert_raw_bytes_of_fragment(&raw_rows, 0);
        assert_raw_bytes_of_fragment(&raw_rows, 100);

        unsafe { lance_scanner_close(scanner) };
    }

    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_scanner_blob_handling_all_descriptions() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe { lance_scanner_set_blob_handling(scanner, BLOB_HANDLING_ALL_DESCRIPTIONS) },
        0
    );

    let (schema, batches) = scan_stream(scanner);
    assert_blob_description_field(&schema, "blob");
    // On lance v11 ALL_DESCRIPTIONS only rewrites fields with blob metadata
    // (`Field::unloaded_mut` is gated on `is_blob`), so `raw` keeps its bytes.
    assert_eq!(
        *schema
            .field_with_name("raw")
            .expect("raw column")
            .data_type(),
        DataType::Binary,
        "a column without blob metadata is not turned into a description"
    );
    assert_eq!(
        batches.iter().map(|b| b.num_rows()).sum::<usize>(),
        10,
        "both fragments should be scanned"
    );

    let raw_rows = collect_raw_bytes(&batches);
    assert_raw_bytes_of_fragment(&raw_rows, 0);
    assert_raw_bytes_of_fragment(&raw_rows, 100);

    unsafe { lance_scanner_close(scanner) };
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_scanner_blob_handling_rejected_after_scan_started() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());

    let mut ffi_stream = FFI_ArrowArrayStream::empty();
    assert_eq!(
        unsafe { lance_scanner_to_arrow_stream(scanner, &mut ffi_stream) },
        0
    );
    // Release the stream; the scan has started either way.
    drop(unsafe { ArrowArrayStreamReader::from_raw(&mut ffi_stream) }.unwrap());

    assert_eq!(
        unsafe { lance_scanner_set_blob_handling(scanner, BLOB_HANDLING_ALL_BINARY) },
        -1,
        "blob handling must not change once the scan has started"
    );
    let message = take_last_error_message();
    assert!(
        message.contains("blob_handling must be set before the scan starts"),
        "unexpected error: {message}"
    );

    unsafe { lance_scanner_close(scanner) };
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_scanner_blob_handling_rejects_invalid_values() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());

    for invalid in [3, -1] {
        assert_eq!(
            unsafe { lance_scanner_set_blob_handling(scanner, invalid) },
            -1,
            "blob_handling {invalid} should be rejected"
        );
        assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
        let message = take_last_error_message();
        assert!(
            message.contains(&format!("got {invalid}")),
            "error for {invalid} should name the rejected value: {message}"
        );
    }

    assert_eq!(
        unsafe { lance_scanner_set_blob_handling(ptr::null_mut(), BLOB_HANDLING_ALL_BINARY) },
        -1,
        "NULL scanner should be rejected"
    );

    // A rejected value leaves the default handling in place.
    let (schema, _batches) = scan_stream(scanner);
    assert_blob_description_field(&schema, "blob");

    unsafe { lance_scanner_close(scanner) };
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_scanner_blob_handling_all_binary_with_fragment_ids() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let c_uri = c_str(&uri);
    let ds = unsafe { lance_dataset_open(c_uri.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());
    assert_eq!(unsafe { lance_dataset_fragment_count(ds) }, 2);

    let mut fragment_ids = vec![0u64; 2];
    assert_eq!(
        unsafe { lance_dataset_fragment_ids(ds, fragment_ids.as_mut_ptr()) },
        0
    );

    let scanner = unsafe { lance_scanner_new(ds, ptr::null(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(
        unsafe { lance_scanner_set_fragment_ids(scanner, fragment_ids[1..].as_ptr(), 1) },
        0
    );
    assert_eq!(
        unsafe { lance_scanner_set_blob_handling(scanner, BLOB_HANDLING_ALL_BINARY) },
        0
    );

    let (schema, batches) = scan_stream(scanner);
    assert_eq!(
        *schema
            .field_with_name("blob")
            .expect("blob column")
            .data_type(),
        DataType::LargeBinary
    );

    let rows = collect_blob_bytes(&batches);
    assert_eq!(
        rows.len(),
        5,
        "only the selected fragment should be scanned"
    );
    assert!(
        rows.iter().all(|(id, _)| (100..105).contains(id)),
        "unexpected rows from the unselected fragment: {:?}",
        rows.iter().map(|(id, _)| *id).collect::<Vec<_>>()
    );
    assert_blob_bytes_of_fragment(&rows, 100);

    unsafe { lance_scanner_close(scanner) };
    unsafe { lance_dataset_close(ds) };
}

// ---------------------------------------------------------------------------
// Blob v2 random access
// ---------------------------------------------------------------------------

/// Row offset (in `id` order) of the packed blob used by the cursor tests.
const PACKED_BLOB_ROW: usize = 1;
/// Row offset (in `id` order) of the dedicated blob used by the cursor tests.
const DEDICATED_BLOB_ROW: usize = 2;

/// Expected bytes at row offset `row` (in `id` order); `None` for the null row.
fn expected_blob(row: usize) -> Option<Vec<u8>> {
    let fragment = row / BLOB_ROW_SIZES.len();
    let seed = BLOB_FRAGMENT_BASE_IDS[fragment] as usize;
    BLOB_ROW_SIZES[row % BLOB_ROW_SIZES.len()].map(|len| blob_payload(len, seed))
}

/// Physical row address of a logical row in the two-fragment blob fixture.
fn blob_row_address(row: usize) -> u64 {
    let fragment = row / BLOB_ROW_SIZES.len();
    let offset = row % BLOB_ROW_SIZES.len();
    ((fragment as u64) << 32) | offset as u64
}

/// Row ids of every row in `id` order, read through the scanner.
fn scan_blob_row_ids(dataset: *const LanceDataset) -> Vec<u64> {
    let id_column = c_str("id");
    let columns: [*const c_char; 2] = [id_column.as_ptr(), ptr::null()];
    let scanner = unsafe { lance_scanner_new(dataset, columns.as_ptr(), ptr::null()) };
    assert!(!scanner.is_null());
    assert_eq!(unsafe { lance_scanner_with_row_id(scanner, true) }, 0);

    let mut stream = FFI_ArrowArrayStream::empty();
    assert_eq!(
        unsafe { lance_scanner_to_arrow_stream(scanner, &mut stream) },
        0
    );
    let reader = unsafe { ArrowArrayStreamReader::from_raw(&mut stream) }.unwrap();

    let mut rows: Vec<(u32, u64)> = Vec::new();
    for batch in reader {
        let batch = batch.unwrap();
        let ids = batch
            .column_by_name("id")
            .unwrap()
            .as_any()
            .downcast_ref::<UInt32Array>()
            .unwrap();
        let row_ids = batch
            .column_by_name("_rowid")
            .unwrap()
            .as_any()
            .downcast_ref::<UInt64Array>()
            .unwrap();
        for row in 0..batch.num_rows() {
            rows.push((ids.value(row), row_ids.value(row)));
        }
    }
    unsafe { lance_scanner_close(scanner) };

    rows.sort_by_key(|(id, _)| *id);
    rows.into_iter().map(|(_, row_id)| row_id).collect()
}

/// Take every blob of the dataset by row ID, asserting the call succeeds.
fn take_all_blobs(dataset: *const LanceDataset) -> Vec<*mut LanceBlobFile> {
    let row_ids = scan_blob_row_ids(dataset);
    assert_eq!(
        row_ids.len(),
        2 * BLOB_ROW_SIZES.len(),
        "two fragments of five rows"
    );

    let column = c_str("blob");
    let mut handles = vec![ptr::null_mut::<LanceBlobFile>(); row_ids.len()];
    let rc = unsafe {
        lance_dataset_take_blobs(
            dataset,
            row_ids.as_ptr(),
            row_ids.len(),
            column.as_ptr(),
            handles.as_mut_ptr(),
        )
    };
    assert_eq!(rc, 0, "take_blobs failed: {}", take_last_error_message());
    handles
}

/// Read a handle from its current cursor to the end, asserting success.
fn read_blob_to_end(handle: *mut LanceBlobFile) -> Vec<u8> {
    let size = unsafe { lance_blob_file_size(handle) };
    let mut cursor = 0u64;
    assert_eq!(unsafe { lance_blob_file_tell(handle, &mut cursor) }, 0);
    let mut buffer = vec![0u8; size.saturating_sub(cursor) as usize];
    assert_eq!(
        unsafe { lance_blob_file_read(handle, buffer.as_mut_ptr(), buffer.len()) },
        0,
        "read failed: {}",
        take_last_error_message()
    );
    buffer
}

/// Close every handle; NULL slots are accepted.
fn close_blob_handles(handles: &[*mut LanceBlobFile]) {
    for handle in handles {
        unsafe { lance_blob_file_close(*handle) };
    }
}

#[test]
fn test_blob_take_by_row_ids_covers_every_storage_layout() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let handles = take_all_blobs(ds);

    // Input order, both fragments: inline, packed, dedicated, empty, null.
    for (row, handle) in handles.iter().copied().enumerate() {
        match expected_blob(row) {
            None => assert!(
                handle.is_null(),
                "row {row}: a null blob must yield a NULL slot"
            ),
            Some(expected) => {
                assert!(
                    !handle.is_null(),
                    "row {row}: a non-null blob must yield a handle"
                );
                assert_eq!(
                    unsafe { lance_blob_file_size(handle) },
                    expected.len() as u64,
                    "row {row}: size must match the written payload"
                );
                assert_eq!(read_blob_to_end(handle), expected, "row {row}: bytes");
            }
        }
    }

    // An empty blob is a real handle of size 0, not a NULL slot.
    let empty = handles[3];
    assert!(!empty.is_null());
    assert_eq!(unsafe { lance_blob_file_size(empty) }, 0);
    let mut untouched = [0xABu8; 4];
    assert_eq!(
        unsafe { lance_blob_file_read(empty, untouched.as_mut_ptr(), untouched.len()) },
        0,
        "reading an empty blob failed: {}",
        take_last_error_message()
    );
    assert_eq!(untouched, [0xABu8; 4], "an empty blob must write no bytes");

    close_blob_handles(&handles);
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_blob_take_by_indices_matches_take_by_row_ids() {
    assert_blob_take_by_indices_matches_row_ids(false);
}

#[test]
fn test_blob_take_by_indices_matches_take_by_row_ids_with_stable_row_ids() {
    // With stable row ids a `_rowid` is not the row address.
    assert_blob_take_by_indices_matches_row_ids(true);
}

fn assert_blob_take_by_indices_matches_row_ids(enable_stable_row_ids: bool) {
    let (_tmp, uri) = create_blob_v2_dataset(enable_stable_row_ids);
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let by_row_id = take_all_blobs(ds);

    let indices = (0..2 * BLOB_ROW_SIZES.len() as u64).collect::<Vec<_>>();
    let column = c_str("blob");
    let mut by_index = vec![ptr::null_mut::<LanceBlobFile>(); indices.len()];
    let rc = unsafe {
        lance_dataset_take_blobs_by_indices(
            ds,
            indices.as_ptr(),
            indices.len(),
            column.as_ptr(),
            by_index.as_mut_ptr(),
        )
    };
    assert_eq!(
        rc,
        0,
        "take_blobs_by_indices failed: {}",
        take_last_error_message()
    );

    for row in 0..indices.len() {
        match (by_row_id[row].is_null(), by_index[row].is_null()) {
            (true, true) => continue,
            (false, false) => assert_eq!(
                read_blob_to_end(by_index[row]),
                read_blob_to_end(by_row_id[row]),
                "row {row}: both addressing schemes must return the same bytes"
            ),
            (row_id_null, index_null) => panic!(
                "row {row}: NULL slots disagree (by row id: {row_id_null}, by index: {index_null})"
            ),
        }
    }

    close_blob_handles(&by_row_id);
    close_blob_handles(&by_index);
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_blob_take_by_addresses_matches_native_and_expected_payloads() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let rows = [7, 2, 3, 4, 2, 9, 0];
    let addresses = rows.map(blob_row_address);

    // Read through the native Rust entry point as a separate oracle.
    let native = lance_c::runtime::block_on(async {
        let dataset = Arc::new(Dataset::open(&uri).await.unwrap());
        let blobs = dataset
            .take_blobs_by_addresses(&addresses, "blob")
            .await
            .unwrap();
        let mut results = Vec::with_capacity(blobs.len());
        for blob in blobs {
            results.push(match blob {
                Some(blob) => Some((blob.size(), blob.read().await.unwrap().to_vec())),
                None => None,
            });
        }
        results
    });

    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());
    let column = c_str("blob");
    let mut handles = vec![ptr::null_mut::<LanceBlobFile>(); rows.len()];
    assert_eq!(
        unsafe {
            lance_dataset_take_blobs_by_addresses(
                ds,
                addresses.as_ptr(),
                addresses.len(),
                column.as_ptr(),
                handles.as_mut_ptr(),
            )
        },
        0,
        "take_blobs_by_addresses failed: {}",
        take_last_error_message()
    );

    // The result must own its readers before the dataset is released.
    unsafe { lance_dataset_close(ds) };

    for (slot, row) in rows.into_iter().enumerate() {
        let expected = expected_blob(row);
        let native = native[slot]
            .as_ref()
            .map(|(size, bytes)| (*size, bytes.as_slice()));
        match expected {
            None => {
                assert!(
                    handles[slot].is_null(),
                    "row {row}: a null blob must yield a NULL slot"
                );
                assert!(native.is_none(), "row {row}: native oracle disagrees");
            }
            Some(expected) => {
                let handle = handles[slot];
                assert!(!handle.is_null(), "row {row}: expected a handle");
                assert_eq!(
                    unsafe { lance_blob_file_size(handle) },
                    expected.len() as u64,
                    "row {row}: size"
                );
                assert_eq!(
                    native,
                    Some((expected.len() as u64, expected.as_slice())),
                    "row {row}: direct native result"
                );

                if slot == 4 {
                    let mut duplicate_cursor = u64::MAX;
                    assert_eq!(
                        unsafe { lance_blob_file_tell(handles[4], &mut duplicate_cursor) },
                        0
                    );
                    assert_eq!(
                        duplicate_cursor, 0,
                        "duplicate addresses must not share a cursor"
                    );
                }
                assert_eq!(read_blob_to_end(handle), expected, "row {row}: bytes");
            }
        }
    }

    close_blob_handles(&handles);
}

#[test]
fn test_blob_take_by_addresses_differs_from_stable_row_ids() {
    let (_tmp, uri) = create_blob_v2_dataset(true);
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let row_ids = scan_blob_row_ids(ds);
    let addresses = (0..2 * BLOB_ROW_SIZES.len())
        .map(blob_row_address)
        .collect::<Vec<_>>();
    assert_eq!(row_ids.len(), addresses.len());
    assert!(
        row_ids
            .iter()
            .zip(&addresses)
            .any(|(row_id, address)| row_id != address),
        "the fixture must contain at least one stable row ID distinct from its physical address: \
         row_ids={row_ids:?}, addresses={addresses:?}"
    );

    let column = c_str("blob");
    let mut by_id = vec![ptr::null_mut::<LanceBlobFile>(); row_ids.len()];
    assert_eq!(
        unsafe {
            lance_dataset_take_blobs(
                ds,
                row_ids.as_ptr(),
                row_ids.len(),
                column.as_ptr(),
                by_id.as_mut_ptr(),
            )
        },
        0,
        "stable-row-ID take failed: {}",
        take_last_error_message()
    );
    let mut by_address = vec![ptr::null_mut::<LanceBlobFile>(); addresses.len()];
    assert_eq!(
        unsafe {
            lance_dataset_take_blobs_by_addresses(
                ds,
                addresses.as_ptr(),
                addresses.len(),
                column.as_ptr(),
                by_address.as_mut_ptr(),
            )
        },
        0,
        "row-address take failed: {}",
        take_last_error_message()
    );

    for (row, expected) in (0..2 * BLOB_ROW_SIZES.len())
        .map(|row| (row, expected_blob(row)))
        .collect::<Vec<_>>()
    {
        match expected {
            None => {
                assert!(by_id[row].is_null(), "stable row id row {row}");
                assert!(by_address[row].is_null(), "row address {row}");
            }
            Some(expected) => {
                assert!(!by_id[row].is_null(), "stable row id row {row}");
                assert!(!by_address[row].is_null(), "row address {row}");
                assert_eq!(
                    read_blob_to_end(by_id[row]),
                    expected,
                    "stable row id row {row}: bytes"
                );
                assert_eq!(
                    read_blob_to_end(by_address[row]),
                    expected,
                    "row address {row}: bytes"
                );
            }
        }
    }

    close_blob_handles(&by_id);
    close_blob_handles(&by_address);
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_blob_take_by_addresses_rejects_invalid_without_writing_out() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let column = c_str("blob");
    let sentinel = ptr::without_provenance_mut::<LanceBlobFile>(0xDEAD_BEEF);
    let mut out = [sentinel; 2];
    let assert_out_untouched = |out: &[*mut LanceBlobFile], case: &str| {
        for (slot, handle) in out.iter().enumerate() {
            assert_eq!(*handle, sentinel, "{case}: slot {slot} was written");
        }
    };

    // Empty selections still validate the column through native. The old
    // entry points retain their early-empty behavior.
    assert_eq!(
        unsafe {
            lance_dataset_take_blobs_by_addresses(
                ds,
                ptr::null(),
                0,
                column.as_ptr(),
                out.as_mut_ptr(),
            )
        },
        0,
        "empty by-address take failed: {}",
        take_last_error_message()
    );
    assert_out_untouched(&out, "empty valid column");

    let missing = c_str("does_not_exist");
    assert_eq!(
        unsafe { lance_dataset_take_blobs(ds, ptr::null(), 0, missing.as_ptr(), out.as_mut_ptr()) },
        0,
        "legacy take must preserve its early-empty behavior"
    );
    assert_out_untouched(&out, "legacy empty unknown column");

    assert_eq!(
        unsafe {
            lance_dataset_take_blobs_by_addresses(
                ds,
                ptr::null(),
                0,
                missing.as_ptr(),
                out.as_mut_ptr(),
            )
        },
        -1
    );
    assert_eq!(
        lance_last_error_code(),
        LanceErrorCode::Internal,
        "the new entry point must keep native unknown-column classification"
    );
    let message = take_last_error_message();
    assert!(message.contains("does_not_exist"), "{message}");
    assert_out_untouched(&out, "new empty unknown column");

    let not_a_blob = c_str("raw");
    assert_eq!(
        unsafe {
            lance_dataset_take_blobs_by_addresses(
                ds,
                ptr::null(),
                0,
                not_a_blob.as_ptr(),
                out.as_mut_ptr(),
            )
        },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(message.contains("not a blob column"), "{message}");
    assert_out_untouched(&out, "new empty non-blob column");

    // A valid address followed by a nonexistent fragment rejects the complete
    // request without filling even the valid slot.
    let addresses = [blob_row_address(0), u64::MAX - 1];
    assert_eq!(
        unsafe {
            lance_dataset_take_blobs_by_addresses(
                ds,
                addresses.as_ptr(),
                addresses.len(),
                column.as_ptr(),
                out.as_mut_ptr(),
            )
        },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains(&(u64::MAX - 1).to_string()), "{message}");
    assert_out_untouched(&out, "partially invalid addresses");

    let valid = [blob_row_address(0)];
    assert_eq!(
        unsafe {
            lance_dataset_take_blobs_by_addresses(
                ds,
                ptr::null(),
                1,
                column.as_ptr(),
                out.as_mut_ptr(),
            )
        },
        -1
    );
    let message = take_last_error_message();
    assert!(
        message.contains("row_addresses must not be NULL when num_row_addresses = 1"),
        "{message}"
    );
    assert_out_untouched(&out, "NULL row_addresses");

    assert_eq!(
        unsafe {
            lance_dataset_take_blobs_by_addresses(
                ptr::null(),
                valid.as_ptr(),
                valid.len(),
                column.as_ptr(),
                out.as_mut_ptr(),
            )
        },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains("dataset must not be NULL"), "{message}");
    assert_out_untouched(&out, "NULL dataset");

    assert_eq!(
        unsafe {
            lance_dataset_take_blobs_by_addresses(
                ds,
                valid.as_ptr(),
                valid.len(),
                ptr::null(),
                out.as_mut_ptr(),
            )
        },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains("column must not be NULL"), "{message}");
    assert_out_untouched(&out, "NULL column");

    assert_eq!(
        unsafe {
            lance_dataset_take_blobs_by_addresses(
                ds,
                valid.as_ptr(),
                valid.len(),
                column.as_ptr(),
                ptr::null_mut(),
            )
        },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains("out must not be NULL"), "{message}");

    let invalid_utf8 = CString::new(vec![b'b', b'l', 0xFF, b'o', b'b']).unwrap();
    assert_eq!(
        unsafe {
            lance_dataset_take_blobs_by_addresses(
                ds,
                valid.as_ptr(),
                valid.len(),
                invalid_utf8.as_ptr(),
                out.as_mut_ptr(),
            )
        },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert_out_untouched(&out, "invalid UTF-8 column");

    unsafe { lance_dataset_close(ds) };
}

/// Rows requested out of storage order: two fragments, a repeated row, and a
/// null blob in the middle.
const PERMUTED_ROWS: [usize; 5] = [7, 2, 2, 9, 0];

#[test]
fn test_blob_take_preserves_permuted_and_duplicated_input_order() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let all_row_ids = scan_blob_row_ids(ds);
    let row_ids = PERMUTED_ROWS
        .iter()
        .map(|row| all_row_ids[*row])
        .collect::<Vec<_>>();
    let indices = PERMUTED_ROWS
        .iter()
        .map(|row| *row as u64)
        .collect::<Vec<_>>();
    let column = c_str("blob");

    for (entry_point, ids) in [("row ids", &row_ids), ("indices", &indices)] {
        let mut handles = vec![ptr::null_mut::<LanceBlobFile>(); ids.len()];
        let rc = if entry_point == "row ids" {
            unsafe {
                lance_dataset_take_blobs(
                    ds,
                    ids.as_ptr(),
                    ids.len(),
                    column.as_ptr(),
                    handles.as_mut_ptr(),
                )
            }
        } else {
            unsafe {
                lance_dataset_take_blobs_by_indices(
                    ds,
                    ids.as_ptr(),
                    ids.len(),
                    column.as_ptr(),
                    handles.as_mut_ptr(),
                )
            }
        };
        assert_eq!(
            rc,
            0,
            "{entry_point}: take failed: {}",
            take_last_error_message()
        );

        for (slot, row) in PERMUTED_ROWS.iter().copied().enumerate() {
            let handle = handles[slot];
            match expected_blob(row) {
                None => assert!(
                    handle.is_null(),
                    "{entry_point}: slot {slot} (row {row}) must be NULL"
                ),
                Some(expected) => {
                    assert!(
                        !handle.is_null(),
                        "{entry_point}: slot {slot} (row {row}) must hold a handle"
                    );
                    assert_eq!(
                        unsafe { lance_blob_file_size(handle) },
                        expected.len() as u64,
                        "{entry_point}: slot {slot} (row {row}) size"
                    );
                    assert_eq!(
                        read_blob_to_end(handle),
                        expected,
                        "{entry_point}: slot {slot} (row {row}) bytes"
                    );
                }
            }
        }

        // Duplicate rows get independent handles with their own cursors.
        assert_eq!(unsafe { lance_blob_file_seek(handles[1], 0) }, 0);
        let mut first = u64::MAX;
        let mut second = u64::MAX;
        assert_eq!(unsafe { lance_blob_file_tell(handles[1], &mut first) }, 0);
        assert_eq!(unsafe { lance_blob_file_tell(handles[2], &mut second) }, 0);
        assert_eq!(first, 0, "{entry_point}: the rewound duplicate");
        assert_eq!(
            second,
            unsafe { lance_blob_file_size(handles[2]) },
            "{entry_point}: duplicates must not share a cursor"
        );

        close_blob_handles(&handles);
    }

    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_blob_fixture_uses_all_three_storage_layouts() {
    // The fixture must really produce three storage kinds; only the Rust API
    // exposes the kind.
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let kinds = lance_c::runtime::block_on(async {
        let dataset = Arc::new(Dataset::open(&uri).await.unwrap());
        let blobs = dataset
            .take_blobs_by_indices(&[0, 1, 2], "blob")
            .await
            .unwrap();
        blobs
            .into_iter()
            .map(|blob| blob.unwrap().kind())
            .collect::<Vec<_>>()
    });

    use lance_core::datatypes::BlobKind;
    assert_eq!(
        kinds,
        vec![BlobKind::Inline, BlobKind::Packed, BlobKind::Dedicated],
        "the 8, 128 and 1024 byte rows must land in three different layouts"
    );
}

#[test]
fn test_blob_cursor_advances_only_on_sequential_reads() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let handles = take_all_blobs(ds);
    let blob = handles[PACKED_BLOB_ROW];
    let payload = expected_blob(PACKED_BLOB_ROW).unwrap();
    let size = unsafe { lance_blob_file_size(blob) };
    assert_eq!(size, payload.len() as u64);

    let mut cursor = u64::MAX;
    assert_eq!(unsafe { lance_blob_file_tell(blob, &mut cursor) }, 0);
    assert_eq!(cursor, 0, "a fresh handle starts at the beginning");

    // A short read moves the cursor by exactly what it read.
    let mut buffer = vec![0u8; 32];
    let mut bytes_read = usize::MAX;
    assert_eq!(
        unsafe {
            lance_blob_file_read_up_to(blob, buffer.as_mut_ptr(), buffer.len(), &mut bytes_read)
        },
        0,
        "read_up_to failed: {}",
        take_last_error_message()
    );
    assert_eq!(bytes_read, 32);
    assert_eq!(buffer, payload[..32]);
    assert_eq!(unsafe { lance_blob_file_tell(blob, &mut cursor) }, 0);
    assert_eq!(cursor, 32);

    // Asking for more than remains reads only what is left.
    let mut rest = vec![0u8; payload.len()];
    assert_eq!(
        unsafe { lance_blob_file_read_up_to(blob, rest.as_mut_ptr(), rest.len(), &mut bytes_read) },
        0,
        "read_up_to failed: {}",
        take_last_error_message()
    );
    assert_eq!(bytes_read, payload.len() - 32);
    assert_eq!(&rest[..bytes_read], &payload[32..]);
    assert_eq!(unsafe { lance_blob_file_tell(blob, &mut cursor) }, 0);
    assert_eq!(cursor, size);

    // At the end, read_up_to reports zero bytes instead of failing.
    assert_eq!(
        unsafe { lance_blob_file_read_up_to(blob, rest.as_mut_ptr(), rest.len(), &mut bytes_read) },
        0
    );
    assert_eq!(bytes_read, 0);

    // seek positions the cursor, and read then starts there.
    assert_eq!(unsafe { lance_blob_file_seek(blob, 64) }, 0);
    assert_eq!(unsafe { lance_blob_file_tell(blob, &mut cursor) }, 0);
    assert_eq!(cursor, 64);
    let mut tail = vec![0u8; (size - 64) as usize];
    assert_eq!(
        unsafe { lance_blob_file_read(blob, tail.as_mut_ptr(), tail.len()) },
        0,
        "read failed: {}",
        take_last_error_message()
    );
    assert_eq!(tail, payload[64..]);

    // Seeking past the end is allowed; the read that follows writes nothing.
    assert_eq!(unsafe { lance_blob_file_seek(blob, size + 16) }, 0);
    let mut untouched = [0xCDu8; 8];
    assert_eq!(
        unsafe { lance_blob_file_read(blob, untouched.as_mut_ptr(), untouched.len()) },
        0,
        "reading past the end failed: {}",
        take_last_error_message()
    );
    assert_eq!(untouched, [0xCDu8; 8]);

    // read_range is positional and leaves the cursor wherever it was.
    assert_eq!(unsafe { lance_blob_file_seek(blob, 5) }, 0);
    let mut window = vec![0u8; 16];
    assert_eq!(
        unsafe { lance_blob_file_read_range(blob, 40, window.as_mut_ptr(), window.len()) },
        0,
        "read_range failed: {}",
        take_last_error_message()
    );
    assert_eq!(window, payload[40..56]);
    assert_eq!(unsafe { lance_blob_file_tell(blob, &mut cursor) }, 0);
    assert_eq!(cursor, 5, "read_range must not move the cursor");

    close_blob_handles(&handles);
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_blob_file_read_ranges_orders_overlaps_and_preserves_cursor() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let handles = take_all_blobs(ds);
    let blob = handles[PACKED_BLOB_ROW];
    let payload = expected_blob(PACKED_BLOB_ROW).unwrap();
    let ranges = [
        LanceBlobRange {
            offset: 100,
            length: 20,
        },
        LanceBlobRange {
            offset: 128,
            length: 0,
        },
        LanceBlobRange {
            offset: 40,
            length: 16,
        },
        LanceBlobRange {
            offset: 100,
            length: 8,
        },
        LanceBlobRange {
            offset: 127,
            length: 1,
        },
        LanceBlobRange {
            offset: 0,
            length: 128,
        },
    ];
    let capacities = [25usize, 0, 20, 8, 2, 130];
    let mut buffers = capacities
        .iter()
        .map(|capacity| vec![0xEEu8; *capacity])
        .collect::<Vec<_>>();
    let destinations = buffers
        .iter_mut()
        .map(|buffer| {
            if buffer.is_empty() {
                ptr::null_mut()
            } else {
                buffer.as_mut_ptr()
            }
        })
        .collect::<Vec<_>>();

    assert_eq!(unsafe { lance_blob_file_seek(blob, 5) }, 0);
    assert_eq!(
        unsafe {
            lance_blob_file_read_ranges(
                blob,
                ranges.as_ptr(),
                ranges.len(),
                destinations.as_ptr(),
                capacities.as_ptr(),
            )
        },
        0,
        "read_ranges failed: {}",
        take_last_error_message()
    );

    for (index, (range, buffer)) in ranges.iter().zip(&buffers).enumerate() {
        let length = range.length as usize;
        assert_eq!(
            &buffer[..length],
            &payload[range.offset as usize..range.offset as usize + length],
            "range {index}: bytes"
        );
        assert!(
            buffer[length..].iter().all(|byte| *byte == 0xEE),
            "range {index}: bytes beyond the requested length were modified"
        );
    }

    let mut cursor = u64::MAX;
    assert_eq!(unsafe { lance_blob_file_tell(blob, &mut cursor) }, 0);
    assert_eq!(cursor, 5, "read_ranges must not move the cursor");

    // An empty request with NULL arrays is valid on an open handle.
    assert_eq!(
        unsafe { lance_blob_file_read_ranges(blob, ptr::null(), 0, ptr::null(), ptr::null(),) },
        0,
        "empty read_ranges failed: {}",
        take_last_error_message()
    );
    assert_eq!(unsafe { lance_blob_file_tell(blob, &mut cursor) }, 0);
    assert_eq!(cursor, 5);

    close_blob_handles(&handles);
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_blob_file_read_ranges_rejects_invalid_without_writing_buffers() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let handles = take_all_blobs(ds);
    let blob = handles[PACKED_BLOB_ROW];
    let size = unsafe { lance_blob_file_size(blob) };
    assert_eq!(unsafe { lance_blob_file_seek(blob, 7) }, 0);

    let mut first = [0xAAu8; 4];
    let mut second = [0xBBu8; 8];
    let destinations = [first.as_mut_ptr(), second.as_mut_ptr()];
    let destination_lens = [first.len(), second.len()];
    let valid_ranges = [
        LanceBlobRange {
            offset: 0,
            length: 4,
        },
        LanceBlobRange {
            offset: 8,
            length: 8,
        },
    ];
    let assert_untouched = |first: &[u8], second: &[u8], case: &str| {
        assert!(
            first.iter().all(|byte| *byte == 0xAA),
            "{case}: first destination was modified"
        );
        assert!(
            second.iter().all(|byte| *byte == 0xBB),
            "{case}: second destination was modified"
        );
    };

    assert_eq!(
        unsafe {
            lance_blob_file_read_ranges(
                blob,
                ptr::null(),
                2,
                destinations.as_ptr(),
                destination_lens.as_ptr(),
            )
        },
        -1
    );
    let message = take_last_error_message();
    assert!(
        message.contains("ranges must not be NULL when num_ranges = 2"),
        "{message}"
    );
    assert_untouched(&first, &second, "NULL ranges");

    assert_eq!(
        unsafe {
            lance_blob_file_read_ranges(
                blob,
                valid_ranges.as_ptr(),
                valid_ranges.len(),
                ptr::null(),
                destination_lens.as_ptr(),
            )
        },
        -1
    );
    let message = take_last_error_message();
    assert!(
        message.contains("destinations must not be NULL when num_ranges = 2"),
        "{message}"
    );
    assert_untouched(&first, &second, "NULL destinations");

    assert_eq!(
        unsafe {
            lance_blob_file_read_ranges(
                blob,
                valid_ranges.as_ptr(),
                valid_ranges.len(),
                destinations.as_ptr(),
                ptr::null(),
            )
        },
        -1
    );
    let message = take_last_error_message();
    assert!(
        message.contains("destination_lens must not be NULL when num_ranges = 2"),
        "{message}"
    );
    assert_untouched(&first, &second, "NULL destination_lens");

    let null_destinations = [ptr::null_mut(), second.as_mut_ptr()];
    assert_eq!(
        unsafe {
            lance_blob_file_read_ranges(
                blob,
                valid_ranges.as_ptr(),
                valid_ranges.len(),
                null_destinations.as_ptr(),
                destination_lens.as_ptr(),
            )
        },
        -1
    );
    let message = take_last_error_message();
    assert!(
        message.contains("destinations[0] must not be NULL"),
        "{message}"
    );
    assert_untouched(&first, &second, "NULL non-empty destination");

    let short_lens = [3usize, second.len()];
    assert_eq!(
        unsafe {
            lance_blob_file_read_ranges(
                blob,
                valid_ranges.as_ptr(),
                valid_ranges.len(),
                destinations.as_ptr(),
                short_lens.as_ptr(),
            )
        },
        -1
    );
    let message = take_last_error_message();
    assert!(
        message.contains("destination_lens[0] = 3 is smaller"),
        "{message}"
    );
    assert_untouched(&first, &second, "short destination");

    let overflow = [LanceBlobRange {
        offset: u64::MAX,
        length: 2,
    }];
    let overflow_destinations = [first.as_mut_ptr()];
    let overflow_lens = [second.len()];
    assert_eq!(
        unsafe {
            lance_blob_file_read_ranges(
                blob,
                overflow.as_ptr(),
                overflow.len(),
                overflow_destinations.as_ptr(),
                overflow_lens.as_ptr(),
            )
        },
        -1
    );
    let message = take_last_error_message();
    assert!(
        message.contains("ranges[0].offset 18446744073709551615"),
        "{message}"
    );
    assert_untouched(&first, &second, "overflowing range");

    let out_of_bounds = [LanceBlobRange {
        offset: size - 1,
        length: 2,
    }];
    let bounds_destinations = [first.as_mut_ptr()];
    let bounds_lens = [second.len()];
    assert_eq!(
        unsafe {
            lance_blob_file_read_ranges(
                blob,
                out_of_bounds.as_ptr(),
                out_of_bounds.len(),
                bounds_destinations.as_ptr(),
                bounds_lens.as_ptr(),
            )
        },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains("exceeds blob size"), "{message}");
    assert_untouched(&first, &second, "out-of-bounds range");

    let mixed_ranges = [
        LanceBlobRange {
            offset: 0,
            length: 4,
        },
        LanceBlobRange {
            offset: size - 1,
            length: 2,
        },
    ];
    assert_eq!(
        unsafe {
            lance_blob_file_read_ranges(
                blob,
                mixed_ranges.as_ptr(),
                mixed_ranges.len(),
                destinations.as_ptr(),
                destination_lens.as_ptr(),
            )
        },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains("exceeds blob size"), "{message}");
    assert_untouched(&first, &second, "valid range followed by invalid range");

    let mut cursor = u64::MAX;
    assert_eq!(unsafe { lance_blob_file_tell(blob, &mut cursor) }, 0);
    assert_eq!(cursor, 7, "rejected range reads must not move the cursor");

    close_blob_handles(&handles);
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_blob_file_native_close_state_and_buffer_control() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let handles = take_all_blobs(ds);
    let blob = handles[PACKED_BLOB_ROW];
    let size = unsafe { lance_blob_file_size(blob) };
    let mut closed = true;
    assert_eq!(unsafe { lance_blob_file_is_closed(blob, &mut closed) }, 0);
    assert!(!closed, "a fresh handle starts open");

    assert_eq!(unsafe { lance_blob_file_set_buffer_size(blob, 0) }, 0);
    assert_eq!(unsafe { lance_blob_file_set_buffer_size(blob, 64) }, 0);
    assert_eq!(
        unsafe { lance_blob_file_set_buffer_size(blob, 1024 * 1024) },
        0
    );

    assert_eq!(unsafe { lance_blob_file_mark_closed(blob) }, 0);
    assert_eq!(unsafe { lance_blob_file_is_closed(blob, &mut closed) }, 0);
    assert!(closed);
    assert_eq!(
        unsafe { lance_blob_file_size(blob) },
        size,
        "size must remain available after marking closed"
    );

    // Native close is idempotent.
    assert_eq!(unsafe { lance_blob_file_mark_closed(blob) }, 0);
    assert_eq!(unsafe { lance_blob_file_is_closed(blob, &mut closed) }, 0);
    assert!(closed);

    assert_eq!(unsafe { lance_blob_file_set_buffer_size(blob, 32) }, -1);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(message.contains("already closed"), "{message}");

    // Empty multi-range requests still reach native closed-state validation.
    assert_eq!(
        unsafe { lance_blob_file_read_ranges(blob, ptr::null(), 0, ptr::null(), ptr::null(),) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(message.contains("already closed"), "{message}");

    let range = [LanceBlobRange {
        offset: 0,
        length: 1,
    }];
    let mut byte = [0xF1u8];
    let destinations = [byte.as_mut_ptr()];
    let destination_lens = [1usize];
    assert_eq!(
        unsafe {
            lance_blob_file_read_ranges(
                blob,
                range.as_ptr(),
                range.len(),
                destinations.as_ptr(),
                destination_lens.as_ptr(),
            )
        },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(message.contains("already closed"), "{message}");
    assert_eq!(byte, [0xF1u8], "a rejected read must not write output");

    let mut cursor = 0u64;
    assert_eq!(unsafe { lance_blob_file_tell(blob, &mut cursor) }, -1);
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let _ = take_last_error_message();

    // Preserve the old zero-length single-range compatibility. Non-empty
    // positional reads follow native closed-state errors.
    assert_eq!(
        unsafe { lance_blob_file_read_range(blob, 0, ptr::null_mut(), 0) },
        0,
        "the existing zero-length read_range must keep succeeding"
    );
    assert_eq!(
        unsafe { lance_blob_file_read_range(blob, 0, byte.as_mut_ptr(), byte.len()) },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(message.contains("already closed"), "{message}");
    assert_eq!(byte, [0xF1u8]);

    assert_eq!(
        unsafe { lance_blob_file_is_closed(blob, ptr::null_mut()) },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains("out_closed must not be NULL"), "{message}");
    assert_eq!(
        unsafe { lance_blob_file_is_closed(ptr::null(), &mut closed) },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains("blob must not be NULL"), "{message}");
    assert_eq!(unsafe { lance_blob_file_mark_closed(ptr::null_mut()) }, -1);
    let message = take_last_error_message();
    assert!(message.contains("blob must not be NULL"), "{message}");

    close_blob_handles(&handles);
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_blob_read_rejects_buffer_smaller_than_remaining() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let handles = take_all_blobs(ds);
    let blob = handles[PACKED_BLOB_ROW];
    let payload = expected_blob(PACKED_BLOB_ROW).unwrap();

    // One byte short of the whole blob.
    let mut buffer = vec![0xEEu8; payload.len() - 1];
    assert_eq!(
        unsafe { lance_blob_file_read(blob, buffer.as_mut_ptr(), buffer.len()) },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains("dst_len 127"), "{message}");
    assert!(message.contains("128 bytes remaining"), "{message}");
    assert!(message.contains("cursor 0"), "{message}");
    assert!(message.contains("blob size 128"), "{message}");
    assert!(
        buffer.iter().all(|byte| *byte == 0xEE),
        "a rejected read must not touch the buffer"
    );

    // The same rejection from a non-zero cursor reports the bytes remaining,
    // not the blob size.
    assert_eq!(unsafe { lance_blob_file_seek(blob, 100) }, 0);
    let mut short = vec![0u8; 27];
    assert_eq!(
        unsafe { lance_blob_file_read(blob, short.as_mut_ptr(), short.len()) },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains("dst_len 27"), "{message}");
    assert!(message.contains("28 bytes remaining"), "{message}");
    assert!(message.contains("cursor 100"), "{message}");
    assert!(message.contains("blob size 128"), "{message}");

    // An exactly sized buffer succeeds.
    let mut exact = vec![0u8; 28];
    assert_eq!(
        unsafe { lance_blob_file_read(blob, exact.as_mut_ptr(), exact.len()) },
        0,
        "read failed: {}",
        take_last_error_message()
    );
    assert_eq!(exact, payload[100..]);

    close_blob_handles(&handles);
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_blob_read_range_rejects_out_of_bounds() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let handles = take_all_blobs(ds);
    let blob = handles[PACKED_BLOB_ROW];
    let size = unsafe { lance_blob_file_size(blob) };

    // Four bytes past the end.
    let mut buffer = vec![0x5Au8; 8];
    assert_eq!(
        unsafe { lance_blob_file_read_range(blob, size - 4, buffer.as_mut_ptr(), buffer.len()) },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains("132"), "{message}");
    assert!(message.contains("exceeds blob size 128"), "{message}");
    assert!(
        buffer.iter().all(|byte| *byte == 0x5A),
        "a rejected read_range must not touch the buffer"
    );

    // An offset plus length that overflows 64 bits is rejected before any read.
    assert_eq!(
        unsafe { lance_blob_file_read_range(blob, u64::MAX, buffer.as_mut_ptr(), 2) },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains(&u64::MAX.to_string()), "{message}");
    assert!(message.contains("len 2"), "{message}");

    // An empty range succeeds and accepts a NULL destination.
    assert_eq!(
        unsafe { lance_blob_file_read_range(blob, 0, ptr::null_mut(), 0) },
        0,
        "empty read_range failed: {}",
        take_last_error_message()
    );

    close_blob_handles(&handles);
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_blob_handles_outlive_the_dataset() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let handles = take_all_blobs(ds);

    // Handles own their readers; the dataset can go first.
    unsafe { lance_dataset_close(ds) };

    for (row, handle) in handles.iter().copied().enumerate() {
        let Some(expected) = expected_blob(row) else {
            continue;
        };
        assert_eq!(
            unsafe { lance_blob_file_size(handle) },
            expected.len() as u64,
            "row {row}: size after the dataset was closed"
        );
        assert_eq!(
            read_blob_to_end(handle),
            expected,
            "row {row}: read after the dataset was closed"
        );

        if expected.is_empty() {
            continue;
        }
        let mut window = vec![0u8; expected.len().min(16)];
        assert_eq!(
            unsafe { lance_blob_file_read_range(handle, 0, window.as_mut_ptr(), window.len()) },
            0,
            "row {row}: read_range after the dataset was closed: {}",
            take_last_error_message()
        );
        assert_eq!(window, expected[..window.len()], "row {row}: range bytes");
    }

    close_blob_handles(&handles);
}

#[test]
fn test_blob_take_rejects_invalid_arguments() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let row_ids = scan_blob_row_ids(ds);
    let blob_column = c_str("blob");

    // Sentinel that no rejected call may overwrite; never dereferenced.
    let sentinel = ptr::without_provenance_mut::<LanceBlobFile>(0xDEAD_BEEF);
    let mut out = vec![sentinel; row_ids.len()];
    let assert_out_untouched = |out: &[*mut LanceBlobFile], case: &str| {
        for (slot, handle) in out.iter().enumerate() {
            assert_eq!(*handle, sentinel, "{case}: slot {slot} was written");
        }
    };

    let missing = c_str("does_not_exist");
    assert_eq!(
        unsafe {
            lance_dataset_take_blobs(
                ds,
                row_ids.as_ptr(),
                row_ids.len(),
                missing.as_ptr(),
                out.as_mut_ptr(),
            )
        },
        -1
    );
    // Read the code first; taking the message clears the error.
    assert_eq!(
        lance_last_error_code(),
        LanceErrorCode::InvalidArgument,
        "a misspelled column is a caller error, not an internal one"
    );
    let message = take_last_error_message();
    assert!(message.contains("does_not_exist"), "{message}");
    assert_out_untouched(&out, "missing column");

    let not_a_blob = c_str("raw");
    assert_eq!(
        unsafe {
            lance_dataset_take_blobs(
                ds,
                row_ids.as_ptr(),
                row_ids.len(),
                not_a_blob.as_ptr(),
                out.as_mut_ptr(),
            )
        },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(message.contains("raw"), "{message}");
    assert!(message.contains("not a blob column"), "{message}");
    assert_out_untouched(&out, "non-blob column");

    // Zero identifiers is a no-op success that writes nothing.
    assert_eq!(
        unsafe {
            lance_dataset_take_blobs(ds, ptr::null(), 0, blob_column.as_ptr(), out.as_mut_ptr())
        },
        0,
        "empty take failed: {}",
        take_last_error_message()
    );
    assert_out_untouched(&out, "zero row ids");
    assert_eq!(
        unsafe {
            lance_dataset_take_blobs_by_indices(
                ds,
                ptr::null(),
                0,
                blob_column.as_ptr(),
                out.as_mut_ptr(),
            )
        },
        0,
        "empty take by index failed: {}",
        take_last_error_message()
    );
    assert_out_untouched(&out, "zero indices");

    assert_eq!(
        unsafe {
            lance_dataset_take_blobs(ds, ptr::null(), 1, blob_column.as_ptr(), out.as_mut_ptr())
        },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains("row_ids must not be NULL"), "{message}");
    assert!(message.contains("num_row_ids = 1"), "{message}");
    assert_out_untouched(&out, "NULL row_ids");

    assert_eq!(
        unsafe {
            lance_dataset_take_blobs_by_indices(
                ds,
                ptr::null(),
                1,
                blob_column.as_ptr(),
                out.as_mut_ptr(),
            )
        },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains("indices must not be NULL"), "{message}");
    assert!(message.contains("num_indices = 1"), "{message}");
    assert_out_untouched(&out, "NULL indices");

    assert_eq!(
        unsafe {
            lance_dataset_take_blobs(
                ptr::null(),
                row_ids.as_ptr(),
                row_ids.len(),
                blob_column.as_ptr(),
                out.as_mut_ptr(),
            )
        },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains("dataset must not be NULL"), "{message}");
    assert_out_untouched(&out, "NULL dataset");

    assert_eq!(
        unsafe {
            lance_dataset_take_blobs(
                ds,
                row_ids.as_ptr(),
                row_ids.len(),
                ptr::null(),
                out.as_mut_ptr(),
            )
        },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains("column must not be NULL"), "{message}");
    assert_out_untouched(&out, "NULL column");

    assert_eq!(
        unsafe {
            lance_dataset_take_blobs(
                ds,
                row_ids.as_ptr(),
                row_ids.len(),
                blob_column.as_ptr(),
                ptr::null_mut(),
            )
        },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains("out must not be NULL"), "{message}");

    // Invalid UTF-8 in the column name.
    let invalid_utf8 = CString::new(b"bl\xFFob".to_vec()).unwrap();
    assert_eq!(
        unsafe {
            lance_dataset_take_blobs(
                ds,
                row_ids.as_ptr(),
                row_ids.len(),
                invalid_utf8.as_ptr(),
                out.as_mut_ptr(),
            )
        },
        -1
    );
    assert_out_untouched(&out, "invalid UTF-8 column");

    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_blob_reads_reject_null_destination_and_out_params() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let handles = take_all_blobs(ds);
    let blob = handles[PACKED_BLOB_ROW];
    let size = unsafe { lance_blob_file_size(blob) };

    // A NULL destination is only legal for a request that reads no bytes.
    assert_eq!(
        unsafe { lance_blob_file_read(blob, ptr::null_mut(), size as usize) },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains("dst must not be NULL"), "{message}");

    let mut bytes_read = usize::MAX;
    assert_eq!(
        unsafe { lance_blob_file_read_up_to(blob, ptr::null_mut(), 8, &mut bytes_read) },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains("dst must not be NULL"), "{message}");
    assert_eq!(
        bytes_read,
        usize::MAX,
        "a rejected read must not report a length"
    );

    assert_eq!(
        unsafe { lance_blob_file_read_range(blob, 0, ptr::null_mut(), 8) },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains("dst must not be NULL"), "{message}");

    let mut pos = u64::MAX;
    assert_eq!(unsafe { lance_blob_file_tell(blob, ptr::null_mut()) }, -1);
    let message = take_last_error_message();
    assert!(message.contains("pos must not be NULL"), "{message}");

    // None of the rejections moved the cursor.
    assert_eq!(unsafe { lance_blob_file_tell(blob, &mut pos) }, 0);
    assert_eq!(pos, 0);

    close_blob_handles(&handles);
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_blob_take_rejects_unknown_row_id() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let column = c_str("blob");
    let sentinel = ptr::without_provenance_mut::<LanceBlobFile>(0xDEAD_BEEF);
    let mut out = [sentinel];
    let unknown = [u64::MAX - 1];

    assert_eq!(
        unsafe {
            lance_dataset_take_blobs(ds, unknown.as_ptr(), 1, column.as_ptr(), out.as_mut_ptr())
        },
        -1
    );
    // The row id decodes to a fragment that does not exist; upstream rejects
    // the whole call.
    let message = take_last_error_message();
    assert!(message.contains("18446744073709551614"), "{message}");
    assert!(message.contains("non-existent fragment"), "{message}");
    assert_eq!(out[0], sentinel, "a rejected take must not write `out`");

    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_blob_take_by_indices_rejects_out_of_range_index() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let column = c_str("blob");
    let sentinel = ptr::without_provenance_mut::<LanceBlobFile>(0xDEAD_BEEF);
    let mut out = [sentinel, sentinel];
    // A valid offset next to one just past the end of the dataset.
    let indices = [0u64, 2 * BLOB_ROW_SIZES.len() as u64];

    assert_eq!(
        unsafe {
            lance_dataset_take_blobs_by_indices(
                ds,
                indices.as_ptr(),
                indices.len(),
                column.as_ptr(),
                out.as_mut_ptr(),
            )
        },
        -1
    );
    // An offset past the end becomes a tombstone address, which upstream
    // rejects; the valid slot is not written either.
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(message.contains("non-existent fragment"), "{message}");
    assert_eq!(
        out,
        [sentinel, sentinel],
        "a rejected take must not write `out`"
    );

    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_blob_read_up_to_requires_bytes_read_out_param() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let handles = take_all_blobs(ds);
    let blob = handles[DEDICATED_BLOB_ROW];
    let mut buffer = [0u8; 8];

    assert_eq!(
        unsafe {
            lance_blob_file_read_up_to(blob, buffer.as_mut_ptr(), buffer.len(), ptr::null_mut())
        },
        -1
    );
    let message = take_last_error_message();
    assert!(message.contains("bytes_read must not be NULL"), "{message}");

    // A zero-length request accepts a NULL destination and reports 0 bytes.
    let mut bytes_read = usize::MAX;
    assert_eq!(
        unsafe { lance_blob_file_read_up_to(blob, ptr::null_mut(), 0, &mut bytes_read) },
        0,
        "zero-length read_up_to failed: {}",
        take_last_error_message()
    );
    assert_eq!(bytes_read, 0);

    close_blob_handles(&handles);
    unsafe { lance_dataset_close(ds) };
}

#[test]
fn test_blob_null_handle_is_rejected_without_crashing() {
    /// Assert that the pending error names the NULL handle.
    fn assert_null_handle_reported() {
        let message = take_last_error_message();
        assert!(message.contains("blob must not be NULL"), "{message}");
    }

    assert_eq!(unsafe { lance_blob_file_size(ptr::null()) }, 0);
    assert_ne!(
        lance_last_error_code(),
        LanceErrorCode::Ok,
        "size must report a NULL handle through the error channel"
    );
    assert_null_handle_reported();

    let mut buffer = [0u8; 4];
    assert_eq!(
        unsafe { lance_blob_file_read(ptr::null_mut(), buffer.as_mut_ptr(), buffer.len()) },
        -1
    );
    assert_null_handle_reported();
    let mut bytes_read = 0usize;
    assert_eq!(
        unsafe {
            lance_blob_file_read_up_to(
                ptr::null_mut(),
                buffer.as_mut_ptr(),
                buffer.len(),
                &mut bytes_read,
            )
        },
        -1
    );
    assert_null_handle_reported();
    assert_eq!(
        unsafe { lance_blob_file_read_range(ptr::null(), 0, buffer.as_mut_ptr(), buffer.len()) },
        -1
    );
    assert_null_handle_reported();
    assert_eq!(unsafe { lance_blob_file_seek(ptr::null_mut(), 0) }, -1);
    assert_null_handle_reported();
    let mut pos = 0u64;
    assert_eq!(unsafe { lance_blob_file_tell(ptr::null(), &mut pos) }, -1);
    assert_null_handle_reported();

    // Closing NULL is a no-op.
    unsafe { lance_blob_file_close(ptr::null_mut()) };
}

#[test]
fn test_blob_close_keeps_the_pending_error_readable() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let uri_c = c_str(&uri);
    let ds = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!ds.is_null());

    let handles = take_all_blobs(ds);
    let blob = handles[PACKED_BLOB_ROW];
    let mut too_small = [0u8; 4];
    assert_eq!(
        unsafe { lance_blob_file_read(blob, too_small.as_mut_ptr(), too_small.len()) },
        -1
    );

    // Closing must not clear an error the caller has not read yet.
    unsafe { lance_blob_file_close(blob) };
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    let message = take_last_error_message();
    assert!(message.contains("dst_len 4"), "{message}");

    let rest = handles
        .iter()
        .copied()
        .filter(|handle| *handle != blob)
        .collect::<Vec<_>>();
    close_blob_handles(&rest);
    unsafe { lance_dataset_close(ds) };
}

const BLOB_SELECTOR_NONE: i32 = 0;
const BLOB_SELECTOR_IDS: i32 = 1;
const BLOB_SELECTOR_ADDRESSES: i32 = 2;
const BLOB_SELECTOR_INDICES: i32 = 3;
const BLOB_ORDER_PRESERVE: i32 = 0;
const BLOB_ORDER_UNORDERED: i32 = 1;

type WholeBlobResult = (u64, Option<Vec<u8>>);
type BlobRangeResult = (usize, u64, u64, u64, Option<Vec<u8>>);

fn c_blob_read_options(io_buffer_size: Option<u64>, preserve_order: bool) -> LanceBlobReadOptions {
    LanceBlobReadOptions {
        has_io_buffer_size: io_buffer_size.is_some(),
        io_buffer_size: io_buffer_size.unwrap_or(0),
        order: if preserve_order {
            BLOB_ORDER_PRESERVE
        } else {
            BLOB_ORDER_UNORDERED
        },
    }
}

fn c_read_blobs(
    dataset: *const LanceDataset,
    column: &str,
    selector: i32,
    rows: &[u64],
    options: &LanceBlobReadOptions,
) -> (i32, FFI_ArrowArrayStream) {
    let mut stream = FFI_ArrowArrayStream::empty();
    let column = c_str(column);
    let rows_ptr = if selector == BLOB_SELECTOR_NONE {
        ptr::null()
    } else {
        rows.as_ptr()
    };
    let rc = unsafe {
        lance_dataset_read_blobs(
            dataset,
            column.as_ptr(),
            selector,
            rows_ptr,
            rows.len(),
            options,
            &mut stream,
        )
    };
    (rc, stream)
}

fn c_read_blob_ranges(
    dataset: *const LanceDataset,
    column: &str,
    selector: i32,
    requests: &[LanceBlobRangeRequest],
    options: &LanceBlobReadOptions,
) -> (i32, FFI_ArrowArrayStream) {
    let mut stream = FFI_ArrowArrayStream::empty();
    let column = c_str(column);
    let requests_ptr = if selector == BLOB_SELECTOR_NONE {
        ptr::null()
    } else {
        requests.as_ptr()
    };
    let rc = unsafe {
        lance_dataset_read_blob_ranges(
            dataset,
            column.as_ptr(),
            selector,
            requests_ptr,
            requests.len(),
            options,
            &mut stream,
        )
    };
    (rc, stream)
}

fn collect_whole_blob_stream(mut stream: FFI_ArrowArrayStream) -> (Schema, Vec<RecordBatch>) {
    let reader = unsafe { ArrowArrayStreamReader::from_raw(&mut stream) }.unwrap();
    let schema = reader.schema().as_ref().clone();
    let batches = reader.map(|batch| batch.unwrap()).collect::<Vec<_>>();
    (schema, batches)
}

fn whole_blob_values(batches: &[RecordBatch]) -> Vec<WholeBlobResult> {
    let mut values = Vec::new();
    for batch in batches {
        assert_eq!(batch.num_rows(), 1, "one native result must be one record");
        let row_addresses = batch
            .column_by_name("row_address")
            .unwrap()
            .as_any()
            .downcast_ref::<UInt64Array>()
            .unwrap();
        let data = batch
            .column_by_name("data")
            .unwrap()
            .as_any()
            .downcast_ref::<LargeBinaryArray>()
            .unwrap();
        values.push((
            row_addresses.value(0),
            (!data.is_null(0)).then(|| data.value(0).to_vec()),
        ));
    }
    values
}

fn collect_blob_range_stream(mut stream: FFI_ArrowArrayStream) -> (Schema, Vec<RecordBatch>) {
    let reader = unsafe { ArrowArrayStreamReader::from_raw(&mut stream) }.unwrap();
    let schema = reader.schema().as_ref().clone();
    let batches = reader.map(|batch| batch.unwrap()).collect::<Vec<_>>();
    (schema, batches)
}

fn blob_range_values(batches: &[RecordBatch]) -> Vec<BlobRangeResult> {
    let mut values = Vec::new();
    for batch in batches {
        assert_eq!(batch.num_rows(), 1, "one native result must be one record");
        let request_index = batch
            .column_by_name("request_index")
            .unwrap()
            .as_any()
            .downcast_ref::<UInt64Array>()
            .unwrap();
        let row_address = batch
            .column_by_name("row_address")
            .unwrap()
            .as_any()
            .downcast_ref::<UInt64Array>()
            .unwrap();
        let offset = batch
            .column_by_name("offset")
            .unwrap()
            .as_any()
            .downcast_ref::<UInt64Array>()
            .unwrap();
        let length = batch
            .column_by_name("length")
            .unwrap()
            .as_any()
            .downcast_ref::<UInt64Array>()
            .unwrap();
        let data = batch
            .column_by_name("data")
            .unwrap()
            .as_any()
            .downcast_ref::<LargeBinaryArray>()
            .unwrap();
        values.push((
            usize::try_from(request_index.value(0)).unwrap(),
            row_address.value(0),
            offset.value(0),
            length.value(0),
            (!data.is_null(0)).then(|| data.value(0).to_vec()),
        ));
    }
    values
}

fn native_whole_blob_values(
    uri: &str,
    column: &str,
    selector: i32,
    rows: &[u64],
    io_buffer_size: Option<u64>,
    preserve_order: bool,
) -> Vec<WholeBlobResult> {
    lance_c::runtime::block_on(async {
        let dataset = Arc::new(Dataset::open(uri).await.unwrap());
        let builder = dataset.read_blobs(column).unwrap();
        let builder = match selector {
            BLOB_SELECTOR_NONE => builder,
            BLOB_SELECTOR_IDS => builder.with_row_ids(rows.to_vec()),
            BLOB_SELECTOR_ADDRESSES => builder.with_row_addresses(rows.to_vec()),
            BLOB_SELECTOR_INDICES => builder.with_row_indices(rows.to_vec()),
            other => panic!("unknown selector {other}"),
        };
        let builder = match io_buffer_size {
            Some(size) => builder.with_io_buffer_size_bytes(size),
            None => builder,
        };
        builder
            .preserve_order(preserve_order)
            .try_into_stream()
            .await
            .unwrap()
            .map(|result| {
                let result = result.unwrap();
                (result.row_address, result.data.map(|bytes| bytes.to_vec()))
            })
            .collect::<Vec<_>>()
            .await
    })
}

fn native_blob_range_values(
    uri: &str,
    column: &str,
    selector: i32,
    requests: &[(u64, u64, u64)],
    io_buffer_size: Option<u64>,
    preserve_order: bool,
) -> Vec<BlobRangeResult> {
    lance_c::runtime::block_on(async {
        let dataset = Arc::new(Dataset::open(uri).await.unwrap());
        let native_requests = requests
            .iter()
            .map(|(row, offset, length)| {
                lance::dataset::BlobRangeRequest::new(*row, *offset, *length)
            })
            .collect::<Vec<_>>();
        let builder = dataset.read_blob_ranges(column).unwrap();
        let builder = match selector {
            BLOB_SELECTOR_NONE => builder,
            BLOB_SELECTOR_IDS => builder.with_row_ids(native_requests),
            BLOB_SELECTOR_ADDRESSES => builder.with_row_addresses(native_requests),
            BLOB_SELECTOR_INDICES => builder.with_row_indices(native_requests),
            other => panic!("unknown selector {other}"),
        };
        let builder = match io_buffer_size {
            Some(size) => builder.with_io_buffer_size_bytes(size),
            None => builder,
        };
        builder
            .preserve_order(preserve_order)
            .try_into_stream()
            .await
            .unwrap()
            .map(|result| {
                let result = result.unwrap();
                (
                    result.request_index,
                    result.row_address,
                    result.range.offset,
                    result.range.length,
                    result.data.map(|bytes| bytes.to_vec()),
                )
            })
            .collect::<Vec<_>>()
            .await
    })
}

fn assert_whole_stream_identity(schema: &Schema, batches: &[RecordBatch]) {
    assert_eq!(
        schema
            .fields()
            .iter()
            .map(|field| field.name().as_str())
            .collect::<Vec<_>>(),
        ["row_address", "data"]
    );
    assert_eq!(schema.field(0).data_type(), &DataType::UInt64);
    assert!(!schema.field(0).is_nullable());
    assert_eq!(schema.field(1).data_type(), &DataType::LargeBinary);
    assert!(schema.field(1).is_nullable());
    assert_eq!(whole_blob_values(batches).len(), batches.len());
}

fn assert_range_stream_identity(schema: &Schema, batches: &[RecordBatch]) {
    assert_eq!(
        schema
            .fields()
            .iter()
            .map(|field| field.name().as_str())
            .collect::<Vec<_>>(),
        ["request_index", "row_address", "offset", "length", "data"]
    );
    for field in &schema.fields()[..4] {
        assert_eq!(field.data_type(), &DataType::UInt64);
        assert!(!field.is_nullable());
    }
    assert_eq!(schema.field(4).data_type(), &DataType::LargeBinary);
    assert!(schema.field(4).is_nullable());
    assert_eq!(blob_range_values(batches).len(), batches.len());
}

fn empty_ffi_stream_with_sentinel(sentinel: *mut c_void) -> FFI_ArrowArrayStream {
    let mut stream = FFI_ArrowArrayStream::empty();
    stream.private_data = sentinel;
    stream
}

fn assert_ffi_stream_untouched(stream: &FFI_ArrowArrayStream, sentinel: *mut c_void) {
    assert_eq!(stream.private_data, sentinel);
    assert!(stream.get_schema.is_none());
    assert!(stream.get_next.is_none());
    assert!(stream.get_last_error.is_none());
    assert!(stream.release.is_none());
}

fn finish_descriptor_builder(
    builder: *mut LanceBlobDescriptorArrayBuilder,
) -> (Field, arrow_array::ArrayRef) {
    let mut array = FFI_ArrowArray::empty();
    let mut schema = FFI_ArrowSchema::empty();
    assert_eq!(
        unsafe { lance_blob_descriptor_array_builder_finish(builder, &mut array, &mut schema) },
        0,
        "{}",
        take_last_error_message()
    );
    let field = Field::try_from(&schema).unwrap();
    let data = unsafe { from_ffi(array, &schema) }.unwrap();
    (field, make_array(data))
}

fn ffi_descriptor_stream(
    field: Field,
    array: arrow_array::ArrayRef,
    schema_metadata: Option<HashMap<String, String>>,
) -> (FFI_ArrowSchema, FFI_ArrowArrayStream) {
    let schema = Arc::new(match schema_metadata {
        Some(metadata) => Schema::new_with_metadata(vec![field], metadata),
        None => Schema::new(vec![field]),
    });
    let batch = RecordBatch::try_new(schema.clone(), vec![array]).unwrap();
    let ffi_schema = FFI_ArrowSchema::try_from(schema.as_ref()).unwrap();
    let reader = arrow::record_batch::RecordBatchIterator::new(vec![Ok(batch)], schema);
    let stream = FFI_ArrowArrayStream::new(Box::new(reader));
    (ffi_schema, stream)
}

fn write_descriptor_dataset(
    uri: &str,
    mode: i32,
    schema: &FFI_ArrowSchema,
    stream: FFI_ArrowArrayStream,
) -> i32 {
    let params = LanceWriteParams {
        max_rows_per_file: 0,
        max_rows_per_group: 0,
        max_bytes_per_file: 0,
        data_storage_version: c"2.2".as_ptr(),
        enable_stable_row_ids: false,
    };
    let mut stream = stream;
    let mut dataset = ptr::null_mut();
    let uri = c_str(uri);
    let rc = unsafe {
        lance_dataset_write_with_params(
            uri.as_ptr(),
            schema,
            &mut stream,
            mode,
            &params,
            ptr::null(),
            &mut dataset,
        )
    };
    if rc == 0 {
        assert!(!dataset.is_null());
        unsafe { lance_dataset_close(dataset) };
    }
    rc
}

fn managed_metadata() -> HashMap<String, String> {
    HashMap::from([("lance.blob.managed".to_string(), "true".to_string())])
}

#[test]
fn test_blob_field_exports_native_metadata_and_checked_options() {
    let mut ffi = FFI_ArrowSchema::empty();
    assert_eq!(
        unsafe { lance_blob_field(c"blob".as_ptr(), true, &mut ffi) },
        0,
        "{}",
        take_last_error_message()
    );
    let field = Field::try_from(&ffi).unwrap();
    assert_eq!(field, lance::blob_field("blob", true));
    assert!(field.is_nullable());
    assert_eq!(
        field
            .metadata()
            .get("ARROW:extension:name")
            .map(String::as_str),
        Some("lance.blob.v2")
    );

    let options = LanceBlobFieldOptions {
        has_inline_size_threshold: true,
        inline_size_threshold: 0,
        has_dedicated_size_threshold: true,
        dedicated_size_threshold: 256,
    };
    let mut ffi = FFI_ArrowSchema::empty();
    assert_eq!(
        unsafe { lance_blob_field_with_options(c"thresholds".as_ptr(), false, &options, &mut ffi) },
        0,
        "{}",
        take_last_error_message()
    );
    let field = Field::try_from(&ffi).unwrap();
    let expected = lance::blob_field_with_options(
        "thresholds",
        false,
        lance::BlobFieldOptions {
            inline_size_threshold: Some(0),
            dedicated_size_threshold: std::num::NonZeroUsize::new(256),
        },
    );
    assert_eq!(field, expected);
    assert!(!field.is_nullable());
    assert_eq!(
        field
            .metadata()
            .get("lance-encoding:blob-inline-size-threshold")
            .map(String::as_str),
        Some("0")
    );
    assert_eq!(
        field
            .metadata()
            .get("lance-encoding:blob-dedicated-size-threshold")
            .map(String::as_str),
        Some("256")
    );

    let invalid_zero = LanceBlobFieldOptions {
        has_dedicated_size_threshold: true,
        dedicated_size_threshold: 0,
        ..LanceBlobFieldOptions::default()
    };
    let mut untouched = FFI_ArrowSchema::empty();
    assert_eq!(
        unsafe {
            lance_blob_field_with_options(c"invalid".as_ptr(), true, &invalid_zero, &mut untouched)
        },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(take_last_error_message().contains("greater than 0"));
    assert!(untouched.release.is_none(), "error must not write output");
    assert!(untouched.format.is_null(), "error must not write output");

    assert_eq!(
        unsafe { lance_blob_field(ptr::null(), true, &mut untouched) },
        -1
    );
    assert!(take_last_error_message().contains("name must not be NULL"));
    assert_eq!(
        unsafe { lance_blob_field(c"blob".as_ptr(), true, ptr::null_mut()) },
        -1
    );
    assert!(take_last_error_message().contains("out must not be NULL"));
}

#[test]
fn test_blob_descriptor_array_builder_matches_native_all_kinds() {
    use lance::{BlobDescriptor, BlobRange as NativeRange};

    let builder = unsafe { lance_blob_descriptor_array_builder_new(c"blob".as_ptr()) };
    assert!(!builder.is_null(), "{}", take_last_error_message());

    let mut field_before = FFI_ArrowSchema::empty();
    assert_eq!(
        unsafe { lance_blob_descriptor_array_builder_field(builder, &mut field_before) },
        0,
        "{}",
        take_last_error_message()
    );

    let inline = b"inline payload";
    assert_eq!(
        unsafe {
            lance_blob_descriptor_array_builder_append_inline(
                builder,
                inline.as_ptr(),
                inline.len(),
            )
        },
        0
    );
    assert_eq!(
        unsafe { lance_blob_descriptor_array_builder_append_null(builder) },
        0
    );
    assert_eq!(
        unsafe { lance_blob_descriptor_array_builder_append_packed(builder, 7, 100, 8) },
        0
    );
    assert_eq!(
        unsafe { lance_blob_descriptor_array_builder_append_dedicated(builder, 9, 1024) },
        0
    );
    assert_eq!(
        unsafe {
            lance_blob_descriptor_array_builder_append_managed(
                builder,
                c"data/a.blob".as_ptr(),
                2,
                3,
                false,
                0,
            )
        },
        0
    );
    assert_eq!(
        unsafe {
            lance_blob_descriptor_array_builder_append_managed(
                builder,
                c"data/b.blob".as_ptr(),
                4,
                5,
                true,
                0,
            )
        },
        0
    );
    let packed_ranges = [
        LanceBlobRange {
            offset: 1,
            length: 2,
        },
        LanceBlobRange {
            offset: 3,
            length: 4,
        },
    ];
    assert_eq!(
        unsafe {
            lance_blob_descriptor_array_builder_extend_packed(
                builder,
                11,
                packed_ranges.as_ptr(),
                packed_ranges.len(),
            )
        },
        0
    );
    assert_eq!(
        unsafe {
            lance_blob_descriptor_array_builder_push_external(
                builder,
                c"file:///tmp/external.bin".as_ptr(),
                true,
                7,
                9,
            )
        },
        0
    );
    assert_eq!(
        unsafe {
            lance_blob_descriptor_array_builder_append_external(
                builder,
                3,
                c"s3://bucket/object".as_ptr(),
                11,
                13,
            )
        },
        0
    );
    assert_eq!(
        unsafe { lance_blob_descriptor_array_builder_append_inline(builder, ptr::null(), 0) },
        0,
        "NULL plus zero length is a valid empty inline blob"
    );

    let mut field_after = FFI_ArrowSchema::empty();
    assert_eq!(
        unsafe { lance_blob_descriptor_array_builder_field(builder, &mut field_after) },
        0
    );
    assert_eq!(
        Field::try_from(&field_before).unwrap(),
        Field::try_from(&field_after).unwrap()
    );

    let mut native = lance::BlobDescriptorArrayBuilder::new("blob");
    native.push_inline(Bytes::copy_from_slice(inline)).unwrap();
    native.push_null().unwrap();
    native
        .push_packed(
            7,
            NativeRange {
                offset: 100,
                size: 8,
            },
        )
        .unwrap();
    native.push_dedicated(9, 1024).unwrap();
    native
        .push(BlobDescriptor::Managed {
            base_id: None,
            uri: "data/a.blob".to_string(),
            offset: 2,
            size: 3,
        })
        .unwrap();
    native
        .push(BlobDescriptor::Managed {
            base_id: Some(0),
            uri: "data/b.blob".to_string(),
            offset: 4,
            size: 5,
        })
        .unwrap();
    native
        .extend_packed(
            11,
            [
                NativeRange { offset: 1, size: 2 },
                NativeRange { offset: 3, size: 4 },
            ],
        )
        .unwrap();
    native
        .push_external(
            "file:///tmp/external.bin".to_string(),
            Some(NativeRange { offset: 7, size: 9 }),
        )
        .unwrap();
    native
        .push(BlobDescriptor::External {
            base_id: 3,
            uri: "s3://bucket/object".to_string(),
            offset: 11,
            size: 13,
        })
        .unwrap();
    native.push_inline(Bytes::new()).unwrap();
    let (native_field, native_array) = native.finish().unwrap().into_parts();

    let (field, array) = finish_descriptor_builder(builder);
    assert_eq!(field, native_field);
    assert_eq!(array.to_data(), native_array.to_data());

    // Native finish is consuming. The field stays available, appends fail.
    let mut post_finish_field = FFI_ArrowSchema::empty();
    assert_eq!(
        unsafe { lance_blob_descriptor_array_builder_field(builder, &mut post_finish_field) },
        0,
        "field must remain exportable after finish"
    );
    assert_eq!(Field::try_from(&post_finish_field).unwrap(), native_field);
    assert_eq!(
        unsafe { lance_blob_descriptor_array_builder_append_null(builder) },
        -1
    );
    assert!(take_last_error_message().contains("already finished"));
    unsafe { lance_blob_descriptor_array_builder_close(builder) };
}

#[test]
fn test_blob_descriptor_array_builder_native_validation_and_partial_progress() {
    let builder = unsafe { lance_blob_descriptor_array_builder_new(c"blob".as_ptr()) };
    assert!(!builder.is_null());
    let ranges = [
        LanceBlobRange {
            offset: 1,
            length: 2,
        },
        LanceBlobRange {
            offset: u64::MAX,
            length: 2,
        },
    ];
    assert_eq!(
        unsafe {
            lance_blob_descriptor_array_builder_extend_packed(
                builder,
                7,
                ranges.as_ptr(),
                ranges.len(),
            )
        },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(take_last_error_message().contains("overflows"));

    // The valid prefix remains, matching native incremental push behavior.
    assert_eq!(
        unsafe { lance_blob_descriptor_array_builder_append_null(builder) },
        0,
        "a failed range must not poison the builder"
    );
    let (field, array) = finish_descriptor_builder(builder);
    unsafe { lance_blob_descriptor_array_builder_close(builder) };

    let mut native = lance::BlobDescriptorArrayBuilder::new("blob");
    native
        .push_packed(7, lance::BlobRange { offset: 1, size: 2 })
        .unwrap();
    native.push_null().unwrap();
    let (native_field, native_array) = native.finish().unwrap().into_parts();
    assert_eq!(field, native_field);
    assert_eq!(array.to_data(), native_array.to_data());

    let builder = unsafe { lance_blob_descriptor_array_builder_new(c"blob".as_ptr()) };
    assert!(!builder.is_null());
    for (uri, offset, length) in [
        ("", 0, 1),
        ("/absolute", 0, 1),
        ("data/../escape", 0, 1),
        ("data/./same", 0, 1),
        ("s3://bucket/object", 0, 1),
        ("data\\windows", 0, 1),
        ("data/a.blob/", 0, 1),
        ("data/a.blob", u64::MAX, 1),
    ] {
        let uri = c_str(uri);
        assert_eq!(
            unsafe {
                lance_blob_descriptor_array_builder_append_managed(
                    builder,
                    uri.as_ptr(),
                    offset,
                    length,
                    false,
                    0,
                )
            },
            -1,
            "managed URI {uri:?} must be rejected by native validation"
        );
        let message = take_last_error_message();
        assert!(
            message.contains("Managed blob_uri") || message.contains("overflows"),
            "{message}"
        );
    }

    assert_eq!(
        unsafe { lance_blob_descriptor_array_builder_append_inline(builder, ptr::null(), 1) },
        -1
    );
    assert!(take_last_error_message().contains("data must not be NULL"));
    assert_eq!(
        unsafe { lance_blob_descriptor_array_builder_append_dedicated(builder, 0, 4) },
        -1
    );
    assert!(take_last_error_message().contains("Blob id 0 is reserved"));
    assert_eq!(
        unsafe { lance_blob_descriptor_array_builder_extend_packed(builder, 7, ptr::null(), 1,) },
        -1
    );
    assert!(take_last_error_message().contains("ranges must not be NULL"));

    // Failed appends added nothing. A valid NULL is the only row.
    assert_eq!(
        unsafe { lance_blob_descriptor_array_builder_append_null(builder) },
        0
    );
    let (_, array) = finish_descriptor_builder(builder);
    unsafe { lance_blob_descriptor_array_builder_close(builder) };
    assert_eq!(array.len(), 1);
    assert!(array.is_null(0));
}

#[test]
fn test_dataset_read_blobs_all_selectors_and_native_identity() {
    let (_tmp, uri) = create_blob_v2_dataset(true);
    let uri_c = c_str(&uri);
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());

    let all_row_ids = scan_blob_row_ids(dataset);
    assert_eq!(all_row_ids.len(), 2 * BLOB_ROW_SIZES.len());
    let indices = [7usize, 2, 2, 9, 0];
    let row_ids = indices
        .iter()
        .map(|index| all_row_ids[*index])
        .collect::<Vec<_>>();
    let addresses = indices
        .iter()
        .map(|index| blob_row_address(*index))
        .collect::<Vec<_>>();
    assert!(
        row_ids
            .iter()
            .zip(&addresses)
            .any(|(row_id, address)| row_id != address),
        "stable row IDs must be distinguishable from physical row addresses"
    );
    let expected = indices
        .iter()
        .map(|index| (blob_row_address(*index), expected_blob(*index)))
        .collect::<Vec<_>>();
    let index_rows = indices.map(|index| index as u64);
    let options = c_blob_read_options(None, true);

    for (selector, rows) in [
        (BLOB_SELECTOR_IDS, row_ids.as_slice()),
        (BLOB_SELECTOR_ADDRESSES, addresses.as_slice()),
        (BLOB_SELECTOR_INDICES, index_rows.as_slice()),
    ] {
        let (rc, stream) = c_read_blobs(dataset, "blob", selector, rows, &options);
        assert_eq!(rc, 0, "{}", take_last_error_message());
        let (schema, batches) = collect_whole_blob_stream(stream);
        assert_whole_stream_identity(&schema, &batches);
        let values = whole_blob_values(&batches);
        assert_eq!(values, expected, "selector {selector}");
        assert_eq!(
            values,
            native_whole_blob_values(&uri, "blob", selector, rows, None, true),
            "selector {selector} must match the native stream"
        );
    }

    // Unordered reads keep native row-address identity and accepted options.
    let unique_indices = [7usize, 2, 9, 0];
    let unique_rows = unique_indices
        .iter()
        .map(|index| *index as u64)
        .collect::<Vec<_>>();
    let (rc, stream) = c_read_blobs(
        dataset,
        "blob",
        BLOB_SELECTOR_INDICES,
        &unique_rows,
        &c_blob_read_options(Some(64), false),
    );
    assert_eq!(rc, 0, "{}", take_last_error_message());
    let (_, batches) = collect_whole_blob_stream(stream);
    let mut unordered = whole_blob_values(&batches);
    unordered.sort_by_key(|(address, _)| *address);
    let mut expected_unique = unique_indices
        .iter()
        .map(|index| (blob_row_address(*index), expected_blob(*index)))
        .collect::<Vec<_>>();
    expected_unique.sort_by_key(|(address, _)| *address);
    assert_eq!(unordered, expected_unique);
    let mut native_unordered = native_whole_blob_values(
        &uri,
        "blob",
        BLOB_SELECTOR_INDICES,
        &unique_rows,
        Some(64),
        false,
    );
    native_unordered.sort_by_key(|(address, _)| *address);
    assert_eq!(unordered, native_unordered);

    unsafe { lance_dataset_close(dataset) };
}

#[test]
fn test_dataset_read_blobs_empty_none_errors_and_ownership() {
    let (_tmp, uri) = create_blob_v2_dataset(false);
    let uri_c = c_str(&uri);
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());
    let options = c_blob_read_options(None, true);

    // Explicit empty selection is a real native selection and yields no rows.
    let (rc, stream) = c_read_blobs(dataset, "blob", BLOB_SELECTOR_IDS, &[], &options);
    assert_eq!(rc, 0, "{}", take_last_error_message());
    let (schema, batches) = collect_whole_blob_stream(stream);
    assert_whole_stream_identity(&schema, &batches);
    assert!(batches.is_empty());

    let sentinel = ptr::without_provenance_mut::<c_void>(0xDEAD_BEEF);
    let mut stream = empty_ffi_stream_with_sentinel(sentinel);
    assert_eq!(
        unsafe {
            lance_dataset_read_blobs(
                dataset,
                c"blob".as_ptr(),
                BLOB_SELECTOR_NONE,
                ptr::null(),
                0,
                &options,
                &mut stream,
            )
        },
        -1
    );
    assert!(take_last_error_message().contains("requires a row selection"));
    assert_ffi_stream_untouched(&stream, sentinel);

    let mut stream = empty_ffi_stream_with_sentinel(sentinel);
    assert_eq!(
        unsafe {
            lance_dataset_read_blobs(
                dataset,
                c"blob".as_ptr(),
                BLOB_SELECTOR_INDICES,
                [0u64].as_ptr(),
                1,
                &c_blob_read_options(Some(0), true),
                &mut stream,
            )
        },
        -1
    );
    assert!(take_last_error_message().contains("greater than 0"));
    assert_ffi_stream_untouched(&stream, sentinel);

    let mut stream = empty_ffi_stream_with_sentinel(sentinel);
    assert_eq!(
        unsafe {
            lance_dataset_read_blobs(
                dataset,
                c"does_not_exist".as_ptr(),
                BLOB_SELECTOR_NONE,
                ptr::null(),
                0,
                &options,
                &mut stream,
            )
        },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::Internal);
    assert!(take_last_error_message().contains("does_not_exist"));
    assert_ffi_stream_untouched(&stream, sentinel);

    let mut stream = empty_ffi_stream_with_sentinel(sentinel);
    assert_eq!(
        unsafe {
            lance_dataset_read_blobs(
                dataset,
                c"raw".as_ptr(),
                BLOB_SELECTOR_NONE,
                ptr::null(),
                0,
                &options,
                &mut stream,
            )
        },
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(take_last_error_message().contains("not a blob column"));
    assert_ffi_stream_untouched(&stream, sentinel);

    let mut stream = empty_ffi_stream_with_sentinel(sentinel);
    let mut invalid_options = options;
    invalid_options.order = 99;
    assert_eq!(
        unsafe {
            lance_dataset_read_blobs(
                dataset,
                c"blob".as_ptr(),
                BLOB_SELECTOR_INDICES,
                [0u64].as_ptr(),
                1,
                &invalid_options,
                &mut stream,
            )
        },
        -1
    );
    assert!(take_last_error_message().contains("invalid blob read order"));
    assert_ffi_stream_untouched(&stream, sentinel);

    // A planned stream owns its snapshot and stays incremental after the
    // dataset handle closes.
    let (rc, stream) = c_read_blobs(
        dataset,
        "blob",
        BLOB_SELECTOR_INDICES,
        &[0, 1, 3, 4],
        &options,
    );
    assert_eq!(rc, 0, "{}", take_last_error_message());
    unsafe { lance_dataset_close(dataset) };
    let (schema, batches) = collect_whole_blob_stream(stream);
    assert_whole_stream_identity(&schema, &batches);
    assert_eq!(batches.len(), 4);
    let values = whole_blob_values(&batches);
    assert_eq!(values[0], (blob_row_address(0), expected_blob(0)));
    assert_eq!(values[2], (blob_row_address(3), Some(Vec::new())));
    assert_eq!(values[3], (blob_row_address(4), None));
}

#[test]
fn test_dataset_read_blob_ranges_identity_nulls_and_options() {
    let (_tmp, uri) = create_blob_v2_dataset(true);
    let uri_c = c_str(&uri);
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());

    let all_row_ids = scan_blob_row_ids(dataset);
    let base_requests = [
        (7usize, 100u64, 20u64),
        (7, 108, 20),
        (2, 128, 0),
        (9, 40, 16),
        (2, 100, 8),
        (9, 127, 1),
        (3, 0, 0),
        // Native NULL blobs skip logical bounds checks.
        (4, 1000, 100),
        (0, 0, 8),
    ];
    let expected = base_requests
        .iter()
        .enumerate()
        .map(|(request_index, (row, offset, length))| {
            let data = match expected_blob(*row) {
                None => None,
                Some(payload) => {
                    let start = *offset as usize;
                    let end = start + *length as usize;
                    Some(payload[start..end].to_vec())
                }
            };
            (
                request_index,
                blob_row_address(*row),
                *offset,
                *length,
                data,
            )
        })
        .collect::<Vec<_>>();
    let options = c_blob_read_options(None, true);

    for selector in [
        BLOB_SELECTOR_IDS,
        BLOB_SELECTOR_ADDRESSES,
        BLOB_SELECTOR_INDICES,
    ] {
        let requests = base_requests
            .iter()
            .map(|(row, offset, length)| LanceBlobRangeRequest {
                row: match selector {
                    BLOB_SELECTOR_IDS => all_row_ids[*row],
                    BLOB_SELECTOR_ADDRESSES => blob_row_address(*row),
                    BLOB_SELECTOR_INDICES => *row as u64,
                    _ => unreachable!(),
                },
                offset: *offset,
                length: *length,
            })
            .collect::<Vec<_>>();
        let native_requests = requests
            .iter()
            .map(|request| (request.row, request.offset, request.length))
            .collect::<Vec<_>>();
        let (rc, stream) = c_read_blob_ranges(dataset, "blob", selector, &requests, &options);
        assert_eq!(rc, 0, "{}", take_last_error_message());
        let (schema, batches) = collect_blob_range_stream(stream);
        assert_range_stream_identity(&schema, &batches);
        assert_eq!(blob_range_values(&batches), expected, "selector {selector}");
        assert_eq!(
            blob_range_values(&batches),
            native_blob_range_values(&uri, "blob", selector, &native_requests, None, true),
            "selector {selector} must match the native stream"
        );
    }

    let unordered_requests = base_requests
        .iter()
        .map(|(row, offset, length)| LanceBlobRangeRequest {
            row: *row as u64,
            offset: *offset,
            length: *length,
        })
        .collect::<Vec<_>>();
    let unordered_native = unordered_requests
        .iter()
        .map(|request| (request.row, request.offset, request.length))
        .collect::<Vec<_>>();
    let (rc, stream) = c_read_blob_ranges(
        dataset,
        "blob",
        BLOB_SELECTOR_INDICES,
        &unordered_requests,
        &c_blob_read_options(Some(32), false),
    );
    assert_eq!(rc, 0, "{}", take_last_error_message());
    let (_, batches) = collect_blob_range_stream(stream);
    let mut actual = blob_range_values(&batches);
    actual.sort_by_key(|value| value.0);
    let mut native = native_blob_range_values(
        &uri,
        "blob",
        BLOB_SELECTOR_INDICES,
        &unordered_native,
        Some(32),
        false,
    );
    native.sort_by_key(|value| value.0);
    assert_eq!(actual, native);
    assert_eq!(actual, expected);

    // Explicit empty selection remains distinct from native no-selection.
    let (rc, stream) = c_read_blob_ranges(dataset, "blob", BLOB_SELECTOR_INDICES, &[], &options);
    assert_eq!(rc, 0, "{}", take_last_error_message());
    let (schema, batches) = collect_blob_range_stream(stream);
    assert_range_stream_identity(&schema, &batches);
    assert!(batches.is_empty());

    let sentinel = ptr::without_provenance_mut::<c_void>(0xDEAD_BEEF);
    for (requests, expected_fragment) in [
        (
            vec![LanceBlobRangeRequest {
                row: 1,
                offset: 127,
                length: 2,
            }],
            "invalid",
        ),
        (
            vec![LanceBlobRangeRequest {
                row: 0,
                offset: u64::MAX,
                length: 2,
            }],
            "overflow",
        ),
    ] {
        let mut stream = empty_ffi_stream_with_sentinel(sentinel);
        assert_eq!(
            unsafe {
                lance_dataset_read_blob_ranges(
                    dataset,
                    c"blob".as_ptr(),
                    BLOB_SELECTOR_INDICES,
                    requests.as_ptr(),
                    requests.len(),
                    &options,
                    &mut stream,
                )
            },
            -1
        );
        let message = take_last_error_message();
        assert!(
            message.to_lowercase().contains(expected_fragment)
                || message.contains("exceeds blob size"),
            "{message}"
        );
        assert_ffi_stream_untouched(&stream, sentinel);
    }

    let mut stream = empty_ffi_stream_with_sentinel(sentinel);
    assert_eq!(
        unsafe {
            lance_dataset_read_blob_ranges(
                dataset,
                c"blob".as_ptr(),
                BLOB_SELECTOR_NONE,
                ptr::null(),
                0,
                &options,
                &mut stream,
            )
        },
        -1
    );
    assert!(take_last_error_message().contains("requires requests"));
    assert_ffi_stream_untouched(&stream, sentinel);

    unsafe { lance_dataset_close(dataset) };
}

#[test]
fn test_dataset_read_blobs_respects_deletions_and_duplicate_indices() {
    let (_tmp, uri) = create_blob_v2_dataset(true);
    lance_c::runtime::block_on(async {
        Dataset::open(&uri)
            .await
            .unwrap()
            .delete("id = 1")
            .await
            .unwrap();
    });

    let uri_c = c_str(&uri);
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());
    let row_ids = scan_blob_row_ids(dataset);
    assert_eq!(row_ids.len(), 9);
    let options = c_blob_read_options(None, true);
    let selected_indices = [0usize, 1, 5, 5, 8];
    let selected_rows = [0usize, 2, 6, 6, 9];
    let selected_ids = selected_indices
        .iter()
        .map(|index| row_ids[*index])
        .collect::<Vec<_>>();
    let expected = selected_rows
        .iter()
        .map(|row| (blob_row_address(*row), expected_blob(*row)))
        .collect::<Vec<_>>();

    let (rc, stream) = c_read_blobs(dataset, "blob", BLOB_SELECTOR_IDS, &selected_ids, &options);
    assert_eq!(rc, 0, "{}", take_last_error_message());
    let (_, batches) = collect_whole_blob_stream(stream);
    assert_eq!(whole_blob_values(&batches), expected);

    let selected_logical = selected_indices
        .iter()
        .map(|index| *index as u64)
        .collect::<Vec<_>>();
    let (rc, stream) = c_read_blobs(
        dataset,
        "blob",
        BLOB_SELECTOR_INDICES,
        &selected_logical,
        &options,
    );
    assert_eq!(rc, 0, "{}", take_last_error_message());
    let (_, batches) = collect_whole_blob_stream(stream);
    assert_eq!(
        whole_blob_values(&batches),
        native_whole_blob_values(
            &uri,
            "blob",
            BLOB_SELECTOR_INDICES,
            &selected_logical,
            None,
            true,
        )
    );
    assert_eq!(whole_blob_values(&batches)[2], expected[2]);
    assert_eq!(whole_blob_values(&batches)[3], expected[3]);

    unsafe { lance_dataset_close(dataset) };
}

#[test]
fn test_managed_blob_descriptor_append_reuse_reopen_and_base_validation() {
    let tmp = tempfile::tempdir().unwrap();
    let uri = tmp
        .path()
        .join("managed_blob")
        .to_str()
        .unwrap()
        .to_string();
    let no_opt_in_uri = tmp
        .path()
        .join("managed_no_opt_in")
        .to_str()
        .unwrap()
        .to_string();
    let unknown_base_uri = tmp
        .path()
        .join("managed_unknown_base")
        .to_str()
        .unwrap()
        .to_string();
    let relative_path = "_blobs/managed.bin";

    let builder = unsafe { lance_blob_descriptor_array_builder_new(c"blob".as_ptr()) };
    assert_eq!(
        unsafe {
            lance_blob_descriptor_array_builder_append_managed(
                builder,
                c_str(relative_path).as_ptr(),
                1,
                5,
                false,
                0,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    let (field, array) = finish_descriptor_builder(builder);
    unsafe { lance_blob_descriptor_array_builder_close(builder) };
    let (schema, stream) =
        ffi_descriptor_stream(field.clone(), array.clone(), Some(managed_metadata()));
    assert_eq!(
        write_descriptor_dataset(&uri, LanceWriteMode::Create as i32, &schema, stream,),
        0,
        "{}",
        take_last_error_message()
    );

    // The managed target is an immutable reference. Missing payload files are
    // a late stream error, not a factory/planning error.
    let uri_c = c_str(&uri);
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());
    let (rc, mut stream) = c_read_blobs(
        dataset,
        "blob",
        BLOB_SELECTOR_INDICES,
        &[0],
        &c_blob_read_options(None, true),
    );
    assert_eq!(rc, 0, "{}", take_last_error_message());
    let mut arrow_array = FFI_ArrowArray::empty();
    let get_next = stream.get_next.unwrap();
    let next_status = unsafe { get_next(&mut stream, &mut arrow_array) };
    assert_ne!(
        next_status, 0,
        "the missing managed payload must fail while consuming the stream"
    );
    let get_last_error = stream.get_last_error.unwrap();
    let error = unsafe { get_last_error(&mut stream) };
    assert!(!error.is_null());
    let error = unsafe { CStr::from_ptr(error) }.to_string_lossy();
    assert!(
        error.to_lowercase().contains("not found")
            || error.to_lowercase().contains("no such file")
            || error.contains("managed.bin"),
        "{error}"
    );
    if let Some(release) = stream.release {
        unsafe { release(&mut stream) };
    }
    unsafe { lance_dataset_close(dataset) };

    let object_path = std::path::Path::new(&uri).join(relative_path);
    std::fs::create_dir_all(object_path.parent().unwrap()).unwrap();
    std::fs::write(&object_path, b"0123456789").unwrap();

    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());
    let (rc, stream) = c_read_blobs(
        dataset,
        "blob",
        BLOB_SELECTOR_INDICES,
        &[0],
        &c_blob_read_options(None, true),
    );
    assert_eq!(rc, 0, "{}", take_last_error_message());
    let (_, batches) = collect_whole_blob_stream(stream);
    assert_eq!(
        whole_blob_values(&batches),
        vec![(blob_row_address(0), Some(b"12345".to_vec()))]
    );
    let first_version = unsafe { lance_dataset_version(dataset) };
    unsafe { lance_dataset_close(dataset) };

    // Reuse the same immutable reference with a different range in an append.
    let builder = unsafe { lance_blob_descriptor_array_builder_new(c"blob".as_ptr()) };
    assert_eq!(
        unsafe {
            lance_blob_descriptor_array_builder_append_managed(
                builder,
                c_str(relative_path).as_ptr(),
                5,
                3,
                false,
                0,
            )
        },
        0
    );
    let (field, array) = finish_descriptor_builder(builder);
    unsafe { lance_blob_descriptor_array_builder_close(builder) };
    let (schema, stream) = ffi_descriptor_stream(field, array, Some(managed_metadata()));
    assert_eq!(
        write_descriptor_dataset(&uri, LanceWriteMode::Append as i32, &schema, stream,),
        0,
        "{}",
        take_last_error_message()
    );

    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());
    let (rc, stream) = c_read_blobs(
        dataset,
        "blob",
        BLOB_SELECTOR_INDICES,
        &[0, 1],
        &c_blob_read_options(None, true),
    );
    assert_eq!(rc, 0, "{}", take_last_error_message());
    let (_, batches) = collect_whole_blob_stream(stream);
    assert_eq!(
        whole_blob_values(&batches),
        vec![
            (blob_row_address(0), Some(b"12345".to_vec())),
            (((1u64) << 32), Some(b"567".to_vec())),
        ]
    );
    unsafe { lance_dataset_close(dataset) };

    // The old snapshot still resolves the first immutable reference.
    let old = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), first_version) };
    assert!(!old.is_null());
    let (rc, stream) = c_read_blobs(
        old,
        "blob",
        BLOB_SELECTOR_INDICES,
        &[0],
        &c_blob_read_options(None, true),
    );
    assert_eq!(rc, 0, "{}", take_last_error_message());
    let (_, batches) = collect_whole_blob_stream(stream);
    assert_eq!(
        whole_blob_values(&batches),
        vec![(blob_row_address(0), Some(b"12345".to_vec()))]
    );
    unsafe { lance_dataset_close(old) };

    // Register an additional base, then append a ManagedWithBase reference.
    let base_dir = tmp.path().join("managed_base");
    let base_object = base_dir.join("_blobs/base.bin");
    std::fs::create_dir_all(base_object.parent().unwrap()).unwrap();
    std::fs::write(&base_object, b"0123456789").unwrap();
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());
    let base_uri = c_str(base_dir.to_str().unwrap());
    let base = LanceBasePath {
        id: 7,
        path: base_uri.as_ptr(),
        name: ptr::null(),
        is_dataset_root: false,
    };
    assert_eq!(
        unsafe { lance_dataset_add_bases(dataset, &base, 1, ptr::null()) },
        0,
        "{}",
        take_last_error_message()
    );
    unsafe { lance_dataset_close(dataset) };

    let builder = unsafe { lance_blob_descriptor_array_builder_new(c"blob".as_ptr()) };
    assert_eq!(
        unsafe {
            lance_blob_descriptor_array_builder_append_managed(
                builder,
                c"_blobs/base.bin".as_ptr(),
                2,
                4,
                true,
                7,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    let (field, array) = finish_descriptor_builder(builder);
    unsafe { lance_blob_descriptor_array_builder_close(builder) };
    let (schema, stream) = ffi_descriptor_stream(field, array, Some(managed_metadata()));
    assert_eq!(
        write_descriptor_dataset(&uri, LanceWriteMode::Append as i32, &schema, stream,),
        0,
        "{}",
        take_last_error_message()
    );
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());
    let (rc, stream) = c_read_blobs(
        dataset,
        "blob",
        BLOB_SELECTOR_INDICES,
        &[2],
        &c_blob_read_options(None, true),
    );
    assert_eq!(rc, 0, "{}", take_last_error_message());
    let (_, batches) = collect_whole_blob_stream(stream);
    assert_eq!(
        whole_blob_values(&batches),
        vec![(((2u64) << 32), Some(b"2345".to_vec()))]
    );
    unsafe { lance_dataset_close(dataset) };

    // A prepared External descriptor can share the same registered base and
    // immutable object without introducing a second payload owner.
    let builder = unsafe { lance_blob_descriptor_array_builder_new(c"blob".as_ptr()) };
    assert_eq!(
        unsafe {
            lance_blob_descriptor_array_builder_append_external(
                builder,
                7,
                c"_blobs/base.bin".as_ptr(),
                1,
                3,
            )
        },
        0,
        "{}",
        take_last_error_message()
    );
    let (field, array) = finish_descriptor_builder(builder);
    unsafe { lance_blob_descriptor_array_builder_close(builder) };
    let (schema, stream) = ffi_descriptor_stream(field, array, Some(managed_metadata()));
    assert_eq!(
        write_descriptor_dataset(&uri, LanceWriteMode::Append as i32, &schema, stream,),
        0,
        "{}",
        take_last_error_message()
    );
    let dataset = unsafe { lance_dataset_open(uri_c.as_ptr(), ptr::null(), 0) };
    assert!(!dataset.is_null());
    let (rc, stream) = c_read_blobs(
        dataset,
        "blob",
        BLOB_SELECTOR_INDICES,
        &[3],
        &c_blob_read_options(None, true),
    );
    assert_eq!(rc, 0, "{}", take_last_error_message());
    let (_, batches) = collect_whole_blob_stream(stream);
    assert_eq!(
        whole_blob_values(&batches),
        vec![(((3u64) << 32), Some(b"123".to_vec()))]
    );
    unsafe { lance_dataset_close(dataset) };
    assert_eq!(std::fs::read(&object_path).unwrap(), b"0123456789");
    assert_eq!(std::fs::read(&base_object).unwrap(), b"0123456789");

    // The native schema opt-in remains mandatory.
    let builder = unsafe { lance_blob_descriptor_array_builder_new(c"blob".as_ptr()) };
    assert_eq!(
        unsafe {
            lance_blob_descriptor_array_builder_append_managed(
                builder,
                c"data/no-opt-in.blob".as_ptr(),
                0,
                1,
                false,
                0,
            )
        },
        0
    );
    let (field, array) = finish_descriptor_builder(builder);
    unsafe { lance_blob_descriptor_array_builder_close(builder) };
    let (schema, stream) = ffi_descriptor_stream(field, array, None);
    assert_eq!(
        write_descriptor_dataset(
            &no_opt_in_uri,
            LanceWriteMode::Create as i32,
            &schema,
            stream,
        ),
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(take_last_error_message().contains("lance.blob.managed=true"));

    // Unknown registered bases are rejected by native write preprocessing.
    let builder = unsafe { lance_blob_descriptor_array_builder_new(c"blob".as_ptr()) };
    assert_eq!(
        unsafe {
            lance_blob_descriptor_array_builder_append_managed(
                builder,
                c"data/unknown-base.blob".as_ptr(),
                0,
                1,
                true,
                999,
            )
        },
        0
    );
    let (field, array) = finish_descriptor_builder(builder);
    unsafe { lance_blob_descriptor_array_builder_close(builder) };
    let (schema, stream) = ffi_descriptor_stream(field, array, Some(managed_metadata()));
    assert_eq!(
        write_descriptor_dataset(
            &unknown_base_uri,
            LanceWriteMode::Create as i32,
            &schema,
            stream,
        ),
        -1
    );
    assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
    assert!(take_last_error_message().contains("unknown base_id 999"));
}

#[test]
fn test_scanner_nearest_batch_null_arguments() {
    let (_dir, uri) = create_vector_dataset(8, 2);
    unsafe {
        let ds = lance_dataset_open(c_str(&uri).as_ptr(), ptr::null(), 0);
        let scan = lance_scanner_new(ds, ptr::null(), ptr::null());
        let query = [0f32, 1.];
        for (scanner, column, data) in [
            (ptr::null_mut(), c_str("embedding"), query.as_ptr().cast()),
            (scan, c_str("embedding"), ptr::null()),
        ] {
            assert_ne!(
                lance_scanner_nearest_batch(scanner, column.as_ptr(), data, 2, 1, 0, 1),
                0
            );
        }
        assert_ne!(
            lance_scanner_nearest_batch(scan, ptr::null(), query.as_ptr().cast(), 2, 1, 0, 1),
            0
        );
        lance_scanner_close(scan);
        lance_dataset_close(ds);
    }
}

#[test]
fn test_prewarm_index_invalid_arguments_and_missing_index() {
    let (_tmp, uri) = create_test_dataset();
    unsafe {
        let ds = lance_dataset_open(c_str(&uri).as_ptr(), ptr::null(), 0);
        assert!(!ds.is_null());
        let name = c_str("missing_idx");
        assert_eq!(lance_dataset_prewarm_index(ptr::null(), name.as_ptr()), -1);
        assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
        for name in [ptr::null(), c"".as_ptr(), c"\xff".as_ptr()] {
            assert_eq!(lance_dataset_prewarm_index(ds, name), -1);
            assert_eq!(lance_last_error_code(), LanceErrorCode::InvalidArgument);
        }
        assert_eq!(lance_dataset_prewarm_index(ds, name.as_ptr()), -1);
        assert_eq!(lance_last_error_code(), LanceErrorCode::NotFound);
        let message = lance_last_error_message();
        assert!(!message.is_null());
        assert!(
            std::ffi::CStr::from_ptr(message)
                .to_string_lossy()
                .contains("missing_idx")
        );
        lance_free_string(message);
        assert_eq!(lance_dataset_prewarm_index(ds, c"id".as_ptr()), -1);
        assert_eq!(lance_last_error_code(), LanceErrorCode::NotFound);
        assert_eq!(lance_dataset_count_rows(ds), 5);
        lance_dataset_close(ds);
    }
}

#[test]
fn test_prewarm_index_scalar_name_collides_with_other_column() {
    for index_type in [LanceScalarIndexType::BTree, LanceScalarIndexType::Inverted] {
        let (_tmp, uri) = create_test_dataset();
        unsafe {
            let ds = lance_dataset_open(c_str(&uri).as_ptr(), ptr::null(), 0);
            assert!(!ds.is_null());
            let params = c_str(r#"{"base_tokenizer":"simple","language":"English"}"#);
            assert_eq!(
                lance_dataset_create_scalar_index(
                    ds,
                    c"name".as_ptr(),
                    c"id".as_ptr(),
                    index_type as i32,
                    if index_type == LanceScalarIndexType::Inverted {
                        params.as_ptr()
                    } else {
                        ptr::null()
                    },
                    false,
                ),
                0,
                "{}",
                take_last_error_message()
            );
            let version = lance_dataset_version(ds);
            lance_dataset_close(ds);
            // Scalar and FTS prewarm must retain their SDK validation on a fresh session too.
            let cold = lance_dataset_open(c_str(&uri).as_ptr(), ptr::null(), version);
            assert!(!cold.is_null());
            assert_eq!(
                lance_dataset_prewarm_index(cold, c"id".as_ptr()),
                0,
                "{}",
                take_last_error_message()
            );
            assert_eq!(lance_dataset_version(cold), version);
            lance_dataset_close(cold);
        }
    }
}

#[test]
fn test_prewarm_index_scalar_segments_and_snapshot() {
    let (_tmp, uri, _) = create_scalar_segment_fixture(lance_index::IndexType::BTree, false);
    unsafe {
        let ds = lance_dataset_open(c_str(&uri).as_ptr(), ptr::null(), 0);
        assert!(!ds.is_null());
        assert_eq!(lance_dataset_index_count(ds), 2);
        let version = lance_dataset_version(ds);
        let historical = lance_dataset_open(c_str(&uri).as_ptr(), ptr::null(), version);
        assert!(!historical.is_null());
        assert_eq!(lance_dataset_prewarm_index(ds, c"key_idx".as_ptr()), 0);
        assert_eq!(lance_dataset_version(ds), version);
        assert_eq!(lance_dataset_drop_index(ds, c"key_idx".as_ptr()), 0);
        assert_eq!(lance_dataset_prewarm_index(ds, c"key_idx".as_ptr()), -1);
        assert_eq!(lance_last_error_code(), LanceErrorCode::NotFound);
        assert_eq!(
            lance_dataset_prewarm_index(historical, c"key_idx".as_ptr()),
            0
        );
        assert_eq!(lance_last_error_code(), LanceErrorCode::Ok);
        assert_eq!(lance_dataset_version(historical), version);
        lance_dataset_close(historical);
        lance_dataset_close(ds);
    }
}

